CREATE OR REPLACE FUNCTION "football"."_seed_fixture"("p_comp_slug" "text", "p_season_label" "text", "p_home" "text", "p_away" "text", "p_kickoff" timestamp with time zone, "p_round" "text" DEFAULT NULL::"text", "p_stage" "text" DEFAULT 'regular_season'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_id uuid;
  v_comp_id uuid;
  v_season_id uuid;
  v_home_id uuid;
  v_away_id uuid;
BEGIN
  SELECT id INTO v_comp_id FROM football.competitions WHERE slug = p_comp_slug;
  SELECT id INTO v_season_id FROM football.seasons
    WHERE competition_id = v_comp_id AND label = p_season_label;
  SELECT id INTO v_home_id FROM football.teams
    WHERE lower(name) = lower(p_home) LIMIT 1;
  SELECT id INTO v_away_id FROM football.teams
    WHERE lower(name) = lower(p_away) LIMIT 1;

  IF v_home_id IS NULL THEN RAISE EXCEPTION 'Home team % not found', p_home; END IF;
  IF v_away_id IS NULL THEN RAISE EXCEPTION 'Away team % not found', p_away; END IF;

  INSERT INTO football.fixtures (
    competition_id, season_id, home_team_id, away_team_id,
    kickoff_at, round_name, stage_name, status,
    external_provider, external_fixture_id
  ) VALUES (
    v_comp_id, v_season_id, v_home_id, v_away_id,
    p_kickoff, p_round, p_stage, 'scheduled'::football.fixture_status,
    'manual', 'manual-' || gen_random_uuid()::text
  )
  ON CONFLICT DO NOTHING
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


ALTER FUNCTION "football"."_seed_fixture"("p_comp_slug" "text", "p_season_label" "text", "p_home" "text", "p_away" "text", "p_kickoff" timestamp with time zone, "p_round" "text", "p_stage" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "football"."_seed_season"("p_comp_slug" "text", "p_label" "text", "p_year_start" integer, "p_year_end" integer) RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_id uuid;
  v_comp_id uuid;
BEGIN
  SELECT id INTO v_comp_id FROM football.competitions WHERE slug = p_comp_slug;
  IF v_comp_id IS NULL THEN RAISE EXCEPTION 'Competition % not found', p_comp_slug; END IF;

  SELECT id
    INTO v_id
  FROM football.seasons
  WHERE competition_id = v_comp_id
    AND (
      label = p_label OR
      (year_start = p_year_start AND year_end = p_year_end)
    )
  ORDER BY
    CASE WHEN label = p_label THEN 0 ELSE 1 END,
    updated_at DESC NULLS LAST,
    created_at DESC NULLS LAST
  LIMIT 1;

  IF v_id IS NOT NULL THEN
    UPDATE football.seasons
    SET label = p_label,
        status = 'active'::football.season_status,
        is_active = true
    WHERE id = v_id;

    RETURN v_id;
  END IF;

  INSERT INTO football.seasons (competition_id, slug, label, year_start, year_end, status, is_active)
  VALUES (
    v_comp_id,
    p_comp_slug || '-' || p_label,
    p_label,
    p_year_start,
    p_year_end,
    'active'::football.season_status,
    true
  )
  ON CONFLICT (competition_id, label) DO UPDATE SET is_active = true
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


ALTER FUNCTION "football"."_seed_season"("p_comp_slug" "text", "p_label" "text", "p_year_start" integer, "p_year_end" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "football"."_seed_team"("p_name" "text", "p_short" "text", "p_country" "text", "p_api_id" integer DEFAULT NULL::integer, "p_type" "text" DEFAULT 'club'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $_$
DECLARE
  v_id uuid;
  v_slug text;
  v_crest text;
BEGIN
  v_slug := lower(regexp_replace(p_name, '[^a-zA-Z0-9]+', '-', 'g'));
  v_slug := regexp_replace(v_slug, '^-+|-+$', '', 'g');
  v_crest := CASE WHEN p_api_id IS NOT NULL
    THEN 'https://media.api-sports.io/football/teams/' || p_api_id || '.png'
    ELSE NULL END;

  SELECT id
  INTO v_id
  FROM football.teams
  WHERE (
      p_api_id IS NOT NULL
      AND external_provider = 'api-football'
      AND external_team_id = p_api_id::text
    )
    OR slug = v_slug
    OR lower(name) = lower(p_name)
  ORDER BY updated_at DESC NULLS LAST, created_at DESC NULLS LAST
  LIMIT 1;

  IF v_id IS NOT NULL THEN
    UPDATE football.teams
    SET slug = v_slug,
        name = p_name,
        short_name = p_short,
        team_type = p_type::football.team_type,
        country_name = p_country,
        crest_url = COALESCE(v_crest, crest_url),
        external_provider = CASE WHEN p_api_id IS NOT NULL THEN 'api-football' ELSE external_provider END,
        external_team_id = CASE
          WHEN p_api_id IS NOT NULL THEN p_api_id::text
          ELSE COALESCE(external_team_id, 'manual-' || v_slug)
        END,
        is_active = true
    WHERE id = v_id;
  ELSE
    INSERT INTO football.teams (slug, name, short_name, team_type, country_name, crest_url,
      external_provider, external_team_id, is_active)
    VALUES (v_slug, p_name, p_short, p_type::football.team_type, p_country, v_crest,
      CASE WHEN p_api_id IS NOT NULL THEN 'api-football' ELSE 'manual' END,
      COALESCE(p_api_id::text, 'manual-' || v_slug), true)
    RETURNING id INTO v_id;
  END IF;

  RETURN v_id;
END;
$_$;


ALTER FUNCTION "football"."_seed_team"("p_name" "text", "p_short" "text", "p_country" "text", "p_api_id" integer, "p_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "football"."auto_lock_fixture_markets"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  -- When a fixture transitions to 'live' or 'finished', lock all its markets
  if new.status in ('live', 'finished') and old.status = 'scheduled' then
    update football.fixture_markets
    set is_locked = true, locked_at = now()
    where fixture_id = new.id
      and is_locked = false;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "football"."auto_lock_fixture_markets"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "football"."award_prediction_fet"("p_prediction_id" "uuid", "p_user_id" "uuid", "p_club_id" bigint, "p_amount" integer, "p_fixture_id" "uuid", "p_market_slug" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'football'
    AS $$
declare
  v_membership public.fan_memberships;
  v_existing public.fet_wallet_ledger_entries;
  v_points integer := greatest(coalesce(p_amount, 0), 0);
  v_idempotency_key text := 'prediction-win:' || p_prediction_id::text;
begin
  if p_prediction_id is null or p_user_id is null or p_club_id is null or v_points <= 0 then
    return false;
  end if;

  select entry.*
    into v_existing
  from public.fet_wallet_ledger_entries entry
  where entry.club_id = p_club_id
    and entry.user_id = p_user_id
    and entry.idempotency_key = v_idempotency_key
  order by entry.created_at desc, entry.id desc
  limit 1;

  if v_existing.id is not null then
    return false;
  end if;

  insert into public.fan_memberships (
    user_id,
    club_id,
    partner_id,
    points,
    tier
  )
  values (
    p_user_id,
    p_club_id,
    public.fet_wallet_resolve_partner_id(p_club_id, p_club_id::text),
    v_points,
    public.resolve_fan_tier(v_points)
  )
  on conflict (user_id, club_id)
  do update set
    points = public.fan_memberships.points + v_points,
    tier = public.resolve_fan_tier(public.fan_memberships.points + v_points),
    renewed_at = timezone('utc', now()),
    updated_at = timezone('utc', now())
  returning * into v_membership;

  insert into public.xp_events (
    user_id,
    club_id,
    event_type,
    xp_awarded,
    metadata,
    event_at
  )
  select
    p_user_id,
    p_club_id,
    'prediction_win',
    v_points,
    jsonb_build_object(
      'prediction_id', p_prediction_id,
      'fixture_id', p_fixture_id,
      'market_slug', p_market_slug,
      'source', 'prediction_settlement'
    ),
    timezone('utc', now())
  where not exists (
    select 1
    from public.xp_events event
    where event.user_id = p_user_id
      and event.event_type = 'prediction_win'
      and event.metadata ->> 'prediction_id' = p_prediction_id::text
  );

  perform public.fet_wallet_append_entry(
    p_club_id := p_club_id,
    p_user_id := p_user_id,
    p_membership_id := v_membership.id,
    p_entry_type := 'earn',
    p_direction := 'credit',
    p_amount := v_points,
    p_balance_after := v_membership.points,
    p_counterparty_user_id := null,
    p_reference_type := 'prediction',
    p_reference_id := p_prediction_id::text,
    p_idempotency_key := v_idempotency_key,
    p_note := 'prediction_win',
    p_metadata := jsonb_build_object(
      'prediction_id', p_prediction_id,
      'fixture_id', p_fixture_id,
      'market_slug', p_market_slug,
      'source', 'prediction_settlement'
    ),
    p_created_by := auth.uid()
  );

  return true;
end;
$$;


ALTER FUNCTION "football"."award_prediction_fet"("p_prediction_id" "uuid", "p_user_id" "uuid", "p_club_id" bigint, "p_amount" integer, "p_fixture_id" "uuid", "p_market_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "football"."generate_fixture_markets"("p_fixture_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'football'
    AS $$
DECLARE
  v_count integer := 0;
  v_market record;
BEGIN
  -- Iterate over all active prediction markets
  FOR v_market IN
    SELECT id, outcome_template, default_fet_value
    FROM football.prediction_markets
    WHERE is_active = true
  LOOP
    -- Skip if already exists (idempotent)
    INSERT INTO football.fixture_markets (fixture_id, market_id, outcomes)
    VALUES (p_fixture_id, v_market.id, v_market.outcome_template)
    ON CONFLICT (fixture_id, market_id) DO NOTHING;

    IF FOUND THEN
      v_count := v_count + 1;
    END IF;
  END LOOP;

  RETURN v_count;
END;
$$;


ALTER FUNCTION "football"."generate_fixture_markets"("p_fixture_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "football"."generate_fixture_markets"("p_fixture_id" "uuid") IS 'Auto-creates fixture_markets for all active prediction_markets. Idempotent.';



