ALTER FUNCTION "football"."update_fixture_market_odds"("p_fixture_market_id" "uuid", "p_outcomes" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "football"."update_fixture_market_odds"("p_fixture_market_id" "uuid", "p_outcomes" "jsonb") IS 'Updates the outcomes JSONB (with odds) for a specific fixture_market.';



CREATE OR REPLACE FUNCTION "football"."update_fixture_odds_batch"("p_fixture_id" "uuid", "p_market_odds" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'football'
    AS $$
DECLARE
  v_entry jsonb;
  v_market_slug text;
  v_outcomes jsonb;
  v_updated integer := 0;
BEGIN
  -- p_market_odds is an array of { market_slug, outcomes }
  FOR v_entry IN SELECT * FROM jsonb_array_elements(p_market_odds)
  LOOP
    v_market_slug := v_entry ->> 'market_slug';
    v_outcomes := v_entry -> 'outcomes';

    UPDATE football.fixture_markets fm
    SET outcomes = v_outcomes,
        updated_at = now()
    FROM football.prediction_markets pm
    WHERE fm.market_id = pm.id
      AND fm.fixture_id = p_fixture_id
      AND pm.slug = v_market_slug;

    IF FOUND THEN
      v_updated := v_updated + 1;
    END IF;
  END LOOP;

  RETURN v_updated;
END;
$$;


ALTER FUNCTION "football"."update_fixture_odds_batch"("p_fixture_id" "uuid", "p_market_odds" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "football"."update_fixture_odds_batch"("p_fixture_id" "uuid", "p_market_odds" "jsonb") IS 'Batch-updates odds for all markets of a fixture.';


