    CONSTRAINT "fan_memberships_tier_check" CHECK (("tier" = ANY (ARRAY['fan'::"text", 'bronze'::"text", 'silver'::"text", 'gold'::"text", 'platinum'::"text", 'imena'::"text", 'inyamibwa'::"text", 'ingenzi-imanzi'::"text"])))
);


