CREATE OR REPLACE FUNCTION "public"."activate_referral_invite_for_user"("p_referral_invite_id" "uuid", "p_invitee_id" "uuid", "p_qualifying_event_type" "text", "p_qualifying_event_id" "text", "p_inviter_points" integer DEFAULT 0, "p_invitee_points" integer DEFAULT 0) RETURNS boolean
