CREATE OR REPLACE FUNCTION "public"."admin_acknowledge_momo_sms_sender_inventory"("p_sender_token" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS TABLE("sender_token" "text", "resolution_status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_sender_token text;
  v_sender_display text;
  v_note text;
  v_now timestamptz := now();
  v_approved_sender_tokens constant text[] := array[
    'mmoney',
    'mmoneyalerts',
    'mobilemoney',
    'momo',
    'momoalerts',
    'mtnmomo',
    'mtnmomorwanda'
  ];
begin
  if not public.is_admin() then
    raise exception 'Admin privileges required';
  end if;

  v_sender_token := regexp_replace(
    lower(coalesce(p_sender_token, '')),
    '[^a-z0-9]+',
    '',
    'g'
  );

  if v_sender_token = '' then
    raise exception 'Sender token is required.';
  end if;

  if v_sender_token = any(v_approved_sender_tokens) then
    raise exception 'Approved sender tokens cannot be acknowledged as legacy unsupported senders.';
  end if;

  select btrim(raw.sender)
  into v_sender_display
  from public.momo_sms_raw raw
  where regexp_replace(
    lower(coalesce(raw.sender, '')),
    '[^a-z0-9]+',
    '',
    'g'
  ) = v_sender_token
  order by raw.sms_received_at desc, raw.created_at desc, raw.id desc
  limit 1;

  if not found then
    raise exception 'Unsupported sender backlog was not found.';
  end if;

  v_note := coalesce(
    nullif(btrim(p_note), ''),
    'Admin acknowledged this unsupported sender as legacy raw SMS history. The sender remains unapproved and stays excluded from active intake policies.'
  );

  insert into public.momo_sms_sender_inventory_resolutions as resolution (
    sender_token,
    sender_display,
    resolution_status,
    resolution_note,
    resolved_by,
    resolved_at,
    created_at,
    updated_at
  )
  values (
    v_sender_token,
    v_sender_display,
    'acknowledged_legacy',
    v_note,
    auth.uid(),
    v_now,
    v_now,
    v_now
  )
  on conflict on constraint momo_sms_sender_inventory_resolutions_pkey do update
  set
    sender_display = excluded.sender_display,
    resolution_status = excluded.resolution_status,
    resolution_note = excluded.resolution_note,
    resolved_by = excluded.resolved_by,
    resolved_at = excluded.resolved_at,
    updated_at = excluded.updated_at;

  return query
  select v_sender_token, 'acknowledged_legacy'::text;
end;
$$;


ALTER FUNCTION "public"."admin_acknowledge_momo_sms_sender_inventory"("p_sender_token" "text", "p_note" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_acknowledge_momo_sms_sender_inventory"("p_sender_token" "text", "p_note" "text") IS 'Admin-only operation that marks an unsupported M-Money SMS sender as acknowledged legacy history without altering the raw SMS records.';



CREATE OR REPLACE FUNCTION "public"."admin_acknowledge_momo_sms_sender_inventory_batch"("p_sender_tokens" "text"[], "p_note" "text" DEFAULT NULL::"text") RETURNS TABLE("acknowledged_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_note text;
  v_now timestamptz := now();
  v_approved_sender_tokens constant text[] := array[
    'mmoney',
    'mmoneyalerts',
    'mobilemoney',
    'momo',
    'momoalerts',
    'mtnmomo',
    'mtnmomorwanda'
  ];
begin
  if not public.is_admin() then
    raise exception 'Admin privileges required';
  end if;

  if coalesce(array_length(p_sender_tokens, 1), 0) = 0 then
    return query
    select 0::integer;
    return;
  end if;

  v_note := coalesce(
    nullif(btrim(p_note), ''),
    'Admin acknowledged this unsupported sender as legacy raw SMS history. The sender remains unapproved and stays excluded from active intake policies.'
  );

  return query
  with normalized_tokens as (
    select distinct regexp_replace(
      lower(coalesce(raw_token, '')),
      '[^a-z0-9]+',
      '',
      'g'
    ) as sender_token
    from unnest(p_sender_tokens) as raw_token
  ),
  eligible_tokens as (
    select nt.sender_token
    from normalized_tokens nt
    where nt.sender_token <> ''
      and not (nt.sender_token = any(v_approved_sender_tokens))
  ),
  source_rows as (
    select
      et.sender_token,
      (
        select btrim(raw.sender)
        from public.momo_sms_raw raw
        where regexp_replace(
          lower(coalesce(raw.sender, '')),
          '[^a-z0-9]+',
          '',
          'g'
        ) = et.sender_token
        order by raw.sms_received_at desc, raw.created_at desc, raw.id desc
        limit 1
      ) as sender_display
    from eligible_tokens et
  ),
  resolved_rows as (
    select
      sr.sender_token,
      sr.sender_display
    from source_rows sr
    where sr.sender_display is not null
  ),
  upserted as (
    insert into public.momo_sms_sender_inventory_resolutions as resolution (
      sender_token,
      sender_display,
      resolution_status,
      resolution_note,
      resolved_by,
      resolved_at,
      created_at,
      updated_at
    )
    select
      rr.sender_token,
      rr.sender_display,
      'acknowledged_legacy',
      v_note,
      auth.uid(),
      v_now,
      v_now,
      v_now
    from resolved_rows rr
    on conflict on constraint momo_sms_sender_inventory_resolutions_pkey do update
    set
      sender_display = excluded.sender_display,
      resolution_status = excluded.resolution_status,
      resolution_note = excluded.resolution_note,
      resolved_by = excluded.resolved_by,
      resolved_at = excluded.resolved_at,
      updated_at = excluded.updated_at
    returning resolution.sender_token
  )
  select count(*)::integer
  from upserted;
end;
$$;


ALTER FUNCTION "public"."admin_acknowledge_momo_sms_sender_inventory_batch"("p_sender_tokens" "text"[], "p_note" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_acknowledge_momo_sms_sender_inventory_batch"("p_sender_tokens" "text"[], "p_note" "text") IS 'Admin-only batch operation that marks unsupported M-Money SMS senders as acknowledged legacy history without altering raw SMS records.';



CREATE OR REPLACE FUNCTION "public"."admin_bulk_update_ticket_status"("p_ticket_ids" "uuid"[], "p_status" "text", "p_club_id" bigint, "p_actor_id" "uuid", "p_role" "text", "p_is_super_admin" boolean DEFAULT false) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_requested_count integer;
  v_matched_count integer;
  v_action text;
begin
  v_requested_count := coalesce(cardinality(p_ticket_ids), 0);

  if v_requested_count < 1 or v_requested_count > 100 then
    raise exception 'Select between 1 and 100 ticket records.';
  end if;

  if p_actor_id is null then
    raise exception 'An authenticated audit actor is required.';
  end if;

  if (
    select count(distinct ticket_id)
    from unnest(p_ticket_ids) as ticket_id
  ) <> v_requested_count then
    raise exception 'Duplicate ticket identifiers are not allowed.';
  end if;

  if p_status not in ('valid', 'used', 'cancelled') then
    raise exception 'Unsupported ticket status action.';
  end if;

  if not coalesce(p_is_super_admin, false)
     and coalesce(p_role, '') not in ('super_admin', 'admin', 'club_admin', 'club_moderator') then
    raise exception 'Your role cannot operate ticket status changes.';
  end if;

  if p_status = 'cancelled'
     and not coalesce(p_is_super_admin, false)
     and coalesce(p_role, '') not in ('super_admin', 'admin', 'club_admin') then
    raise exception 'Ticket cancellation requires club-admin authority.';
  end if;

  select count(*)
    into v_matched_count
    from public.tickets
   where id = any(p_ticket_ids)
     and club_id = p_club_id;

  if v_matched_count <> v_requested_count then
    raise exception 'One or more tickets are missing or outside the active club.';
  end if;

  if exists (
    select 1
      from public.tickets
     where id = any(p_ticket_ids)
       and club_id = p_club_id
       and not (
         (status = 'pending' and p_status in ('valid', 'cancelled'))
         or (status = 'valid' and p_status in ('used', 'cancelled'))
       )
  ) then
    raise exception 'One or more selected tickets have a stale or invalid status transition.';
  end if;

  v_action := case
    when v_requested_count = 1 then 'ticket_status_update'
    else 'bulk_ticket_status_update'
  end;

  insert into public.admin_audit_log (
    actor_id,
    user_id,
    action,
    target_table,
    target_id,
    old_data,
    new_data,
    club_id,
    entity_type,
    entity_id,
    metadata
  )
  select
    p_actor_id,
    p_actor_id,
    v_action,
    'tickets',
    ticket.id::text,
    jsonb_build_object('status', ticket.status),
    jsonb_build_object('status', p_status),
    p_club_id,
    'ticket',
    ticket.id::text,
    jsonb_build_object(
      'scope', 'active_club',
      'selection_count', v_requested_count,
      'source', 'admin_ticket_queue'
    )
  from public.tickets as ticket
  where ticket.id = any(p_ticket_ids)
    and ticket.club_id = p_club_id;

  update public.tickets
     set status = p_status
   where id = any(p_ticket_ids)
     and club_id = p_club_id;

  return v_requested_count;
end;
$$;


ALTER FUNCTION "public"."admin_bulk_update_ticket_status"("p_ticket_ids" "uuid"[], "p_status" "text", "p_club_id" bigint, "p_actor_id" "uuid", "p_role" "text", "p_is_super_admin" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_bulk_update_ticket_status_if_unchanged"("p_ticket_ids" "uuid"[], "p_expected_updated_ats" timestamp with time zone[], "p_status" "text", "p_club_id" bigint, "p_actor_id" "uuid", "p_role" "text", "p_is_super_admin" boolean DEFAULT false) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_requested_count integer := coalesce(pg_catalog.cardinality(p_ticket_ids), 0);
  v_expected_count integer := coalesce(
    pg_catalog.cardinality(p_expected_updated_ats),
    0
  );
  v_matched_count integer;
  v_action text;
  v_previous public.tickets;
  v_updated public.tickets;
begin
  if v_requested_count < 1 or v_requested_count > 100 then
    raise exception 'Select between 1 and 100 ticket records.';
  end if;

  if v_expected_count <> v_requested_count then
    raise exception 'Every selected ticket requires its loaded version.';
  end if;

  if p_actor_id is null then
    raise exception 'An authenticated audit actor is required.';
  end if;

  if p_club_id is null then
    raise exception 'An active club is required.';
  end if;

  if exists (
    select 1
      from pg_catalog.unnest(p_ticket_ids) with ordinality
        as requested(ticket_id, position)
      join pg_catalog.unnest(p_expected_updated_ats) with ordinality
        as expected(expected_updated_at, position)
        using (position)
     where requested.ticket_id is null
        or expected.expected_updated_at is null
  ) then
    raise exception 'Ticket ids and loaded versions are required.';
  end if;

  if (
    select pg_catalog.count(distinct requested.ticket_id)
      from pg_catalog.unnest(p_ticket_ids) as requested(ticket_id)
  ) <> v_requested_count then
    raise exception 'Duplicate ticket identifiers are not allowed.';
  end if;

  if p_status not in ('valid', 'used', 'cancelled') then
    raise exception 'Unsupported ticket status action.';
  end if;

  if not coalesce(p_is_super_admin, false)
     and coalesce(p_role, '') not in (
       'super_admin',
       'admin',
       'club_admin',
       'club_moderator'
     ) then
    raise exception 'Your role cannot operate ticket status changes.';
  end if;

  if p_status = 'cancelled'
     and not coalesce(p_is_super_admin, false)
     and coalesce(p_role, '') not in (
       'super_admin',
       'admin',
       'club_admin'
     ) then
    raise exception 'Ticket cancellation requires club-admin authority.';
  end if;

  -- Deterministic lock order prevents two overlapping bulk selections from
  -- deadlocking while preserving the all-or-nothing review contract.
  perform 1
    from public.tickets as ticket
   where ticket.id = any(p_ticket_ids)
     and ticket.club_id = p_club_id
   order by ticket.id
   for update;

  select pg_catalog.count(*)::integer
    into v_matched_count
    from public.tickets as ticket
   where ticket.id = any(p_ticket_ids)
     and ticket.club_id = p_club_id;

  if v_matched_count <> v_requested_count then
    raise exception 'One or more tickets are missing or outside the active club.';
  end if;

  if exists (
    select 1
      from pg_catalog.unnest(p_ticket_ids) with ordinality
        as requested(ticket_id, position)
      join pg_catalog.unnest(p_expected_updated_ats) with ordinality
        as expected(expected_updated_at, position)
        using (position)
      join public.tickets as ticket
        on ticket.id = requested.ticket_id
       and ticket.club_id = p_club_id
     where ticket.updated_at is distinct from expected.expected_updated_at
  ) then
    raise exception
      'One or more tickets changed after they were loaded. Refresh the ticket queue and review before retrying.';
  end if;

  if exists (
    select 1
      from public.tickets as ticket
     where ticket.id = any(p_ticket_ids)
       and ticket.club_id = p_club_id
       and not (
         (ticket.status = 'pending' and p_status in ('valid', 'cancelled'))
         or (ticket.status = 'valid' and p_status in ('used', 'cancelled'))
       )
  ) then
    raise exception 'One or more selected tickets have an invalid status transition.';
  end if;

  v_action := case
    when v_requested_count = 1 then 'ticket_status_update'
    else 'bulk_ticket_status_update'
  end;

  for v_previous in
    select ticket.*
      from public.tickets as ticket
     where ticket.id = any(p_ticket_ids)
       and ticket.club_id = p_club_id
     order by ticket.id
  loop
    update public.tickets as ticket
       set status = p_status
     where ticket.id = v_previous.id
    returning ticket.* into v_updated;

    insert into public.admin_audit_log (
      actor_id,
      user_id,
      action,
      target_table,
      target_id,
      old_data,
      new_data,
      club_id,
      entity_type,
      entity_id,
      metadata
    ) values (
      p_actor_id,
      p_actor_id,
      v_action,
      'tickets',
      v_updated.id::text,
      pg_catalog.jsonb_build_object(
        'status', v_previous.status,
        'updated_at', v_previous.updated_at
      ),
      pg_catalog.jsonb_build_object(
        'status', v_updated.status,
        'updated_at', v_updated.updated_at
      ),
      p_club_id,
      'ticket',
      v_updated.id::text,
      pg_catalog.jsonb_build_object(
        'scope', 'active_club',
        'selection_count', v_requested_count,
        'source', 'admin_ticket_queue',
        'optimistic_concurrency', true
      )
    );
  end loop;

  return v_requested_count;
end;
$$;


ALTER FUNCTION "public"."admin_bulk_update_ticket_status_if_unchanged"("p_ticket_ids" "uuid"[], "p_expected_updated_ats" timestamp with time zone[], "p_status" "text", "p_club_id" bigint, "p_actor_id" "uuid", "p_role" "text", "p_is_super_admin" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_delete_mutable_record_if_unchanged"("p_table_name" "text", "p_record_id" "text", "p_expected_updated_at" timestamp with time zone, "p_actor_id" "uuid", "p_club_id" bigint DEFAULT NULL::bigint, "p_enforce_club_scope" boolean DEFAULT false, "p_requires_platform_admin" boolean DEFAULT false, "p_action" "text" DEFAULT 'delete'::"text", "p_source" "text" DEFAULT 'admin_workspace'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_allowed_tables constant text[] := array[
    'ai_content',
    'club_app_config',
    'club_players',
    'club_standings',
    'contribution_groups',
    'fan_clubs',
    'fan_engagement_token_catalog',
    'fet_partner_offers',
    'groups',
    'home_banners',
    'league_standings',
    'livescore_competition_sources',
    'matches',
    'membership_tiers',
    'news_articles',
    'players',
    'platform_content_blocks',
    'platform_option_sets',
    'platform_option_values',
    'platform_route_registry',
    'rs_news_articles',
    'rs_shop_products',
    'rs_squad_players',
    'rs_standings',
    'runtime_copy',
    'shop_products',
    'site_navigation_items',
    'site_search_items',
    'squad_players',
    'standings',
    'venue_governance_controls'
  ];
  v_is_platform_admin boolean := false;
  v_is_club_admin boolean := false;
  v_deleted jsonb;
  v_sql text;
begin
  if p_table_name is null or not (p_table_name = any(v_allowed_tables)) then
    raise exception 'Table is not approved for governed admin deletion.';
  end if;

  if p_record_id is null or btrim(p_record_id) = '' then
    raise exception 'A record id is required.';
  end if;

  if p_expected_updated_at is null then
    raise exception
      'This record has no loaded version. Refresh the latest data before deleting it.';
  end if;

  if p_actor_id is null then
    raise exception 'An authenticated audit actor is required.';
  end if;

  select exists (
    select 1
    from public.admin_role_assignments assignment
    where assignment.user_id = p_actor_id
      and assignment.is_active = true
      and assignment.revoked_at is null
      and assignment.role in ('super_admin', 'admin')
  )
  into v_is_platform_admin;

  select exists (
    select 1
    from public.admin_role_assignments assignment
    where assignment.user_id = p_actor_id
      and assignment.is_active = true
      and assignment.revoked_at is null
      and assignment.role = 'club_admin'
      and p_club_id is not null
      and assignment.club_id = p_club_id
  )
  into v_is_club_admin;

  if p_requires_platform_admin and not v_is_platform_admin then
    raise exception 'Platform admin access is required for this deletion.';
  end if;

  if not p_requires_platform_admin
     and not v_is_platform_admin
     and not v_is_club_admin then
    raise exception 'Club-admin access is required for this deletion.';
  end if;

  if p_enforce_club_scope and p_club_id is null then
    raise exception 'An active club scope is required for this deletion.';
  end if;

  v_sql := format(
    'delete from public.%I
       where id::text = $1
         and updated_at = $2',
    p_table_name
  );

  if p_enforce_club_scope then
    v_sql := v_sql || ' and club_id = $3';
  end if;

  v_sql := v_sql || ' returning to_jsonb(' || quote_ident(p_table_name) || '.*)';

  if p_enforce_club_scope then
    execute v_sql
      into v_deleted
      using p_record_id, p_expected_updated_at, p_club_id;
  else
    execute v_sql
      into v_deleted
      using p_record_id, p_expected_updated_at;
  end if;

  if v_deleted is null then
    raise exception
      'Record changed after it was loaded or is outside the active admin scope. Refresh and review before retrying.';
  end if;

  insert into public.admin_audit_log (
    actor_id,
    user_id,
    action,
    target_table,
    target_id,
    old_data,
    club_id,
    entity_type,
    entity_id,
    metadata
  )
  values (
    p_actor_id,
    p_actor_id,
    coalesce(nullif(btrim(p_action), ''), 'delete'),
    p_table_name,
    p_record_id,
    v_deleted,
    p_club_id,
    p_table_name,
    p_record_id,
    jsonb_build_object(
      'scope',
      case
        when p_enforce_club_scope then 'active_club'
        when p_requires_platform_admin then 'platform'
        else 'authorized_admin'
      end,
      'source',
      coalesce(nullif(btrim(p_source), ''), 'admin_workspace'),
      'undo',
      'not_available'
    )
  );

  return v_deleted;
end;
$_$;


ALTER FUNCTION "public"."admin_delete_mutable_record_if_unchanged"("p_table_name" "text", "p_record_id" "text", "p_expected_updated_at" timestamp with time zone, "p_actor_id" "uuid", "p_club_id" bigint, "p_enforce_club_scope" boolean, "p_requires_platform_admin" boolean, "p_action" "text", "p_source" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_delete_mutable_record_if_unchanged"("p_table_name" "text", "p_record_id" "text", "p_expected_updated_at" timestamp with time zone, "p_actor_id" "uuid", "p_club_id" bigint, "p_enforce_club_scope" boolean, "p_requires_platform_admin" boolean, "p_action" "text", "p_source" "text") IS 'Atomically re-validates the resolved admin actor, deletes a whitelisted mutable record at its loaded version and scope, and records immutable audit evidence.';



CREATE OR REPLACE FUNCTION "public"."admin_get_shop_products"("p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0, "p_include_inactive" boolean DEFAULT true) RETURNS TABLE("id" "uuid", "partner_id" "uuid", "club_id" bigint, "name" "text", "subtitle" "text", "description" "text", "category" "text", "price" numeric, "stock" integer, "is_active" boolean, "is_new" boolean, "image_url" "text", "sizes" "jsonb", "available_sizes" "text"[], "badge_label" "text", "collection" "text", "sort_order" integer, "product_id" "text", "product_type" "text", "currency" "text", "image_rights_approved" boolean, "image_provenance_id" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_club_id bigint;
begin
  if auth.uid() is null then
    raise exception 'An authenticated club administrator is required.';
  end if;

  if p_limit < 1 or p_limit > 100 or p_offset < 0 then
    raise exception 'Product page bounds are invalid.';
  end if;

  begin
    v_club_id := nullif(public.requesting_club_id(), '')::bigint;
  exception
    when invalid_text_representation then
      raise exception 'A valid trusted club scope is required.';
  end;

  if v_club_id is null or not public.is_club_admin(v_club_id) then
    raise exception 'Club administrator permission is required.';
  end if;

  return query
  select
    product.id,
    product.partner_id,
    product.club_id,
    product.name,
    product.subtitle,
    product.description,
    product.category,
    product.price,
    product.stock,
    product.is_active,
    product.is_new,
    product.image_url,
    product.sizes,
    product.available_sizes,
    product.badge_label,
    product.collection,
    product.sort_order,
    product.product_id,
    product.product_type,
    product.currency,
    product.image_rights_approved,
    product.image_provenance_id,
    product.created_at,
    product.updated_at
  from public.shop_products as product
  where product.club_id = v_club_id
    and (p_include_inactive or product.is_active)
  order by product.sort_order, product.name, product.id
  limit p_limit
  offset p_offset;
end;
$$;


ALTER FUNCTION "public"."admin_get_shop_products"("p_limit" integer, "p_offset" integer, "p_include_inactive" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_reject_momo_sms_manual_review"("p_review_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS TABLE("review_id" "uuid", "match_status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_review public.momo_reconciliations%rowtype;
  v_parsed public.momo_sms_parsed%rowtype;
  v_pra public.payment_receiver_accounts%rowtype;
  v_note text;
  v_now timestamptz := now();
begin
  if p_review_id is null then
    raise exception 'Review id is required.';
  end if;

  select *
  into v_review
  from public.momo_reconciliations mr
  where mr.id = p_review_id
  for update;

  if not found then
    raise exception 'Manual review allocation was not found.';
  end if;

  if v_review.match_status not in ('pending_review', 'manual_review') then
    raise exception 'Only pending or manual-review reconciliations can be closed.';
  end if;

  select *
  into v_parsed
  from public.momo_sms_parsed
  where id = v_review.parsed_sms_id;

  select *
  into v_pra
  from public.payment_receiver_accounts
  where payee_number_or_code = v_parsed.payee_number_or_code;

  if not (
    public.user_has_admin_workspace_access(
      coalesce(v_parsed.club_id, v_review.club_id),
      v_pra.partner_id
    )
    or v_pra.owner_user_id = auth.uid()
  ) then
    raise exception 'Admin or account owner privileges required.';
  end if;

  v_note := coalesce(
    nullif(btrim(p_note), ''),
    'Review rejected because it does not map to an app payment target.'
  );

  update public.momo_reconciliations
  set
    target_table = null,
    target_record_id = null,
    match_type = 'manual_rejection',
    match_status = 'rejected',
    notes = v_note,
    metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
      'manual_rejection', true,
      'manual_rejection_actor_id', auth.uid(),
      'manual_rejection_source', 'custodian_operations',
      'manual_rejection_reason', 'not_app_linked',
      'rejected_at', v_now
    ),
    reconciled_at = null,
    updated_at = v_now
  where id = v_review.id;

  update public.momo_ledger_entries
  set
    target_table = null,
    target_record_id = null,
    ledger_status = 'draft',
    metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
      'manual_rejection', true,
      'manual_rejection_actor_id', auth.uid(),
      'manual_rejection_source', 'custodian_operations',
      'manual_rejection_reason', 'not_app_linked',
      'rejected_at', v_now
    ),
    updated_at = v_now
  where parsed_sms_id = v_review.parsed_sms_id;

  return query
  select v_review.id, 'rejected'::text;
end;
$$;


ALTER FUNCTION "public"."admin_reject_momo_sms_manual_review"("p_review_id" "uuid", "p_note" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_reject_momo_sms_manual_review"("p_review_id" "uuid", "p_note" "text") IS 'Admin-only operation that closes a generic M-Money SMS manual review as not app-linked without deleting the underlying wallet history.';



CREATE OR REPLACE FUNCTION "public"."admin_reject_momo_sms_manual_review_batch"("p_review_ids" "uuid"[], "p_note" "text" DEFAULT NULL::"text") RETURNS TABLE("rejected_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_now timestamptz := now();
  v_note text;
begin
  if coalesce(array_length(p_review_ids, 1), 0) = 0 then
    return query
    select 0::integer;
    return;
  end if;

  v_note := coalesce(
    nullif(btrim(p_note), ''),
    'Review rejected because it does not map to an app payment target.'
  );

  return query
  with input_ids as (
    select distinct rid as review_id
    from unnest(p_review_ids) as rid
    where rid is not null
  ),
  eligible_reviews as (
    select mr.id, mr.parsed_sms_id
    from public.momo_reconciliations mr
    join input_ids ids
      on ids.review_id = mr.id
    join public.momo_sms_parsed parsed
      on parsed.id = mr.parsed_sms_id
    left join public.payment_receiver_accounts pra
      on pra.payee_number_or_code = parsed.payee_number_or_code
    where mr.match_status in ('pending_review', 'manual_review')
      and (
        public.user_has_admin_workspace_access(
          coalesce(parsed.club_id, mr.club_id),
          pra.partner_id
        )
        or pra.owner_user_id = auth.uid()
      )
    for update of mr
  ),
  updated_reviews as (
    update public.momo_reconciliations mr
    set
      target_table = null,
      target_record_id = null,
      match_type = 'manual_rejection',
      match_status = 'rejected',
      notes = v_note,
      metadata = coalesce(mr.metadata, '{}'::jsonb) || jsonb_build_object(
        'manual_rejection', true,
        'manual_rejection_actor_id', auth.uid(),
        'manual_rejection_source', 'custodian_operations',
        'manual_rejection_reason', 'not_app_linked',
        'rejected_at', v_now
      ),
      reconciled_at = null,
      updated_at = v_now
    from eligible_reviews er
    where mr.id = er.id
    returning er.parsed_sms_id
  ),
  updated_ledger as (
    update public.momo_ledger_entries ledger
    set
      target_table = null,
      target_record_id = null,
      ledger_status = 'draft',
      metadata = coalesce(ledger.metadata, '{}'::jsonb) || jsonb_build_object(
        'manual_rejection', true,
        'manual_rejection_actor_id', auth.uid(),
        'manual_rejection_source', 'custodian_operations',
        'manual_rejection_reason', 'not_app_linked',
        'rejected_at', v_now
      ),
      updated_at = v_now
    where ledger.parsed_sms_id in (
      select parsed_sms_id
      from updated_reviews
    )
    returning ledger.id
  )
  select count(*)::integer
  from updated_reviews;
end;
$$;


ALTER FUNCTION "public"."admin_reject_momo_sms_manual_review_batch"("p_review_ids" "uuid"[], "p_note" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_reject_momo_sms_manual_review_batch"("p_review_ids" "uuid"[], "p_note" "text") IS 'Admin-only batch operation that closes generic M-Money SMS manual reviews as not app-linked.';



CREATE TABLE IF NOT EXISTS "public"."group_contributions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "group_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "amount" integer DEFAULT 0 NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "momo_reference" "text",
    "is_mock" boolean DEFAULT false NOT NULL,
    "mock_batch" "text",
    "payment_status" "public"."payment_status" DEFAULT 'pending_verification'::"public"."payment_status" NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    "confirmed_at" timestamp with time zone,
    "client_request_reference" "text",
    "idempotency_key" "text",
    "reconciled_ledger_entry_id" "uuid",
    "reconciliation_id" "uuid",
    "reconciliation_idempotency_key" "text",
    "reconciled_by" "uuid",
    CONSTRAINT "group_contributions_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'confirmed'::"text", 'failed'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "public"."group_contributions" OWNER TO "postgres";


COMMENT ON COLUMN "public"."group_contributions"."is_mock" IS 'Internal-only marker for removable demo seed rows. Not intended for customer-facing UI.';



COMMENT ON COLUMN "public"."group_contributions"."mock_batch" IS 'Internal batch key used to identify and bulk remove demo seed rows.';



CREATE OR REPLACE FUNCTION "public"."admin_review_group_contribution_if_unchanged"("p_contribution_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_status" "text", "p_club_id" bigint, "p_actor_id" "uuid", "p_role" "text", "p_is_super_admin" boolean DEFAULT false) RETURNS "public"."group_contributions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_contribution public.group_contributions;
  v_previous public.group_contributions;
begin
  if p_contribution_id is null or p_expected_updated_at is null then
    raise exception 'Contribution id and loaded version are required.';
  end if;

  if p_actor_id is null then
    raise exception 'An authenticated audit actor is required.';
  end if;

  if not coalesce(p_is_super_admin, false)
     and coalesce(p_role, '') not in (
       'super_admin',
       'admin',
       'club_admin',
       'club_moderator'
     ) then
    raise exception 'Your role cannot review contributions.';
  end if;

  if p_status not in ('confirmed', 'failed') then
    raise exception 'Unsupported contribution review status.';
  end if;

  select contribution.*
    into v_previous
    from public.group_contributions as contribution
    join public.contribution_groups as contribution_group
      on contribution_group.id = contribution.group_id
   where contribution.id = p_contribution_id
     and contribution_group.club_id = p_club_id;

  if not found then
    raise exception 'Contribution is missing or outside the active club.';
  end if;

  if v_previous.status <> 'pending' then
    raise exception 'Contribution is no longer pending. Refresh the queue.';
  end if;

  update public.group_contributions
     set status = p_status
   where id = p_contribution_id
     and status = 'pending'
     and updated_at = p_expected_updated_at
  returning * into v_contribution;

  if not found then
    raise exception
      'Contribution changed after it was loaded. Refresh the queue and review before retrying.';
  end if;

  insert into public.admin_audit_log (
    actor_id,
    user_id,
    action,
    target_table,
    target_id,
    old_data,
    new_data,
    club_id,
    entity_type,
    entity_id,
    metadata
  )
  values (
    p_actor_id,
    p_actor_id,
    'contribution_status_review',
    'group_contributions',
    v_contribution.id::text,
    jsonb_build_object(
      'status',
      v_previous.status,
      'updated_at',
      v_previous.updated_at
    ),
    jsonb_build_object(
      'status',
      v_contribution.status,
      'updated_at',
      v_contribution.updated_at
    ),
    p_club_id,
    'contribution',
    v_contribution.id::text,
    jsonb_build_object(
      'scope',
      'active_club',
      'source',
      'admin_contribution_queue'
    )
  );

  return v_contribution;
end;
$$;


ALTER FUNCTION "public"."admin_review_group_contribution_if_unchanged"("p_contribution_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_status" "text", "p_club_id" bigint, "p_actor_id" "uuid", "p_role" "text", "p_is_super_admin" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_review_group_contribution_if_unchanged"("p_contribution_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_status" "text", "p_club_id" bigint, "p_actor_id" "uuid", "p_role" "text", "p_is_super_admin" boolean) IS 'Atomically reviews a still-pending contribution at its loaded version and records an immutable admin audit entry.';



CREATE TABLE IF NOT EXISTS "public"."membership_applications" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "club_id" bigint NOT NULL,
    "tier" "text" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text",
    "payment_status" "text" DEFAULT 'unpaid'::"text",
    "application_date" timestamp with time zone DEFAULT "now"() NOT NULL,
    "review_date" timestamp with time zone,
    "reviewer_id" "uuid",
    "notes" "text",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "membership_applications_payment_status_check" CHECK (("payment_status" = ANY (ARRAY['unpaid'::"text", 'paid'::"text", 'failed'::"text"]))),
    CONSTRAINT "membership_applications_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'approved'::"text", 'rejected'::"text"])))
);


ALTER TABLE "public"."membership_applications" OWNER TO "postgres";


COMMENT ON TABLE "public"."membership_applications" IS 'Fan applications for specific membership tiers, requiring admin review or payment verification.';



CREATE OR REPLACE FUNCTION "public"."admin_review_membership_application_if_unchanged"("p_application_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_decision" "text", "p_notes" "text", "p_club_id" bigint, "p_partner_id" "uuid", "p_actor_id" "uuid") RETURNS "public"."membership_applications"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_application public.membership_applications;
  v_previous public.membership_applications;
  v_membership public.fan_memberships;
  v_chapter text;
begin
  if p_decision not in ('approved', 'rejected') then
    raise exception 'Membership review decision must be approved or rejected.';
  end if;

  select *
    into v_previous
    from public.membership_applications
   where id = p_application_id
     and club_id = p_club_id
   for update;

  if not found then
    raise exception 'Membership application is not available in the active club.';
  end if;

  if v_previous.updated_at is distinct from p_expected_updated_at then
    raise exception
      'Membership application changed after it was loaded. Refresh the queue and review before retrying.';
  end if;

  if v_previous.status <> 'pending' then
    raise exception
      'Membership application is no longer pending. Refresh the queue and review before retrying.';
  end if;

  if p_decision = 'approved' and v_previous.payment_status <> 'paid' then
    raise exception 'Only paid membership applications can be approved.';
  end if;

  update public.membership_applications
     set status = p_decision,
         notes = p_notes,
         review_date = now(),
         reviewer_id = p_actor_id
   where id = p_application_id
     and updated_at = p_expected_updated_at
  returning * into v_application;

  if not found then
    raise exception
      'Membership application changed after it was loaded. Refresh the queue and review before retrying.';
  end if;

  if p_decision = 'approved' then
    v_chapter := coalesce(
      nullif(btrim(v_previous.metadata ->> 'chapter'), ''),
      'Central'
    );

    v_membership := public.apply_membership_points(
      v_previous.user_id,
      p_partner_id,
      0,
      v_chapter
    );

    update public.fan_memberships
       set tier = v_previous.tier,
           status = 'active',
           club_id = p_club_id,
           chapter = v_chapter
     where id = v_membership.id;

    if not found then
      raise exception
        'Membership approval did not materialize a supporter membership row.';
    end if;
  end if;

  insert into public.admin_audit_log (
    actor_id,
    user_id,
    action,
    target_table,
    target_id,
    old_data,
    new_data,
    club_id,
    entity_type,
    entity_id,
    metadata
  )
  values (
    p_actor_id,
    p_actor_id,
    'membership_application_review',
    'membership_applications',
    v_application.id::text,
    to_jsonb(v_previous),
    to_jsonb(v_application),
    p_club_id,
    'membership_application',
    v_application.id::text,
    jsonb_build_object(
      'decision',
      p_decision,
      'partner_id',
      p_partner_id,
      'scope',
      'active_club'
    )
  );

  return v_application;
end;
$$;


ALTER FUNCTION "public"."admin_review_membership_application_if_unchanged"("p_application_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_decision" "text", "p_notes" "text", "p_club_id" bigint, "p_partner_id" "uuid", "p_actor_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_review_membership_application_if_unchanged"("p_application_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_decision" "text", "p_notes" "text", "p_club_id" bigint, "p_partner_id" "uuid", "p_actor_id" "uuid") IS 'Atomically reviews a still-pending membership application, materializes paid approvals, and records immutable audit evidence.';



CREATE TABLE IF NOT EXISTS "public"."platform_features" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "feature_key" "text" NOT NULL,
    "display_name" "text" NOT NULL,
    "description" "text",
    "category" "text",
    "club_id" bigint,
    "is_enabled" boolean DEFAULT true NOT NULL,
    "visibility_state" "text" DEFAULT 'visible'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    CONSTRAINT "platform_features_visibility_state_check" CHECK (("visibility_state" = ANY (ARRAY['visible'::"text", 'hidden'::"text", 'maintenance'::"text"])))
);


ALTER TABLE "public"."platform_features" OWNER TO "postgres";


COMMENT ON TABLE "public"."platform_features" IS 'Central feature registry. club_id NULL = global default; specific club_id = override.';



CREATE OR REPLACE FUNCTION "public"."admin_update_platform_feature_if_unchanged"("p_feature_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_club_id" bigint, "p_updates" "jsonb", "p_actor_id" "uuid") RETURNS "public"."platform_features"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_source public.platform_features;
  v_target public.platform_features;
  v_target_id uuid;
  v_channel jsonb;
  v_rules jsonb;
begin
  select *
    into v_source
    from public.platform_features
   where id = p_feature_id
   for update;

  if not found then
    raise exception 'Feature configuration is no longer available.';
  end if;

  if v_source.updated_at is distinct from p_expected_updated_at then
    raise exception
      'Feature configuration changed after it was loaded. Refresh and review before retrying.';
  end if;

  if v_source.club_id is not distinct from p_club_id then
    v_target_id := v_source.id;
  elsif v_source.club_id is null and p_club_id is not null then
    select *
      into v_target
      from public.platform_features
     where feature_key = v_source.feature_key
       and club_id = p_club_id
     for update;

    if found then
      raise exception
        'A scoped override was created after this feature was loaded. Refresh and review before retrying.';
    end if;

    insert into public.platform_features (
      feature_key,
      display_name,
      description,
      category,
      club_id,
      is_enabled,
      visibility_state
    )
    values (
      v_source.feature_key,
      v_source.display_name,
      v_source.description,
      v_source.category,
      p_club_id,
      v_source.is_enabled,
      v_source.visibility_state
    )
    returning id into v_target_id;

    insert into public.platform_feature_channels (
      feature_id,
      channel,
      is_enabled,
      is_visible,
      show_in_navigation,
      show_on_home,
      sort_order,
      route_key,
      placement_key
    )
    select
      v_target_id,
      channel,
      is_enabled,
      is_visible,
      show_in_navigation,
      show_on_home,
      sort_order,
      route_key,
      placement_key
    from public.platform_feature_channels
    where feature_id = v_source.id;

    insert into public.platform_feature_rules (
      feature_id,
      auth_required,
      role_restrictions,
      dependency_rules,
      rollout_rules,
      metadata,
      schedule_start_at,
      schedule_end_at
    )
    select
      v_target_id,
      auth_required,
      role_restrictions,
      dependency_rules,
      rollout_rules,
      metadata,
      schedule_start_at,
      schedule_end_at
    from public.platform_feature_rules
    where feature_id = v_source.id;
  else
    raise exception
      'Feature configuration scope changed after it was loaded. Refresh and review before retrying.';
  end if;

  update public.platform_features
     set display_name = case
           when p_updates ? 'displayName'
             then btrim(p_updates ->> 'displayName')
           else display_name
         end,
         description = case
           when p_updates ? 'description'
             then p_updates ->> 'description'
           else description
         end,
         category = case
           when p_updates ? 'category'
             then p_updates ->> 'category'
           else category
         end,
         is_enabled = case
           when p_updates ? 'isEnabled'
             then (p_updates ->> 'isEnabled')::boolean
           else is_enabled
         end,
         visibility_state = case
           when p_updates ? 'visibilityState'
             then p_updates ->> 'visibilityState'
           else visibility_state
         end
   where id = v_target_id;

  for v_channel in
    select value
      from jsonb_array_elements(
        case
          when jsonb_typeof(p_updates -> 'channels') = 'array'
            then p_updates -> 'channels'
          else '[]'::jsonb
        end
      )
  loop
    if v_channel ->> 'channel' not in ('mobile', 'web') then
      raise exception 'Feature channel must be mobile or web.';
    end if;

    insert into public.platform_feature_channels (
      feature_id,
      channel,
      is_enabled,
      is_visible,
      show_in_navigation,
      show_on_home,
      sort_order,
      route_key,
      placement_key
    )
    values (
      v_target_id,
      v_channel ->> 'channel',
      coalesce((v_channel ->> 'isEnabled')::boolean, true),
      coalesce((v_channel ->> 'isVisible')::boolean, true),
      coalesce((v_channel ->> 'showInNavigation')::boolean, false),
      coalesce((v_channel ->> 'showOnHome')::boolean, false),
      (v_channel ->> 'sortOrder')::integer,
      nullif(btrim(v_channel ->> 'routeKey'), ''),
      nullif(btrim(v_channel ->> 'placementKey'), '')
    )
    on conflict (feature_id, channel)
    do update set
      is_enabled = excluded.is_enabled,
      is_visible = excluded.is_visible,
      show_in_navigation = excluded.show_in_navigation,
      show_on_home = excluded.show_on_home,
      sort_order = excluded.sort_order,
      route_key = excluded.route_key,
      placement_key = excluded.placement_key;
  end loop;

  if p_updates ? 'rules'
     and jsonb_typeof(p_updates -> 'rules') = 'object' then
    v_rules := p_updates -> 'rules';

    insert into public.platform_feature_rules (
      feature_id,
      auth_required,
      role_restrictions,
      dependency_rules,
      rollout_rules,
      metadata,
      schedule_start_at,
      schedule_end_at
    )
    values (
      v_target_id,
      coalesce((v_rules ->> 'authRequired')::boolean, false),
      coalesce(v_rules -> 'roleRestrictions', '[]'::jsonb),
      coalesce(v_rules -> 'dependencyRules', '{}'::jsonb),
      coalesce(v_rules -> 'rolloutRules', '{}'::jsonb),
      coalesce(v_rules -> 'metadata', '{}'::jsonb),
      nullif(v_rules ->> 'scheduleStartAt', '')::timestamptz,
      nullif(v_rules ->> 'scheduleEndAt', '')::timestamptz
    )
    on conflict (feature_id)
    do update set
      auth_required = excluded.auth_required,
      role_restrictions = excluded.role_restrictions,
      dependency_rules = excluded.dependency_rules,
      rollout_rules = excluded.rollout_rules,
      metadata = excluded.metadata,
      schedule_start_at = excluded.schedule_start_at,
      schedule_end_at = excluded.schedule_end_at;
  end if;

  select *
    into v_target
    from public.platform_features
   where id = v_target_id;

  insert into public.admin_audit_log (
    actor_id,
    user_id,
    action,
    target_table,
    target_id,
    old_data,
    new_data,
    club_id,
    entity_type,
    entity_id,
    metadata
  )
  values (
    p_actor_id,
    p_actor_id,
    'platform_feature_update',
    'platform_features',
    v_target.id::text,
    to_jsonb(v_source),
    to_jsonb(v_target),
    p_club_id,
    'platform_feature',
    v_target.id::text,
    jsonb_build_object(
      'source_feature_id',
      v_source.id,
      'copy_on_write',
      v_source.id <> v_target.id,
      'scope',
      case when p_club_id is null then 'global' else 'active_club' end
    )
  );

  return v_target;
end;
$$;


ALTER FUNCTION "public"."admin_update_platform_feature_if_unchanged"("p_feature_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_club_id" bigint, "p_updates" "jsonb", "p_actor_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_update_platform_feature_if_unchanged"("p_feature_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_club_id" bigint, "p_updates" "jsonb", "p_actor_id" "uuid") IS 'Atomically version-checks a feature, creates a scoped override when needed, updates feature/channel/rule state, and records audit evidence.';



