    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN NEW.updated_at = now(); RETURN NEW; END;
$$;


ALTER FUNCTION "public"."ai_content_set_updated_at"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."allocate_momo_manual_review"("p_review_id" "uuid", "p_intent_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS TABLE("review_id" "uuid", "intent_id" "uuid", "matched_reference" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_review public.momo_reconciliations%rowtype;
  v_intent public.payment_intents%rowtype;
  v_amount numeric;
  v_currency text;
  v_tx_datetime timestamptz;
  v_parsed_reference text;
  v_reference text;
  v_note text;
  v_user_id uuid;
  v_now timestamptz := now();
  v_parsed_club_id bigint;
  v_review_partner_id uuid;
  v_review_owner_user_id uuid;
  v_intent_kind text;
begin
  if p_review_id is null then
    raise exception 'Review id is required.';
  end if;

  if p_intent_id is null then
    raise exception 'Intent id is required.';
  end if;

  select *
  into v_review
  from public.momo_reconciliations mr
  where mr.id = p_review_id
  for update;

  if not found then
    raise exception 'Manual review allocation was not found.';
  end if;

  if v_review.match_status not in ('pending_review', 'manual_review') then
    raise exception 'Only pending or manual-review allocations can be resolved.';
  end if;

  select
    parsed.amount,
    parsed.currency,
    coalesce(parsed.tx_datetime, parsed.created_at),
    nullif(parsed.momo_tx_id, ''),
    parsed.user_id,
    parsed.club_id,
    pra.partner_id,
    pra.owner_user_id
  into
    v_amount,
    v_currency,
    v_tx_datetime,
    v_parsed_reference,
    v_user_id,
    v_parsed_club_id,
    v_review_partner_id,
    v_review_owner_user_id
  from public.momo_sms_parsed parsed
  left join public.payment_receiver_accounts pra
    on pra.payee_number_or_code = parsed.payee_number_or_code
  where parsed.id = v_review.parsed_sms_id;

  if not (
    public.user_has_admin_workspace_access(
      coalesce(v_parsed_club_id, v_review.club_id),
      v_review_partner_id
    )
    or v_review_owner_user_id = auth.uid()
  ) then
    raise exception 'Admin or account-owner privileges are required to allocate this review.';
  end if;

  if coalesce(v_amount, 0) <= 0 then
    raise exception 'The reviewed payment does not have a usable amount.';
  end if;

  select *
  into v_intent
  from public.payment_intents pi
  where pi.id = p_intent_id
  for update;

  if not found then
    raise exception 'Payment intent was not found.';
  end if;

  if v_intent.status <> 'pending' then
    raise exception 'Only pending payment intents can be allocated to.';
  end if;

  if v_intent.expected_amount <> v_amount then
    raise exception 'Payment intent expected amount (%) does not match SMS amount (%).', v_intent.expected_amount, v_amount;
  end if;

  v_reference := coalesce(v_parsed_reference, format('MR-%s', v_review.id));
  v_intent_kind := coalesce(nullif(v_intent.target_table, ''), 'payment_intents');

  update public.payment_intents
  set
    status = 'completed',
    updated_at = v_now
  where id = v_intent.id;

  v_note := coalesce(
    nullif(btrim(p_note), ''),
    'Admin manually allocated this payment.'
  );

  update public.momo_reconciliations
  set
    target_table = v_intent_kind,
    target_record_id = coalesce(v_intent.target_record_id, v_intent.id),
    match_type = format('admin_manual_allocation_to_%s', v_intent_kind),
    match_status = 'matched',
    notes = v_note,
    metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
      'manual_allocation', true,
      'intent_id', p_intent_id,
      'matched_reference', v_reference,
      'allocation_actor_id', auth.uid(),
      'allocation_source', 'admin_operations'
    ),
    reconciled_at = v_now,
    updated_at = v_now
  where id = v_review.id;

  insert into public.momo_ledger_entries (
    parsed_sms_id,
    user_id,
    entry_type,
    ledger_scope,
    ledger_status,
    amount,
    currency,
    tx_datetime,
    external_reference,
    target_table,
    target_record_id,
    description,
    metadata,
    created_at,
    updated_at
  ) values (
    v_review.parsed_sms_id,
    v_user_id,
    case when coalesce(v_amount, 0) >= 0 then 'credit' else 'debit' end,
    case
      when v_intent_kind in ('group_contributions', 'contribution_groups', 'groups') then 'group'
      when v_intent_kind in ('subscriptions', 'membership_applications', 'membership_tiers') then 'subscription'
      when v_intent_kind in ('shop_orders', 'orders', 'partners') then 'partner'
      when v_intent_kind in ('tickets', 'matches') then 'ticket'
      else 'wallet'
    end,
    'posted',
    v_amount,
    coalesce(v_currency, 'RWF'),
    coalesce(v_tx_datetime, v_now),
    v_reference,
    v_intent_kind,
    coalesce(v_intent.target_record_id, v_intent.id),
    'Manual allocation via admin review',
    jsonb_build_object(
      'manual_allocation', true,
      'intent_id', p_intent_id,
      'matched_reference', v_reference,
      'allocation_actor_id', auth.uid(),
      'allocation_source', 'admin_operations'
    ),
    v_now,
    v_now
  )
  on conflict (parsed_sms_id) do update set
    target_table = excluded.target_table,
    target_record_id = excluded.target_record_id,
    ledger_status = 'posted',
    ledger_scope = excluded.ledger_scope,
    external_reference = coalesce(
      public.momo_ledger_entries.external_reference,
      excluded.external_reference
    ),
    metadata = coalesce(public.momo_ledger_entries.metadata, '{}'::jsonb) ||
      jsonb_build_object(
        'manual_allocation', true,
        'intent_id', p_intent_id,
        'matched_reference', excluded.external_reference,
        'allocation_actor_id', auth.uid(),
        'allocation_source', 'admin_operations'
      ),
    updated_at = v_now;

  return query
  select v_review.id, v_intent.id, v_reference;
end;
$$;


ALTER FUNCTION "public"."allocate_momo_manual_review"("p_review_id" "uuid", "p_intent_id" "uuid", "p_note" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."allocate_momo_manual_review"("p_review_id" "uuid", "p_intent_id" "uuid", "p_note" "text") IS 'Scoped admin or receiver-account-owner operation to explicitly route a pending manual review SMS to a specific payment intent and post to the ledger.';



CREATE OR REPLACE FUNCTION "public"."apply_group_club_defaults"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_club_id bigint;
  v_country text;
  v_currency text;
begin
  if new.club_id is null then
    new.club_id := nullif(public.requesting_club_id(), '')::bigint;
  end if;

  v_club_id := new.club_id;
  if v_club_id is null then
    return new;
  end if;

  v_country := public.resolve_club_country_code(v_club_id);
  v_currency := public.resolve_club_currency_code(v_club_id);

  if tg_op = 'INSERT' then
    if nullif(btrim(coalesce(new.country, '')), '') is null or (new.country = 'RW' and v_country <> 'RW') then
      new.country := v_country;
    end if;

    if nullif(btrim(coalesce(new.currency, '')), '') is null or (new.currency = 'RWF' and v_currency <> 'RWF') then
      new.currency := v_currency;
    end if;
  else
    if nullif(btrim(coalesce(new.country, '')), '') is null then
      new.country := v_country;
    end if;

    if nullif(btrim(coalesce(new.currency, '')), '') is null then
      new.currency := v_currency;
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."apply_group_club_defaults"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_membership_points"("p_user_id" "uuid", "p_partner_id" "uuid", "p_points" integer, "p_chapter" "text" DEFAULT NULL::"text") RETURNS "public"."fan_memberships"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_membership public.fan_memberships;
  v_chapter text := coalesce(nullif(btrim(coalesce(p_chapter, '')), ''), 'Central');
begin
  insert into public.fan_memberships (
    user_id,
    partner_id,
    display_name,
    points,
    chapter,
    membership_number,
    joined_at,
    created_at,
    updated_at
  )
  values (
    p_user_id,
    p_partner_id,
    public.rs_resolve_public_identity(p_user_id),
    greatest(coalesce(p_points, 0), 0),
    v_chapter,
    'FM-' || to_char(now(), 'YYYY') || '-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 6)),
    now(),
    now(),
    now()
  )
  on conflict (user_id, partner_id)
  do update set
    points = greatest(public.fan_memberships.points + coalesce(p_points, 0), 0),
    display_name = public.rs_resolve_public_identity(excluded.user_id, public.fan_memberships.display_name),
    chapter = coalesce(nullif(btrim(public.fan_memberships.chapter), ''), excluded.chapter),
    updated_at = now()
  returning * into v_membership;

  return v_membership;
end;
$$;


