    to_jsonb(new),
    coalesce(new.club_id, old.club_id),
    'momo_sms_manual_review',
    new.id::text,
    jsonb_build_object(
      'scope',
      'record_and_active_club',
      'source',
      'admin_sms_monitor',
      'undo',
      'manual_recovery'
    )
  );
  return new;
end;
$$;


