CREATE OR REPLACE FUNCTION "public"."cleanup_stale_fcm_tokens"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  deleted_count INTEGER;
BEGIN
  DELETE FROM public.user_fcm_tokens
  WHERE updated_at < now() - INTERVAL '60 days';

  GET DIAGNOSTICS deleted_count = ROW_COUNT;
  RETURN deleted_count;
END;
$$;


ALTER FUNCTION "public"."cleanup_stale_fcm_tokens"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."compat_parse_partner_id"("p_partner_id" "text") RETURNS bigint
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  SELECT NULLIF(regexp_replace(trim(coalesce(p_partner_id, '')), '[^0-9]', '', 'g'), '')::bigint
$$;


ALTER FUNCTION "public"."compat_parse_partner_id"("p_partner_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."compat_parse_partner_id"("p_partner_id" "uuid") RETURNS bigint
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT afc.id
  FROM public.partners p
  JOIN public.african_football_clubs afc
    ON (
      lower(regexp_replace(coalesce(afc.club_name, ''), '[^a-z0-9]+', '', 'g')) =
      lower(regexp_replace(coalesce(p.name, ''), '[^a-z0-9]+', '', 'g'))
    )
    OR (
      lower(regexp_replace(coalesce(afc.club_slug, ''), '[^a-z0-9]+', '', 'g')) =
      lower(regexp_replace(coalesce(p.slug, ''), '[^a-z0-9]+', '', 'g'))
    )
  WHERE p.id = p_partner_id
  LIMIT 1;
$$;


ALTER FUNCTION "public"."compat_parse_partner_id"("p_partner_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."consume_request_rate_limit"("p_bucket_key" "text", "p_limit" integer, "p_window_ms" integer) RETURNS TABLE("allowed" boolean, "retry_after_seconds" integer, "remaining" integer, "reset_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  now_ts timestamptz := timezone('utc', now());
  window_interval interval := (GREATEST(p_window_ms, 1)::text || ' milliseconds')::interval;
  current_count integer;
  current_reset_at timestamptz;
BEGIN
  IF p_bucket_key IS NULL OR btrim(p_bucket_key) = '' THEN
    RAISE EXCEPTION 'p_bucket_key is required';
  END IF;

  IF p_limit <= 0 THEN
    RAISE EXCEPTION 'p_limit must be positive';
  END IF;

  LOOP
    UPDATE public.request_rate_limits
    SET
      count = CASE
        WHEN request_rate_limits.reset_at <= now_ts THEN 1
        ELSE request_rate_limits.count + 1
      END,
      reset_at = CASE
        WHEN request_rate_limits.reset_at <= now_ts THEN now_ts + window_interval
        ELSE request_rate_limits.reset_at
      END,
      updated_at = now_ts
    WHERE request_rate_limits.bucket_key = p_bucket_key
    RETURNING request_rate_limits.count, request_rate_limits.reset_at
      INTO current_count, current_reset_at;

    EXIT WHEN FOUND;

    BEGIN
      INSERT INTO public.request_rate_limits (
        bucket_key,
        count,
        reset_at,
        created_at,
        updated_at
      )
      VALUES (
        p_bucket_key,
        1,
        now_ts + window_interval,
        now_ts,
        now_ts
      )
      RETURNING request_rate_limits.count, request_rate_limits.reset_at
        INTO current_count, current_reset_at;

      EXIT;
    EXCEPTION
      WHEN unique_violation THEN
        NULL;
    END;
  END LOOP;

  RETURN QUERY
  SELECT
    current_count <= p_limit,
    CASE
      WHEN current_count > p_limit THEN GREATEST(1, CEIL(EXTRACT(EPOCH FROM current_reset_at - now_ts))::integer)
      ELSE 0
    END,
    GREATEST(p_limit - LEAST(current_count, p_limit), 0),
    current_reset_at;
END;
$$;


ALTER FUNCTION "public"."consume_request_rate_limit"("p_bucket_key" "text", "p_limit" integer, "p_window_ms" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contribution_groups_write"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_requesting_club_id bigint := nullif(public.requesting_club_id(), '')::bigint;
  v_group_id uuid;
  v_group record;
  v_result record;
begin
  if v_actor_id is null then
    raise exception 'Authentication is required.';
  end if;

  if tg_op = 'DELETE' then
    select g.*
    into v_group
    from public.groups g
    where g.id = old.id;

    if not found then
      return old;
    end if;

    if not (
      public.is_super_admin()
      or public.is_club_admin(v_group.club_id)
    ) then
      raise exception 'Only platform or club admins can delete public initiatives.';
    end if;

    delete from public.groups where id = old.id;
    return old;
  end if;

  if tg_op = 'UPDATE' then
    select g.*
    into v_group
    from public.groups g
    where g.id = old.id;

    if not found then
      raise exception 'Contribution initiative not found.';
    end if;

    if not (
      public.is_super_admin()
      or public.is_club_admin(v_group.club_id)
    ) then
      raise exception 'Only platform or club admins can update public initiatives.';
    end if;

    if new.club_id is not null
       and new.club_id <> v_group.club_id
       and not public.is_super_admin() then
      raise exception 'Contribution initiatives cannot be moved across clubs.';
    end if;

    update public.groups
    set
      creator_id = coalesce(new.creator_id, v_group.creator_id),
      name = new.name,
      description = nullif(btrim(coalesce(new.description, '')), ''),
      group_type = coalesce(new.group_type, v_group.group_type, v_group.type, 'community'),
      target_amount = coalesce(new.target_amount, 0),
      current_total = coalesce(new.current_total, new.amount, v_group.current_total, v_group.amount, 0),
      momo_code = coalesce(
        nullif(btrim(coalesce(new.receiving_momo_code, '')), ''),
        nullif(btrim(coalesce(new.momo_recipient_code, '')), ''),
        nullif(btrim(coalesce(new.momo_number, '')), ''),
        v_group.momo_code
      ),
      deadline = new.deadline,
      is_recurring = coalesce(new.is_recurring, false),
      is_closed = coalesce(new.is_closed, false),
      member_count = greatest(coalesce(new.member_count, v_group.member_count, 0), 0),
      club_id = coalesce(new.club_id, v_group.club_id),
      partner_id = coalesce(new.partner_id, v_group.partner_id),
      currency = coalesce(nullif(btrim(coalesce(new.currency, '')), ''), v_group.currency),
      updated_at = now(),
      is_active = coalesce(new.is_active, coalesce(new.is_closed, false) = false),
      country = coalesce(nullif(btrim(coalesce(new.country, '')), ''), v_group.country),
      visibility = 'public',
      type = case
        when lower(coalesce(new.group_type, v_group.group_type, v_group.type, 'community')) in ('project', 'club', 'team_project')
          then 'project'
        else 'community'
      end,
      amount = coalesce(new.amount, new.current_total, v_group.amount, v_group.current_total, 0)::integer,
      monthly_contribution = coalesce(new.monthly_contribution, new.contribution_amount, v_group.monthly_contribution),
      bank_partner_id = coalesce(new.bank_partner_id, v_group.bank_partner_id),
      momo_number = coalesce(new.momo_number, v_group.momo_number),
      frequency = coalesce(new.frequency, v_group.frequency),
      receiving_momo_route_type = coalesce(new.receiving_momo_route_type, new.momo_route_type, v_group.receiving_momo_route_type),
      receiving_momo_code = coalesce(new.receiving_momo_code, new.momo_recipient_code, v_group.receiving_momo_code),
      cycle_days = coalesce(new.cycle_days, v_group.cycle_days, 30),
      contribution_amount = coalesce(new.contribution_amount, new.monthly_contribution, v_group.contribution_amount, 0)
    where id = old.id
    returning id into v_group_id;
  else
    if coalesce(new.club_id, v_requesting_club_id) is null then
      raise exception 'A club scope is required to create a contribution initiative.';
    end if;

    if not (
      public.is_super_admin()
      or public.is_club_admin(coalesce(new.club_id, v_requesting_club_id))
    ) then
      raise exception 'Only platform or club admins can create public initiatives.';
    end if;

    insert into public.groups (
      creator_id,
      name,
      description,
      group_type,
      target_amount,
      current_total,
      momo_code,
      deadline,
      is_recurring,
      is_closed,
      member_count,
      club_id,
      partner_id,
      currency,
      is_active,
      country,
      visibility,
      type,
      amount,
      monthly_contribution,
      bank_partner_id,
      momo_number,
      frequency,
      receiving_momo_route_type,
      receiving_momo_code,
      cycle_days,
      contribution_amount
    )
    values (
      coalesce(new.creator_id, v_actor_id),
      new.name,
      nullif(btrim(coalesce(new.description, '')), ''),
      coalesce(new.group_type, 'community'),
      coalesce(new.target_amount, 0),
      coalesce(new.current_total, new.amount, 0),
      coalesce(
        nullif(btrim(coalesce(new.receiving_momo_code, '')), ''),
        nullif(btrim(coalesce(new.momo_recipient_code, '')), ''),
        nullif(btrim(coalesce(new.momo_number, '')), '')
      ),
      new.deadline,
      coalesce(new.is_recurring, false),
      coalesce(new.is_closed, false),
      greatest(coalesce(new.member_count, 0), 0),
      coalesce(new.club_id, v_requesting_club_id),
      new.partner_id,
      nullif(btrim(coalesce(new.currency, '')), ''),
      coalesce(new.is_active, coalesce(new.is_closed, false) = false),
      nullif(btrim(coalesce(new.country, '')), ''),
      'public',
      case
        when lower(coalesce(new.group_type, 'community')) in ('project', 'club', 'team_project')
          then 'project'
        else 'community'
      end,
      coalesce(new.amount, new.current_total, 0)::integer,
      coalesce(new.monthly_contribution, new.contribution_amount),
      new.bank_partner_id,
      nullif(btrim(coalesce(new.momo_number, '')), ''),
      nullif(btrim(coalesce(new.frequency, '')), ''),
      coalesce(new.receiving_momo_route_type, new.momo_route_type),
      coalesce(new.receiving_momo_code, new.momo_recipient_code),
      coalesce(new.cycle_days, 30),
      coalesce(new.contribution_amount, new.monthly_contribution, 0)
    )
    returning id into v_group_id;
  end if;

  select *
  into v_result
  from public.contribution_groups
  where id = v_group_id;

  new := v_result;
  return new;
end;
$$;


ALTER FUNCTION "public"."contribution_groups_write"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cool_events_write"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_event_id uuid;
  v_row record;
begin
  if tg_op = 'DELETE' then
    delete from public.fet_events
    where id = old.id;
    return old;
  end if;

  if tg_op = 'UPDATE' then
    update public.fet_events
    set
      user_id = new.user_id,
      club_id = coalesce(new.club_id, old.club_id),
      event_type = new.event_type,
      fet_awarded = coalesce(new.fet_awarded, new.xp_awarded, new.points_awarded, 0),
      metadata = jsonb_strip_nulls(
        coalesce(new.metadata, '{}'::jsonb)
        || jsonb_build_object(
          'source_id', nullif(btrim(coalesce(new.source_id, '')), ''),
          'referrer_id', new.referrer_id,
          'dedupe_key', nullif(btrim(coalesce(new.dedupe_key, '')), ''),
          'campaign_id', nullif(btrim(coalesce(new.campaign_id, '')), ''),
          'season_id', new.season_id,
          'mock_batch', nullif(btrim(coalesce(new.mock_batch, '')), ''),
          'source_table', 'cool_events'
        )
      ),
      event_at = coalesce(new.event_at, old.event_at),
      created_at = coalesce(new.created_at, old.created_at)
    where id = old.id;
    v_event_id := old.id;
  else
    insert into public.fet_events (
      user_id,
      club_id,
      event_type,
      fet_awarded,
      metadata,
      event_at,
      created_at
    )
    values (
      new.user_id,
      new.club_id,
      new.event_type,
      coalesce(new.fet_awarded, new.xp_awarded, new.points_awarded, 0),
      jsonb_strip_nulls(
        coalesce(new.metadata, '{}'::jsonb)
        || jsonb_build_object(
          'source_id', nullif(btrim(coalesce(new.source_id, '')), ''),
          'referrer_id', new.referrer_id,
          'dedupe_key', nullif(btrim(coalesce(new.dedupe_key, '')), ''),
          'campaign_id', nullif(btrim(coalesce(new.campaign_id, '')), ''),
          'season_id', new.season_id,
          'mock_batch', nullif(btrim(coalesce(new.mock_batch, '')), ''),
          'source_table', 'cool_events'
        )
      ),
      coalesce(new.event_at, timezone('utc', now())),
      coalesce(new.created_at, timezone('utc', now()))
    )
    returning id into v_event_id;
  end if;

  select *
  into v_row
  from public.cool_events
  where id = v_event_id
  order by created_at desc
  limit 1;

  new := v_row;
  return new;
end;
$$;


ALTER FUNCTION "public"."cool_events_write"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cool_status_tier_for_points"("p_points" integer) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE
    WHEN greatest(coalesce(p_points, 0), 0) >= 5000 THEN 'platinum'
    WHEN greatest(coalesce(p_points, 0), 0) >= 2000 THEN 'gold'
    WHEN greatest(coalesce(p_points, 0), 0) >= 1000 THEN 'bronze'
    ELSE 'fan'
  END;
$$;


ALTER FUNCTION "public"."cool_status_tier_for_points"("p_points" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_pending_group_contribution"("p_group_id" "uuid", "p_amount" integer, "p_client_request_reference" "text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_actor_id uuid := auth.uid();
  v_club_claim text := public.requesting_club_id();
  v_club_id bigint;
  v_client_request_reference text;
  v_idempotency_key text;
  v_contribution public.group_contributions%rowtype;
  v_inserted boolean := false;
begin
  if v_actor_id is null then
    raise exception 'An authenticated supporter is required.';
  end if;

  if v_club_claim is null or v_club_claim !~ '^[0-9]+$' then
    raise exception 'A valid authenticated club scope is required.';
  end if;
  v_club_id := v_club_claim::bigint;

  if p_group_id is null then
    raise exception 'A contribution group is required.';
  end if;

  if p_amount is null or p_amount < 1 or p_amount > 100000000 then
    raise exception 'Contribution amount must be between 1 and 100000000 RWF.';
  end if;

  v_client_request_reference := pg_catalog.upper(
    pg_catalog.regexp_replace(
      pg_catalog.btrim(coalesce(p_client_request_reference, '')),
      '[^A-Za-z0-9]',
      '',
      'g'
    )
  );
  if pg_catalog.length(v_client_request_reference) < 6
     or pg_catalog.length(v_client_request_reference) > 64 then
    raise exception 'A valid client request reference between 6 and 64 characters is required.';
  end if;

  v_idempotency_key := pg_catalog.lower(
    pg_catalog.regexp_replace(
      pg_catalog.btrim(
        coalesce(p_idempotency_key, 'momo:' || v_client_request_reference)
      ),
      '[^A-Za-z0-9:_-]',
      '',
      'g'
    )
  );
  if pg_catalog.length(v_idempotency_key) < 8
     or pg_catalog.length(v_idempotency_key) > 128 then
    raise exception 'A valid idempotency key between 8 and 128 characters is required.';
  end if;

  perform 1
    from public.groups as contribution_group
   where contribution_group.id = p_group_id
     and contribution_group.club_id = v_club_id
     and coalesce(contribution_group.is_active, true)
     and not coalesce(contribution_group.is_closed, false)
     and coalesce(contribution_group.visibility, 'public') = 'public'
   for share;

  if not found then
    raise exception 'Contribution group is unavailable in the authenticated club.';
  end if;

  if not public.is_group_member(p_group_id, v_actor_id) then
    raise exception 'Only a current group member may contribute.';
  end if;

  select contribution.*
    into v_contribution
    from public.group_contributions as contribution
   where contribution.user_id = v_actor_id
     and contribution.group_id = p_group_id
     and contribution.client_request_reference = v_client_request_reference
   order by contribution.created_at desc
   limit 1
   for update;

  if found then
    if v_contribution.amount is distinct from p_amount
       or (
         v_contribution.idempotency_key is not null
         and v_contribution.idempotency_key is distinct from v_idempotency_key
       ) then
      raise exception 'Client request reference is already bound to another contribution request.';
    end if;
  else
    begin
      insert into public.group_contributions (
        group_id,
        user_id,
        amount,
        status,
        payment_status,
        client_request_reference,
        idempotency_key
      ) values (
        p_group_id,
        v_actor_id,
        p_amount,
        'pending',
        'pending_verification'::public.payment_status,
        v_client_request_reference,
        v_idempotency_key
      )
      on conflict on constraint group_contributions_idempotency_key_key
      do nothing
      returning * into v_contribution;
      v_inserted := found;
    exception
      when unique_violation then
        v_contribution := null;
    end;

    if v_contribution.id is null then
      select contribution.*
        into v_contribution
        from public.group_contributions as contribution
       where (
         contribution.user_id = v_actor_id
         and contribution.group_id = p_group_id
         and contribution.idempotency_key = v_idempotency_key
       ) or (
         contribution.user_id = v_actor_id
         and contribution.group_id = p_group_id
         and contribution.client_request_reference = v_client_request_reference
       )
       order by
         case when contribution.idempotency_key = v_idempotency_key then 0 else 1 end
       limit 1
       for update;
    end if;

    if v_contribution.id is null
       or v_contribution.user_id is distinct from v_actor_id
       or v_contribution.group_id is distinct from p_group_id
       or v_contribution.amount is distinct from p_amount
       or v_contribution.client_request_reference is distinct from v_client_request_reference
       or (
         v_contribution.idempotency_key is not null
         and v_contribution.idempotency_key is distinct from v_idempotency_key
       ) then
      raise exception 'Idempotency key or client request reference conflicts with another request.';
    end if;
  end if;

  return pg_catalog.jsonb_build_object(
    'id', v_contribution.id,
    'status', v_contribution.status,
    'payment_status', v_contribution.payment_status,
    'created_at', v_contribution.created_at,
    'updated_at', v_contribution.updated_at,
    'replayed', not v_inserted
  );
end;
$_$;


ALTER FUNCTION "public"."create_pending_group_contribution"("p_group_id" "uuid", "p_amount" integer, "p_client_request_reference" "text", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_pending_group_contribution"("p_group_id" "uuid", "p_amount" integer, "p_client_request_reference" "text", "p_idempotency_key" "text") IS 'Creates only the authenticated member''s own-club pending contribution, with a normalized immutable client request reference, an unbound provider reference and idempotent replay.';



CREATE OR REPLACE FUNCTION "public"."create_shop_order"("p_items" "jsonb", "p_delivery_address" "text", "p_payment_reference" "text") RETURNS "public"."shop_orders"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_club_id bigint;
  v_item jsonb;
  v_product_id uuid;
  v_product public.shop_products;
  v_partner_id uuid;
  v_quantity integer;
  v_selected_variant text;
  v_subtotal bigint := 0;
  v_canonical_items jsonb := '[]'::jsonb;
  v_seen_product_ids uuid[] := '{}'::uuid[];
  v_delivery_address text := nullif(
    pg_catalog.btrim(coalesce(p_delivery_address, '')),
    ''
  );
  v_payment_reference text := nullif(
    pg_catalog.btrim(coalesce(p_payment_reference, '')),
    ''
  );
  v_order public.shop_orders;
begin
  if v_actor_id is null then
    raise exception 'An authenticated supporter is required.';
  end if;

  begin
    v_club_id := nullif(public.requesting_club_id(), '')::bigint;
  exception
    when invalid_text_representation then
      raise exception 'A valid trusted club scope is required.';
  end;

  if v_club_id is null then
    raise exception 'A trusted club scope is required.';
  end if;

  if pg_catalog.jsonb_typeof(p_items) <> 'array'
     or pg_catalog.jsonb_array_length(p_items) < 1
     or pg_catalog.jsonb_array_length(p_items) > 20 then
    raise exception 'An order must contain between 1 and 20 products.';
  end if;

  if v_delivery_address is null
     or pg_catalog.length(v_delivery_address) < 5
     or pg_catalog.length(v_delivery_address) > 500 then
    raise exception 'A valid delivery address is required.';
  end if;

  if v_payment_reference is null
     or pg_catalog.length(v_payment_reference) > 120 then
    raise exception 'A valid payment reference is required.';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      v_actor_id::text || ':' || v_club_id::text || ':' || v_payment_reference,
      0
    )
  );

  perform public.release_expired_shop_order_reservations(v_club_id);

  select shop_order.*
    into v_order
    from public.shop_orders as shop_order
   where shop_order.user_id = v_actor_id
     and shop_order.club_id = v_club_id
     and shop_order.momo_reference = v_payment_reference
   order by shop_order.created_at desc, shop_order.id
   limit 1;

  if v_order.id is not null then
    return v_order;
  end if;

  for v_item in
    select value
    from pg_catalog.jsonb_array_elements(p_items)
  loop
    begin
      v_product_id := nullif(v_item ->> 'product_id', '')::uuid;
      v_quantity := (v_item ->> 'quantity')::integer;
    exception
      when invalid_text_representation then
        raise exception 'Order item product and quantity must be valid.';
    end;

    if v_product_id is null or v_quantity < 1 or v_quantity > 20 then
      raise exception 'Each product quantity must be between 1 and 20.';
    end if;

    if v_product_id = any(v_seen_product_ids) then
      raise exception 'Duplicate products are not allowed in one order.';
    end if;
    v_seen_product_ids := pg_catalog.array_append(v_seen_product_ids, v_product_id);

    v_selected_variant := nullif(
      pg_catalog.btrim(coalesce(v_item ->> 'selected_variant', '')),
      ''
    );
    if pg_catalog.length(coalesce(v_selected_variant, '')) > 80 then
      raise exception 'Selected product variant is too long.';
    end if;

    select product.*
      into v_product
      from public.shop_products as product
     where product.id = v_product_id
       and product.club_id = v_club_id
       and product.is_active
       and (product.image_url is null or product.image_rights_approved)
     for update;

    if not found then
      raise exception 'Order item is unavailable in the active club catalog.';
    end if;

    if v_product.stock < v_quantity then
      raise exception 'Order item has insufficient stock.';
    end if;

    if v_product.price < 0
       or v_product.price <> pg_catalog.trunc(v_product.price)
       or v_product.price > 2147483647 then
      raise exception 'Order item price is not a valid RWF amount.';
    end if;

    if pg_catalog.cardinality(v_product.available_sizes) > 0
       and (
         v_selected_variant is null
         or not (v_selected_variant = any(v_product.available_sizes))
       ) then
      raise exception 'A valid available product variant is required.';
    end if;

    if v_partner_id is null then
      v_partner_id := v_product.partner_id;
    elsif v_partner_id is distinct from v_product.partner_id then
      raise exception 'All order products must use one fulfillment partner.';
    end if;

    v_subtotal := v_subtotal + (v_product.price::bigint * v_quantity);
    if v_subtotal > 2147483647 then
      raise exception 'Order total exceeds the supported amount.';
    end if;

    v_canonical_items := v_canonical_items || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'product_id', v_product.id,
        'product', pg_catalog.jsonb_build_object(
          'id', v_product.id,
          'partner_id', v_product.partner_id,
          'club_id', v_product.club_id,
          'name', v_product.name,
          'description', v_product.description,
          'category', v_product.category,
          'price', v_product.price::integer,
          'is_active', v_product.is_active,
          'is_new', v_product.is_new,
          'image_url', v_product.image_url,
          'available_sizes', v_product.available_sizes,
          'badge_label', v_product.badge_label,
          'collection', v_product.collection,
          'sort_order', v_product.sort_order
        ),
        'quantity', v_quantity,
        'selected_variant', v_selected_variant
      )
    );
  end loop;

  insert into public.shop_orders (
    user_id,
    club_id,
    partner_id,
    items,
    subtotal,
    discount,
    discount_amount,
    delivery_fee,
    total,
    delivery_address,
    momo_reference,
    status,
    inventory_reserved,
    reservation_expires_at
  ) values (
    v_actor_id,
    v_club_id,
    v_partner_id,
    v_canonical_items,
    v_subtotal::integer,
    0,
    0,
    0,
    v_subtotal::integer,
    v_delivery_address,
    v_payment_reference,
    'pending',
    true,
    pg_catalog.now() + interval '15 minutes'
  )
  returning * into v_order;

  insert into public.admin_audit_log (
    actor_id,
    user_id,
    action,
    target_table,
    target_id,
    old_data,
    new_data,
    club_id,
    entity_type,
    entity_id,
    metadata
  ) values (
    v_actor_id,
    v_actor_id,
    'supporter_shop_order_created',
    'shop_orders',
    v_order.id::text,
    null,
    pg_catalog.jsonb_build_object(
      'status', v_order.status,
      'subtotal', v_order.subtotal,
      'total', v_order.total,
      'reservation_expires_at', v_order.reservation_expires_at
    ),
    v_club_id,
    'shop_order',
    v_order.id::text,
    pg_catalog.jsonb_build_object(
      'scope', 'active_club',
      'source', 'mobile_shop_checkout',
      'authoritative_pricing', true,
      'inventory_reserved', true
    )
  );

  return v_order;
end;
$$;


ALTER FUNCTION "public"."create_shop_order"("p_items" "jsonb", "p_delivery_address" "text", "p_payment_reference" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."custom_access_token_hook"("event" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  claims                jsonb;
  app_meta              jsonb;
  v_raw_club_id         text;
  v_normalized_club_id  text;
  v_user_role           text;
begin
  claims := event -> 'claims';
  app_meta := claims -> 'app_metadata';

  -- Authorization claims must come only from server-controlled app_metadata.
  -- user_metadata is user-editable and must never influence club or role scope.
  v_raw_club_id := coalesce(app_meta ->> 'club_id', '');
  v_normalized_club_id := coalesce(
    public.normalize_club_id(nullif(v_raw_club_id, ''))::text,
    v_raw_club_id
  );
  v_user_role := coalesce(nullif(app_meta ->> 'role', ''), 'fan');

  claims := jsonb_set(claims, '{club_id}', to_jsonb(v_normalized_club_id));
  claims := jsonb_set(claims, '{user_role}', to_jsonb(v_user_role));
  event := jsonb_set(event, '{claims}', claims);
  return event;
end;
$$;


ALTER FUNCTION "public"."custom_access_token_hook"("event" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."custom_access_token_hook"("event" "jsonb") IS 'Adds app_metadata-derived club_id and user_role while preserving the authenticated PostgreSQL JWT role required by PostgREST and RLS. Executable only by Supabase Auth.';



CREATE OR REPLACE FUNCTION "public"."derive_momo_cashflow_bucket"("p_tx_category" "text", "p_tx_direction" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  select case
    when lower(coalesce(p_tx_category, '')) in ('salary', 'cash_in', 'transfer_in', 'loan_disbursement') then 'income'
    when lower(coalesce(p_tx_category, '')) in ('group_contribution', 'savings') then 'savings'
    when lower(coalesce(p_tx_category, '')) in ('loan', 'loan_repayment') then 'loan'
    when lower(coalesce(p_tx_category, '')) in ('fees', 'charge') then 'fees'
    when lower(coalesce(p_tx_category, '')) in ('transfer_in', 'transfer_out', 'transfer', 'bank_transfer') then 'transfer'
    when lower(coalesce(p_tx_category, '')) in ('merchant_payment', 'cash_out', 'airtime', 'subscription') then 'expense'
    when lower(coalesce(p_tx_direction, '')) = 'credit' then 'income'
    when lower(coalesce(p_tx_direction, '')) = 'debit' then 'expense'
    else 'unknown'
  end;
$$;


ALTER FUNCTION "public"."derive_momo_cashflow_bucket"("p_tx_category" "text", "p_tx_direction" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."derive_momo_tx_category"("p_tx_type" "text", "p_tx_direction" "text", "p_target_table" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  select case
    when lower(coalesce(p_target_table, '')) = 'group_contributions' then 'group_contribution'
    when lower(coalesce(p_target_table, '')) = 'driver_subscriptions' then 'subscription'
    when lower(coalesce(p_tx_type, '')) in ('salary', 'payroll') then 'salary'
    when lower(coalesce(p_tx_type, '')) in ('subscription', 'bundle') then 'subscription'
    when lower(coalesce(p_tx_type, '')) in ('cash_in', 'deposit') then 'cash_in'
    when lower(coalesce(p_tx_type, '')) in ('cash_out', 'withdrawal') then 'cash_out'
    when lower(coalesce(p_tx_type, '')) in ('merchant_payment', 'bill_payment', 'payment') then 'merchant_payment'
    when lower(coalesce(p_tx_type, '')) in ('transfer', 'send_money', 'received_money') then
      case
        when lower(coalesce(p_tx_direction, '')) = 'credit' then 'transfer_in'
        when lower(coalesce(p_tx_direction, '')) = 'debit' then 'transfer_out'
        else 'transfer'
      end
    when lower(coalesce(p_tx_type, '')) in ('airtime', 'bundle_purchase') then 'airtime'
    when lower(coalesce(p_tx_type, '')) in ('bank_transfer', 'bank_deposit') then 'bank_transfer'
    when lower(coalesce(p_tx_type, '')) in ('fee', 'charge') then 'fees'
    when lower(coalesce(p_tx_type, '')) in ('loan', 'loan_repayment', 'loan_disbursement') then lower(coalesce(p_tx_type, ''))
    when lower(coalesce(p_tx_direction, '')) = 'credit' then 'transfer_in'
    when lower(coalesce(p_tx_direction, '')) = 'debit' then 'transfer_out'
    else 'uncategorized'
  end;
$$;


ALTER FUNCTION "public"."derive_momo_tx_category"("p_tx_type" "text", "p_tx_direction" "text", "p_target_table" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_group_contribution_identity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if new.group_id is distinct from old.group_id
     or new.user_id is distinct from old.user_id
     or new.amount is distinct from old.amount
     or new.client_request_reference is distinct from old.client_request_reference
     or new.idempotency_key is distinct from old.idempotency_key then
    raise exception
      'Contribution identity, amount, client request reference and idempotency key are immutable.';
  end if;

  if old.momo_reference is not null
     and new.momo_reference is distinct from old.momo_reference then
    raise exception 'A provider payment reference is immutable after binding.';
  end if;

  if old.reconciled_ledger_entry_id is not null
     and new.reconciled_ledger_entry_id is distinct from old.reconciled_ledger_entry_id then
    raise exception 'A reconciled contribution cannot be rebound to another ledger entry.';
  end if;

  if old.reconciliation_id is not null
     and new.reconciliation_id is distinct from old.reconciliation_id then
    raise exception 'A reconciled contribution cannot be rebound to another reconciliation.';
  end if;

  if old.reconciliation_idempotency_key is not null
     and new.reconciliation_idempotency_key is distinct from old.reconciliation_idempotency_key then
    raise exception 'A reconciliation idempotency key is immutable after binding.';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_group_contribution_identity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_group_momo_fields"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_route_type text;
  v_recipient text;
begin
  new.country := public.normalize_country_code(
    coalesce(nullif(btrim(coalesce(new.country, '')), ''), 'RW')
  );
  new.type := coalesce(nullif(lower(btrim(coalesce(new.type, ''))), ''), 'saving');
  new.momo_number := nullif(btrim(coalesce(new.momo_number, '')), '');
  new.receiving_momo_code := nullif(
    btrim(coalesce(new.receiving_momo_code, '')),
    ''
  );
  new.receiving_momo_route_type := nullif(
    lower(btrim(coalesce(new.receiving_momo_route_type, ''))),
    ''
  );

  if new.receiving_momo_code is null and new.momo_number is not null then
    new.receiving_momo_code := new.momo_number;
  end if;

  if new.receiving_momo_route_type is null
     and new.receiving_momo_code is not null then
    new.receiving_momo_route_type := public.infer_momo_route_type_for_country(
      new.country,
      new.receiving_momo_code
    );
  end if;

  if new.type = 'community'
     and new.receiving_momo_code is null
     and new.momo_number is null then
    raise exception 'Community groups require a MoMo number or merchant code.';
  end if;

  v_route_type := new.receiving_momo_route_type;
  if v_route_type is null and new.momo_number is not null then
    v_route_type := 'phone_number';
  end if;

  if v_route_type is null then
    return new;
  end if;

  if v_route_type not in ('phone_number', 'code') then
    raise exception 'Unsupported receiving_momo_route_type: %', v_route_type;
  end if;

  v_recipient := coalesce(new.receiving_momo_code, new.momo_number);
  if v_recipient is null then
    raise exception 'A MoMo recipient is required for route type %.', v_route_type;
  end if;

  if v_route_type = 'phone_number' then
    v_recipient := public.normalize_momo_phone_for_country(
      new.country,
      v_recipient
    );
    new.momo_number := v_recipient;
    new.receiving_momo_code := v_recipient;
    new.receiving_momo_route_type := 'phone_number';
  else
    v_recipient := public.normalize_momo_code_for_country(
      new.country,
      v_recipient
    );
    new.momo_number := null;
    new.receiving_momo_code := v_recipient;
    new.receiving_momo_route_type := 'code';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_group_momo_fields"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_owned_user_club_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_trusted_club_id bigint;
begin
  if current_user in ('postgres', 'service_role', 'supabase_admin') then
    return new;
  end if;

  if v_actor_id is null or new.user_id is distinct from v_actor_id then
    raise exception 'The row must belong to the authenticated user.';
  end if;

  begin
    v_trusted_club_id := nullif(public.requesting_club_id(), '')::bigint;
  exception
    when invalid_text_representation then
      raise exception 'A valid trusted club context is required.';
  end;

  if v_trusted_club_id is null then
    raise exception 'A trusted club context is required.';
  end if;

  if tg_op = 'UPDATE' then
    if new.user_id is distinct from old.user_id
       or new.club_id is distinct from old.club_id then
      raise exception 'User and club scope cannot be changed.';
    end if;
  elsif new.club_id is not null
        and new.club_id is distinct from v_trusted_club_id then
    raise exception 'Requested club does not match the authenticated club context.';
  end if;

  new.club_id := v_trusted_club_id;
  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_owned_user_club_scope"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_partner_payment_route_fields"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_country public.supported_countries;
begin
  new.country := 'RW';
  new.provider := public.normalize_partner_payment_provider(new.provider);
  new.status := lower(btrim(coalesce(new.status, 'draft')));
  new.reconciliation_label := regexp_replace(
    lower(btrim(coalesce(new.reconciliation_label, ''))),
    '[^a-z0-9]+',
    '_',
    'g'
  );
  new.reconciliation_label := btrim(new.reconciliation_label, '_');
  new.recipient_code := public.normalize_momo_code_for_country(
    new.country,
    new.recipient_code
  );

  select *
  into v_country
  from public.get_supported_country_momo_config('RW');

  if v_country.iso_code is null then
    raise exception 'Rwanda mobile money configuration is missing.';
  end if;

  if new.provider = '' then
    raise exception 'Payment provider is required.';
  end if;

  if new.reconciliation_label = '' then
    raise exception 'Reconciliation label is required.';
  end if;

  if new.status not in ('draft', 'active', 'inactive') then
    raise exception 'Invalid payment route status: %', new.status;
  end if;

  if coalesce(nullif(v_country.momo_code_ussd_template, ''), '') = '' then
    raise exception 'Merchant-code payments are not configured for Rwanda.';
  end if;

  if new.status = 'active' and new.recipient_code is null then
    raise exception 'Active payment routes require a merchant code.';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_partner_payment_route_fields"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_store_release_rule_authority"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  sensitive_keys constant text[] := array[
    'store_release_authorized',
    'stakes_have_no_real_world_value',
    'contest_rules_approved',
    'rewards_have_no_real_world_value',
    'rewards_catalog_approved',
    'terms_acceptance_enabled',
    'content_filtering_enabled',
    'reporting_enabled',
    'blocking_enabled',
    'moderation_operations_approved',
    'store_billing_authorized'
  ];
  key text;
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  foreach key in array sensitive_keys loop
    if coalesce((new.rollout_rules ->> key)::boolean, false) then
      raise exception using
        errcode = '42501',
        message = 'Store-release approval rules require service-role authority';
    end if;
  end loop;

  return new;
exception
  when invalid_text_representation then
    raise exception using
      errcode = '22023',
      message = 'Store-release approval rules must be boolean values';
end;
$$;


ALTER FUNCTION "public"."enforce_store_release_rule_authority"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_ticket_provider_attestation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_reference text := pg_catalog.upper(
    pg_catalog.regexp_replace(
      pg_catalog.btrim(coalesce(new.momo_reference, '')),
      '[^A-Za-z0-9]',
      '',
      'g'
    )
  );
begin
  -- Cancellation of a still-pending supporter request remains safe and does
  -- not need provider evidence. Only attestation to VALID is gated here.
  if old.status = 'pending' and new.status = 'valid' then
    if pg_catalog.length(v_reference) < 6
       or not exists (
         select 1
           from public.momo_reconciliations as reconciliation
           join public.momo_sms_parsed as parsed_sms
             on parsed_sms.id = reconciliation.parsed_sms_id
           join public.momo_ledger_entries as ledger_entry
             on ledger_entry.parsed_sms_id = parsed_sms.id
          where reconciliation.target_table = 'tickets'
            and (
              reconciliation.target_record_id = new.id
              or coalesce(
                reconciliation.metadata -> 'ticket_ids',
                '[]'::jsonb
              ) @> pg_catalog.jsonb_build_array(new.id)
            )
            and reconciliation.match_status = 'matched'
            and reconciliation.reconciled_at is not null
            and reconciliation.user_id = new.user_id
            and reconciliation.club_id = new.club_id
            and not coalesce(reconciliation.is_mock, false)
            and parsed_sms.parse_status = 'parsed'
            and parsed_sms.tx_direction = 'debit'
            and parsed_sms.user_id = new.user_id
            and parsed_sms.club_id = new.club_id
            and parsed_sms.amount = ledger_entry.amount
            and not coalesce(parsed_sms.is_mock, false)
            and ledger_entry.entry_type = 'debit'
            and ledger_entry.ledger_status = 'posted'
            and ledger_entry.target_table = 'tickets'
            and (
              ledger_entry.target_record_id = new.id
              or coalesce(
                ledger_entry.metadata -> 'ticket_ids',
                '[]'::jsonb
              ) @> pg_catalog.jsonb_build_array(new.id)
            )
            and ledger_entry.user_id = new.user_id
            and ledger_entry.club_id = new.club_id
            and ledger_entry.amount = (
              select coalesce(
                pg_catalog.sum(ticket.amount_paid),
                0::bigint
              )::integer
                from public.tickets as ticket
               where ticket.user_id = new.user_id
                 and ticket.club_id = new.club_id
                 and ticket.status in ('pending', 'valid')
                 and pg_catalog.upper(
                   pg_catalog.regexp_replace(
                     pg_catalog.btrim(coalesce(ticket.momo_reference, '')),
                     '[^A-Za-z0-9]',
                     '',
                     'g'
                   )
                 ) = v_reference
            )
            and not coalesce(ledger_entry.is_mock, false)
            and pg_catalog.upper(
              pg_catalog.regexp_replace(
                pg_catalog.btrim(coalesce(parsed_sms.momo_tx_id, '')),
                '[^A-Za-z0-9]',
                '',
                'g'
              )
            ) = v_reference
            and pg_catalog.upper(
              pg_catalog.regexp_replace(
                pg_catalog.btrim(coalesce(ledger_entry.external_reference, '')),
                '[^A-Za-z0-9]',
                '',
                'g'
              )
            ) = v_reference
       ) then
      raise exception
        'A matched, posted provider payment is required before ticket validation.';
    end if;

    new.confirmed_at := coalesce(
      new.confirmed_at,
      pg_catalog.timezone('utc', pg_catalog.now())
    );
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_ticket_provider_attestation"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enforce_ticket_provider_attestation"() IS 'Rejects pending-to-valid ticket transitions unless exact non-mock parsed SMS, posted ledger and matched reconciliation evidence bind the ticket or ticket batch, owner, club, total amount and provider reference.';



CREATE OR REPLACE FUNCTION "public"."enforce_user_momo_fields"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_country public.supported_countries;
begin
  new.country := 'RW';
  new.language_code := 'en';
  new.momo_number := nullif(btrim(coalesce(new.momo_number, '')), '');
  new.momo_code := nullif(btrim(coalesce(new.momo_code, '')), '');
  new.momo_route_type := nullif(
    lower(btrim(coalesce(new.momo_route_type, ''))),
    ''
  );
  new.momo_provider := coalesce(new.momo_provider, '');

  if new.momo_number is not null then
    new.momo_number := public.normalize_momo_phone_for_country(
      new.country,
      new.momo_number
    );
  end if;

  if new.momo_code is not null then
    new.momo_code := public.normalize_momo_code_for_country(
      new.country,
      new.momo_code
    );
  end if;

  if btrim(new.momo_provider) = '' then
    select *
    into v_country
    from public.get_supported_country_momo_config(new.country);

    if v_country.iso_code is not null then
      new.momo_provider := coalesce(v_country.momo_provider_id, '');
    end if;
  end if;

  if new.momo_route_type = 'phone_number' then
    if new.momo_number is null then
      raise exception using
        errcode = '23514',
        message = 'momo_route_type phone_number requires momo_number';
    end if;
  elsif new.momo_route_type = 'code' then
    if new.momo_code is null then
      raise exception using
        errcode = '23514',
        message = 'momo_route_type code requires momo_code';
    end if;
  elsif new.momo_number is not null then
    new.momo_route_type := 'phone_number';
  elsif new.momo_code is not null then
    new.momo_route_type := 'code';
  else
    new.momo_route_type := null;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_user_momo_fields"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fet_admin_adjust_balance"("p_user_id" "uuid", "p_amount" integer, "p_reason" "text", "p_idempotency_key" "text" DEFAULT NULL::"text", "p_club_id" bigint DEFAULT NULL::bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_caller_id uuid := auth.uid();
  v_club_id bigint;
  v_membership public.fan_memberships;
  v_existing public.fet_wallet_ledger_entries;
  v_amount integer := coalesce(p_amount, 0);
  v_abs_amount integer := abs(coalesce(p_amount, 0));
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_idempotency_key text := nullif(btrim(coalesce(p_idempotency_key, '')), '');
  v_direction text;
  v_reference_id text := gen_random_uuid()::text;
begin
  if v_caller_id is null then
    raise exception 'Authentication is required.';
  end if;

  v_club_id := public.fet_require_club_context(p_club_id);

  if not (public.is_club_admin(v_club_id) or public.is_super_admin()) then
    raise exception 'Club admin access is required.';
  end if;

  if p_user_id is null then
    raise exception 'A target user is required.';
  end if;

  if v_reason is null then
    raise exception 'Adjustment reason is required.';
  end if;

  if v_abs_amount = 0 then
    raise exception 'Adjustment amount must be non-zero.';
  end if;

  if v_idempotency_key is not null then
    select *
      into v_existing
      from public.fet_wallet_ledger_entries e
     where e.club_id = v_club_id
       and e.user_id = p_user_id
       and e.idempotency_key = v_idempotency_key
       and e.entry_type = 'admin_adjustment'
     order by e.created_at desc, e.id desc
     limit 1;

    if v_existing.id is not null then
      return jsonb_build_object(
        'status', 'success',
        'already_processed', true,
        'amount', case when v_existing.direction = 'debit' then -v_existing.amount else v_existing.amount end,
        'balance', v_existing.balance_after,
        'reference_id', v_existing.reference_id
      );
    end if;
  end if;

  perform public.fet_wallet_ensure_membership(p_user_id, v_club_id);

  select *
    into v_membership
    from public.fan_memberships
   where user_id = p_user_id
     and club_id = v_club_id
   for update;

  if v_amount < 0 and coalesce(v_membership.points, 0) < v_abs_amount then
    raise exception 'Adjustment would overdraw the supporter wallet.';
  end if;

  if v_amount > 0 then
    update public.fan_memberships
       set points = points + v_abs_amount,
           tier = public.resolve_fan_tier(points + v_abs_amount),
           renewed_at = timezone('utc', now()),
           updated_at = timezone('utc', now())
     where id = v_membership.id
    returning * into v_membership;
    v_direction := 'credit';

    insert into public.xp_events (
      user_id,
      club_id,
      event_type,
      xp_awarded,
      metadata,
      event_at
    )
    values (
      p_user_id,
      v_club_id,
      'admin_adjustment',
      v_abs_amount,
      jsonb_build_object(
        'reason',
        v_reason,
        'source',
        'fet_admin_adjust_balance',
        'source_table',
        'cool_events'
      ),
      timezone('utc', now())
    );
  else
    update public.fan_memberships
       set points = points - v_abs_amount,
           tier = public.resolve_fan_tier(points - v_abs_amount),
           updated_at = timezone('utc', now())
     where id = v_membership.id
    returning * into v_membership;
    v_direction := 'debit';
  end if;

  perform public.fet_wallet_append_entry(
    p_club_id := v_club_id,
    p_user_id := p_user_id,
    p_membership_id := v_membership.id,
    p_entry_type := 'admin_adjustment',
    p_direction := v_direction,
    p_amount := v_abs_amount,
    p_balance_after := v_membership.points,
    p_counterparty_user_id := null,
    p_reference_type := 'admin_adjustment',
    p_reference_id := v_reference_id,
    p_idempotency_key := v_idempotency_key,
    p_note := v_reason,
    p_metadata := jsonb_build_object('requested_amount', v_amount),
    p_created_by := v_caller_id
  );

  return jsonb_build_object(
    'status', 'success',
    'amount', v_amount,
    'balance', v_membership.points,
    'reference_id', v_reference_id
  );
end;
$$;


ALTER FUNCTION "public"."fet_admin_adjust_balance"("p_user_id" "uuid", "p_amount" integer, "p_reason" "text", "p_idempotency_key" "text", "p_club_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fet_admin_get_wallet_ledger"("p_club_id" bigint DEFAULT NULL::bigint, "p_search" "text" DEFAULT NULL::"text", "p_user_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "user_id" "uuid", "public_user_id" "text", "display_name" "text", "entry_type" "text", "direction" "text", "amount" integer, "balance_after" integer, "counterparty_user_id" "uuid", "counterparty_display_name" "text", "counterparty_public_user_id" "text", "note" "text", "reference_type" "text", "reference_id" "text", "created_at" timestamp with time zone, "total_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_club_id bigint;
  v_search text := nullif(btrim(coalesce(p_search, '')), '');
begin
  v_club_id := public.fet_require_club_context(p_club_id);

  if not (public.is_club_admin(v_club_id) or public.is_super_admin()) then
    raise exception 'Club admin access is required.';
  end if;

  return query
  with scoped as (
    select
      e.id,
      e.user_id,
      coalesce(nullif(btrim(p.public_user_id), ''), u.public_user_id) as public_user_id,
      coalesce(
        nullif(btrim(p.display_name), ''),
        nullif(btrim(p.full_name), ''),
        nullif(btrim(u.public_user_id), ''),
        'Supporter'
      ) as display_name,
      e.entry_type,
      e.direction,
      e.amount,
      e.balance_after,
      e.counterparty_user_id,
      coalesce(
        nullif(btrim(cp.display_name), ''),
        nullif(btrim(cp.full_name), ''),
        nullif(btrim(cu.public_user_id), ''),
        'Supporter'
      ) as counterparty_display_name,
      coalesce(nullif(btrim(cp.public_user_id), ''), cu.public_user_id) as counterparty_public_user_id,
      e.note,
      e.reference_type,
      e.reference_id,
      e.created_at,
      count(*) over() as total_count
    from public.fet_wallet_ledger_entries e
    left join public.profiles p
      on p.id = e.user_id
    left join public.users u
      on u.id = e.user_id
    left join public.profiles cp
      on cp.id = e.counterparty_user_id
    left join public.users cu
      on cu.id = e.counterparty_user_id
    where e.club_id = v_club_id
      and (p_user_id is null or e.user_id = p_user_id)
      and (
        v_search is null
        or coalesce(p.public_user_id, '') ilike '%' || v_search || '%'
        or coalesce(p.display_name, '') ilike '%' || v_search || '%'
        or coalesce(p.full_name, '') ilike '%' || v_search || '%'
        or coalesce(cp.public_user_id, '') ilike '%' || v_search || '%'
        or coalesce(cp.display_name, '') ilike '%' || v_search || '%'
        or coalesce(cp.full_name, '') ilike '%' || v_search || '%'
        or coalesce(e.reference_id, '') ilike '%' || v_search || '%'
      )
  )
  select
    scoped.id,
    scoped.user_id,
    scoped.public_user_id,
    scoped.display_name,
    scoped.entry_type,
    scoped.direction,
    scoped.amount,
    scoped.balance_after,
    scoped.counterparty_user_id,
    scoped.counterparty_display_name,
    scoped.counterparty_public_user_id,
    scoped.note,
    scoped.reference_type,
    scoped.reference_id,
    scoped.created_at,
    scoped.total_count
  from scoped
  order by scoped.created_at desc, scoped.id desc
  limit greatest(coalesce(p_limit, 100), 1)
  offset greatest(coalesce(p_offset, 0), 0);
end;
$$;


ALTER FUNCTION "public"."fet_admin_get_wallet_ledger"("p_club_id" bigint, "p_search" "text", "p_user_id" "uuid", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fet_admin_get_wallet_overview"("p_club_id" bigint DEFAULT NULL::bigint, "p_search" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS TABLE("user_id" "uuid", "public_user_id" "text", "display_name" "text", "tier" "text", "balance" integer, "transaction_count" integer, "last_transaction_at" timestamp with time zone, "lifetime_earned" integer, "lifetime_spent" integer, "total_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_club_id bigint;
  v_search text := nullif(btrim(coalesce(p_search, '')), '');
begin
  v_club_id := public.fet_require_club_context(p_club_id);

  if not (public.is_club_admin(v_club_id) or public.is_super_admin()) then
    raise exception 'Club admin access is required.';
  end if;

  return query
  with ledger_agg as (
    select
      e.user_id,
      count(*)::integer as transaction_count,
      max(e.created_at) as last_transaction_at,
      coalesce(sum(case when e.direction = 'credit' then e.amount else 0 end), 0)::integer as lifetime_earned,
      coalesce(sum(case when e.direction = 'debit' then e.amount else 0 end), 0)::integer as lifetime_spent
    from public.fet_wallet_ledger_entries e
    where e.club_id = v_club_id
    group by e.user_id
  ),
  scoped as (
    select
      p.id as user_id,
      coalesce(nullif(btrim(p.public_user_id), ''), u.public_user_id) as public_user_id,
      coalesce(
        nullif(btrim(p.display_name), ''),
        nullif(btrim(p.full_name), ''),
        nullif(btrim(u.public_user_id), ''),
        'Supporter'
      ) as display_name,
      coalesce(fm.tier, public.resolve_fan_tier(coalesce(fm.points, 0))) as tier,
      coalesce(fm.points, 0)::integer as balance,
      coalesce(la.transaction_count, 0)::integer as transaction_count,
      la.last_transaction_at,
      greatest(coalesce(la.lifetime_earned, 0), coalesce(fm.points, 0))::integer as lifetime_earned,
      coalesce(la.lifetime_spent, 0)::integer as lifetime_spent,
      count(*) over() as total_count
    from public.profiles p
    left join public.users u
      on u.id = p.id
    left join public.fan_memberships fm
      on fm.user_id = p.id
     and fm.club_id = v_club_id
    left join ledger_agg la
      on la.user_id = p.id
    where p.club_id = v_club_id
      and (
        v_search is null
        or coalesce(p.public_user_id, '') ilike '%' || v_search || '%'
        or coalesce(p.display_name, '') ilike '%' || v_search || '%'
        or coalesce(p.full_name, '') ilike '%' || v_search || '%'
        or coalesce(p.phone, '') ilike '%' || v_search || '%'
      )
  )
  select
    scoped.user_id,
    scoped.public_user_id,
    scoped.display_name,
    scoped.tier,
    scoped.balance,
    scoped.transaction_count,
    scoped.last_transaction_at,
    scoped.lifetime_earned,
    scoped.lifetime_spent,
    scoped.total_count
  from scoped
  order by scoped.balance desc, scoped.display_name asc
  limit greatest(coalesce(p_limit, 50), 1)
  offset greatest(coalesce(p_offset, 0), 0);
end;
$$;


ALTER FUNCTION "public"."fet_admin_get_wallet_overview"("p_club_id" bigint, "p_search" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fet_admin_update_reward_redemption"("p_redemption_id" "uuid", "p_status" "text", "p_fulfillment_channel" "text" DEFAULT NULL::"text", "p_fulfillment_reference" "text" DEFAULT NULL::"text", "p_admin_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_status text := lower(nullif(btrim(coalesce(p_status, '')), ''));
  v_redemption public.fet_reward_redemptions;
begin
  if auth.uid() is null then
    raise exception 'Authentication is required.';
  end if;

  if v_status not in ('pending', 'processing', 'fulfilled', 'cancelled', 'failed') then
    raise exception 'Unsupported redemption status.';
  end if;

  select *
    into v_redemption
  from public.fet_reward_redemptions redemption
  where redemption.id = p_redemption_id
  for update;

  if v_redemption.id is null then
    raise exception 'Reward redemption not found.';
  end if;

  if not (public.is_club_admin(v_redemption.club_id) or public.is_super_admin() or public.is_admin_user()) then
    raise exception 'Club admin access is required.';
  end if;

  update public.fet_reward_redemptions
  set status = v_status,
      fulfillment_channel = nullif(btrim(coalesce(p_fulfillment_channel, '')), ''),
      fulfillment_reference = nullif(btrim(coalesce(p_fulfillment_reference, '')), ''),
      admin_note = nullif(btrim(coalesce(p_admin_note, '')), ''),
      fulfilled_at = case
        when v_status = 'fulfilled' then timezone('utc', now())
        else fulfilled_at
      end,
      updated_at = timezone('utc', now())
  where id = v_redemption.id
  returning * into v_redemption;

  return jsonb_build_object(
    'status', v_redemption.status,
    'redemption_id', v_redemption.id,
    'message', format('Reward redemption marked %s.', v_redemption.status)
  );
end;
$$;


ALTER FUNCTION "public"."fet_admin_update_reward_redemption"("p_redemption_id" "uuid", "p_status" "text", "p_fulfillment_channel" "text", "p_fulfillment_reference" "text", "p_admin_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fet_find_supporters"("p_query" "text", "p_club_id" bigint DEFAULT NULL::bigint, "p_limit" integer DEFAULT 8) RETURNS TABLE("user_id" "uuid", "public_user_id" "text", "display_name" "text", "tier" "text", "balance" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_club_id bigint;
  v_query text := nullif(btrim(coalesce(p_query, '')), '');
begin
  if v_user_id is null then
    raise exception 'Authentication is required.';
  end if;

  if v_query is null then
    return;
  end if;

  v_club_id := public.fet_require_club_context(p_club_id);

  return query
  with scoped as (
    select
      p.id as user_id,
      coalesce(nullif(btrim(p.public_user_id), ''), u.public_user_id) as public_user_id,
      coalesce(
        nullif(btrim(p.display_name), ''),
        nullif(btrim(p.full_name), ''),
        nullif(btrim(u.public_user_id), ''),
        'Supporter'
      ) as display_name,
      coalesce(fm.tier, public.resolve_fan_tier(coalesce(fm.points, 0))) as tier,
      coalesce(fm.points, 0)::integer as balance
    from public.profiles p
    left join public.users u
      on u.id = p.id
    left join public.fan_memberships fm
      on fm.user_id = p.id
     and fm.club_id = v_club_id
    where p.club_id = v_club_id
      and p.id <> v_user_id
      and (
        coalesce(p.public_user_id, '') ilike '%' || v_query || '%'
        or coalesce(p.display_name, '') ilike '%' || v_query || '%'
        or coalesce(p.full_name, '') ilike '%' || v_query || '%'
        or coalesce(p.phone, '') ilike '%' || v_query || '%'
      )
  )
  select
    scoped.user_id,
    scoped.public_user_id,
    scoped.display_name,
    scoped.tier,
    scoped.balance
  from scoped
  order by scoped.balance desc, scoped.display_name asc
  limit greatest(coalesce(p_limit, 8), 1);
end;
$$;


ALTER FUNCTION "public"."fet_find_supporters"("p_query" "text", "p_club_id" bigint, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fet_get_catalog"("p_club_id" bigint DEFAULT NULL::bigint, "p_include_inactive" boolean DEFAULT false) RETURNS TABLE("id" "uuid", "club_id" bigint, "code" "text", "template_scope" "text", "category" "text", "item_name" "text", "fet_value" integer, "trigger_condition" "text", "activation_timing" "text", "description" "text", "badge_name" "text", "implementation_notes" "text", "sort_order" integer, "is_active" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_club_id bigint;
begin
  v_club_id := public.fet_resolve_public_club_id(p_club_id);
  if v_club_id is null then
    return;
  end if;

  return query
  select
    catalog.id,
    catalog.club_id,
    catalog.code,
    catalog.template_scope,
    catalog.category,
    catalog.item_name,
    catalog.fet_value,
    catalog.trigger_condition,
    catalog.activation_timing,
    catalog.description,
    catalog.badge_name,
    null::text as implementation_notes,
    catalog.sort_order,
    catalog.is_active
  from public.fan_engagement_token_catalog as catalog
  where catalog.club_id = v_club_id
    and (p_include_inactive or catalog.is_active)
  order by catalog.sort_order, catalog.code;
end;
$$;


ALTER FUNCTION "public"."fet_get_catalog"("p_club_id" bigint, "p_include_inactive" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fet_get_catalog"("p_club_id" bigint, "p_include_inactive" boolean) IS 'Public FET catalog with a compatibility-null implementation_notes field; internal implementation notes are never exposed.';



CREATE OR REPLACE FUNCTION "public"."fet_get_friends"("p_club_id" bigint DEFAULT NULL::bigint, "p_limit" integer DEFAULT 20, "p_search" "text" DEFAULT NULL::"text") RETURNS TABLE("user_id" "uuid", "public_user_id" "text", "display_name" "text", "tier" "text", "balance" integer, "friendship_id" "uuid", "friendship_status" "text", "is_online" boolean, "last_seen_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_club_id bigint;
  v_search text := nullif(btrim(coalesce(p_search, '')), '');
begin
  if v_user_id is null then
    raise exception 'Authentication is required.';
  end if;

  v_club_id := public.fet_require_club_context(p_club_id);

  return query
  with accepted_friendships as (
    select
      friendship.id,
      friendship.status,
      case
        when friendship.requester_user_id = v_user_id then friendship.addressee_user_id
        else friendship.requester_user_id
      end as friend_user_id
    from public.supporter_friendships friendship
    where friendship.club_id = v_club_id
      and friendship.status = 'accepted'
      and (
        friendship.requester_user_id = v_user_id
        or friendship.addressee_user_id = v_user_id
      )
  )
  select
    profile.id as user_id,
    coalesce(nullif(btrim(profile.public_user_id), ''), user_row.public_user_id) as public_user_id,
    case
      when coalesce(profile.privacy_show_real_name, false)
        and nullif(btrim(profile.full_name), '') is not null
        then profile.full_name
      else coalesce(
        nullif(btrim(profile.display_name), ''),
        nullif(btrim(profile.public_user_id), ''),
        nullif(btrim(user_row.public_user_id), ''),
        'Supporter'
      )
    end as display_name,
    coalesce(membership.tier, public.resolve_fan_tier(coalesce(membership.points, 0))) as tier,
    coalesce(membership.points, 0)::integer as balance,
    friendship.id as friendship_id,
    friendship.status as friendship_status,
    case
      when coalesce(privacy.show_activity_status, true) then coalesce(presence.is_online, false)
      else false
    end as is_online,
    case
      when coalesce(privacy.show_activity_status, true) then presence.last_seen_at
      else null
    end as last_seen_at
  from accepted_friendships friendship
  join public.profiles profile
    on profile.id = friendship.friend_user_id
  left join public.users user_row
    on user_row.id = profile.id
  left join public.fan_memberships membership
    on membership.user_id = profile.id
   and membership.club_id = v_club_id
  left join public.user_privacy_settings privacy
    on privacy.user_id = profile.id
   and coalesce(privacy.club_id, v_club_id) = v_club_id
  left join public.supporter_presence_catalog presence
    on presence.user_id = profile.id
   and presence.club_id = v_club_id
  where profile.club_id = v_club_id
    and (
      v_search is null
      or coalesce(profile.display_name, '') ilike '%' || v_search || '%'
      or coalesce(profile.full_name, '') ilike '%' || v_search || '%'
      or coalesce(profile.public_user_id, '') ilike '%' || v_search || '%'
    )
  order by
    coalesce(
      case
        when coalesce(privacy.show_activity_status, true) then presence.is_online
        else false
      end,
      false
    ) desc,
    coalesce(membership.points, 0) desc,
    coalesce(nullif(btrim(profile.display_name), ''), nullif(btrim(profile.full_name), ''), 'Supporter') asc
  limit greatest(coalesce(p_limit, 20), 1);
end;
$$;


ALTER FUNCTION "public"."fet_get_friends"("p_club_id" bigint, "p_limit" integer, "p_search" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."supporter_friendships" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "club_id" bigint NOT NULL,
    "requester_user_id" "uuid" NOT NULL,
    "addressee_user_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "last_action_by" "uuid",
    "requested_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    "responded_at" timestamp with time zone,
    "accepted_at" timestamp with time zone,
    "note" "text",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    CONSTRAINT "supporter_friendships_distinct_users_check" CHECK (("requester_user_id" <> "addressee_user_id")),
    CONSTRAINT "supporter_friendships_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'accepted'::"text", 'declined'::"text", 'blocked'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "public"."supporter_friendships" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fet_get_friendship_row"("p_self_user_id" "uuid", "p_other_user_id" "uuid", "p_club_id" bigint) RETURNS "public"."supporter_friendships"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select friendship.*
  from public.supporter_friendships friendship
  where friendship.club_id = p_club_id
    and (
      (
        friendship.requester_user_id = p_self_user_id
        and friendship.addressee_user_id = p_other_user_id
      ) or (
        friendship.requester_user_id = p_other_user_id
        and friendship.addressee_user_id = p_self_user_id
      )
    )
  order by friendship.created_at desc, friendship.id desc
  limit 1;
$$;


ALTER FUNCTION "public"."fet_get_friendship_row"("p_self_user_id" "uuid", "p_other_user_id" "uuid", "p_club_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fet_get_leaderboard"("p_club_id" bigint DEFAULT NULL::bigint, "p_limit" integer DEFAULT 10) RETURNS TABLE("rank" integer, "user_id" "uuid", "supporter_alias" "text", "display_name" "text", "total_fet" integer, "tier" "text", "is_current_user" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_club_id bigint;
  v_limit integer := GREATEST(COALESCE(p_limit, 10), 1);
BEGIN
  v_club_id := public.fet_resolve_public_club_id(p_club_id);
  IF v_club_id IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH ranked_rows AS (
    SELECT
      ROW_NUMBER() OVER (
        ORDER BY fm.points DESC, fm.joined_at ASC, fm.user_id ASC
      )::integer AS rank,
      fm.user_id,
      COALESCE(
        NULLIF(BTRIM(pr.public_user_id), ''),
        NULLIF(BTRIM(fm.display_name), ''),
        NULLIF(BTRIM(u.public_user_id), ''),
        '000000'
      ) AS supporter_alias,
      COALESCE(
        NULLIF(BTRIM(pr.display_name), ''),
        NULLIF(BTRIM(fm.display_name), ''),
        NULLIF(BTRIM(u.full_name), ''),
        'Supporter'
      ) AS display_name,
      GREATEST(COALESCE(fm.points, 0), 0)::integer AS total_fet,
      COALESCE(
        NULLIF(BTRIM(fm.tier), ''),
        public.resolve_fan_tier(GREATEST(COALESCE(fm.points, 0), 0))
      ) AS tier,
      (fm.user_id = auth.uid()) AS is_current_user
    FROM public.fan_memberships AS fm
    LEFT JOIN public.profiles AS pr
      ON pr.id = fm.user_id
    LEFT JOIN public.users AS u
      ON u.id = fm.user_id
    WHERE fm.club_id = v_club_id
  ),
  top_rows AS (
    SELECT *
    FROM ranked_rows
    ORDER BY rank ASC
    LIMIT v_limit
  ),
  current_row AS (
    SELECT *
    FROM ranked_rows AS ranked_entry
    WHERE ranked_entry.user_id = auth.uid()
      AND NOT EXISTS (
        SELECT 1
        FROM top_rows
        WHERE top_rows.user_id = auth.uid()
      )
  )
  SELECT
    combined.rank,
    combined.user_id,
    combined.supporter_alias,
    combined.display_name,
    combined.total_fet,
    combined.tier,
    combined.is_current_user
  FROM (
    SELECT * FROM top_rows
    UNION ALL
    SELECT * FROM current_row
  ) AS combined
  ORDER BY combined.rank ASC;
END;
$$;


ALTER FUNCTION "public"."fet_get_leaderboard"("p_club_id" bigint, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fet_get_partner_offers"("p_club_id" bigint DEFAULT NULL::bigint, "p_include_inactive" boolean DEFAULT false, "p_limit" integer DEFAULT 500) RETURNS TABLE("id" "uuid", "club_id" bigint, "catalog_item_id" "uuid", "code" "text", "partner_id" "uuid", "partner_slug" "text", "partner_name" "text", "partner_emoji" "text", "partner_category" "text", "partner_subtitle" "text", "partner_brand_primary_color" "text", "partner_brand_secondary_color" "text", "title" "text", "subtitle" "text", "fet_value" integer, "trigger_condition" "text", "activation_timing" "text", "description" "text", "badge_name" "text", "cta_label" "text", "verification_mode" "text", "deeplink_route" "text", "external_url" "text", "is_featured" boolean, "is_active" boolean, "sort_order" integer, "metadata" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_club_id bigint;
  v_limit integer := greatest(coalesce(p_limit, 50), 1);
begin
  v_club_id := public.fet_resolve_public_club_id(p_club_id);
  if v_club_id is null then
    return;
  end if;

  return query
  select
    offer.id,
    offer.club_id,
    offer.catalog_item_id,
    catalog.code,
    offer.partner_id,
    partner.slug as partner_slug,
    partner.name as partner_name,
    partner.emoji as partner_emoji,
    partner.category as partner_category,
    partner.subtitle as partner_subtitle,
    partner.brand_primary_color as partner_brand_primary_color,
    partner.brand_secondary_color as partner_brand_secondary_color,
    catalog.item_name as title,
    coalesce(
      nullif(btrim(offer.subtitle), ''),
      nullif(btrim(partner.subtitle), ''),
      nullif(btrim(catalog.activation_timing), ''),
      'Partner offer'
    ) as subtitle,
    catalog.fet_value,
    catalog.trigger_condition,
    catalog.activation_timing,
    catalog.description,
    nullif(btrim(catalog.badge_name), '') as badge_name,
    offer.cta_label,
    offer.verification_mode,
    offer.deeplink_route,
    offer.external_url,
    offer.is_featured,
    offer.is_active,
    offer.sort_order,
    jsonb_strip_nulls(
      coalesce(offer.metadata, '{}'::jsonb)
      || jsonb_build_object(
        'partner_website_url', nullif(btrim(coalesce(partner.website_url, '')), ''),
        'partner_banner_url', nullif(btrim(coalesce(partner.banner_url, '')), '')
      )
    ) as metadata
  from public.fet_partner_offers as offer
  join public.fan_engagement_token_catalog as catalog
    on catalog.id = offer.catalog_item_id
  join public.partners as partner
    on partner.id = offer.partner_id
  where offer.club_id = v_club_id
    and catalog.club_id = v_club_id
    and partner.is_active = true
    and (p_include_inactive or offer.is_active = true)
  order by
    offer.is_featured desc,
    offer.sort_order asc,
    catalog.fet_value desc,
    catalog.code asc
  limit v_limit;
end;
$$;


ALTER FUNCTION "public"."fet_get_partner_offers"("p_club_id" bigint, "p_include_inactive" boolean, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fet_get_reward_redemptions"("p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0, "p_club_id" bigint DEFAULT NULL::bigint) RETURNS TABLE("id" "uuid", "reward_item_id" "uuid", "reward_slug" "text", "reward_title" "text", "cost_fet" integer, "wallet_reference_id" "text", "status" "text", "fulfillment_channel" "text", "fulfillment_reference" "text", "supporter_note" "text", "admin_note" "text", "consumed_at" timestamp with time zone, "fulfilled_at" timestamp with time zone, "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_club_id bigint;
begin
  if v_user_id is null then
    raise exception 'Authentication is required.';
  end if;

  v_club_id := public.fet_require_club_context(p_club_id);

  return query
  select
    redemption.id,
    redemption.reward_item_id,
    redemption.reward_slug,
    redemption.reward_title,
    redemption.cost_fet,
    redemption.wallet_reference_id,
    redemption.status,
    redemption.fulfillment_channel,
    redemption.fulfillment_reference,
    redemption.supporter_note,
    redemption.admin_note,
    redemption.consumed_at,
    redemption.fulfilled_at,
    redemption.created_at
  from public.fet_reward_redemptions redemption
  where redemption.user_id = v_user_id
    and redemption.club_id = v_club_id
  order by redemption.created_at desc
  limit greatest(coalesce(p_limit, 20), 1)
  offset greatest(coalesce(p_offset, 0), 0);
end;
$$;


ALTER FUNCTION "public"."fet_get_reward_redemptions"("p_limit" integer, "p_offset" integer, "p_club_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fet_get_wallet"("p_club_id" bigint DEFAULT NULL::bigint) RETURNS TABLE("user_id" "uuid", "club_id" bigint, "membership_id" "uuid", "balance" integer, "tier" "text", "weekly_earned" integer, "monthly_earned" integer, "lifetime_earned" integer, "lifetime_spent" integer, "transaction_count" integer, "legacy_balance_gap" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_club_id bigint;
  v_membership public.fan_memberships;
begin
  if v_user_id is null then
    raise exception 'Authentication is required.';
  end if;

  v_club_id := public.fet_require_club_context(p_club_id);
  perform public.fet_wallet_ensure_membership(v_user_id, v_club_id);

  select *
    into v_membership
    from public.fan_memberships
   where fan_memberships.user_id = v_user_id
     and fan_memberships.club_id = v_club_id
   limit 1;

  return query
  with ledger as (
    select e.*
    from public.fet_wallet_ledger_entries e
    where e.club_id = v_club_id
      and e.user_id = v_user_id
  ),
  aggregates as (
    select
      coalesce(sum(case when direction = 'credit' and entry_type = 'earn' and created_at >= timezone('utc', now()) - interval '7 days' then amount else 0 end), 0)::integer as weekly_earned,
      coalesce(sum(case when direction = 'credit' and entry_type = 'earn' and created_at >= timezone('utc', now()) - interval '30 days' then amount else 0 end), 0)::integer as monthly_earned,
      coalesce(sum(case when direction = 'credit' then amount else 0 end), 0)::integer as lifetime_earned,
      coalesce(sum(case when direction = 'debit' then amount else 0 end), 0)::integer as lifetime_spent,
      count(*)::integer as transaction_count,
      coalesce(sum(case when direction = 'credit' then amount else -amount end), 0)::integer as ledger_net
    from ledger
  )
  select
    v_user_id,
    v_club_id,
    v_membership.id,
    coalesce(v_membership.points, 0)::integer,
    coalesce(v_membership.tier, public.resolve_fan_tier(coalesce(v_membership.points, 0))),
    aggregates.weekly_earned,
    aggregates.monthly_earned,
    greatest(aggregates.lifetime_earned, coalesce(v_membership.points, 0))::integer,
    aggregates.lifetime_spent,
    aggregates.transaction_count,
    greatest(coalesce(v_membership.points, 0) - greatest(aggregates.ledger_net, 0), 0)::integer
  from aggregates;
end;
$$;


ALTER FUNCTION "public"."fet_get_wallet"("p_club_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fet_get_wallet_transactions"("p_club_id" bigint DEFAULT NULL::bigint, "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "entry_type" "text", "direction" "text", "amount" integer, "balance_after" integer, "counterparty_user_id" "uuid", "counterparty_display_name" "text", "counterparty_public_user_id" "text", "note" "text", "reference_type" "text", "reference_id" "text", "created_at" timestamp with time zone, "total_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_club_id bigint;
begin
  if v_user_id is null then
    raise exception 'Authentication is required.';
  end if;

  v_club_id := public.fet_require_club_context(p_club_id);

  return query
  with scoped as (
    select
      e.id,
      e.entry_type,
      e.direction,
      e.amount,
      e.balance_after,
      e.counterparty_user_id,
      coalesce(
        nullif(btrim(cp.display_name), ''),
        nullif(btrim(cp.full_name), ''),
        nullif(btrim(cu.public_user_id), ''),
        'Supporter'
      ) as counterparty_display_name,
      cp.public_user_id as counterparty_public_user_id,
      e.note,
      e.reference_type,
      e.reference_id,
      e.created_at,
      count(*) over() as total_count
    from public.fet_wallet_ledger_entries e
    left join public.profiles cp
      on cp.id = e.counterparty_user_id
    left join public.users cu
      on cu.id = e.counterparty_user_id
    where e.club_id = v_club_id
      and e.user_id = v_user_id
  )
  select
    scoped.id,
    scoped.entry_type,
    scoped.direction,
    scoped.amount,
    scoped.balance_after,
    scoped.counterparty_user_id,
    scoped.counterparty_display_name,
    scoped.counterparty_public_user_id,
    scoped.note,
    scoped.reference_type,
    scoped.reference_id,
    scoped.created_at,
    scoped.total_count
  from scoped
  order by scoped.created_at desc, scoped.id desc
  limit greatest(coalesce(p_limit, 50), 1)
  offset greatest(coalesce(p_offset, 0), 0);
end;
$$;


ALTER FUNCTION "public"."fet_get_wallet_transactions"("p_club_id" bigint, "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fet_redeem"("p_amount" integer, "p_note" "text" DEFAULT NULL::"text", "p_idempotency_key" "text" DEFAULT NULL::"text", "p_club_id" bigint DEFAULT NULL::bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_club_id bigint;
  v_membership public.fan_memberships;
  v_existing public.fet_wallet_ledger_entries;
  v_amount integer := greatest(coalesce(p_amount, 0), 0);
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_idempotency_key text := nullif(btrim(coalesce(p_idempotency_key, '')), '');
  v_reference_id text := gen_random_uuid()::text;
begin
  if v_user_id is null then
    raise exception 'Authentication is required.';
  end if;

  if v_amount <= 0 then
    raise exception 'Redemption amount must be greater than zero.';
  end if;

  v_club_id := public.fet_require_club_context(p_club_id);

  if v_idempotency_key is not null then
    select *
      into v_existing
      from public.fet_wallet_ledger_entries e
     where e.club_id = v_club_id
       and e.user_id = v_user_id
       and e.idempotency_key = v_idempotency_key
       and e.entry_type = 'redeem'
     order by e.created_at desc, e.id desc
     limit 1;

    if v_existing.id is not null then
      return jsonb_build_object(
        'status', 'success',
        'already_processed', true,
        'amount', v_existing.amount,
        'balance', v_existing.balance_after,
        'reference_id', v_existing.reference_id
      );
    end if;
  end if;

  perform public.fet_wallet_ensure_membership(v_user_id, v_club_id);

  select *
    into v_membership
    from public.fan_memberships
   where user_id = v_user_id
     and club_id = v_club_id
   for update;

  if coalesce(v_membership.points, 0) < v_amount then
    raise exception 'Insufficient FET balance.';
  end if;

  update public.fan_memberships
     set points = points - v_amount,
         tier = public.resolve_fan_tier(points - v_amount),
         updated_at = timezone('utc', now())
   where id = v_membership.id
  returning * into v_membership;

  perform public.fet_wallet_append_entry(
    p_club_id := v_club_id,
    p_user_id := v_user_id,
    p_membership_id := v_membership.id,
    p_entry_type := 'redeem',
    p_direction := 'debit',
    p_amount := v_amount,
    p_balance_after := v_membership.points,
    p_counterparty_user_id := null,
    p_reference_type := 'redemption',
    p_reference_id := v_reference_id,
    p_idempotency_key := v_idempotency_key,
    p_note := coalesce(v_note, 'Wallet redemption request'),
    p_metadata := jsonb_build_object('channel', 'wallet_redemption'),
    p_created_by := v_user_id
  );

  return jsonb_build_object(
    'status', 'success',
    'amount', v_amount,
    'balance', v_membership.points,
    'reference_id', v_reference_id
  );
end;
$$;


ALTER FUNCTION "public"."fet_redeem"("p_amount" integer, "p_note" "text", "p_idempotency_key" "text", "p_club_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fet_redeem_reward"("p_reward_item_id" "uuid", "p_note" "text" DEFAULT NULL::"text", "p_idempotency_key" "text" DEFAULT NULL::"text", "p_club_id" bigint DEFAULT NULL::bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_club_id bigint;
  v_idempotency_key text := nullif(btrim(coalesce(p_idempotency_key, '')), '');
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_item public.fet_reward_store_items;
  v_existing public.fet_reward_redemptions;
  v_redeem_result jsonb;
  v_redemption public.fet_reward_redemptions;
begin
  if v_user_id is null then
    raise exception 'Authentication is required.';
  end if;

  if p_reward_item_id is null then
    raise exception 'Reward item is required.';
  end if;

  v_club_id := public.fet_require_club_context(p_club_id);

  select *
    into v_item
  from public.fet_reward_store_items item
  where item.id = p_reward_item_id
    and item.is_active = true
    and (item.club_id is null or item.club_id = v_club_id)
  limit 1;

  if v_item.id is null then
    raise exception 'Reward item not found.';
  end if;

  if v_item.cost_fet <= 0 then
    raise exception 'Reward item is not redeemable.';
  end if;

  if v_idempotency_key is not null then
    select *
      into v_existing
    from public.fet_reward_redemptions redemption
    where redemption.club_id = v_club_id
      and redemption.user_id = v_user_id
      and redemption.idempotency_key = v_idempotency_key
    order by redemption.created_at desc, redemption.id desc
    limit 1;

    if v_existing.id is not null then
      return jsonb_build_object(
        'status', 'submitted',
        'already_processed', true,
        'redemption_id', v_existing.id,
        'reward_item_id', v_existing.reward_item_id,
        'reward_slug', v_existing.reward_slug,
        'reward_title', v_existing.reward_title,
        'balance', null,
        'reference_id', v_existing.wallet_reference_id,
        'message', 'Reward redemption already recorded.'
      );
    end if;
  end if;

  v_redeem_result := public.fet_redeem(
    p_amount := v_item.cost_fet,
    p_note := coalesce(v_note, format('FANZONE reward: %s', v_item.reward)),
    p_idempotency_key := v_idempotency_key,
    p_club_id := v_club_id
  );

  insert into public.fet_reward_redemptions (
    club_id,
    user_id,
    reward_item_id,
    reward_slug,
    reward_title,
    cost_fet,
    wallet_reference_id,
    status,
    supporter_note,
    idempotency_key,
    metadata
  )
  values (
    v_club_id,
    v_user_id,
    v_item.id,
    v_item.slug,
    v_item.reward,
    v_item.cost_fet,
    nullif(v_redeem_result ->> 'reference_id', ''),
    'pending',
    v_note,
    v_idempotency_key,
    jsonb_build_object(
      'cost_label', v_item.cost_label,
      'category', v_item.category,
      'emoji', v_item.emoji,
      'wallet_status', v_redeem_result ->> 'status'
    )
  )
  returning * into v_redemption;

  return jsonb_build_object(
    'status', 'submitted',
    'already_processed', false,
    'redemption_id', v_redemption.id,
    'reward_item_id', v_redemption.reward_item_id,
    'reward_slug', v_redemption.reward_slug,
    'reward_title', v_redemption.reward_title,
    'balance', (v_redeem_result ->> 'balance')::integer,
    'reference_id', v_redemption.wallet_reference_id,
    'message', format('Redeemed %s.', v_redemption.reward_title)
  );
exception
  when unique_violation then
    if v_idempotency_key is null then
      raise;
    end if;

    select *
      into v_existing
    from public.fet_reward_redemptions redemption
    where redemption.club_id = v_club_id
      and redemption.user_id = v_user_id
      and redemption.idempotency_key = v_idempotency_key
    order by redemption.created_at desc, redemption.id desc
    limit 1;

    if v_existing.id is null then
      raise;
    end if;

    return jsonb_build_object(
      'status', 'submitted',
      'already_processed', true,
      'redemption_id', v_existing.id,
      'reward_item_id', v_existing.reward_item_id,
      'reward_slug', v_existing.reward_slug,
      'reward_title', v_existing.reward_title,
      'balance', null,
      'reference_id', v_existing.wallet_reference_id,
      'message', 'Reward redemption already recorded.'
    );
end;
$$;


ALTER FUNCTION "public"."fet_redeem_reward"("p_reward_item_id" "uuid", "p_note" "text", "p_idempotency_key" "text", "p_club_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fet_request_friend"("p_target_user_id" "uuid", "p_club_id" bigint DEFAULT NULL::bigint, "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_club_id bigint;
  v_existing public.supporter_friendships;
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
begin
  if v_user_id is null then
    raise exception 'Authentication is required.';
  end if;

  if p_target_user_id is null then
    raise exception 'A supporter is required.';
  end if;

  if p_target_user_id = v_user_id then
    raise exception 'You cannot add yourself.';
  end if;

  v_club_id := public.fet_require_club_context(p_club_id);

  if not exists (
    select 1
    from public.profiles profile
    where profile.id = p_target_user_id
      and profile.club_id = v_club_id
  ) then
    raise exception 'Supporter not found in this club context.';
  end if;

  select *
    into v_existing
  from public.fet_get_friendship_row(v_user_id, p_target_user_id, v_club_id);

  if v_existing.id is not null then
    if v_existing.status = 'accepted' then
      return jsonb_build_object(
        'status', 'accepted',
        'friendship_id', v_existing.id,
        'message', 'You are already friends.'
      );
    end if;

    if v_existing.status = 'pending' and v_existing.requester_user_id = v_user_id then
      return jsonb_build_object(
        'status', 'pending_outgoing',
        'friendship_id', v_existing.id,
        'message', 'Friend request already sent.'
      );
    end if;

    if v_existing.status = 'pending' and v_existing.addressee_user_id = v_user_id then
      update public.supporter_friendships
      set status = 'accepted',
          last_action_by = v_user_id,
          responded_at = timezone('utc', now()),
          accepted_at = timezone('utc', now()),
          updated_at = timezone('utc', now())
      where id = v_existing.id;

      return jsonb_build_object(
        'status', 'accepted',
        'friendship_id', v_existing.id,
        'message', 'Friend request accepted.'
      );
    end if;

    if v_existing.status = 'blocked' and coalesce(v_existing.last_action_by, p_target_user_id) <> v_user_id then
      raise exception 'This supporter is not available for friend requests.';
    end if;

    update public.supporter_friendships
    set requester_user_id = v_user_id,
        addressee_user_id = p_target_user_id,
        status = 'pending',
        last_action_by = v_user_id,
        requested_at = timezone('utc', now()),
        responded_at = null,
        accepted_at = null,
        note = v_note,
        metadata = coalesce(metadata, '{}'::jsonb),
        updated_at = timezone('utc', now())
    where id = v_existing.id;

    return jsonb_build_object(
      'status', 'pending_outgoing',
      'friendship_id', v_existing.id,
      'message', 'Friend request sent.'
    );
  end if;

  insert into public.supporter_friendships (
    club_id,
    requester_user_id,
    addressee_user_id,
    status,
    last_action_by,
    note
  )
  values (
    v_club_id,
    v_user_id,
    p_target_user_id,
    'pending',
    v_user_id,
    v_note
  )
  returning * into v_existing;

  return jsonb_build_object(
    'status', 'pending_outgoing',
    'friendship_id', v_existing.id,
    'message', 'Friend request sent.'
  );
end;
$$;


ALTER FUNCTION "public"."fet_request_friend"("p_target_user_id" "uuid", "p_club_id" bigint, "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fet_require_club_context"("p_club_id" bigint DEFAULT NULL::bigint) RETURNS bigint
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_claims jsonb := coalesce(
    nullif(pg_catalog.current_setting('request.jwt.claims', true), '')::jsonb,
    '{}'::jsonb
  );
  v_role text;
  v_trusted_club_id bigint;
begin
  v_role := coalesce(
    nullif(pg_catalog.current_setting('request.jwt.claim.role', true), ''),
    nullif(v_claims ->> 'role', '')
  );

  begin
    v_trusted_club_id := nullif(public.requesting_club_id(), '')::bigint;
  exception
    when invalid_text_representation then
      raise exception 'A valid trusted club context is required.';
  end;

  if v_role = 'service_role' then
    v_trusted_club_id := coalesce(p_club_id, v_trusted_club_id);
  else
    if v_actor_id is null then
      raise exception 'Authentication is required.';
    end if;

    if v_trusted_club_id is null then
      raise exception 'A trusted club context is required.';
    end if;

    if p_club_id is not null and p_club_id is distinct from v_trusted_club_id then
      raise exception 'Requested club does not match the authenticated club context.';
    end if;
  end if;

  if v_trusted_club_id is null then
    raise exception 'Club context required for FET wallet operations.';
  end if;

  return v_trusted_club_id;
end;
$$;


ALTER FUNCTION "public"."fet_require_club_context"("p_club_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fet_resolve_public_club_id"("p_club_id" bigint DEFAULT NULL::bigint) RETURNS bigint
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
  SELECT COALESCE(
    p_club_id,
    CASE
      WHEN COALESCE(public.requesting_club_id(), '') ~ '^[0-9]+$'
        THEN public.requesting_club_id()::bigint
      ELSE NULL::bigint
    END
  );
$_$;


ALTER FUNCTION "public"."fet_resolve_public_club_id"("p_club_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fet_respond_friend_request"("p_friendship_id" "uuid", "p_action" "text", "p_club_id" bigint DEFAULT NULL::bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_club_id bigint;
  v_action text := lower(nullif(btrim(coalesce(p_action, '')), ''));
  v_friendship public.supporter_friendships;
begin
  if v_user_id is null then
    raise exception 'Authentication is required.';
  end if;

  if p_friendship_id is null then
    raise exception 'Friend request is required.';
  end if;

  if v_action not in ('accepted', 'declined', 'cancelled', 'blocked') then
    raise exception 'Unsupported friend action.';
  end if;

  v_club_id := public.fet_require_club_context(p_club_id);

  select *
    into v_friendship
  from public.supporter_friendships friendship
  where friendship.id = p_friendship_id
    and friendship.club_id = v_club_id
  for update;

  if v_friendship.id is null then
    raise exception 'Friend request not found.';
  end if;

  if v_action in ('accepted', 'declined') and v_friendship.addressee_user_id <> v_user_id then
    raise exception 'Only the invited supporter can accept or decline this request.';
  end if;

  if v_action = 'cancelled' and v_friendship.requester_user_id <> v_user_id then
    raise exception 'Only the requester can cancel this request.';
  end if;

  if v_action = 'blocked'
     and v_user_id not in (v_friendship.requester_user_id, v_friendship.addressee_user_id) then
    raise exception 'Only participants can block a supporter.';
  end if;

  update public.supporter_friendships
  set status = v_action,
      last_action_by = v_user_id,
      responded_at = case
        when v_action in ('accepted', 'declined', 'blocked') then timezone('utc', now())
        else responded_at
      end,
      accepted_at = case
        when v_action = 'accepted' then timezone('utc', now())
        else null
      end,
      updated_at = timezone('utc', now())
  where id = v_friendship.id
  returning * into v_friendship;

  return jsonb_build_object(
    'status', v_friendship.status,
    'friendship_id', v_friendship.id,
    'message', case v_friendship.status
      when 'accepted' then 'Friend request accepted.'
      when 'declined' then 'Friend request declined.'
      when 'cancelled' then 'Friend request cancelled.'
      when 'blocked' then 'Supporter blocked.'
      else 'Friend request updated.'
    end
  );
end;
$$;


ALTER FUNCTION "public"."fet_respond_friend_request"("p_friendship_id" "uuid", "p_action" "text", "p_club_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fet_search_supporters"("p_query" "text", "p_club_id" bigint DEFAULT NULL::bigint, "p_limit" integer DEFAULT 8) RETURNS TABLE("user_id" "uuid", "public_user_id" "text", "display_name" "text", "tier" "text", "balance" integer, "friendship_id" "uuid", "friendship_status" "text", "is_online" boolean, "last_seen_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_club_id bigint;
  v_query text := nullif(btrim(coalesce(p_query, '')), '');
begin
  if v_user_id is null then
    raise exception 'Authentication is required.';
  end if;

  if v_query is null then
    return;
  end if;

  v_club_id := public.fet_require_club_context(p_club_id);

  return query
  with scoped as (
    select
      profile.id as user_id,
      coalesce(nullif(btrim(profile.public_user_id), ''), user_row.public_user_id) as public_user_id,
      case
        when coalesce(profile.privacy_show_real_name, false)
          and nullif(btrim(profile.full_name), '') is not null
          then profile.full_name
        else coalesce(
          nullif(btrim(profile.display_name), ''),
          nullif(btrim(profile.public_user_id), ''),
          nullif(btrim(user_row.public_user_id), ''),
          'Supporter'
        )
      end as display_name,
      coalesce(membership.tier, public.resolve_fan_tier(coalesce(membership.points, 0))) as tier,
      coalesce(membership.points, 0)::integer as balance,
      friendship.id as friendship_id,
      case
        when friendship.id is null then 'none'
        when friendship.status = 'pending' and friendship.requester_user_id = v_user_id then 'pending_outgoing'
        when friendship.status = 'pending' and friendship.addressee_user_id = v_user_id then 'pending_incoming'
        else friendship.status
      end as friendship_status,
      case
        when coalesce(privacy.show_activity_status, true) then coalesce(presence.is_online, false)
        else false
      end as is_online,
      case
        when coalesce(privacy.show_activity_status, true) then presence.last_seen_at
        else null
      end as last_seen_at
    from public.profiles profile
    left join public.users user_row
      on user_row.id = profile.id
    left join public.fan_memberships membership
      on membership.user_id = profile.id
     and membership.club_id = v_club_id
    left join lateral (
      select *
      from public.fet_get_friendship_row(v_user_id, profile.id, v_club_id)
    ) friendship on true
    left join public.user_privacy_settings privacy
      on privacy.user_id = profile.id
     and coalesce(privacy.club_id, v_club_id) = v_club_id
    left join public.supporter_presence_catalog presence
      on presence.user_id = profile.id
     and presence.club_id = v_club_id
    where profile.club_id = v_club_id
      and profile.id <> v_user_id
      and (
        coalesce(profile.public_user_id, '') ilike '%' || v_query || '%'
        or coalesce(profile.display_name, '') ilike '%' || v_query || '%'
        or coalesce(profile.full_name, '') ilike '%' || v_query || '%'
        or (
          coalesce(profile.privacy_findable_by_phone, false)
          and coalesce(profile.phone, '') ilike '%' || v_query || '%'
        )
      )
  )
  select
    scoped.user_id,
    scoped.public_user_id,
    scoped.display_name,
    scoped.tier,
    scoped.balance,
    scoped.friendship_id,
    scoped.friendship_status,
    scoped.is_online,
    scoped.last_seen_at
  from scoped
  order by
    case scoped.friendship_status
      when 'accepted' then 0
      when 'pending_incoming' then 1
      when 'pending_outgoing' then 2
      when 'none' then 3
      else 4
    end asc,
    scoped.balance desc,
    scoped.display_name asc
  limit greatest(coalesce(p_limit, 8), 1);
end;
$$;


ALTER FUNCTION "public"."fet_search_supporters"("p_query" "text", "p_club_id" bigint, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fet_transfer"("p_recipient_user_id" "uuid", "p_amount" integer, "p_note" "text" DEFAULT NULL::"text", "p_idempotency_key" "text" DEFAULT NULL::"text", "p_club_id" bigint DEFAULT NULL::bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_sender_id uuid := auth.uid();
  v_club_id bigint;
  v_sender public.fan_memberships;
  v_recipient public.fan_memberships;
  v_existing public.fet_wallet_ledger_entries;
  v_amount integer := greatest(coalesce(p_amount, 0), 0);
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_idempotency_key text := nullif(btrim(coalesce(p_idempotency_key, '')), '');
  v_reference_id text := gen_random_uuid()::text;
begin
  if v_sender_id is null then
    raise exception 'Authentication is required.';
  end if;

  if p_recipient_user_id is null then
    raise exception 'Recipient is required.';
  end if;

  if p_recipient_user_id = v_sender_id then
    raise exception 'You cannot transfer FET to yourself.';
  end if;

  if v_amount <= 0 then
    raise exception 'Transfer amount must be greater than zero.';
  end if;

  v_club_id := public.fet_require_club_context(p_club_id);

  if v_idempotency_key is not null then
    select *
      into v_existing
      from public.fet_wallet_ledger_entries e
     where e.club_id = v_club_id
       and e.user_id = v_sender_id
       and e.idempotency_key = v_idempotency_key
       and e.entry_type = 'transfer_out'
     order by e.created_at desc, e.id desc
     limit 1;

    if v_existing.id is not null then
      return jsonb_build_object(
        'status', 'success',
        'already_processed', true,
        'amount', v_existing.amount,
        'balance', v_existing.balance_after,
        'reference_id', v_existing.reference_id
      );
    end if;
  end if;

  perform public.fet_wallet_ensure_membership(v_sender_id, v_club_id);
  perform public.fet_wallet_ensure_membership(p_recipient_user_id, v_club_id);

  select *
    into v_sender
    from public.fan_memberships
   where user_id = v_sender_id
     and club_id = v_club_id
   for update;

  select *
    into v_recipient
    from public.fan_memberships
   where user_id = p_recipient_user_id
     and club_id = v_club_id
   for update;

  if coalesce(v_sender.points, 0) < v_amount then
    raise exception 'Insufficient FET balance.';
  end if;

  update public.fan_memberships
     set points = points - v_amount,
         tier = public.resolve_fan_tier(points - v_amount),
         updated_at = timezone('utc', now())
   where id = v_sender.id
  returning * into v_sender;

  update public.fan_memberships
     set points = points + v_amount,
         tier = public.resolve_fan_tier(points + v_amount),
         renewed_at = timezone('utc', now()),
         updated_at = timezone('utc', now())
   where id = v_recipient.id
  returning * into v_recipient;

  perform public.fet_wallet_append_entry(
    p_club_id := v_club_id,
    p_user_id := v_sender_id,
    p_membership_id := v_sender.id,
    p_entry_type := 'transfer_out',
    p_direction := 'debit',
    p_amount := v_amount,
    p_balance_after := v_sender.points,
    p_counterparty_user_id := p_recipient_user_id,
    p_reference_type := 'transfer',
    p_reference_id := v_reference_id,
    p_idempotency_key := v_idempotency_key,
    p_note := v_note,
    p_metadata := jsonb_build_object('channel', 'wallet_transfer'),
    p_created_by := v_sender_id
  );

  perform public.fet_wallet_append_entry(
    p_club_id := v_club_id,
    p_user_id := p_recipient_user_id,
    p_membership_id := v_recipient.id,
    p_entry_type := 'transfer_in',
    p_direction := 'credit',
    p_amount := v_amount,
    p_balance_after := v_recipient.points,
    p_counterparty_user_id := v_sender_id,
    p_reference_type := 'transfer',
    p_reference_id := v_reference_id,
    p_idempotency_key := v_idempotency_key,
    p_note := v_note,
    p_metadata := jsonb_build_object('channel', 'wallet_transfer'),
    p_created_by := v_sender_id
  );

  return jsonb_build_object(
    'status', 'success',
    'amount', v_amount,
    'balance', v_sender.points,
    'reference_id', v_reference_id,
    'recipient_user_id', p_recipient_user_id
  );
end;
$$;


ALTER FUNCTION "public"."fet_transfer"("p_recipient_user_id" "uuid", "p_amount" integer, "p_note" "text", "p_idempotency_key" "text", "p_club_id" bigint) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."fet_wallet_ledger_entries" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "club_id" bigint NOT NULL,
    "user_id" "uuid" NOT NULL,
    "membership_id" "uuid",
    "entry_type" "text" NOT NULL,
    "direction" "text" NOT NULL,
    "amount" integer NOT NULL,
    "balance_after" integer NOT NULL,
    "counterparty_user_id" "uuid",
    "reference_type" "text",
    "reference_id" "text",
    "idempotency_key" "text",
    "note" "text",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    CONSTRAINT "fet_wallet_ledger_entries_amount_check" CHECK (("amount" > 0)),
    CONSTRAINT "fet_wallet_ledger_entries_balance_after_check" CHECK (("balance_after" >= 0)),
    CONSTRAINT "fet_wallet_ledger_entries_direction_check" CHECK (("direction" = ANY (ARRAY['credit'::"text", 'debit'::"text"]))),
    CONSTRAINT "fet_wallet_ledger_entries_type_check" CHECK (("entry_type" = ANY (ARRAY['earn'::"text", 'transfer_in'::"text", 'transfer_out'::"text", 'redeem'::"text", 'admin_adjustment'::"text", 'opening_balance'::"text", 'partner_promotion_earn'::"text", 'partner_pool_entry'::"text", 'partner_pool_payout'::"text", 'partner_pool_refund'::"text"])))
);


ALTER TABLE "public"."fet_wallet_ledger_entries" OWNER TO "postgres";


COMMENT ON TABLE "public"."fet_wallet_ledger_entries" IS 'Auditable supporter FET wallet ledger. fan_memberships.points remains the current wallet balance.';



COMMENT ON COLUMN "public"."fet_wallet_ledger_entries"."entry_type" IS 'Wallet operation type: earn, partner_promotion_earn, partner_pool_entry, partner_pool_payout, partner_pool_refund, transfer_in, transfer_out, redeem, admin_adjustment, or opening_balance. Public transfers/redeems are legacy-disabled for launch.';



COMMENT ON COLUMN "public"."fet_wallet_ledger_entries"."idempotency_key" IS 'Optional client-generated operation key used to make transfer/redeem/admin actions retry-safe.';



COMMENT ON COLUMN "public"."fet_wallet_ledger_entries"."created_by" IS 'Auth user that executed the wallet action. This can be an admin account without a public.users profile row.';



CREATE OR REPLACE FUNCTION "public"."fet_wallet_append_entry"("p_club_id" bigint, "p_user_id" "uuid", "p_membership_id" "uuid", "p_entry_type" "text", "p_direction" "text", "p_amount" integer, "p_balance_after" integer, "p_counterparty_user_id" "uuid" DEFAULT NULL::"uuid", "p_reference_type" "text" DEFAULT NULL::"text", "p_reference_id" "text" DEFAULT NULL::"text", "p_idempotency_key" "text" DEFAULT NULL::"text", "p_note" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."fet_wallet_ledger_entries"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_entry public.fet_wallet_ledger_entries;
  v_idempotency_key text := nullif(btrim(coalesce(p_idempotency_key, '')), '');
begin
  insert into public.fet_wallet_ledger_entries (
    club_id,
    user_id,
    membership_id,
    entry_type,
    direction,
    amount,
    balance_after,
    counterparty_user_id,
    reference_type,
    reference_id,
    idempotency_key,
    note,
    metadata,
    created_by
  )
  values (
    p_club_id,
    p_user_id,
    p_membership_id,
    lower(btrim(coalesce(p_entry_type, ''))),
    lower(btrim(coalesce(p_direction, ''))),
    greatest(coalesce(p_amount, 0), 0),
    greatest(coalesce(p_balance_after, 0), 0),
    p_counterparty_user_id,
    nullif(btrim(coalesce(p_reference_type, '')), ''),
    nullif(btrim(coalesce(p_reference_id, '')), ''),
    v_idempotency_key,
    nullif(btrim(coalesce(p_note, '')), ''),
    coalesce(p_metadata, '{}'::jsonb),
    p_created_by
  )
  returning * into v_entry;

  return v_entry;
exception
  when unique_violation then
    if v_idempotency_key is null then
      raise;
    end if;

    select *
      into v_entry
      from public.fet_wallet_ledger_entries
     where club_id = p_club_id
       and user_id = p_user_id
       and idempotency_key = v_idempotency_key
     order by created_at desc, id desc
     limit 1;

    if v_entry.id is null then
      raise;
    end if;

    return v_entry;
end;
$$;


ALTER FUNCTION "public"."fet_wallet_append_entry"("p_club_id" bigint, "p_user_id" "uuid", "p_membership_id" "uuid", "p_entry_type" "text", "p_direction" "text", "p_amount" integer, "p_balance_after" integer, "p_counterparty_user_id" "uuid", "p_reference_type" "text", "p_reference_id" "text", "p_idempotency_key" "text", "p_note" "text", "p_metadata" "jsonb", "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fet_wallet_ensure_membership"("p_user_id" "uuid", "p_club_id" bigint) RETURNS "public"."fan_memberships"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_membership public.fan_memberships;
begin
  insert into public.fan_memberships (
    user_id,
    club_id,
    partner_id,
    tier,
    points,
    renewed_at
  )
  values (
    p_user_id,
    p_club_id,
    public.fet_wallet_resolve_partner_id(p_club_id, null),
    public.resolve_fan_tier(0),
    0,
    timezone('utc', now())
  )
  on conflict (user_id, club_id)
  do update set updated_at = public.fan_memberships.updated_at
  returning * into v_membership;

  return v_membership;
end;
$$;


ALTER FUNCTION "public"."fet_wallet_ensure_membership"("p_user_id" "uuid", "p_club_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fet_wallet_resolve_partner_id"("p_club_id" bigint, "p_partner_hint" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_partner_id uuid;
begin
  if nullif(btrim(coalesce(p_partner_hint, '')), '') ~*
    '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
    v_partner_id := lower(btrim(p_partner_hint))::uuid;
  end if;

  if v_partner_id is null then
    v_partner_id := (public.resolve_partner_ids_for_club(p_club_id))[1];
  end if;

  if v_partner_id is null then
    raise exception 'Partner scope required for club %.', p_club_id;
  end if;

  return v_partner_id;
end;
$_$;


ALTER FUNCTION "public"."fet_wallet_resolve_partner_id"("p_club_id" bigint, "p_partner_hint" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."find_auth_user_by_phone_or_email"("p_phone" "text", "p_email" "text") RETURNS TABLE("user_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
  select au.id as user_id
  from auth.users au
  where au.email = p_email
     or au.phone = p_phone
     or au.phone_change = p_phone
     or coalesce(au.raw_user_meta_data ->> 'phone', '') = p_phone
  order by case
    when au.email = p_email then 0
    when au.phone = p_phone then 1
    when au.phone_change = p_phone then 2
    when coalesce(au.raw_user_meta_data ->> 'phone', '') = p_phone then 3
    else 9
  end,
  au.created_at asc
  limit 1;
$$;


ALTER FUNCTION "public"."find_auth_user_by_phone_or_email"("p_phone" "text", "p_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fixtures_calendar"("p_date_from" "date" DEFAULT CURRENT_DATE, "p_date_to" "date" DEFAULT CURRENT_DATE, "p_competition_slug" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 200) RETURNS TABLE("id" "uuid", "competition_id" "uuid", "competition_slug" "text", "competition_name" "text", "season_id" "uuid", "season_slug" "text", "season_label" "text", "stage_name" "text", "group_name" "text", "round_name" "text", "matchday" integer, "fixture_number" integer, "kickoff_at" timestamp with time zone, "venue_name" "text", "venue_city" "text", "venue_country" "text", "home_team_id" "uuid", "home_team_slug" "text", "home_team_name" "text", "home_team_short_name" "text", "away_team_id" "uuid", "away_team_slug" "text", "away_team_name" "text", "away_team_short_name" "text", "home_score" integer, "away_score" integer, "leg_number" integer, "status" "text", "metadata" "jsonb", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    f.id, f.competition_id, f.competition_slug, f.competition_name,
    f.season_id, f.season_slug, f.season_label,
    f.stage_name, f.group_name, f.round_name,
    f.matchday, f.fixture_number, f.kickoff_at,
    f.venue_name, f.venue_city, f.venue_country,
    f.home_team_id, f.home_team_slug, f.home_team_name, f.home_team_short_name,
    f.away_team_id, f.away_team_slug, f.away_team_name, f.away_team_short_name,
    f.home_score, f.away_score, f.leg_number,
    f.status::text, f.metadata, f.created_at, f.updated_at
  FROM prediction_supported_fixtures_catalog f
  WHERE (f.kickoff_at::date >= p_date_from)
    AND (f.kickoff_at::date <= p_date_to)
    AND (p_competition_slug IS NULL OR f.competition_slug = p_competition_slug)
    AND (p_status IS NULL OR f.status::text = p_status)
  ORDER BY f.kickoff_at ASC, f.competition_name ASC
  LIMIT p_limit;
$$;


ALTER FUNCTION "public"."fixtures_calendar"("p_date_from" "date", "p_date_to" "date", "p_competition_slug" "text", "p_status" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fixtures_date_summary"("p_date_from" "date" DEFAULT (CURRENT_DATE - 7), "p_date_to" "date" DEFAULT (CURRENT_DATE + 30), "p_competition_slug" "text" DEFAULT NULL::"text") RETURNS TABLE("match_date" "date", "fixture_count" integer, "has_live" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    f.kickoff_at::date AS match_date,
    count(*)::int AS fixture_count,
    bool_or(f.status::text = 'live') AS has_live
  FROM prediction_supported_fixtures_catalog f
  WHERE (f.kickoff_at::date >= p_date_from)
    AND (f.kickoff_at::date <= p_date_to)
    AND (p_competition_slug IS NULL OR f.competition_slug = p_competition_slug)
  GROUP BY f.kickoff_at::date
  ORDER BY match_date;
$$;


ALTER FUNCTION "public"."fixtures_date_summary"("p_date_from" "date", "p_date_to" "date", "p_competition_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_admin_access_for_user"("p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := coalesce(p_user_id, auth.uid());
  v_is_platform_admin boolean := false;
  v_has_partner boolean := false;
  v_role_rows jsonb := '[]'::jsonb;
  v_bank_ids jsonb := '[]'::jsonb;
  v_partner_ids jsonb := '[]'::jsonb;
  v_club_ids jsonb := '[]'::jsonb;
begin
  if v_user_id is null then
    return jsonb_build_object(
      'has_platform_access', false,
      'has_bank_access', false,
      'has_partner_access', false,
      'has_rayon_access', false,
      'bank_partner_ids', '[]'::jsonb,
      'partner_admin_ids', '[]'::jsonb,
      'club_admin_ids', '[]'::jsonb,
      'role_assignments', '[]'::jsonb
    );
  end if;

  select coalesce(u.is_admin, false)
  into v_is_platform_admin
  from public.users u
  where u.id = v_user_id;

  if not v_is_platform_admin then
    select exists (
      select 1
      from public.admin_role_assignments ra
      where ra.user_id = v_user_id
        and ra.is_active = true
        and ra.role in ('admin', 'super_admin')
    )
    into v_is_platform_admin;
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', ra.id,
        'role', ra.role,
        'partner_scope_id', ra.partner_scope_id,
        'club_id', ra.club_id,
        'partner_name', p.name,
        'granted_at', ra.granted_at,
        'is_active', ra.is_active
      )
      order by ra.granted_at desc
    ),
    '[]'::jsonb
  )
  into v_role_rows
  from public.admin_role_assignments ra
  left join public.partners p
    on p.id = ra.partner_scope_id
  where ra.user_id = v_user_id
    and ra.is_active = true;

  select coalesce(jsonb_agg(ra.partner_scope_id), '[]'::jsonb)
  into v_bank_ids
  from public.admin_role_assignments ra
  where ra.user_id = v_user_id
    and ra.is_active = true
    and ra.role = 'bank'
    and ra.partner_scope_id is not null;

  select coalesce(jsonb_agg(ra.partner_scope_id), '[]'::jsonb)
  into v_partner_ids
  from public.admin_role_assignments ra
  where ra.user_id = v_user_id
    and ra.is_active = true
    and ra.role in ('partner', 'rayon_sport')
    and ra.partner_scope_id is not null;

  select coalesce(jsonb_agg(ra.club_id), '[]'::jsonb)
  into v_club_ids
  from public.admin_role_assignments ra
  where ra.user_id = v_user_id
    and ra.is_active = true
    and ra.role in ('club_admin', 'club_moderator')
    and ra.club_id is not null;

  v_has_partner := v_is_platform_admin
    or jsonb_array_length(v_partner_ids) > 0
    or jsonb_array_length(v_club_ids) > 0;

  return jsonb_build_object(
    'has_platform_access', v_is_platform_admin,
    'has_bank_access', v_is_platform_admin or jsonb_array_length(v_bank_ids) > 0,
    'has_partner_access', v_has_partner,
    'has_rayon_access', v_has_partner,
    'bank_partner_ids', v_bank_ids,
    'partner_admin_ids', v_partner_ids,
    'club_admin_ids', v_club_ids,
    'role_assignments', v_role_rows
  );
end;
$$;


ALTER FUNCTION "public"."get_admin_access_for_user"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_admin_audit_log"("p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0, "p_action" "text" DEFAULT NULL::"text", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS SETOF "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select jsonb_build_object(
    'id', a.id,
    'actor_id', a.actor_id,
    'actor_name', u.full_name,
    'actor_phone', u.phone,
    'action', a.action,
    'target_table', a.target_table,
    'target_id', a.target_id,
    'old_data', a.old_data,
    'new_data', a.new_data,
    'notes', a.notes,
    'created_at', a.created_at
  )
  from public.admin_audit_log a
  left join public.users u on u.id = a.actor_id
  where
    (p_action is null or a.action = p_action)
    and (p_actor_id is null or a.actor_id = p_actor_id)
    and exists (
      select 1 from public.users caller
      where caller.id = auth.uid() and caller.is_admin = true
    )
  order by a.created_at desc
  limit p_limit
  offset p_offset;
$$;


ALTER FUNCTION "public"."get_admin_audit_log"("p_limit" integer, "p_offset" integer, "p_action" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_admin_dashboard_actions"("p_club_id" bigint DEFAULT NULL::bigint, "p_role" "text" DEFAULT NULL::"text", "p_is_super_admin" boolean DEFAULT false) RETURNS TABLE("id" "uuid", "action_key" "text", "title" "text", "subtitle" "text", "route" "text", "icon_key" "text", "category" "text", "club_id" bigint, "required_role" "text", "sort_order" integer, "metadata" "jsonb")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  with scoped as (
    select
      ada.*,
      case when ada.club_id = p_club_id then 0 else 1 end as scope_rank
    from public.admin_dashboard_actions ada
    where ada.is_active = true
      and (ada.club_id is null or ada.club_id = p_club_id)
      and (
        ada.required_role is null
        or p_is_super_admin = true
        or ada.required_role = p_role
      )
  ),
  preferred as (
    select distinct on (scoped.action_key)
      scoped.id,
      scoped.action_key,
      scoped.title,
      scoped.subtitle,
      scoped.route,
      scoped.icon_key,
      scoped.category,
      scoped.club_id,
      scoped.required_role,
      scoped.sort_order,
      scoped.metadata
    from scoped
    order by scoped.action_key, scoped.scope_rank, scoped.sort_order
  )
  select
    preferred.id,
    preferred.action_key,
    preferred.title,
    preferred.subtitle,
    preferred.route,
    preferred.icon_key,
    preferred.category,
    preferred.club_id,
    preferred.required_role,
    preferred.sort_order,
    preferred.metadata
  from preferred
  order by preferred.sort_order, preferred.title;
$$;


ALTER FUNCTION "public"."get_admin_dashboard_actions"("p_club_id" bigint, "p_role" "text", "p_is_super_admin" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_bank_custody_contributions"("p_partner_id" "uuid", "p_group_id" "uuid" DEFAULT NULL::"uuid", "p_status" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 1000, "p_offset" integer DEFAULT 0) RETURNS TABLE("contribution_id" "uuid", "group_id" "uuid", "group_name" "text", "user_id" "uuid", "contributor_name" "text", "amount" integer, "status" "text", "momo_reference" "text", "created_at" timestamp with time zone, "total_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if p_partner_id is null then
    raise exception 'Partner id is required.';
  end if;

  if auth.uid() is null or not public.can_read_bank_custody(p_partner_id) then
    raise exception 'Not authorized to view bank custody contributions.';
  end if;

  if p_group_id is not null and not public.group_belongs_to_bank_partner(p_group_id, p_partner_id) then
    raise exception 'This group is not linked to the requested bank workspace.';
  end if;

  return query
  with scoped_contributions as (
    select
      gc.id as contribution_id,
      gc.group_id,
      g.name as group_name,
      gc.user_id,
      coalesce(
        nullif(btrim(gm.display_name), ''),
        nullif(btrim(u.public_user_id), ''),
        nullif(btrim(u.full_name), ''),
        'Member'
      ) as contributor_name,
      gc.amount,
      gc.status,
      gc.momo_reference,
      gc.created_at
    from public.group_contributions gc
    join public.groups g
      on g.id = gc.group_id
    left join public.group_members gm
      on gm.group_id = gc.group_id
      and gm.user_id = gc.user_id
    left join public.users u
      on u.id = gc.user_id
    where public.group_belongs_to_bank_partner(g.id, p_partner_id)
      and (p_group_id is null or gc.group_id = p_group_id)
      and (
        p_status is null
        or btrim(p_status) = ''
        or lower(gc.status) = lower(btrim(p_status))
      )
  )
  select
    sc.contribution_id,
    sc.group_id,
    sc.group_name,
    sc.user_id,
    sc.contributor_name,
    sc.amount,
    sc.status,
    sc.momo_reference,
    sc.created_at,
    count(*) over() as total_count
  from scoped_contributions sc
  order by sc.created_at desc, sc.contribution_id desc
  limit greatest(coalesce(p_limit, 1000), 1)
  offset greatest(coalesce(p_offset, 0), 0);
end;
$$;


ALTER FUNCTION "public"."get_bank_custody_contributions"("p_partner_id" "uuid", "p_group_id" "uuid", "p_status" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_bank_custody_group_members"("p_partner_id" "uuid", "p_group_id" "uuid" DEFAULT NULL::"uuid", "p_search" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 1000, "p_offset" integer DEFAULT 0) RETURNS TABLE("group_id" "uuid", "group_name" "text", "user_id" "uuid", "display_name" "text", "is_admin" boolean, "is_anonymous" boolean, "contribution_amount" integer, "joined_at" timestamp with time zone, "total_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if p_partner_id is null then
    raise exception 'Partner id is required.';
  end if;

  if auth.uid() is null or not public.can_read_bank_custody(p_partner_id) then
    raise exception 'Not authorized to view bank custody members.';
  end if;

  if p_group_id is not null and not public.group_belongs_to_bank_partner(p_group_id, p_partner_id) then
    raise exception 'This group is not linked to the requested bank workspace.';
  end if;

  return query
  with scoped_members as (
    select
      gm.group_id,
      g.name as group_name,
      gm.user_id,
      coalesce(
        nullif(btrim(gm.display_name), ''),
        nullif(btrim(u.public_user_id), ''),
        nullif(btrim(u.full_name), ''),
        'Member'
      ) as display_name,
      gm.is_admin,
      gm.is_anonymous,
      gm.contribution_amount,
      gm.joined_at
    from public.group_members gm
    join public.groups g
      on g.id = gm.group_id
    left join public.users u
      on u.id = gm.user_id
    where public.group_belongs_to_bank_partner(g.id, p_partner_id)
      and (p_group_id is null or gm.group_id = p_group_id)
      and (
        p_search is null
        or btrim(p_search) = ''
        or coalesce(gm.display_name, '') ilike '%' || btrim(p_search) || '%'
        or coalesce(u.public_user_id, '') ilike '%' || btrim(p_search) || '%'
        or coalesce(u.full_name, '') ilike '%' || btrim(p_search) || '%'
        or g.name ilike '%' || btrim(p_search) || '%'
      )
  )
  select
    sm.group_id,
    sm.group_name,
    sm.user_id,
    sm.display_name,
    sm.is_admin,
    sm.is_anonymous,
    sm.contribution_amount,
    sm.joined_at,
    count(*) over() as total_count
  from scoped_members sm
  order by sm.joined_at desc nulls last, sm.group_name asc, sm.display_name asc
  limit greatest(coalesce(p_limit, 1000), 1)
  offset greatest(coalesce(p_offset, 0), 0);
end;
$$;


ALTER FUNCTION "public"."get_bank_custody_group_members"("p_partner_id" "uuid", "p_group_id" "uuid", "p_search" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_bank_manual_review_allocations"("p_partner_id" "uuid", "p_limit" integer DEFAULT 1000, "p_offset" integer DEFAULT 0) RETURNS TABLE("review_id" "uuid", "group_id" "uuid", "group_name" "text", "payer_user_id" "uuid", "payer_name" "text", "match_status" "text", "reason" "text", "matched_reference" "text", "amount" integer, "provider" "text", "payee_digits" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "total_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
begin
  if p_partner_id is null then
    raise exception 'Partner id is required.';
  end if;

  if auth.uid() is null or not public.can_read_bank_custody(p_partner_id) then
    raise exception 'Not authorized to view bank custody allocations.';
  end if;

  return query
  with candidate_rows as (
    select
      mr.id as review_id,
      coalesce(
        gc.group_id,
        nullif(mr.metadata ->> 'group_id', '')::uuid,
        (
          select candidate_id::uuid
          from jsonb_array_elements_text(coalesce(mr.metadata -> 'matching_group_ids', '[]'::jsonb)) candidate(candidate_id)
          where candidate_id ~* '^[0-9a-f-]{36}$'
          limit 1
        )
      ) as group_id,
      mr.user_id as payer_user_id,
      coalesce(
        nullif(btrim(u.public_user_id), ''),
        nullif(btrim(u.full_name), ''),
        'Member'
      ) as payer_name,
      mr.match_status,
      coalesce(nullif(mr.metadata ->> 'reason', ''), nullif(mr.notes, ''), 'manual_review') as reason,
      nullif(mr.metadata ->> 'matched_reference', '') as matched_reference,
      coalesce((mr.metadata ->> 'amount')::integer, 0) as amount,
      nullif(mr.metadata ->> 'provider', '') as provider,
      coalesce(
        nullif(mr.metadata ->> 'receiver_source_of_truth', ''),
        nullif(mr.metadata ->> 'payee_number_or_code', ''),
        nullif(mr.metadata ->> 'merchant_code', '')
      ) as payee_digits,
      mr.created_at,
      coalesce(mr.updated_at, mr.created_at) as updated_at
    from public.momo_reconciliations mr
    left join public.group_contributions gc
      on mr.target_table = 'group_contributions'
      and mr.target_record_id = gc.id
    left join public.users u
      on u.id = mr.user_id
    where mr.match_status in ('pending_review', 'manual_review')
  ),
  scoped_reviews as (
    select
      cr.review_id,
      cr.group_id,
      g.name as group_name,
      cr.payer_user_id,
      cr.payer_name,
      cr.match_status,
      cr.reason,
      cr.matched_reference,
      cr.amount,
      cr.provider,
      cr.payee_digits,
      cr.created_at,
      cr.updated_at
    from candidate_rows cr
    join public.groups g
      on g.id = cr.group_id
    where public.group_belongs_to_bank_partner(g.id, p_partner_id)
  )
  select
    sr.review_id,
    sr.group_id,
    sr.group_name,
    sr.payer_user_id,
    sr.payer_name,
    sr.match_status,
    sr.reason,
    sr.matched_reference,
    sr.amount,
    sr.provider,
    sr.payee_digits,
    sr.created_at,
    sr.updated_at,
    count(*) over() as total_count
  from scoped_reviews sr
  order by sr.updated_at desc, sr.review_id desc
  limit greatest(coalesce(p_limit, 1000), 1)
  offset greatest(coalesce(p_offset, 0), 0);
end;
$_$;


ALTER FUNCTION "public"."get_bank_manual_review_allocations"("p_partner_id" "uuid", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_club_fan_analytics"("p_club_id" bigint DEFAULT NULL::bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_club_id bigint := coalesce(p_club_id, nullif(public.requesting_club_id(), '')::bigint);
  v_partner_ids uuid[] := '{}'::uuid[];
  v_result jsonb;
begin
  if v_club_id is null then
    raise exception 'Club scope is required.';
  end if;

  if not (public.is_super_admin() or public.is_club_admin(v_club_id) or public.is_admin_user()) then
    raise exception 'Unauthorized: Requires club or platform admin access.';
  end if;

  v_partner_ids := public.resolve_partner_ids_for_club(v_club_id);

  select jsonb_build_object(
    'club_id', v_club_id,
    'partner_ids', to_jsonb(v_partner_ids),
    'total_fans', (
      select count(*)
      from public.fan_memberships fm
      where coalesce(array_length(v_partner_ids, 1), 0) > 0
        and fm.partner_id = any(v_partner_ids)
    ),
    'active_memberships', (
      select count(*)
      from public.fan_memberships fm
      where coalesce(array_length(v_partner_ids, 1), 0) > 0
        and fm.partner_id = any(v_partner_ids)
    ),
    'total_tickets_sold', (
      select count(*)
      from public.tickets t
      where t.club_id = v_club_id
        and t.status in ('valid', 'used')
    ),
    'ticket_revenue', (
      select coalesce(sum(t.amount_paid), 0)
      from public.tickets t
      where t.club_id = v_club_id
        and t.status in ('valid', 'used')
    ),
    'total_initiatives', (
      select count(*)
      from public.initiatives i
      where i.club_id = v_club_id
    ),
    'total_contributions', (
      select coalesce(sum(ic.amount), 0)
      from public.initiative_contributions ic
      where ic.club_id = v_club_id
        and ic.status = 'confirmed'
    ),
    'total_shop_revenue', (
      select coalesce(sum(so.total), 0)
      from public.shop_orders so
      where so.club_id = v_club_id
        and so.status in ('paid', 'confirmed', 'packed', 'fulfilled', 'delivered')
    ),
    'tier_breakdown', (
      select coalesce(jsonb_object_agg(tier, cnt), '{}'::jsonb)
      from (
        select fm.tier, count(*) as cnt
        from public.fan_memberships fm
        where coalesce(array_length(v_partner_ids, 1), 0) > 0
          and fm.partner_id = any(v_partner_ids)
        group by fm.tier
      ) t
    )
  )
  into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."get_club_fan_analytics"("p_club_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_club_member_registry"("p_club_id" bigint, "p_search_query" "text" DEFAULT NULL::"text", "p_filter_tier" "text" DEFAULT NULL::"text", "p_region" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS TABLE("user_id" "uuid", "display_name" "text", "membership_number" "text", "points" integer, "tier" "text", "chapter" "text", "joined_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_search text := nullif(btrim(coalesce(p_search_query, '')), '');
  v_tier text := lower(nullif(btrim(coalesce(p_filter_tier, '')), ''));
  v_region text := nullif(btrim(coalesce(p_region, '')), '');
  v_partner_ids uuid[] := public.resolve_partner_ids_for_club(p_club_id);
begin
  if auth.uid() is null then
    raise exception 'Authentication is required.';
  end if;

  if not (public.is_super_admin() or public.is_club_admin(p_club_id) or public.is_admin_user()) then
    raise exception 'Unauthorized: Requires club or platform admin access.';
  end if;

  return query
  select
    membership.user_id,
    membership.display_name,
    membership.membership_number,
    membership.points,
    membership.tier,
    membership.chapter,
    membership.joined_at
  from public.fan_memberships membership
  where coalesce(array_length(v_partner_ids, 1), 0) > 0
    and membership.partner_id = any(v_partner_ids)
    and (v_tier is null or lower(membership.tier) = v_tier)
    and (v_region is null or coalesce(membership.chapter, '') ilike '%' || v_region || '%')
    and (
      v_search is null
      or membership.display_name ilike '%' || v_search || '%'
      or membership.membership_number ilike '%' || v_search || '%'
    )
  order by membership.points desc, membership.joined_at asc, membership.membership_number asc
  limit greatest(coalesce(p_limit, 20), 1)
  offset greatest(coalesce(p_offset, 0), 0);
end;
$$;


ALTER FUNCTION "public"."get_club_member_registry"("p_club_id" bigint, "p_search_query" "text", "p_filter_tier" "text", "p_region" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


