CREATE OR REPLACE FUNCTION "public"."get_my_notification_events"("p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT jsonb_agg(row_to_json(t))
  INTO result
  FROM (
    SELECT
      id,
      title,
      body,
      route,
      image_url,
      data,
      provider,
      send_status,
      sent_count,
      failed_count,
      cleaned_tokens,
      errors,
      created_at,
      sent_at
    FROM public.notification_events
    WHERE target_type = 'user'
      AND user_id = auth.uid()
    ORDER BY COALESCE(sent_at, created_at) DESC, created_at DESC
    LIMIT GREATEST(p_limit, 1)
    OFFSET GREATEST(p_offset, 0)
  ) t;

  RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION "public"."get_my_notification_events"("p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_my_notification_events"("p_limit" integer, "p_offset" integer) IS 'Returns the authenticated user''s recent server-trusted notification events.';



CREATE OR REPLACE FUNCTION "public"."get_nearby_drivers"("p_lat" double precision, "p_lng" double precision, "p_vehicle_type" "text" DEFAULT NULL::"text", "p_country" "text" DEFAULT NULL::"text", "radius_km" double precision DEFAULT 10) RETURNS TABLE("driver_id" "uuid", "user_id" "uuid", "vehicle_type" "text", "vehicle_emoji" "text", "distance_km" double precision, "is_online" boolean, "rating" double precision, "trip_count" integer, "scheduled_route" "text", "has_return_trip" boolean, "latitude" double precision, "longitude" double precision)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
  select
    dp.user_id as driver_id,
    dp.user_id,
    dp.vehicle_type,
    coalesce(
      dp.vehicle_emoji,
      case lower(dp.vehicle_type)
        when 'moto' then '🛺'
        when 'moto taxi' then '🛺'
        when 'cab' then '🚗'
        when 'truck' then '🚛'
        when 'trike' then '🚐'
        else '🚗'
      end
    ) as vehicle_emoji,
    round(
      (st_distancesphere(
        dp.location::geometry,
        st_setsrid(st_makepoint(p_lng, p_lat), 4326)
      ) / 1000.0)::numeric,
      2
    )::double precision as distance_km,
    dp.is_online,
    dp.rating,
    dp.trips_done as trip_count,
    (
      select mt.from_location || ' -> ' || mt.to_location
      from public.mobility_trips mt
      where mt.driver_id = dp.user_id
        and mt.status = 'open'
        and mt.departure_at >= now()
      order by mt.departure_at asc
      limit 1
    ) as scheduled_route,
    exists (
      select 1
      from public.mobility_trips mt
      where mt.driver_id = dp.user_id
        and mt.status = 'open'
        and mt.is_driver_return_trip = true
        and coalesce(mt.expires_at, mt.departure_at + interval '1 hour') >= now()
    ) as has_return_trip,
    dp.latitude,
    dp.longitude
  from public.driver_profiles dp
  where dp.is_online = true
    and dp.location is not null
    and (
      p_country is null
      or dp.country = public.normalize_country_code(p_country)
    )
    and st_dwithin(
      dp.location,
      st_setsrid(st_makepoint(p_lng, p_lat), 4326)::geography,
      radius_km * 1000
    )
    and (p_vehicle_type is null or dp.vehicle_type = p_vehicle_type)
  order by distance_km;
$$;


ALTER FUNCTION "public"."get_nearby_drivers"("p_lat" double precision, "p_lng" double precision, "p_vehicle_type" "text", "p_country" "text", "radius_km" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_operational_release_dashboard"() RETURNS TABLE("service_key" "text", "label" "text", "health_status" "text", "ok_count_24h" integer, "warn_count_24h" integer, "error_count_24h" integer, "issue_count" integer, "last_signal_at" timestamp with time zone, "summary" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
begin
  if not public.is_admin() then
    raise exception 'Admin privileges required';
  end if;

  return query
  select
    ord.service_key,
    ord.label,
    ord.health_status,
    ord.ok_count_24h,
    ord.warn_count_24h,
    ord.error_count_24h,
    ord.issue_count,
    ord.last_signal_at,
    ord.summary
  from public.operational_release_dashboard ord
  order by
    case ord.health_status
      when 'failing' then 0
      when 'degraded' then 1
      when 'unknown' then 2
      else 3
    end,
    ord.label asc;
end;
$$;


ALTER FUNCTION "public"."get_operational_release_dashboard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_operational_triage_issues"() RETURNS TABLE("issue_id" "text", "issue_type" "text", "severity" "text", "service" "text", "title" "text", "detail" "text", "subject_table" "text", "subject_id" "text", "user_id" "uuid", "reference" "text", "first_seen_at" timestamp with time zone, "last_seen_at" timestamp with time zone, "metadata" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
begin
  if not public.is_admin() then
