CREATE OR REPLACE FUNCTION "public"."get_partner_member_registry"("p_partner_id" "uuid", "p_search_query" "text" DEFAULT NULL::"text", "p_filter_tier" "text" DEFAULT NULL::"text", "p_region" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS TABLE("user_id" "uuid", "display_name" "text", "membership_number" "text", "points" integer, "tier" "text", "chapter" "text", "joined_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_search text := nullif(btrim(coalesce(p_search_query, '')), '');
  v_tier text := lower(nullif(btrim(coalesce(p_filter_tier, '')), ''));
  v_region text := nullif(btrim(coalesce(p_region, '')), '');
begin
  if auth.uid() is null then
    raise exception 'Authentication is required.';
  end if;

  if not (public.is_partner_admin(p_partner_id) or public.is_admin_user()) then
    raise exception 'Unauthorized: Requires partner or platform admin access.';
  end if;

  return query
  select
    membership.user_id,
    membership.display_name,
    membership.membership_number,
    membership.points,
    membership.tier,
    membership.chapter,
    membership.joined_at
  from public.fan_memberships membership
  where membership.partner_id = p_partner_id
    and (v_tier is null or lower(membership.tier) = v_tier)
    and (v_region is null or coalesce(membership.chapter, '') ilike '%' || v_region || '%')
    and (
      v_search is null
      or membership.display_name ilike '%' || v_search || '%'
      or membership.membership_number ilike '%' || v_search || '%'
    )
  order by membership.points desc, membership.joined_at asc, membership.membership_number asc
  limit greatest(coalesce(p_limit, 20), 1)
  offset greatest(coalesce(p_offset, 0), 0);
end;
$$;


ALTER FUNCTION "public"."get_partner_member_registry"("p_partner_id" "uuid", "p_search_query" "text", "p_filter_tier" "text", "p_region" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_partner_payment_ledger_entries"("p_partner_id" "uuid", "p_start_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_end_before" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_payer_user_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 1000, "p_offset" integer DEFAULT 0) RETURNS TABLE("ledger_id" "uuid", "payer_user_id" "uuid", "payer_name" "text", "payer_phone" "text", "amount" integer, "currency" "text", "tx_datetime" timestamp with time zone, "external_reference" "text", "tx_category" "text", "cashflow_bucket" "text", "statement_label" "text", "counterparty_name" "text", "target_table" "text", "target_record_id" "uuid", "total_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if p_partner_id is null then
    raise exception 'Partner id is required.';
  end if;

  if auth.uid() is null or not public.can_read_partner_payment_ledger(p_partner_id) then
    raise exception 'Not authorized to view this partner payment ledger.';
  end if;

  return query
  with ledger_rows as (
    select
      ledger.id as ledger_id,
      ledger.user_id as payer_user_id,
      coalesce(
        nullif(trim(payer.full_name), ''),
        nullif(trim(payer.official_name), ''),
        'Member'
      ) as payer_name,
      nullif(trim(coalesce(payer.official_phone, payer.phone)), '') as payer_phone,
      ledger.amount,
      ledger.currency,
      coalesce(ledger.tx_datetime, ledger.created_at) as tx_datetime,
      ledger.external_reference,
      ledger.tx_category,
      ledger.cashflow_bucket,
      ledger.statement_label,
      ledger.counterparty_name,
      ledger.target_table,
      ledger.target_record_id
    from public.momo_ledger_entries as ledger
    left join public.users as payer
      on payer.id = ledger.user_id
    where ledger.payee_partner_id = p_partner_id
      and ledger.ledger_status = 'posted'
      and (p_start_at is null or coalesce(ledger.tx_datetime, ledger.created_at) >= p_start_at)
      and (p_end_before is null or coalesce(ledger.tx_datetime, ledger.created_at) < p_end_before)
      and (p_payer_user_id is null or ledger.user_id = p_payer_user_id)
  )
  select
    row.ledger_id,
    row.payer_user_id,
    row.payer_name,
    row.payer_phone,
    row.amount,
    row.currency,
    row.tx_datetime,
    row.external_reference,
    row.tx_category,
    row.cashflow_bucket,
    row.statement_label,
    row.counterparty_name,
    row.target_table,
    row.target_record_id,
    count(*) over() as total_count
  from ledger_rows as row
  order by row.tx_datetime desc, row.ledger_id desc
  limit greatest(coalesce(p_limit, 1000), 1)
  offset greatest(coalesce(p_offset, 0), 0);
end;
$$;


ALTER FUNCTION "public"."get_partner_payment_ledger_entries"("p_partner_id" "uuid", "p_start_at" timestamp with time zone, "p_end_before" timestamp with time zone, "p_payer_user_id" "uuid", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_partner_payment_route"("p_partner_id" "uuid", "p_country" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_route record;
begin
  p_country := nullif(btrim(coalesce(p_country, '')), '');

  if p_partner_id is null then
    return null;
  end if;

  select
    ppr.id,
    ppr.partner_id,
    ppr.country,
    ppr.provider,
    ppr.recipient_code,
    ppr.reconciliation_label,
    ppr.status,
    p.name as partner_name,
    p.slug as partner_slug
  into v_route
  from public.partner_payment_routes ppr
  join public.partners p
    on p.id = ppr.partner_id
  where ppr.partner_id = p_partner_id
    and ppr.status = 'active'
    and ppr.recipient_code is not null
    and ppr.country = 'RW'
  order by ppr.updated_at desc
  limit 1;

  if v_route is null then
    return null;
  end if;

  return jsonb_build_object(
    'id', v_route.id,
    'partner_id', v_route.partner_id,
    'partner_name', v_route.partner_name,
    'partner_slug', v_route.partner_slug,
    'country', 'RW',
    'provider', v_route.provider,
    'recipient_code', v_route.recipient_code,
    'reconciliation_label', v_route.reconciliation_label,
    'status', v_route.status
  );
end;
$$;


ALTER FUNCTION "public"."get_partner_payment_route"("p_partner_id" "uuid", "p_country" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_platform_config"("p_channel" "text" DEFAULT 'mobile'::"text", "p_club_id" bigint DEFAULT NULL::bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_result jsonb;
  v_features jsonb;
  v_content_blocks jsonb;
  v_routes jsonb;
  v_option_sets jsonb;
  v_runtime_copy jsonb;
  v_site_navigation jsonb;
  v_site_search jsonb;
  v_venue_governance jsonb;
  v_now timestamptz := now();
begin
  with resolved_features as (
    select distinct on (pf.feature_key)
      pf.id,
      pf.feature_key,
      pf.display_name,
      pf.description,
      pf.category,
      pf.club_id,
      pf.is_enabled,
      pf.visibility_state
    from public.platform_features pf
    where pf.club_id is null
       or pf.club_id = p_club_id
    order by pf.feature_key, pf.club_id desc nulls last
  )
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'feature_key', rf.feature_key,
      'display_name', rf.display_name,
      'description', rf.description,
      'category', rf.category,
      'is_enabled', rf.is_enabled,
      'visibility_state', rf.visibility_state,
      'channel', (
        select jsonb_build_object(
          'is_enabled', coalesce(ch.is_enabled, true),
          'is_visible', coalesce(ch.is_visible, true),
          'show_in_navigation', coalesce(ch.show_in_navigation, false),
          'show_on_home', coalesce(ch.show_on_home, false),
          'sort_order', ch.sort_order,
          'route_key', ch.route_key,
          'placement_key', ch.placement_key
        )
        from public.platform_feature_channels ch
        where ch.feature_id = rf.id
          and ch.channel = p_channel
      ),
      'rules', (
        select jsonb_build_object(
          'auth_required', coalesce(r.auth_required, false),
          'role_restrictions', coalesce(r.role_restrictions, '[]'::jsonb),
          'dependency_rules', coalesce(r.dependency_rules, '{}'::jsonb),
          'rollout_rules', coalesce(r.rollout_rules, '{}'::jsonb),
          'schedule_start_at', r.schedule_start_at,
          'schedule_end_at', r.schedule_end_at,
          'is_within_schedule',
            case
              when r.schedule_start_at is null and r.schedule_end_at is null then true
              when r.schedule_start_at is not null and r.schedule_end_at is not null
                then v_now >= r.schedule_start_at and v_now < r.schedule_end_at
              when r.schedule_start_at is not null then v_now >= r.schedule_start_at
              when r.schedule_end_at is not null then v_now < r.schedule_end_at
              else true
            end
        )
        from public.platform_feature_rules r
        where r.feature_id = rf.id
      )
    )
    order by rf.feature_key
  ), '[]'::jsonb)
  into v_features
  from resolved_features rf;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'block_key', cb.block_key,
      'block_type', cb.block_type,
      'title', cb.title,
      'subtitle', cb.subtitle,
      'content', cb.content,
      'target_channel', cb.target_channel,
      'placement_key', cb.placement_key,
      'feature_key', pf.feature_key,
      'is_active', cb.is_active,
      'sort_order', cb.sort_order,
      'metadata', cb.metadata
    )
    order by cb.sort_order nulls last, cb.created_at
  ), '[]'::jsonb)
  into v_content_blocks
  from public.platform_content_blocks cb
  left join public.platform_features pf on pf.id = cb.feature_id
  where cb.is_active = true
    and (cb.target_channel = p_channel or cb.target_channel = 'both')
    and (cb.club_id is null or cb.club_id = p_club_id);

  with resolved_routes as (
    select distinct on (prr.route_key, prr.surface)
      prr.*
    from public.platform_route_registry prr
    where prr.is_active = true
      and (prr.surface = p_channel or prr.surface = 'both')
      and (prr.club_id is null or prr.club_id = p_club_id)
    order by prr.route_key, prr.surface, prr.club_id desc nulls last
  )
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'route_key', route_key,
      'path_pattern', path_pattern,
      'surface', surface,
      'feature_key', feature_key,
      'label', label,
      'auth_required', auth_required,
      'required_roles', required_roles,
      'presentation', presentation,
      'show_in_navigation', show_in_navigation,
      'show_on_home', show_on_home,
      'sort_order', sort_order,
      'metadata', metadata
    )
    order by sort_order, route_key
  ), '[]'::jsonb)
  into v_routes
  from resolved_routes;

  with resolved_sets as (
    select distinct on (pos.option_set_key)
      pos.*
    from public.platform_option_sets pos
    where pos.is_active = true
      and (pos.surface = p_channel or pos.surface = 'both')
      and (pos.club_id is null or pos.club_id = p_club_id)
    order by pos.option_set_key, pos.club_id desc nulls last
  )
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'option_set_key', rs.option_set_key,
      'label', rs.label,
      'description', rs.description,
      'value_type', rs.value_type,
      'surface', rs.surface,
      'metadata', rs.metadata,
      'values', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'option_key', pov.option_key,
            'label', pov.label,
            'value', pov.value,
            'sort_order', pov.sort_order,
            'is_default', pov.is_default,
            'metadata', pov.metadata
          )
          order by pov.sort_order, pov.label
        )
        from public.platform_option_values pov
        where pov.option_set_id = rs.id
          and pov.is_active = true
      ), '[]'::jsonb)
    )
    order by rs.option_set_key
  ), '[]'::jsonb)
  into v_option_sets
  from resolved_sets rs;

  with resolved_copy as (
    select distinct on (rc.copy_key, rc.locale)
      rc.*
    from public.runtime_copy rc
    where rc.is_active = true
      and (rc.surface = p_channel or rc.surface = 'both')
      and (rc.club_id is null or rc.club_id = p_club_id)
    order by rc.copy_key, rc.locale, rc.club_id desc nulls last
  )
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'copy_key', copy_key,
      'surface', surface,
      'locale', locale,
      'text_value', text_value,
      'description', description,
      'metadata', metadata
    )
    order by copy_key, locale
  ), '[]'::jsonb)
  into v_runtime_copy
  from resolved_copy;

  with resolved_navigation as (
    select distinct on (sni.nav_key, sni.surface, sni.nav_group)
      sni.*
    from public.site_navigation_items sni
    where sni.is_active = true
      and (sni.surface = p_channel or sni.surface = 'both' or (p_channel = 'web' and sni.surface = 'web'))
      and (sni.club_id is null or sni.club_id = p_club_id)
    order by sni.nav_key, sni.surface, sni.nav_group, sni.club_id desc nulls last
  )
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'nav_key', nav_key,
      'label', label,
      'href', href,
      'nav_group', nav_group,
      'surface', surface,
      'feature_key', feature_key,
      'sort_order', sort_order,
      'metadata', metadata
    )
    order by nav_group, sort_order, label
  ), '[]'::jsonb)
  into v_site_navigation
  from resolved_navigation;

  with resolved_search as (
    select distinct on (ssi.search_key, ssi.surface)
      ssi.*
    from public.site_search_items ssi
    where ssi.is_active = true
      and (ssi.surface = p_channel or ssi.surface = 'both' or (p_channel = 'web' and ssi.surface = 'web'))
      and (ssi.club_id is null or ssi.club_id = p_club_id)
    order by ssi.search_key, ssi.surface, ssi.club_id desc nulls last
  )
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'search_key', search_key,
      'title', title,
      'description', description,
      'href', href,
      'category', category,
      'meta_label', meta_label,
      'surface', surface,
      'feature_key', feature_key,
      'sort_order', sort_order,
      'metadata', metadata
    )
    order by sort_order, title
  ), '[]'::jsonb)
  into v_site_search
  from resolved_search;

  with resolved_venue_controls as (
    select distinct on (vgc.control_key)
      vgc.*
    from public.venue_governance_controls vgc
    where vgc.is_active = true
      and (vgc.club_id is null or vgc.club_id = p_club_id)
      and vgc.venue_id is null
    order by vgc.control_key, vgc.club_id desc nulls last
  )
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'control_key', control_key,
      'label', label,
      'detail', detail,
      'status_label', status_label,
      'action_label', action_label,
      'control_group', control_group,
      'sort_order', sort_order,
      'metadata', metadata
    )
    order by control_group, sort_order, label
  ), '[]'::jsonb)
  into v_venue_governance
  from resolved_venue_controls;

  v_result := jsonb_build_object(
    'features', v_features,
    'content_blocks', v_content_blocks,
    'route_registry', v_routes,
    'option_sets', v_option_sets,
    'runtime_copy', v_runtime_copy,
    'site_navigation', v_site_navigation,
    'site_search', v_site_search,
    'venue_governance_controls', v_venue_governance,
    'config_version', v_now,
    'channel', p_channel,
    'club_id', p_club_id
  );

  return v_result;
end;
$$;


