CREATE OR REPLACE FUNCTION "public"."get_recent_operational_health_events"("p_limit" integer DEFAULT 40) RETURNS TABLE("id" "uuid", "service" "text", "component" "text", "status" "text", "severity" "text", "issue_code" "text", "message" "text", "function_name" "text", "user_id" "uuid", "subject_type" "text", "subject_id" "text", "metadata" "jsonb", "occurred_at" timestamp with time zone)
