CREATE OR REPLACE FUNCTION "public"."get_runtime_app_config"("p_key" "text" DEFAULT NULL::"text", "p_club_id" bigint DEFAULT NULL::bigint) RETURNS TABLE("scope" "text", "key" "text", "value" "text", "club_id" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with allowed_global as (
    select
      'global'::text as scope,
      config.key,
      config.value,
      null::bigint as club_id,
      0 as precedence
    from public.app_config as config
    where (
      config.key like 'feature\_%' escape '\'
      or config.key like 'kill\_%' escape '\'
      or config.key in (
        'default_payment_method',
        'support_whatsapp',
        'support_email'
      )
    )
      and (p_key is null or config.key = p_key)
  ),
  allowed_club as (
    select
      'club'::text as scope,
      config.key,
      config.value,
      config.club_id,
      1 as precedence
    from public.club_app_config as config
    where config.club_id = coalesce(
      p_club_id,
      nullif(public.requesting_club_id(), '')::bigint
    )
      and (
        config.key like 'feature\_%' escape '\'
        or config.key like 'kill\_%' escape '\'
        or config.key in (
          'default_payment_method',
          'support_whatsapp',
          'support_email'
        )
      )
      and (p_key is null or config.key = p_key)
  )
  select allowed.scope, allowed.key, allowed.value, allowed.club_id
  from (
    select * from allowed_global
    union all
    select * from allowed_club
  ) as allowed
  order by allowed.key, allowed.precedence;
$$;


