CREATE OR REPLACE FUNCTION "public"."get_scheduled_trips"("p_lat" double precision, "p_lng" double precision, "p_vehicle_type" "text" DEFAULT NULL::"text", "p_trip_type" "text" DEFAULT NULL::"text", "p_country" "text" DEFAULT NULL::"text", "radius_km" double precision DEFAULT 10) RETURNS TABLE("id" "uuid", "user_id" "uuid", "role" "text", "vehicle_type" "text", "trip_type" "text", "from_location" "text", "from_lat" double precision, "from_lng" double precision, "to_location" "text", "to_lat" double precision, "to_lng" double precision, "travel_time" timestamp with time zone, "repeat_days" "text"[], "status" "text", "contact_phone" "text", "contact_name" "text", "whatsapp_number" "text", "created_at" timestamp with time zone, "distance_km" double precision)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
  select
    mt.id,
    mt.user_id,
    mt.role,
    mt.vehicle_type,
    mt.trip_type,
    mt.from_location,
    mt.from_lat,
    mt.from_lng,
    mt.to_location,
    mt.to_lat,
    mt.to_lng,
    mt.travel_time,
    mt.repeat_days,
    mt.status,
    mt.contact_phone,
    mt.contact_name,
    mt.whatsapp_number,
    mt.created_at,
    round(
      (st_distancesphere(
        mt.origin_geo::geometry,
        st_setsrid(st_makepoint(p_lng, p_lat), 4326)
      ) / 1000.0)::numeric,
      2
    )::double precision as distance_km
  from public.mobility_trips mt
  where mt.status in ('open', 'active')
    and mt.origin_geo is not null
    and (
      p_country is null
      or mt.country = public.normalize_country_code(p_country)
    )
    and st_dwithin(
      mt.origin_geo,
      st_setsrid(st_makepoint(p_lng, p_lat), 4326)::geography,
      radius_km * 1000
    )
    and (
      p_vehicle_type is null
      or mt.vehicle_type = p_vehicle_type
    )
    and (
      p_trip_type is null
      or mt.trip_type = p_trip_type
    )
  order by mt.travel_time asc, mt.created_at desc;
$$;


ALTER FUNCTION "public"."get_scheduled_trips"("p_lat" double precision, "p_lng" double precision, "p_vehicle_type" "text", "p_trip_type" "text", "p_country" "text", "radius_km" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_supported_country_momo_config"("p_country" "text") RETURNS "public"."supported_countries"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_country_code text := public.normalize_country_code(p_country);
  v_config public.supported_countries;
BEGIN
  WITH curated_catalog AS (
    SELECT *
    FROM (
      VALUES
        (
          'RW',
          'Rwanda',
          '+250',
          'momo_rw',
          '*182*8*1*{CODE}#',
          '^0?7[23589]\d{7}$',
          ARRAY[9, 10]::integer[],
          '+250781234567',
          '^0?7[23589]\d{7}$',
          '^\+2507[23589]\d{7}$',
          '^\d{4,9}$',
          4,
          9
        ),
        (
          'UG',
          'Uganda',
          '+256',
          'momo_ug',
          NULL,
          '^0?7[0-9]\d{7}$',
          ARRAY[9, 10]::integer[],
          '+256771234567',
          '^0?7[0-9]\d{7}$',
          '^\+2567[0-9]\d{7}$',
          NULL,
          NULL,
          NULL
        ),
        (
          'KE',
          'Kenya',
          '+254',
          'momo_ke',
          '*247*{recipient}*{amount}#',
          '^0?7[0-9]\d{7}$',
          ARRAY[9, 10]::integer[],
          '+254712345678',
          '^0?7[0-9]\d{7}$',
          '^\+2547[0-9]\d{7}$',
          '^\d{4,10}$',
          4,
          10
        ),
        (
          'TZ',
          'Tanzania',
          '+255',
          'momo_tz',
          NULL,
          '^0?[67][0-9]\d{7}$',
          ARRAY[9, 10]::integer[],
          '+255712345678',
          '^0?[67][0-9]\d{7}$',
          '^\+255[67][0-9]\d{7}$',
          NULL,
          NULL,
          NULL
        ),
        (
          'GH',
          'Ghana',
          '+233',
          'momo_gh',
          NULL,
          '^0?[235][0-9]\d{7}$',
          ARRAY[9, 10]::integer[],
          '+233241234567',
          '^0?[235][0-9]\d{7}$',
          '^\+233[235][0-9]\d{7}$',
          NULL,
          NULL,
          NULL
        )
    ) AS catalog (
      iso_code,
      country_name,
      dial_code,
      momo_provider_id,
      momo_code_ussd_template,
      mobile_national_number_pattern,
      mobile_possible_lengths,
      mobile_example_e164,
      momo_number_local_pattern,
      momo_number_e164_pattern,
      momo_code_pattern,
      momo_code_min_length,
      momo_code_max_length
    )
  ),
  current_countries AS (
    SELECT
      c.id::text AS iso_code,
      c.name::text AS country_name,
      c.dialing_code::text AS dial_code,
      'momo_' || lower(c.id::text) AS momo_provider_id,
      NULLIF(c.ussd_code_format, '')::text AS momo_code_ussd_template,
      '^[0-9]{8,12}$'::text AS mobile_national_number_pattern,
      ARRAY[8, 9, 10, 11, 12]::integer[] AS mobile_possible_lengths,
      CASE
        WHEN c.dialing_code IS NULL OR btrim(c.dialing_code) = '' THEN NULL
        ELSE c.dialing_code || '000000000'
      END AS mobile_example_e164,
      '^[0-9]{8,12}$'::text AS momo_number_local_pattern,
      CASE
        WHEN c.dialing_code IS NULL OR btrim(c.dialing_code) = '' THEN NULL
        ELSE '^\+' || replace(c.dialing_code, '+', '') || '[0-9]{6,12}$'
      END AS momo_number_e164_pattern,
      CASE
        WHEN NULLIF(c.ussd_code_format, '') IS NULL THEN NULL
        ELSE '^\d{4,12}$'
      END AS momo_code_pattern,
      CASE
        WHEN NULLIF(c.ussd_code_format, '') IS NULL THEN NULL
        ELSE 4
      END AS momo_code_min_length,
      CASE
        WHEN NULLIF(c.ussd_code_format, '') IS NULL THEN NULL
        ELSE 12
      END AS momo_code_max_length
    FROM public.countries c
    WHERE c.id = v_country_code
      AND coalesce(c.is_active, true) = true
  ),
  resolved_catalog AS (
    SELECT
      coalesce(cur.iso_code, cat.iso_code) AS iso_code,
      coalesce(cur.country_name, cat.country_name) AS country_name,
      coalesce(cur.dial_code, cat.dial_code) AS dial_code,
      coalesce(cat.momo_provider_id, cur.momo_provider_id) AS momo_provider_id,
      coalesce(cat.momo_code_ussd_template, cur.momo_code_ussd_template) AS momo_code_ussd_template,
      coalesce(cat.mobile_national_number_pattern, cur.mobile_national_number_pattern) AS mobile_national_number_pattern,
      coalesce(cat.mobile_possible_lengths, cur.mobile_possible_lengths) AS mobile_possible_lengths,
      coalesce(cat.mobile_example_e164, cur.mobile_example_e164) AS mobile_example_e164,
      coalesce(cat.momo_number_local_pattern, cur.momo_number_local_pattern) AS momo_number_local_pattern,
      coalesce(cat.momo_number_e164_pattern, cur.momo_number_e164_pattern) AS momo_number_e164_pattern,
      coalesce(cat.momo_code_pattern, cur.momo_code_pattern) AS momo_code_pattern,
      coalesce(cat.momo_code_min_length, cur.momo_code_min_length) AS momo_code_min_length,
      coalesce(cat.momo_code_max_length, cur.momo_code_max_length) AS momo_code_max_length
    FROM curated_catalog cat
    FULL OUTER JOIN current_countries cur ON cur.iso_code = cat.iso_code
    WHERE coalesce(cur.iso_code, cat.iso_code) = v_country_code
  )
  SELECT
    iso_code,
    country_name,
    dial_code,
    momo_provider_id,
    momo_code_ussd_template,
    mobile_national_number_pattern,
    mobile_possible_lengths,
    mobile_example_e164,
    momo_number_local_pattern,
    momo_number_e164_pattern,
    momo_code_pattern,
    momo_code_min_length,
    momo_code_max_length
  INTO v_config
  FROM resolved_catalog
  LIMIT 1;

  RETURN v_config;
END;
$_$;


ALTER FUNCTION "public"."get_supported_country_momo_config"("p_country" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_wallet_statement_entries"("p_start_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_end_before" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_limit" integer DEFAULT 1000, "p_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "entry_type" "text", "ledger_status" "text", "amount" integer, "currency" "text", "tx_datetime" timestamp with time zone, "external_reference" "text", "tx_category" "text", "cashflow_bucket" "text", "counterparty_name" "text", "statement_label" "text", "description" "text", "created_at" timestamp with time zone, "total_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with statement_rows as (
    select
      ledger.id,
      ledger.entry_type,
      ledger.ledger_status,
      ledger.amount,
      ledger.currency,
      coalesce(ledger.tx_datetime, ledger.created_at) as tx_datetime,
      ledger.external_reference,
      coalesce(
        nullif(trim(ledger.tx_category), ''),
        public.derive_momo_tx_category(
          ledger.entry_type,
          ledger.ledger_scope,
          ledger.target_table
        )
      ) as tx_category,
      coalesce(
        nullif(trim(ledger.cashflow_bucket), ''),
        public.derive_momo_cashflow_bucket(
          coalesce(
            nullif(trim(ledger.tx_category), ''),
            public.derive_momo_tx_category(
              ledger.entry_type,
              ledger.ledger_scope,
              ledger.target_table
            )
          ),
          ledger.entry_type
        )
      ) as cashflow_bucket,
      nullif(trim(ledger.counterparty_name), '') as counterparty_name,
      coalesce(
        nullif(trim(ledger.statement_label), ''),
        nullif(trim(ledger.description), ''),
        initcap(replace(coalesce(ledger.tx_category, ledger.entry_type), '_', ' '))
      ) as statement_label,
      ledger.description,
      ledger.created_at
    from public.momo_ledger_entries as ledger
    where ledger.user_id = auth.uid()
      and ledger.ledger_status = 'posted'
      and (p_start_at is null or coalesce(ledger.tx_datetime, ledger.created_at) >= p_start_at)
      and (p_end_before is null or coalesce(ledger.tx_datetime, ledger.created_at) < p_end_before)
  )
  select
    row.id,
    row.entry_type,
    row.ledger_status,
    row.amount,
    row.currency,
    row.tx_datetime,
    row.external_reference,
    row.tx_category,
    row.cashflow_bucket,
    row.counterparty_name,
    row.statement_label,
    row.description,
    row.created_at,
    count(*) over() as total_count
  from statement_rows as row
  order by row.tx_datetime desc, row.created_at desc
  limit greatest(coalesce(p_limit, 1000), 1)
  offset greatest(coalesce(p_offset, 0), 0);
$$;


ALTER FUNCTION "public"."get_wallet_statement_entries"("p_start_at" timestamp with time zone, "p_end_before" timestamp with time zone, "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."group_belongs_to_bank_partner"("p_group_id" "uuid", "p_partner_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.groups g
    left join public.partners p
      on p.id = p_partner_id
    where g.id = p_group_id
      and (
        g.institution_id = p_partner_id::text
        or lower(btrim(coalesce(g.institution_id, ''))) = lower(btrim(coalesce(p.slug, '')))
        or lower(btrim(coalesce(g.bank_partner, ''))) = lower(btrim(coalesce(p.name, '')))
        or lower(btrim(coalesce(g.bank_partner, ''))) = lower(btrim(coalesce(p.slug, '')))
      )
  );
$$;


ALTER FUNCTION "public"."group_belongs_to_bank_partner"("p_group_id" "uuid", "p_partner_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_candidate_club_id bigint;
  v_club_id bigint;
  v_country_code text;
  v_display_name text;
  v_language_code text;
begin
  v_candidate_club_id := public.normalize_club_id(
    nullif(new.raw_app_meta_data ->> 'club_id', '')
  );

  select club.id
    into v_club_id
    from public.african_football_clubs as club
   where club.id = v_candidate_club_id
     and club.is_active
   limit 1;

  v_country_code := coalesce(
    nullif(pg_catalog.upper(new.raw_user_meta_data ->> 'country_code'), ''),
    nullif(pg_catalog.upper(new.raw_user_meta_data ->> 'country'), ''),
    'RW'
  );
  v_display_name := coalesce(
    nullif(pg_catalog.btrim(new.raw_user_meta_data ->> 'display_name'), ''),
    nullif(pg_catalog.btrim(new.raw_user_meta_data ->> 'full_name'), '')
  );
  v_language_code := coalesce(
    nullif(pg_catalog.lower(new.raw_user_meta_data ->> 'language_code'), ''),
    'rw'
  );

  insert into public.profiles (
    id,
    club_id,
    display_name,
    full_name,
    country_code,
    country,
    language_code,
    is_active
  ) values (
    new.id,
    v_club_id,
    v_display_name,
    v_display_name,
    v_country_code,
    v_country_code,
    v_language_code,
    true
  )
  on conflict (id) do nothing;

  insert into public.user_privacy_settings (user_id, club_id)
  values (new.id, v_club_id)
  on conflict (user_id) do nothing;

  insert into public.user_notification_settings (user_id, club_id)
  values (new.id, v_club_id)
  on conflict (user_id) do nothing;

  return new;
end;
$$;


ALTER FUNCTION "public"."handle_new_user"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."infer_momo_route_type_for_country"("p_country" "text", "p_value" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
declare
  v_country public.supported_countries;
  v_trimmed text := btrim(coalesce(p_value, ''));
  v_digits text;
  v_dial_digits text;
begin
  if v_trimmed = '' then
    return null;
  end if;

  if public.is_valid_momo_phone_for_country(p_country, v_trimmed) then
    return 'phone_number';
  end if;

  if public.is_valid_momo_code_for_country(p_country, v_trimmed) then
    return 'code';
  end if;

  select *
  into v_country
  from public.get_supported_country_momo_config(p_country);

  if v_country.iso_code is null then
    return null;
  end if;

  v_digits := regexp_replace(v_trimmed, '[^0-9]', '', 'g');
  v_dial_digits := replace(v_country.dial_code, '+', '');

  if left(v_trimmed, 1) = '+'
     or left(v_trimmed, 1) = '0'
     or left(v_digits, length(v_dial_digits)) = v_dial_digits
     or char_length(v_digits) >= 9 then
    return 'phone_number';
  end if;

  return 'code';
end;
$$;


ALTER FUNCTION "public"."infer_momo_route_type_for_country"("p_country" "text", "p_value" "text") OWNER TO "postgres";


