CREATE OR REPLACE FUNCTION "public"."is_valid_momo_code_for_country"("p_country" "text", "p_value" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
