CREATE OR REPLACE FUNCTION "public"."list_admin_role_assignments"("p_role" "text" DEFAULT NULL::"text", "p_active_only" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller_id uuid;
  v_result jsonb;
BEGIN
  v_caller_id := auth.uid();

  -- Only platform admins can list all assignments
  IF NOT EXISTS (
    SELECT 1 FROM public.users u
    WHERE u.id = v_caller_id AND u.is_admin = true
  ) THEN
    RAISE EXCEPTION 'Only platform admins can list admin role assignments.';
  END IF;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', ra.id,
      'user_id', ra.user_id,
      'user_name', u.full_name,
      'user_phone', u.phone,
      'role', ra.role,
      'partner_scope_id', ra.partner_scope_id,
      'partner_name', p.name,
      'granted_by', ra.granted_by,
      'granted_at', ra.granted_at,
      'revoked_at', ra.revoked_at,
      'is_active', ra.is_active,
      'notes', ra.notes
    ) ORDER BY ra.granted_at DESC
  ), '[]'::jsonb)
  INTO v_result
  FROM public.admin_role_assignments ra
  LEFT JOIN public.users u ON u.id = ra.user_id
  LEFT JOIN public.partners p ON p.id = ra.partner_scope_id
  WHERE (p_role IS NULL OR ra.role = p_role)
    AND (NOT p_active_only OR ra.is_active = true);

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."list_admin_role_assignments"("p_role" "text", "p_active_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_admin_mutation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_target_id text;
  v_old_json jsonb;
  v_new_json jsonb;
BEGIN
  IF TG_OP = 'DELETE' or TG_OP = 'UPDATE' THEN
    v_old_json := to_jsonb(OLD);
  END IF;

  IF TG_OP = 'INSERT' or TG_OP = 'UPDATE' THEN
    v_new_json := to_jsonb(NEW);
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF TG_TABLE_NAME = 'app_config' THEN
      v_target_id := (v_old_json->>'key')::text;
    ELSE
      v_target_id := (v_old_json->>'id')::text;
    END IF;
  ELSE
    IF TG_TABLE_NAME = 'app_config' THEN
      v_target_id := (v_new_json->>'key')::text;
    ELSE
      v_target_id := (v_new_json->>'id')::text;
    END IF;
  END IF;

  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.admin_audit_log (actor_id, action, target_table, target_id, new_data)
    VALUES (auth.uid(), 'create', TG_TABLE_NAME, v_target_id, v_new_json);
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' THEN
    INSERT INTO public.admin_audit_log (actor_id, action, target_table, target_id, old_data, new_data)
    VALUES (auth.uid(), 'update', TG_TABLE_NAME, v_target_id, v_old_json, v_new_json);
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    INSERT INTO public.admin_audit_log (actor_id, action, target_table, target_id, old_data)
    VALUES (auth.uid(), 'delete', TG_TABLE_NAME, v_target_id, v_old_json);
    RETURN OLD;
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."log_admin_mutation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_feature_config_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_feature_id uuid;
  v_action text;
  v_before jsonb := '{}'::jsonb;
  v_after  jsonb := '{}'::jsonb;
BEGIN
  IF TG_TABLE_NAME = 'platform_features' THEN
    IF TG_OP = 'DELETE' THEN
      v_feature_id := NULL;
    ELSE
      v_feature_id := NEW.id;
    END IF;
  ELSIF TG_TABLE_NAME = 'platform_feature_channels' THEN
    IF TG_OP = 'DELETE' THEN
      v_feature_id := OLD.feature_id;
    ELSE
      v_feature_id := NEW.feature_id;
    END IF;
  ELSIF TG_TABLE_NAME = 'platform_feature_rules' THEN
    IF TG_OP = 'DELETE' THEN
      v_feature_id := OLD.feature_id;
    ELSE
      v_feature_id := NEW.feature_id;
    END IF;
  ELSIF TG_TABLE_NAME = 'platform_content_blocks' THEN
    IF TG_OP = 'DELETE' THEN
      v_feature_id := OLD.feature_id;
    ELSE
      v_feature_id := NEW.feature_id;
    END IF;
  END IF;

  IF v_feature_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.platform_features
    WHERE id = v_feature_id
  ) THEN
    v_feature_id := NULL;
  END IF;

  v_action := lower(TG_OP) || '_' || TG_TABLE_NAME;

  IF TG_OP IN ('UPDATE', 'DELETE') THEN
    v_before := to_jsonb(OLD);
  END IF;
  IF TG_OP IN ('INSERT', 'UPDATE') THEN
    v_after := to_jsonb(NEW);
  END IF;

  INSERT INTO public.platform_feature_audit_logs (
    feature_id,
    action,
    changed_by,
    before_state,
    after_state
  ) VALUES (
    v_feature_id,
    v_action,
    auth.uid(),
    v_before,
    v_after
  );

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."log_feature_config_change"() OWNER TO "postgres";


