    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  new.updated_at := now();
  return new;
end;
$$;


ALTER FUNCTION "public"."partners_set_updated_at"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."populate_event_club_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  IF NEW.club_id IS NULL THEN
    NEW.club_id := NULLIF(public.requesting_club_id(), '')::bigint;
  END IF;

  IF NEW.club_id IS NULL THEN
    SELECT club_id INTO NEW.club_id
      FROM public.profiles
     WHERE id = NEW.user_id;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."populate_event_club_scope"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."populate_group_message_defaults"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$ begin if new.alias is null then new.alias := substr(md5(new.sender_id::text || new.group_id::text), 1, 6); end if; return new; end; $$;


ALTER FUNCTION "public"."populate_group_message_defaults"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prediction_admin_get_challenges"("p_club_id" bigint DEFAULT NULL::bigint, "p_statuses" "text"[] DEFAULT NULL::"text"[], "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'football', 'auth'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_club_id bigint;
  v_payload jsonb;
begin
  if v_user_id is null then
    raise exception 'Auth required.';
  end if;

  v_club_id := public.fet_require_club_context(p_club_id);

  if not (public.is_super_admin() or public.is_admin_user() or public.is_club_admin(v_club_id)) then
    raise exception 'Admin access required.';
  end if;

  select coalesce(
    jsonb_agg(
      ranked.payload
      order by ranked.sort_updated desc nulls last, ranked.created_at desc
    ),
    '[]'::jsonb
  )
    into v_payload
    from (
      select
        (public.prediction_challenge_summary_json(challenge.id, v_user_id)
          || jsonb_build_object(
            'admin', jsonb_build_object(
              'audit_status', challenge.status,
              'settlement_state', case
                when settlement.challenge_id is not null then 'recorded'
                when challenge.status in ('settled', 'void', 'cancelled') then 'missing_record'
                else 'pending'
              end,
              'settlement_mode', settlement.settlement_mode,
              'executed_at', settlement.executed_at,
              'metadata', coalesce(settlement.metadata, '{}'::jsonb)
            )
          )) as payload,
        coalesce(challenge.updated_at, challenge.created_at) as sort_updated,
        challenge.created_at
      from football.prediction_challenges challenge
      left join football.prediction_challenge_settlements settlement
        on settlement.challenge_id = challenge.id
      where challenge.club_id = v_club_id
        and (
          p_statuses is null
          or array_length(p_statuses, 1) is null
          or challenge.status = any(p_statuses)
        )
      order by coalesce(challenge.updated_at, challenge.created_at) desc
      limit greatest(coalesce(p_limit, 50), 1)
      offset greatest(coalesce(p_offset, 0), 0)
    ) ranked;

  return coalesce(v_payload, '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."prediction_admin_get_challenges"("p_club_id" bigint, "p_statuses" "text"[], "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prediction_admin_settle"("p_fixture_id" "uuid", "p_home_score" integer, "p_away_score" integer, "p_status" "text" DEFAULT 'finished'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'football'
    AS $$
declare
  v_status football.fixture_status := coalesce(nullif(p_status, ''), 'finished')::football.fixture_status;
  v_settlements jsonb := '[]'::jsonb;
  v_fm record;
  v_correct_outcome text;
  v_total_goals int;
  v_settle_result jsonb;
  v_acca_result jsonb;
  v_notif_result jsonb;
  v_streak_user record;
begin
  if auth.role() != 'service_role' then
    return jsonb_build_object('status', 'error', 'message', 'Service role required.');
  end if;

  if not exists (select 1 from football.fixtures where id = p_fixture_id) then
    return jsonb_build_object('status', 'error', 'message', 'Fixture not found.');
  end if;

  update football.fixtures
  set home_score = p_home_score,
      away_score = p_away_score,
      status = v_status,
      updated_at = now()
  where id = p_fixture_id;

  v_total_goals := p_home_score + p_away_score;

  for v_fm in
    select fm.id as fm_id, pm.slug as market_slug
    from football.fixture_markets fm
    join football.prediction_markets pm on pm.id = fm.market_id
    where fm.fixture_id = p_fixture_id
  loop
    v_correct_outcome := null;

    case v_fm.market_slug
      when '1x2' then
        v_correct_outcome := case
          when p_home_score > p_away_score then 'Home'
          when p_home_score = p_away_score then 'Draw'
          else 'Away'
        end;
      when 'btts' then
        v_correct_outcome := case
          when p_home_score > 0 and p_away_score > 0 then 'Yes'
          else 'No'
        end;
      when 'over-under-1-5' then
        v_correct_outcome := case when v_total_goals > 1 then 'Over 1.5' else 'Under 1.5' end;
      when 'over-under-2-5' then
        v_correct_outcome := case when v_total_goals > 2 then 'Over 2.5' else 'Under 2.5' end;
      else
        v_correct_outcome := null;
    end case;

    if v_correct_outcome is not null then
      v_settlements := v_settlements || jsonb_build_object(
        'market_slug', v_fm.market_slug,
        'correct_outcome', v_correct_outcome
      );
    end if;
  end loop;

  v_settle_result := '{"status":"skipped"}'::jsonb;
  if jsonb_array_length(v_settlements) > 0 then
    v_settle_result := public.prediction_settle_fixture(p_fixture_id, v_settlements);
  end if;

  v_acca_result := public.prediction_settle_acca_slips(p_fixture_id);
  v_notif_result := public.prediction_queue_settlement_notifications(p_fixture_id);

  for v_streak_user in
    select distinct p.user_id
    from football.predictions p
    where p.fixture_id = p_fixture_id
      and p.status in ('won', 'lost')
      and p.settled_at >= now() - interval '10 seconds'
  loop
    begin
      perform public.prediction_check_streak_reward(v_streak_user.user_id);
    exception when others then
      raise notice 'Streak check failed for user %: %', v_streak_user.user_id, sqlerrm;
    end;
  end loop;

  return jsonb_build_object(
    'status', 'success',
    'fixture_id', p_fixture_id,
    'score', format('%s - %s', p_home_score, p_away_score),
    'markets_settled', jsonb_array_length(v_settlements),
    'settlement', v_settle_result,
    'acca', v_acca_result,
    'notifications', v_notif_result
  );
end;
$$;


ALTER FUNCTION "public"."prediction_admin_settle"("p_fixture_id" "uuid", "p_home_score" integer, "p_away_score" integer, "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prediction_admin_settle"("p_fixture_id" "uuid", "p_home_score" integer, "p_away_score" integer, "p_status" "text" DEFAULT 'finished'::"text", "p_ht_home_score" integer DEFAULT NULL::integer, "p_ht_away_score" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'football'
    AS $$
declare
  v_status football.fixture_status := coalesce(nullif(p_status, ''), 'finished')::football.fixture_status;
  v_settlements jsonb := '[]'::jsonb;
  v_fm record;
  v_correct_outcome text;
  v_total_goals int;
  v_settle_result jsonb;
  v_acca_result jsonb;
  v_notif_result jsonb;
  v_streak_user record;
begin
  if auth.role() != 'service_role' then
    return jsonb_build_object('status', 'error', 'message', 'Service role required.');
  end if;

  if not exists (select 1 from football.fixtures where id = p_fixture_id) then
    return jsonb_build_object('status', 'error', 'message', 'Fixture not found.');
  end if;

  update football.fixtures
  set home_score = p_home_score,
      away_score = p_away_score,
      status = v_status,
      updated_at = now()
  where id = p_fixture_id;

  v_total_goals := p_home_score + p_away_score;

  for v_fm in
    select fm.id as fm_id, pm.slug as market_slug
    from football.fixture_markets fm
    join football.prediction_markets pm on pm.id = fm.market_id
    where fm.fixture_id = p_fixture_id
  loop
    v_correct_outcome := null;

    case v_fm.market_slug
      when '1x2' then
        v_correct_outcome := case
          when p_home_score > p_away_score then 'home'
          when p_home_score = p_away_score then 'draw'
          else 'away'
        end;
      when 'btts' then
        v_correct_outcome := case when p_home_score > 0 and p_away_score > 0 then 'yes' else 'no' end;
      when 'over-under-1-5' then
        v_correct_outcome := case when v_total_goals > 1 then 'over' else 'under' end;
      when 'over-under-2-5' then
        v_correct_outcome := case when v_total_goals > 2 then 'over' else 'under' end;
      when 'over-under-3-5' then
        v_correct_outcome := case when v_total_goals > 3 then 'over' else 'under' end;
      when 'half-time-result' then
        if p_ht_home_score is not null and p_ht_away_score is not null then
          v_correct_outcome := case
            when p_ht_home_score > p_ht_away_score then 'home'
            when p_ht_home_score = p_ht_away_score then 'draw'
            else 'away'
          end;
        end if;
      when 'correct-score' then
        v_correct_outcome := p_home_score::text || '-' || p_away_score::text;
      else
        v_correct_outcome := null;
    end case;

    if v_correct_outcome is not null then
      v_settlements := v_settlements || jsonb_build_object(
        'market_slug', v_fm.market_slug,
        'correct_outcome', v_correct_outcome
      );
    end if;
  end loop;

  v_settle_result := '{"status":"skipped"}'::jsonb;
  if jsonb_array_length(v_settlements) > 0 then
    v_settle_result := public.prediction_settle_fixture(p_fixture_id, v_settlements);
  end if;

  v_acca_result := public.prediction_settle_acca_slips(p_fixture_id);
  v_notif_result := public.prediction_queue_settlement_notifications(p_fixture_id);

  for v_streak_user in
    select distinct p.user_id
    from football.predictions p
    where p.fixture_id = p_fixture_id
      and p.status in ('won', 'lost')
      and p.settled_at >= now() - interval '10 seconds'
  loop
    begin
      perform public.prediction_check_streak_reward(v_streak_user.user_id);
    exception when others then
      raise notice 'Streak check failed for user %: %', v_streak_user.user_id, sqlerrm;
    end;
  end loop;

  return jsonb_build_object(
    'status', 'success',
    'fixture_id', p_fixture_id,
    'score', format('%s - %s', p_home_score, p_away_score),
    'ht_score', case
      when p_ht_home_score is not null then format('%s - %s', p_ht_home_score, p_ht_away_score)
      else null
    end,
    'markets_settled', jsonb_array_length(v_settlements),
    'settlement', v_settle_result,
    'acca', v_acca_result,
    'notifications', v_notif_result
  );
end;
$$;


ALTER FUNCTION "public"."prediction_admin_settle"("p_fixture_id" "uuid", "p_home_score" integer, "p_away_score" integer, "p_status" "text", "p_ht_home_score" integer, "p_ht_away_score" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prediction_award_badge"("p_user_id" "uuid", "p_badge_slug" "text", "p_badge_name" "text", "p_description" "text", "p_threshold" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'football'
    AS $$
begin
  if auth.role() != 'service_role' then
    return jsonb_build_object('status', 'error', 'message', 'Service role required.');
  end if;

  insert into football.prediction_badges (
    user_id, badge_slug, badge_name, badge_description, threshold_wins
  )
  values (p_user_id, p_badge_slug, p_badge_name, p_description, p_threshold)
  on conflict (user_id, badge_slug) do nothing;

  return jsonb_build_object(
    'status', 'ok',
    'badge', p_badge_slug,
    'awarded', true
  );
end;
$$;


ALTER FUNCTION "public"."prediction_award_badge"("p_user_id" "uuid", "p_badge_slug" "text", "p_badge_name" "text", "p_description" "text", "p_threshold" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prediction_cancel"("p_prediction_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'football'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_pred record;
begin
  if v_user_id is null then
    return jsonb_build_object('status', 'error', 'message', 'Authentication required.');
  end if;

  select p.*, f.status as fixture_status, f.kickoff_at
  into v_pred
  from football.predictions p
  join football.fixtures f on f.id = p.fixture_id
  where p.id = p_prediction_id
    and p.user_id = v_user_id;

  if v_pred is null then
    return jsonb_build_object('status', 'error', 'message', 'Prediction not found.');
  end if;

  if v_pred.status != 'pending' then
    return jsonb_build_object('status', 'error', 'message', 'Only pending predictions can be cancelled.');
  end if;

  if v_pred.fixture_status in ('live', 'finished') then
    return jsonb_build_object('status', 'error', 'message', 'Cannot cancel — fixture already started.');
  end if;

  update football.predictions
  set status = 'cancelled'
  where id = p_prediction_id;

  -- Update slip status if single
  update football.prediction_slips
  set status = 'cancelled'
  where id = v_pred.slip_id
    and slip_type = 'single';

  return jsonb_build_object(
    'status', 'cancelled',
    'prediction_id', p_prediction_id,
    'message', 'Prediction cancelled.'
  );
end;
$$;


ALTER FUNCTION "public"."prediction_cancel"("p_prediction_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prediction_challenge_adjust_wallet"("p_club_id" bigint, "p_user_id" "uuid", "p_amount_fet" bigint, "p_direction" "text", "p_reference_type" "text", "p_reference_id" "text", "p_idempotency_key" "text" DEFAULT NULL::"text", "p_note" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_membership public.fan_memberships;
  v_existing public.fet_wallet_ledger_entries;
  v_direction text := lower(btrim(coalesce(p_direction, '')));
  v_idempotency_key text := nullif(btrim(coalesce(p_idempotency_key, '')), '');
  v_reference_type text := nullif(btrim(coalesce(p_reference_type, '')), '');
  v_reference_id text := nullif(btrim(coalesce(p_reference_id, '')), '');
  v_amount integer := greatest(coalesce(p_amount_fet, 0), 0)::integer;
  v_entry_type text;
  v_new_balance integer;
begin
  if p_club_id is null then
    raise exception 'Club scope is required.';
  end if;

  if p_user_id is null then
    raise exception 'Target user is required.';
  end if;

  if v_amount <= 0 then
    return coalesce((
      select membership.points::bigint
        from public.fan_memberships membership
       where membership.user_id = p_user_id
         and membership.club_id = p_club_id
       limit 1
    ), 0);
  end if;

  if v_direction not in ('debit', 'credit') then
    raise exception 'Invalid wallet direction: %.', p_direction;
  end if;

  if v_idempotency_key is not null then
    select *
      into v_existing
      from public.fet_wallet_ledger_entries ledger
     where ledger.club_id = p_club_id
       and ledger.user_id = p_user_id
       and ledger.idempotency_key = v_idempotency_key
     order by ledger.created_at desc, ledger.id desc
     limit 1;

    if v_existing.id is not null then
      return coalesce(v_existing.balance_after, 0);
    end if;
  end if;

  perform public.fet_wallet_ensure_membership(p_user_id, p_club_id);

  select *
    into v_membership
    from public.fan_memberships membership
   where membership.user_id = p_user_id
     and membership.club_id = p_club_id
   for update;

  if v_membership.id is null then
    raise exception 'Wallet membership not found.';
  end if;

  if v_direction = 'debit' then
    if coalesce(v_membership.points, 0) < v_amount then
      raise exception 'Insufficient FET balance.';
    end if;
    v_new_balance := coalesce(v_membership.points, 0) - v_amount;
    v_entry_type := 'redeem';
  else
    v_new_balance := coalesce(v_membership.points, 0) + v_amount;
    v_entry_type := 'earn';
  end if;

  update public.fan_memberships
     set points = v_new_balance,
         tier = public.resolve_fan_tier(v_new_balance),
         updated_at = timezone('utc', now())
   where id = v_membership.id
  returning * into v_membership;

  perform public.fet_wallet_append_entry(
    p_club_id := p_club_id,
    p_user_id := p_user_id,
    p_membership_id := v_membership.id,
    p_entry_type := v_entry_type,
    p_direction := v_direction,
    p_amount := v_amount,
    p_balance_after := v_membership.points,
    p_counterparty_user_id := null,
    p_reference_type := v_reference_type,
    p_reference_id := v_reference_id,
    p_idempotency_key := v_idempotency_key,
    p_note := p_note,
    p_metadata := coalesce(p_metadata, '{}'::jsonb),
    p_created_by := auth.uid()
  );

  return v_membership.points;
end;
$$;


ALTER FUNCTION "public"."prediction_challenge_adjust_wallet"("p_club_id" bigint, "p_user_id" "uuid", "p_amount_fet" bigint, "p_direction" "text", "p_reference_type" "text", "p_reference_id" "text", "p_idempotency_key" "text", "p_note" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prediction_challenge_admin_retry_settlement"("p_challenge_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'football', 'auth'
    AS $$
declare
  v_club_id bigint;
begin
  select challenge.club_id
    into v_club_id
    from football.prediction_challenges challenge
   where challenge.id = p_challenge_id
   limit 1;

  if v_club_id is null then
    raise exception 'Challenge not found.';
  end if;

  if not (public.is_super_admin() or public.is_admin_user() or public.is_club_admin(v_club_id)) then
    raise exception 'Admin access required.';
  end if;

  return public.prediction_challenge_settle_internal(
    p_challenge_id := p_challenge_id,
    p_force := true
  );
end;
$$;


ALTER FUNCTION "public"."prediction_challenge_admin_retry_settlement"("p_challenge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prediction_challenge_cancel"("p_challenge_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'football', 'auth'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_challenge football.prediction_challenges;
begin
  if v_user_id is null then
    raise exception 'Auth required.';
  end if;

  select *
    into v_challenge
    from football.prediction_challenges challenge
   where challenge.id = p_challenge_id
   for update;

  if v_challenge.id is null then
    raise exception 'Challenge not found.';
  end if;

  if v_challenge.creator_user_id <> v_user_id then
    raise exception 'Only the creator can cancel this challenge.';
  end if;

  if v_challenge.status = 'cancelled' then
    return jsonb_build_object(
      'status', 'cancelled',
      'challenge', public.prediction_challenge_summary_json(p_challenge_id, v_user_id)
    );
  end if;

  if v_challenge.status != 'open' or v_challenge.lock_at <= timezone('utc', now()) then
    raise exception 'Challenge can no longer be cancelled.';
  end if;

  if v_challenge.total_participants > 1 then
    raise exception 'Challenge cannot be cancelled after another participant joins.';
  end if;

  update football.prediction_challenges
     set status = 'cancelled',
         cancelled_at = timezone('utc', now()),
         updated_at = timezone('utc', now())
   where id = p_challenge_id;

  update football.prediction_challenge_entries
     set status = 'cancelled',
         settled_at = timezone('utc', now())
   where challenge_id = p_challenge_id;

  perform public.prediction_challenge_adjust_wallet(
    p_club_id := v_challenge.club_id,
    p_user_id := v_user_id,
    p_amount_fet := v_challenge.stake_fet,
    p_direction := 'credit',
    p_reference_type := 'challenge_cancel',
    p_reference_id := p_challenge_id::text,
    p_idempotency_key := 'challenge-cancel-refund:' || p_challenge_id::text || ':' || v_user_id::text,
    p_note := 'Refund for cancelled challenge',
    p_metadata := jsonb_build_object(
      'challenge_id', p_challenge_id,
      'match_id', v_challenge.match_id,
      'kind', 'challenge_refund'
    )
  );

  insert into football.prediction_challenge_settlements (
    challenge_id,
    match_id,
    official_home_score,
    official_away_score,
    winners_count,
    losers_count,
    total_pool_fet,
    losers_pool_fet,
    payout_per_winner_fet,
    settlement_mode,
    executed_at,
    metadata
  )
  values (
    p_challenge_id,
    v_challenge.match_id,
    null,
    null,
    0,
    0,
    v_challenge.total_pool_fet,
    0,
    0,
    'cancelled',
    timezone('utc', now()),
    jsonb_build_object('reason', 'creator_cancelled')
  )
  on conflict (challenge_id) do update
    set settlement_mode = excluded.settlement_mode,
        executed_at = excluded.executed_at,
        metadata = excluded.metadata;

  perform public.prediction_challenge_queue_notification(
    p_user_id := v_user_id,
    p_notification_type := 'challenge_cancelled',
    p_title := 'Challenge cancelled',
    p_body := format('Your %s FET stake was refunded.', v_challenge.stake_fet),
    p_payload := jsonb_build_object(
      'challenge_id', p_challenge_id,
      'fixture_id', v_challenge.match_id,
      'earned', v_challenge.stake_fet,
      'route', '/challenge/' || p_challenge_id::text
    )
  );

  return jsonb_build_object(
    'status', 'cancelled',
    'challenge', public.prediction_challenge_summary_json(p_challenge_id, v_user_id)
  );
end;
$$;


ALTER FUNCTION "public"."prediction_challenge_cancel"("p_challenge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prediction_challenge_create"("p_match_id" "uuid", "p_home_score" integer, "p_away_score" integer, "p_stake_fet" bigint, "p_club_id" bigint DEFAULT NULL::bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'football', 'auth'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_club_id bigint;
  v_fixture record;
  v_challenge_id uuid;
  v_existing_challenge_id uuid;
begin
  if v_user_id is null then
    raise exception 'Auth required.';
  end if;

  if p_home_score is null or p_away_score is null or p_home_score < 0 or p_away_score < 0 or p_home_score > 20 or p_away_score > 20 then
    raise exception 'Invalid score prediction.';
  end if;

  if p_stake_fet < 100 or p_stake_fet > 100000 then
    raise exception 'Stake must be between 100 and 100000 FET.';
  end if;

  v_club_id := public.fet_require_club_context(p_club_id);

  select fixture.id, fixture.kickoff_at, fixture.status
    into v_fixture
    from football.fixtures fixture
   where fixture.id = p_match_id
   limit 1;

  if v_fixture.id is null then
    raise exception 'Match not found.';
  end if;

  if v_fixture.kickoff_at is null or v_fixture.kickoff_at <= timezone('utc', now()) then
    raise exception 'Match has already started.';
  end if;

  if coalesce(v_fixture.status::text, 'scheduled') not in ('scheduled', 'pending') then
    raise exception 'Challenge creation is only available for upcoming matches.';
  end if;

  select challenge.id
    into v_existing_challenge_id
    from football.prediction_challenges challenge
    join football.prediction_challenge_entries creator_entry
      on creator_entry.challenge_id = challenge.id
     and creator_entry.user_id = challenge.creator_user_id
   where challenge.club_id = v_club_id
     and challenge.creator_user_id = v_user_id
     and challenge.match_id = p_match_id
     and challenge.stake_fet = p_stake_fet
     and challenge.status in ('open', 'locked')
     and creator_entry.predicted_home_score = p_home_score
     and creator_entry.predicted_away_score = p_away_score
   order by challenge.created_at desc
   limit 1;

  if v_existing_challenge_id is not null then
    return jsonb_build_object(
      'status', 'already_processed',
      'challenge', public.prediction_challenge_summary_json(v_existing_challenge_id, v_user_id)
    );
  end if;

  insert into football.prediction_challenges (
    club_id,
    match_id,
    creator_user_id,
    stake_fet,
    currency_code,
    status,
    lock_at,
    total_participants,
    total_pool_fet
  )
  values (
    v_club_id,
    p_match_id,
    v_user_id,
    p_stake_fet,
    'FET',
    'open',
    v_fixture.kickoff_at,
    1,
    p_stake_fet
  )
  returning id into v_challenge_id;

  insert into football.prediction_challenge_entries (
    challenge_id,
    user_id,
    predicted_home_score,
    predicted_away_score,
    stake_fet,
    status
  )
  values (
    v_challenge_id,
    v_user_id,
    p_home_score,
    p_away_score,
    p_stake_fet,
    'active'
  );

  perform public.prediction_challenge_adjust_wallet(
    p_club_id := v_club_id,
    p_user_id := v_user_id,
    p_amount_fet := p_stake_fet,
    p_direction := 'debit',
    p_reference_type := 'challenge_create',
    p_reference_id := v_challenge_id::text,
    p_idempotency_key := 'challenge-create-stake:' || v_challenge_id::text,
    p_note := 'Stake locked for challenge creation',
    p_metadata := jsonb_build_object(
      'challenge_id', v_challenge_id,
      'match_id', p_match_id,
      'kind', 'challenge_stake'
    )
  );

  perform public.prediction_challenge_queue_notification(
    p_user_id := v_user_id,
    p_notification_type := 'challenge_created',
    p_title := 'Challenge created',
    p_body := format(
      'Your %s-%s challenge is live with %s FET at stake.',
      p_home_score,
      p_away_score,
      p_stake_fet
    ),
    p_payload := jsonb_build_object(
      'challenge_id', v_challenge_id,
      'fixture_id', p_match_id,
      'route', '/challenge/' || v_challenge_id::text
    )
  );

  return jsonb_build_object(
    'status', 'created',
    'challenge', public.prediction_challenge_summary_json(v_challenge_id, v_user_id)
  );
end;
$$;


ALTER FUNCTION "public"."prediction_challenge_create"("p_match_id" "uuid", "p_home_score" integer, "p_away_score" integer, "p_stake_fet" bigint, "p_club_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prediction_challenge_fixture_json"("p_match_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'football'
    AS $$
  select coalesce(
    (
      select jsonb_build_object(
        'id', fixture.id,
        'competition_slug', fixture.competition_slug,
        'competition_name', fixture.competition_name,
        'season_label', fixture.season_label,
        'matchday', fixture.matchday,
        'home_team_slug', fixture.home_team_slug,
        'home_team_name', fixture.home_team_name,
        'home_team_short_name', fixture.home_team_short_name,
        'away_team_slug', fixture.away_team_slug,
        'away_team_name', fixture.away_team_name,
        'away_team_short_name', fixture.away_team_short_name,
        'kickoff_at', fixture.kickoff_at,
        'venue_name', fixture.venue_name,
        'status', fixture.status,
        'home_score', fixture.home_score,
        'away_score', fixture.away_score,
        'home_team_logo_url', coalesce(fixture.home_team_logo, fixture.home_team_logo_url),
        'away_team_logo_url', coalesce(fixture.away_team_logo, fixture.away_team_logo_url),
        'competition_logo_url', coalesce(fixture.competition_logo, fixture.competition_logo_url)
      )
        from public.football_fixtures_catalog fixture
       where fixture.id = p_match_id
       limit 1
    ),
    '{}'::jsonb
  );
$$;


ALTER FUNCTION "public"."prediction_challenge_fixture_json"("p_match_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prediction_challenge_join"("p_challenge_id" "uuid", "p_home_score" integer, "p_away_score" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'football', 'auth'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_challenge football.prediction_challenges;
begin
  if v_user_id is null then
    raise exception 'Auth required.';
  end if;

  if p_home_score is null or p_away_score is null or p_home_score < 0 or p_away_score < 0 or p_home_score > 20 or p_away_score > 20 then
    raise exception 'Invalid score prediction.';
  end if;

  select *
    into v_challenge
    from football.prediction_challenges challenge
   where challenge.id = p_challenge_id
   for update;

  if v_challenge.id is null then
    raise exception 'Challenge not found.';
  end if;

  if v_challenge.status != 'open' or v_challenge.lock_at <= timezone('utc', now()) then
    raise exception 'Challenge is closed.';
  end if;

  if exists (
    select 1
      from football.prediction_challenge_entries entry
     where entry.challenge_id = p_challenge_id
       and entry.user_id = v_user_id
  ) then
    return jsonb_build_object(
      'status', 'already_joined',
      'challenge', public.prediction_challenge_summary_json(p_challenge_id, v_user_id)
    );
  end if;

  insert into football.prediction_challenge_entries (
    challenge_id,
    user_id,
    predicted_home_score,
    predicted_away_score,
    stake_fet,
    status
  )
  values (
    p_challenge_id,
    v_user_id,
    p_home_score,
    p_away_score,
    v_challenge.stake_fet,
    'active'
  );

  update football.prediction_challenges
     set total_participants = total_participants + 1,
         total_pool_fet = total_pool_fet + v_challenge.stake_fet,
         updated_at = timezone('utc', now())
   where id = p_challenge_id;

  perform public.prediction_challenge_adjust_wallet(
    p_club_id := v_challenge.club_id,
    p_user_id := v_user_id,
    p_amount_fet := v_challenge.stake_fet,
    p_direction := 'debit',
    p_reference_type := 'challenge_join',
    p_reference_id := p_challenge_id::text,
    p_idempotency_key := 'challenge-join-stake:' || p_challenge_id::text || ':' || v_user_id::text,
    p_note := 'Stake locked for challenge join',
    p_metadata := jsonb_build_object(
      'challenge_id', p_challenge_id,
      'match_id', v_challenge.match_id,
      'kind', 'challenge_stake'
    )
  );

  perform public.prediction_challenge_queue_notification(
    p_user_id := v_user_id,
    p_notification_type := 'challenge_joined',
    p_title := 'Challenge joined',
    p_body := format(
      'You joined the challenge with %s-%s for %s FET.',
      p_home_score,
      p_away_score,
      v_challenge.stake_fet
    ),
    p_payload := jsonb_build_object(
      'challenge_id', p_challenge_id,
      'fixture_id', v_challenge.match_id,
      'route', '/challenge/' || p_challenge_id::text
    )
  );

  if v_challenge.creator_user_id <> v_user_id then
    perform public.prediction_challenge_queue_notification(
      p_user_id := v_challenge.creator_user_id,
      p_notification_type := 'challenge_participant_joined',
      p_title := 'A supporter joined your challenge',
      p_body := format('Your %s FET pool just picked up another participant.', v_challenge.stake_fet),
      p_payload := jsonb_build_object(
        'challenge_id', p_challenge_id,
        'fixture_id', v_challenge.match_id,
        'route', '/challenge/' || p_challenge_id::text
      )
    );
  end if;

  return jsonb_build_object(
    'status', 'joined',
    'challenge', public.prediction_challenge_summary_json(p_challenge_id, v_user_id)
  );
end;
$$;


ALTER FUNCTION "public"."prediction_challenge_join"("p_challenge_id" "uuid", "p_home_score" integer, "p_away_score" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prediction_challenge_lock_due"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'football', 'auth'
    AS $$
declare
  v_challenge record;
  v_entry record;
  v_locked_count integer := 0;
  v_voided_count integer := 0;
begin
  if auth.role() != 'service_role' then
    raise exception 'Service role required.';
  end if;

  for v_challenge in
    select challenge.id, challenge.club_id, challenge.match_id, challenge.total_participants
      from football.prediction_challenges challenge
     where challenge.status = 'open'
       and challenge.lock_at <= timezone('utc', now())
     order by challenge.lock_at asc, challenge.created_at asc
     for update skip locked
  loop
    if coalesce(v_challenge.total_participants, 0) <= 1 then
      perform public.prediction_challenge_refund_all(
        p_challenge_id := v_challenge.id,
        p_void_reason := 'no_opponents',
        p_settlement_mode := 'no_opponents',
        p_notification_title := 'Challenge voided',
        p_notification_body := 'No one joined before kickoff. Your stake has been refunded.',
        p_metadata := jsonb_build_object('locked_at', timezone('utc', now()))
      );
      v_voided_count := v_voided_count + 1;
      continue;
    end if;

    update football.prediction_challenges
       set status = 'locked',
           updated_at = timezone('utc', now())
     where id = v_challenge.id
       and status = 'open';

    for v_entry in
      select entry.user_id
        from football.prediction_challenge_entries entry
       where entry.challenge_id = v_challenge.id
    loop
      perform public.prediction_challenge_queue_notification(
        p_user_id := v_entry.user_id,
        p_notification_type := 'challenge_locked',
        p_title := 'Challenge locked',
        p_body := 'Kickoff has passed. The pool is now locked for settlement.',
        p_payload := jsonb_build_object(
          'challenge_id', v_challenge.id,
          'fixture_id', v_challenge.match_id,
          'route', '/challenge/' || v_challenge.id::text
        )
      );
    end loop;

    v_locked_count := v_locked_count + 1;
  end loop;

  return jsonb_build_object(
    'status', 'ok',
    'locked', v_locked_count,
    'voided_no_opponents', v_voided_count
  );
end;
$$;


ALTER FUNCTION "public"."prediction_challenge_lock_due"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prediction_challenge_queue_notification"("p_user_id" "uuid", "p_notification_type" "text", "p_title" "text", "p_body" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'football'
    AS $$
begin
  if p_user_id is null then
    return;
  end if;

  insert into football.prediction_notifications (
    user_id,
    notification_type,
    title,
    body,
    payload
  )
  values (
    p_user_id,
    coalesce(nullif(btrim(p_notification_type), ''), 'challenge'),
    coalesce(nullif(btrim(p_title), ''), 'Challenge update'),
    coalesce(nullif(btrim(p_body), ''), 'Your challenge has been updated.'),
    coalesce(p_payload, '{}'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."prediction_challenge_queue_notification"("p_user_id" "uuid", "p_notification_type" "text", "p_title" "text", "p_body" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prediction_challenge_refund_all"("p_challenge_id" "uuid", "p_void_reason" "text", "p_settlement_mode" "text", "p_notification_title" "text", "p_notification_body" "text", "p_official_home_score" integer DEFAULT NULL::integer, "p_official_away_score" integer DEFAULT NULL::integer, "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'football', 'auth'
    AS $$
declare
  v_challenge football.prediction_challenges;
  v_entry football.prediction_challenge_entries;
  v_metadata jsonb := coalesce(p_metadata, '{}'::jsonb) || jsonb_build_object(
    'void_reason', coalesce(p_void_reason, 'unknown')
  );
begin
  select *
    into v_challenge
    from football.prediction_challenges challenge
   where challenge.id = p_challenge_id
   for update;

  if v_challenge.id is null then
    return jsonb_build_object('status', 'missing');
  end if;

  if v_challenge.status = 'void' then
    return jsonb_build_object('status', 'void', 'already_processed', true);
  end if;

  for v_entry in
    select entry.*
      from football.prediction_challenge_entries entry
     where entry.challenge_id = p_challenge_id
       and entry.status = 'active'
     order by entry.joined_at asc
  loop
    perform public.prediction_challenge_adjust_wallet(
      p_club_id := v_challenge.club_id,
      p_user_id := v_entry.user_id,
      p_amount_fet := v_entry.stake_fet,
      p_direction := 'credit',
      p_reference_type := 'challenge_refund',
      p_reference_id := p_challenge_id::text,
      p_idempotency_key := 'challenge-refund:' || p_challenge_id::text || ':' || v_entry.id::text || ':' || coalesce(p_void_reason, 'void'),
      p_note := 'Challenge stake refunded',
      p_metadata := jsonb_build_object(
        'challenge_id', p_challenge_id,
        'entry_id', v_entry.id,
        'match_id', v_challenge.match_id,
        'void_reason', p_void_reason,
        'kind', 'challenge_refund'
      )
    );

    update football.prediction_challenge_entries
       set status = 'refunded',
           payout_fet = stake_fet,
           settled_at = timezone('utc', now())
     where id = v_entry.id;

    perform public.prediction_challenge_queue_notification(
      p_user_id := v_entry.user_id,
      p_notification_type := 'challenge_refunded',
      p_title := p_notification_title,
      p_body := p_notification_body,
      p_payload := jsonb_build_object(
        'challenge_id', p_challenge_id,
        'fixture_id', v_challenge.match_id,
        'earned', v_entry.stake_fet,
        'void_reason', p_void_reason,
        'route', '/challenge/' || p_challenge_id::text
      )
    );
  end loop;

  insert into football.prediction_challenge_settlements (
    challenge_id,
    match_id,
    official_home_score,
    official_away_score,
    winners_count,
    losers_count,
    total_pool_fet,
    losers_pool_fet,
    payout_per_winner_fet,
    settlement_mode,
    executed_at,
    metadata
  )
  values (
    p_challenge_id,
    v_challenge.match_id,
    p_official_home_score,
    p_official_away_score,
    0,
    0,
    v_challenge.total_pool_fet,
    0,
    0,
    coalesce(nullif(btrim(p_settlement_mode), ''), 'void'),
    timezone('utc', now()),
    v_metadata
  )
  on conflict (challenge_id) do update
    set official_home_score = excluded.official_home_score,
        official_away_score = excluded.official_away_score,
        winners_count = excluded.winners_count,
        losers_count = excluded.losers_count,
        total_pool_fet = excluded.total_pool_fet,
        losers_pool_fet = excluded.losers_pool_fet,
        payout_per_winner_fet = excluded.payout_per_winner_fet,
        settlement_mode = excluded.settlement_mode,
        executed_at = excluded.executed_at,
        metadata = excluded.metadata;

  update football.prediction_challenges
     set status = 'void',
         settled_at = timezone('utc', now()),
         void_reason = coalesce(nullif(btrim(p_void_reason), ''), 'void'),
         winner_count = 0,
         loser_count = 0,
         payout_per_winner_fet = 0,
         official_home_score = p_official_home_score,
         official_away_score = p_official_away_score,
         updated_at = timezone('utc', now())
   where id = p_challenge_id;

  return jsonb_build_object(
    'status', 'void',
    'void_reason', p_void_reason,
    'challenge', public.prediction_challenge_summary_json(p_challenge_id, auth.uid())
  );
end;
$$;


ALTER FUNCTION "public"."prediction_challenge_refund_all"("p_challenge_id" "uuid", "p_void_reason" "text", "p_settlement_mode" "text", "p_notification_title" "text", "p_notification_body" "text", "p_official_home_score" integer, "p_official_away_score" integer, "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prediction_challenge_settle"("p_challenge_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'football', 'auth'
    AS $$
begin
  return public.prediction_challenge_settle_internal(
    p_challenge_id := p_challenge_id,
    p_force := false
  );
end;
$$;


ALTER FUNCTION "public"."prediction_challenge_settle"("p_challenge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prediction_challenge_settle_due"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'football', 'auth'
    AS $$
declare
  v_challenge record;
  v_result jsonb;
  v_settled_count integer := 0;
  v_voided_count integer := 0;
  v_pending_count integer := 0;
begin
  if auth.role() != 'service_role' then
    raise exception 'Service role required.';
  end if;

  for v_challenge in
    select challenge.id
      from football.prediction_challenges challenge
      join football.fixtures fixture on fixture.id = challenge.match_id
     where challenge.status = 'locked'
       and (
         fixture.status::text in ('finished', 'postponed', 'cancelled', 'abandoned')
         or challenge.lock_at <= timezone('utc', now()) - interval '3 days'
       )
     order by challenge.lock_at asc, challenge.created_at asc
     for update skip locked
  loop
    v_result := public.prediction_challenge_settle(v_challenge.id);

    case coalesce(v_result ->> 'status', '')
      when 'settled' then
        v_settled_count := v_settled_count + 1;
      when 'void' then
        v_voided_count := v_voided_count + 1;
      else
        v_pending_count := v_pending_count + 1;
    end case;
  end loop;

  return jsonb_build_object(
    'status', 'ok',
    'settled', v_settled_count,
    'voided', v_voided_count,
    'pending', v_pending_count
  );
end;
$$;


ALTER FUNCTION "public"."prediction_challenge_settle_due"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prediction_challenge_settle_internal"("p_challenge_id" "uuid", "p_force" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'football', 'auth'
    AS $$
declare
  v_challenge football.prediction_challenges;
  v_fixture record;
  v_total_active integer := 0;
  v_winners_count integer := 0;
  v_losers_count integer := 0;
  v_losers_pool_fet bigint := 0;
  v_base_payout_per_winner_fet bigint := 0;
  v_remainder_fet bigint := 0;
  v_entry football.prediction_challenge_entries;
  v_actual_payout bigint;
  v_winner_payouts jsonb := '[]'::jsonb;
begin
  select *
    into v_challenge
    from football.prediction_challenges challenge
   where challenge.id = p_challenge_id
   for update;

  if v_challenge.id is null then
    return jsonb_build_object('status', 'missing');
  end if;

  if not (
    auth.role() = 'service_role'
    or (
      p_force
      and (public.is_super_admin() or public.is_admin_user() or public.is_club_admin(v_challenge.club_id))
    )
  ) then
    raise exception 'Permission denied.';
  end if;

  if v_challenge.status in ('settled', 'void', 'cancelled') then
    return jsonb_build_object(
      'status', v_challenge.status,
      'already_processed', true,
      'challenge', public.prediction_challenge_summary_json(p_challenge_id, auth.uid())
    );
  end if;

  if v_challenge.status = 'open' and v_challenge.lock_at <= timezone('utc', now()) then
    if coalesce(v_challenge.total_participants, 0) <= 1 then
      return public.prediction_challenge_refund_all(
        p_challenge_id := p_challenge_id,
        p_void_reason := 'no_opponents',
        p_settlement_mode := 'no_opponents',
        p_notification_title := 'Challenge voided',
        p_notification_body := 'No one joined before kickoff. Your stake has been refunded.',
        p_metadata := jsonb_build_object('settled_from', 'open')
      );
    end if;

    update football.prediction_challenges
       set status = 'locked',
           updated_at = timezone('utc', now())
     where id = p_challenge_id
       and status = 'open'
    returning * into v_challenge;
  end if;

  if v_challenge.status <> 'locked' then
    return jsonb_build_object('status', 'pending', 'message', 'Challenge is not ready for settlement.');
  end if;

  select fixture.id, fixture.status, fixture.home_score, fixture.away_score
    into v_fixture
    from football.fixtures fixture
   where fixture.id = v_challenge.match_id
   limit 1;

  if v_fixture.id is null then
    return public.prediction_challenge_refund_all(
      p_challenge_id := p_challenge_id,
      p_void_reason := 'match_invalid',
      p_settlement_mode := 'match_invalid',
      p_notification_title := 'Challenge refunded',
      p_notification_body := 'The official result is unavailable. Your stake has been refunded.',
      p_metadata := jsonb_build_object('fixture_missing', true)
    );
  end if;

  if coalesce(v_challenge.total_participants, 0) <= 1 then
    return public.prediction_challenge_refund_all(
      p_challenge_id := p_challenge_id,
      p_void_reason := 'no_opponents',
      p_settlement_mode := 'no_opponents',
      p_notification_title := 'Challenge voided',
      p_notification_body := 'No one joined before kickoff. Your stake has been refunded.',
      p_metadata := jsonb_build_object('fixture_status', v_fixture.status)
    );
  end if;

  if coalesce(v_fixture.status::text, '') in ('postponed', 'cancelled', 'abandoned') then
    return public.prediction_challenge_refund_all(
      p_challenge_id := p_challenge_id,
      p_void_reason := 'match_invalid',
      p_settlement_mode := 'match_invalid',
      p_notification_title := 'Challenge refunded',
      p_notification_body := 'The fixture did not finish officially. Your stake has been refunded.',
      p_metadata := jsonb_build_object('fixture_status', v_fixture.status)
    );
  end if;

  if coalesce(v_fixture.status::text, '') <> 'finished'
     or v_fixture.home_score is null
     or v_fixture.away_score is null then
    if v_challenge.lock_at <= timezone('utc', now()) - interval '3 days' then
      return public.prediction_challenge_refund_all(
        p_challenge_id := p_challenge_id,
        p_void_reason := 'match_invalid',
        p_settlement_mode := 'match_invalid',
        p_notification_title := 'Challenge refunded',
        p_notification_body := 'The official result was not confirmed in time. Your stake has been refunded.',
        p_metadata := jsonb_build_object('fixture_status', v_fixture.status, 'stale_lock', true)
      );
    end if;

    return jsonb_build_object('status', 'pending', 'message', 'Official result is not available yet.');
  end if;

  select count(*)
    into v_total_active
    from football.prediction_challenge_entries entry
   where entry.challenge_id = p_challenge_id
     and entry.status = 'active';

  if v_total_active <= 1 then
    return public.prediction_challenge_refund_all(
      p_challenge_id := p_challenge_id,
      p_void_reason := 'no_opponents',
      p_settlement_mode := 'no_opponents',
      p_notification_title := 'Challenge voided',
      p_notification_body := 'No valid opponent remained at settlement. Your stake has been refunded.',
      p_official_home_score := v_fixture.home_score,
      p_official_away_score := v_fixture.away_score,
      p_metadata := jsonb_build_object('fixture_status', v_fixture.status)
    );
  end if;

  select count(*)
    into v_winners_count
    from football.prediction_challenge_entries entry
   where entry.challenge_id = p_challenge_id
     and entry.status = 'active'
     and entry.predicted_home_score = v_fixture.home_score
     and entry.predicted_away_score = v_fixture.away_score;

  if v_winners_count = 0 then
    return public.prediction_challenge_refund_all(
      p_challenge_id := p_challenge_id,
      p_void_reason := 'no_exact_winner',
      p_settlement_mode := 'no_exact_winner',
      p_notification_title := 'Challenge refunded',
      p_notification_body := 'No one hit the exact score. All stakes were refunded.',
      p_official_home_score := v_fixture.home_score,
      p_official_away_score := v_fixture.away_score,
      p_metadata := jsonb_build_object('fixture_status', v_fixture.status)
    );
  end if;

  v_losers_count := greatest(v_total_active - v_winners_count, 0);
  v_losers_pool_fet := v_losers_count * v_challenge.stake_fet;
  v_base_payout_per_winner_fet := v_challenge.stake_fet + floor(v_losers_pool_fet / v_winners_count);
  v_remainder_fet := mod(v_losers_pool_fet, v_winners_count);

  for v_entry in
    select entry.*
      from football.prediction_challenge_entries entry
     where entry.challenge_id = p_challenge_id
       and entry.status = 'active'
     order by entry.joined_at asc, entry.id asc
  loop
    if v_entry.predicted_home_score = v_fixture.home_score
       and v_entry.predicted_away_score = v_fixture.away_score then
      v_actual_payout := v_base_payout_per_winner_fet;
      if v_remainder_fet > 0 then
        v_actual_payout := v_actual_payout + 1;
        v_remainder_fet := v_remainder_fet - 1;
      end if;

      perform public.prediction_challenge_adjust_wallet(
        p_club_id := v_challenge.club_id,
        p_user_id := v_entry.user_id,
        p_amount_fet := v_actual_payout,
        p_direction := 'credit',
        p_reference_type := 'challenge_payout',
        p_reference_id := p_challenge_id::text,
        p_idempotency_key := 'challenge-payout:' || p_challenge_id::text || ':' || v_entry.id::text,
        p_note := 'Challenge payout',
        p_metadata := jsonb_build_object(
          'challenge_id', p_challenge_id,
          'entry_id', v_entry.id,
          'match_id', v_challenge.match_id,
          'kind', 'challenge_payout'
        )
      );

      update football.prediction_challenge_entries
         set status = 'winner',
             payout_fet = v_actual_payout,
             settled_at = timezone('utc', now())
       where id = v_entry.id;

      v_winner_payouts := v_winner_payouts || jsonb_build_object(
        'entry_id', v_entry.id,
        'user_id', v_entry.user_id,
        'payout_fet', v_actual_payout
      );

      perform public.prediction_challenge_queue_notification(
        p_user_id := v_entry.user_id,
        p_notification_type := 'challenge_won',
        p_title := 'Challenge won',
        p_body := format('Exact score hit. You earned %s FET.', v_actual_payout),
        p_payload := jsonb_build_object(
          'challenge_id', p_challenge_id,
          'fixture_id', v_challenge.match_id,
          'earned', v_actual_payout,
          'route', '/challenge/' || p_challenge_id::text
        )
      );
    else
      update football.prediction_challenge_entries
         set status = 'loser',
             payout_fet = 0,
             settled_at = timezone('utc', now())
       where id = v_entry.id;

      perform public.prediction_challenge_queue_notification(
        p_user_id := v_entry.user_id,
        p_notification_type := 'challenge_lost',
        p_title := 'Challenge settled',
        p_body := 'The challenge has settled and this pick did not win.',
        p_payload := jsonb_build_object(
          'challenge_id', p_challenge_id,
          'fixture_id', v_challenge.match_id,
          'route', '/challenge/' || p_challenge_id::text
        )
      );
    end if;
  end loop;

  insert into football.prediction_challenge_settlements (
    challenge_id,
    match_id,
    official_home_score,
    official_away_score,
    winners_count,
    losers_count,
    total_pool_fet,
    losers_pool_fet,
    payout_per_winner_fet,
    settlement_mode,
    executed_at,
    metadata
  )
  values (
    p_challenge_id,
    v_challenge.match_id,
    v_fixture.home_score,
    v_fixture.away_score,
    v_winners_count,
    v_losers_count,
    v_challenge.total_pool_fet,
    v_losers_pool_fet,
    v_base_payout_per_winner_fet,
    'standard',
    timezone('utc', now()),
    jsonb_build_object(
      'winner_payouts', v_winner_payouts,
      'remainder_distribution_applied', jsonb_array_length(v_winner_payouts),
      'official_status', v_fixture.status
    )
  )
  on conflict (challenge_id) do update
    set official_home_score = excluded.official_home_score,
        official_away_score = excluded.official_away_score,
        winners_count = excluded.winners_count,
        losers_count = excluded.losers_count,
        total_pool_fet = excluded.total_pool_fet,
        losers_pool_fet = excluded.losers_pool_fet,
        payout_per_winner_fet = excluded.payout_per_winner_fet,
        settlement_mode = excluded.settlement_mode,
        executed_at = excluded.executed_at,
        metadata = excluded.metadata;

  update football.prediction_challenges
     set status = 'settled',
         settled_at = timezone('utc', now()),
         winner_count = v_winners_count,
         loser_count = v_losers_count,
         payout_per_winner_fet = v_base_payout_per_winner_fet,
         official_home_score = v_fixture.home_score,
         official_away_score = v_fixture.away_score,
         updated_at = timezone('utc', now())
   where id = p_challenge_id;

  return jsonb_build_object(
    'status', 'settled',
    'challenge', public.prediction_challenge_summary_json(p_challenge_id, auth.uid())
  );
end;
$$;


ALTER FUNCTION "public"."prediction_challenge_settle_internal"("p_challenge_id" "uuid", "p_force" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prediction_challenge_summary_json"("p_challenge_id" "uuid", "p_viewer_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'football', 'auth'
    AS $$
declare
  v_payload jsonb;
begin
  select
    jsonb_build_object(
      'id', challenge.id,
      'club_id', challenge.club_id,
      'match_id', challenge.match_id,
      'creator_user_id', challenge.creator_user_id,
      'stake_fet', challenge.stake_fet,
      'currency_code', challenge.currency_code,
      'status', challenge.status,
      'lock_at', challenge.lock_at,
      'settled_at', challenge.settled_at,
      'cancelled_at', challenge.cancelled_at,
      'void_reason', challenge.void_reason,
      'total_participants', challenge.total_participants,
      'total_pool_fet', challenge.total_pool_fet,
      'winner_count', challenge.winner_count,
      'loser_count', challenge.loser_count,
      'payout_per_winner_fet', challenge.payout_per_winner_fet,
      'official_home_score', challenge.official_home_score,
      'official_away_score', challenge.official_away_score,
      'created_at', challenge.created_at,
      'updated_at', challenge.updated_at,
      'fixture', fixture_data.fixture_json,
      'creator', creator_data.creator_json,
      'creator_name', creator_data.creator_json ->> 'display_name',
      'creator_avatar', creator_data.creator_json ->> 'avatar_url',
      'creator_prediction',
        case
          when creator_entry.id is null then null
          else jsonb_build_object(
            'home_score', creator_entry.predicted_home_score,
            'away_score', creator_entry.predicted_away_score,
            'joined_at', creator_entry.joined_at
          )
        end,
      'my_entry',
        case
          when viewer_entry.id is null then null
          else jsonb_build_object(
            'id', viewer_entry.id,
            'challenge_id', viewer_entry.challenge_id,
            'user_id', viewer_entry.user_id,
            'predicted_home_score', viewer_entry.predicted_home_score,
            'predicted_away_score', viewer_entry.predicted_away_score,
            'stake_fet', viewer_entry.stake_fet,
            'status', viewer_entry.status,
            'payout_fet', viewer_entry.payout_fet,
            'joined_at', viewer_entry.joined_at,
            'settled_at', viewer_entry.settled_at,
            'user_name', viewer_data.viewer_json ->> 'display_name',
            'user_avatar', viewer_data.viewer_json ->> 'avatar_url',
            'user', viewer_data.viewer_json
          )
        end,
      'permissions', jsonb_build_object(
        'has_joined', viewer_entry.id is not null,
        'is_creator', coalesce(p_viewer_user_id = challenge.creator_user_id, false),
        'can_join',
          coalesce(p_viewer_user_id is not null, false)
          and challenge.status = 'open'
          and challenge.lock_at > timezone('utc', now())
          and viewer_entry.id is null,
        'can_cancel',
          coalesce(p_viewer_user_id = challenge.creator_user_id, false)
          and challenge.status = 'open'
          and challenge.total_participants = 1
          and challenge.lock_at > timezone('utc', now()),
        'can_retry_settlement',
          challenge.status = 'locked'
          and (public.is_super_admin() or public.is_admin_user() or public.is_club_admin(challenge.club_id))
      ),
      'settlement',
        case
          when settlement.challenge_id is null then null
          else jsonb_build_object(
            'challenge_id', settlement.challenge_id,
            'match_id', settlement.match_id,
            'official_home_score', settlement.official_home_score,
            'official_away_score', settlement.official_away_score,
            'winners_count', settlement.winners_count,
            'losers_count', settlement.losers_count,
            'total_pool_fet', settlement.total_pool_fet,
            'losers_pool_fet', settlement.losers_pool_fet,
            'payout_per_winner_fet', settlement.payout_per_winner_fet,
            'settlement_mode', settlement.settlement_mode,
            'executed_at', settlement.executed_at,
            'metadata', coalesce(settlement.metadata, '{}'::jsonb)
          )
        end
    )
    into v_payload
    from football.prediction_challenges challenge
    cross join lateral (
      select public.prediction_challenge_fixture_json(challenge.match_id) as fixture_json
    ) fixture_data
    cross join lateral (
      select public.prediction_challenge_user_json(challenge.creator_user_id, challenge.club_id) as creator_json
    ) creator_data
    left join lateral (
      select entry.*
        from football.prediction_challenge_entries entry
       where entry.challenge_id = challenge.id
         and entry.user_id = challenge.creator_user_id
       order by entry.joined_at asc
       limit 1
    ) creator_entry on true
    left join lateral (
      select entry.*
        from football.prediction_challenge_entries entry
       where entry.challenge_id = challenge.id
         and entry.user_id = p_viewer_user_id
       order by entry.joined_at asc
       limit 1
    ) viewer_entry on true
    cross join lateral (
      select case
        when viewer_entry.id is null then null::jsonb
        else public.prediction_challenge_user_json(viewer_entry.user_id, challenge.club_id)
      end as viewer_json
    ) viewer_data
    left join football.prediction_challenge_settlements settlement
      on settlement.challenge_id = challenge.id
   where challenge.id = p_challenge_id
   limit 1;

  return v_payload;
end;
$$;


ALTER FUNCTION "public"."prediction_challenge_summary_json"("p_challenge_id" "uuid", "p_viewer_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prediction_challenge_user_json"("p_user_id" "uuid", "p_club_id" bigint DEFAULT NULL::bigint) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select jsonb_build_object(
    'id', p_user_id,
    'display_name', coalesce(
      nullif(btrim((
        select profile.display_name
          from public.profiles profile
         where profile.id = p_user_id
         limit 1
      )), ''),
      nullif(btrim((
        select profile.full_name
          from public.profiles profile
         where profile.id = p_user_id
         limit 1
      )), ''),
      nullif(btrim((
        select membership.display_name
          from public.fan_memberships membership
         where membership.user_id = p_user_id
           and (p_club_id is null or membership.club_id = p_club_id)
         order by membership.updated_at desc nulls last, membership.created_at desc nulls last
         limit 1
      )), ''),
      'Supporter'
    ),
    'avatar_url', (
      select profile.avatar_url
        from public.profiles profile
       where profile.id = p_user_id
       limit 1
    )
  );
$$;


ALTER FUNCTION "public"."prediction_challenge_user_json"("p_user_id" "uuid", "p_club_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prediction_check_streak_reward"("p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'football'
    AS $$
declare
  v_streak integer;
  v_streak_type text;
  v_reward_fet integer := 0;
  v_milestone text;
  v_club_id bigint;
begin
  if auth.role() != 'service_role' then
    return jsonb_build_object('status', 'error', 'message', 'Service role required.');
  end if;

  -- Get current streak
  select
    current_streak, streak_type
  into v_streak, v_streak_type
  from public.prediction_user_stats
  where user_id = p_user_id;

  if v_streak_type != 'won' then
    return jsonb_build_object('status', 'ok', 'streak', 0, 'reward', 0);
  end if;

  -- Check milestone (only reward exact milestone hits)
  if v_streak = 3 then
    v_reward_fet := 50;
    v_milestone := 'streak_3';
  elsif v_streak = 5 then
    v_reward_fet := 150;
    v_milestone := 'streak_5';
  elsif v_streak = 10 then
    v_reward_fet := 500;
    v_milestone := 'streak_10';
  elsif v_streak = 20 then
    v_reward_fet := 1000;
    v_milestone := 'streak_20';
  else
    return jsonb_build_object('status', 'ok', 'streak', v_streak, 'reward', 0);
  end if;

  select id into v_club_id from public.african_football_clubs limit 1;

  if v_club_id is not null then
    begin
      perform public.add_fan_points(
        p_user_id   := p_user_id,
        p_partner_id := v_club_id::text,
        p_points    := v_reward_fet,
        p_reason    := v_milestone
      );
    exception when others then
      raise notice 'Streak reward failed for user %: %', p_user_id, sqlerrm;
    end;
  end if;

  return jsonb_build_object(
    'status', 'ok',
    'streak', v_streak,
    'milestone', v_milestone,
    'reward_fet', v_reward_fet
  );
end;
$$;


ALTER FUNCTION "public"."prediction_check_streak_reward"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prediction_create_friend_challenge"("p_opponent_user_id" "uuid", "p_fixture_market_id" "uuid", "p_selected_outcome" "text", "p_message" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'football'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_market record;
  v_existing record;
  v_challenge football.prediction_friend_challenges;
  v_selected_outcome text := lower(nullif(btrim(coalesce(p_selected_outcome, '')), ''));
  v_message text := nullif(btrim(coalesce(p_message, '')), '');
  v_club_id bigint;
begin
  if v_user_id is null then
    raise exception 'Authentication is required.';
  end if;

  if p_opponent_user_id is null then
    raise exception 'An opponent is required.';
  end if;

  if p_opponent_user_id = v_user_id then
    raise exception 'You cannot challenge yourself.';
  end if;

  if v_selected_outcome is null then
    raise exception 'A prediction outcome is required.';
  end if;

  select
    fm.id,
    fm.fixture_id,
    fm.market_id,
    fm.outcomes,
    fm.is_locked,
    f.status as fixture_status,
    f.kickoff_at
    into v_market
  from football.fixture_markets fm
  join football.fixtures f on f.id = fm.fixture_id
  where fm.id = p_fixture_market_id
  limit 1;

  if v_market.id is null then
    raise exception 'Fixture market not found.';
  end if;

  if v_market.is_locked
     or v_market.fixture_status in ('live', 'finished')
     or (v_market.kickoff_at is not null and v_market.kickoff_at <= now()) then
    raise exception 'This market is no longer available for challenges.';
  end if;

  if not exists (
    select 1
    from jsonb_array_elements(v_market.outcomes) outcome
    where lower(coalesce(outcome ->> 'key', outcome ->> 'label', '')) = v_selected_outcome
       or lower(coalesce(outcome ->> 'label', outcome ->> 'key', '')) = v_selected_outcome
  ) then
    raise exception 'Selected outcome is not valid for this market.';
  end if;

  v_club_id := football.prediction_fixture_club_id(v_market.fixture_id);

  if not exists (
    select 1
    from public.supporter_friendships friendship
    where friendship.club_id = v_club_id
      and friendship.status = 'accepted'
      and (
        (
          friendship.requester_user_id = v_user_id
          and friendship.addressee_user_id = p_opponent_user_id
        ) or (
          friendship.requester_user_id = p_opponent_user_id
          and friendship.addressee_user_id = v_user_id
        )
      )
  ) then
    raise exception 'Only accepted friends can be challenged.';
  end if;

  select
    challenge.id,
    challenge.status
    into v_existing
  from football.prediction_friend_challenges challenge
  where challenge.fixture_market_id = p_fixture_market_id
    and challenge.status in ('pending', 'accepted')
    and (
      (
        challenge.challenger_user_id = v_user_id
        and challenge.opponent_user_id = p_opponent_user_id
      ) or (
        challenge.challenger_user_id = p_opponent_user_id
        and challenge.opponent_user_id = v_user_id
      )
    )
  order by challenge.created_at desc
  limit 1;

  if v_existing.id is not null then
    return jsonb_build_object(
      'status', v_existing.status,
      'challenge_id', v_existing.id,
      'message', 'A challenge already exists for this fixture.'
    );
  end if;

  insert into football.prediction_friend_challenges (
    club_id,
    fixture_id,
    fixture_market_id,
    challenger_user_id,
    opponent_user_id,
    challenger_outcome,
    challenge_note,
    expires_at
  )
  values (
    v_club_id,
    v_market.fixture_id,
    p_fixture_market_id,
    v_user_id,
    p_opponent_user_id,
    v_selected_outcome,
    v_message,
    v_market.kickoff_at
  )
  returning * into v_challenge;

  return jsonb_build_object(
    'status', 'created',
    'challenge_id', v_challenge.id,
    'message', 'Challenge sent.'
  );
end;
$$;


ALTER FUNCTION "public"."prediction_create_friend_challenge"("p_opponent_user_id" "uuid", "p_fixture_market_id" "uuid", "p_selected_outcome" "text", "p_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prediction_get_active"("p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'football'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_rows jsonb;
begin
  if v_user_id is null then
    return '[]'::jsonb;
  end if;

  select coalesce(jsonb_agg(row_data order by placed_at desc), '[]'::jsonb)
  into v_rows
  from (
    select jsonb_build_object(
      'id', p.id,
      'fixture_id', p.fixture_id,
      'market_slug', pm.slug,
      'market_name', pm.short_name,
      'market_group', pm.market_group,
      'home_team', ht.name,
      'home_team_short', ht.short_name,
      'away_team', att.name,
      'away_team_short', att.short_name,
      'kickoff_at', f.kickoff_at,
      'fixture_status', f.status,
      'competition_name', c.short_name,
      'selected_outcome', p.selected_outcome,
      'status', p.status,
      'fet_potential', coalesce(fm.fet_value_override, pm.default_fet_value),
      'placed_at', p.placed_at,
      'slip_id', p.slip_id
    ) as row_data,
    p.placed_at
    from football.predictions p
    join football.fixture_markets fm on fm.id = p.fixture_market_id
    join football.prediction_markets pm on pm.id = fm.market_id
    join football.fixtures f on f.id = p.fixture_id
    join football.teams ht on ht.id = f.home_team_id
    join football.teams att on att.id = f.away_team_id
    join football.competitions c on c.id = f.competition_id
    where p.user_id = v_user_id
      and p.status = 'pending'
    order by p.placed_at desc
    limit p_limit
    offset p_offset
  ) sub;

  return v_rows;
end;
$$;


ALTER FUNCTION "public"."prediction_get_active"("p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prediction_get_active_jackpot_round"("p_club_id" bigint DEFAULT NULL::bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'football'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_club_id bigint := coalesce(p_club_id, nullif(public.requesting_club_id(), '')::bigint);
  v_round football.jackpot_rounds;
  v_user_entries integer := 0;
  v_bonus_entries integer := 0;
begin
  select round.*
    into v_round
  from football.jackpot_rounds round
  where round.status in ('open', 'locked')
    and (round.club_id is null or round.club_id = v_club_id)
  order by
    case when round.club_id = v_club_id then 0 else 1 end,
    round.entry_deadline_at asc,
    round.created_at desc
  limit 1;

  if v_round.id is null then
    return null;
  end if;

  if v_user_id is not null then
    select count(*)
      into v_user_entries
    from football.prediction_slips slip
    where slip.user_id = v_user_id
      and slip.jackpot_round_id = v_round.id
      and slip.slip_type = 'jackpot'
      and slip.status <> 'cancelled';

    select count(*)
      into v_bonus_entries
    from public.fet_reward_redemptions redemption
    where redemption.user_id = v_user_id
      and redemption.reward_slug = 'jackpot-extra-entry'
      and redemption.consumed_at is null
      and redemption.status in ('pending', 'processing', 'fulfilled')
      and (v_round.club_id is null or redemption.club_id = v_round.club_id);
  end if;

  return jsonb_build_object(
    'id', v_round.id,
    'club_id', v_round.club_id,
    'slug', v_round.slug,
    'title', v_round.title,
    'description', v_round.description,
    'status', v_round.status,
    'opens_at', v_round.opens_at,
    'entry_deadline_at', v_round.entry_deadline_at,
    'kickoff_window_start_at', v_round.kickoff_window_start_at,
    'kickoff_window_end_at', v_round.kickoff_window_end_at,
    'prize_pool_fet', v_round.prize_pool_fet,
    'max_legs', v_round.max_legs,
    'max_entries_per_user', v_round.max_entries_per_user,
    'user_entry_count', v_user_entries,
    'bonus_entry_count', v_bonus_entries,
    'remaining_entries', greatest((v_round.max_entries_per_user + v_bonus_entries) - v_user_entries, 0),
    'can_enter',
      v_round.status = 'open'
      and timezone('utc', now()) < v_round.entry_deadline_at
      and greatest((v_round.max_entries_per_user + v_bonus_entries) - v_user_entries, 0) > 0,
    'fixtures',
      coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'fixture_market_id', leg.fixture_market_id,
            'fixture_id', fixture.id,
            'competition_name', fixture.competition_name,
            'competition_slug', fixture.competition_slug,
            'home_team_name', fixture.home_team_name,
            'home_team_short_name', fixture.home_team_short_name,
            'away_team_name', fixture.away_team_name,
            'away_team_short_name', fixture.away_team_short_name,
            'kickoff_at', fixture.kickoff_at,
            'status', fixture.status,
            'market_name', market.name,
            'market_short_name', market.short_name,
            'outcomes', fixture_market.outcomes
          )
          order by leg.sort_order
        )
        from football.jackpot_round_legs leg
        join public.prediction_supported_fixtures_catalog fixture
          on fixture.id = leg.fixture_id
        join football.fixture_markets fixture_market
          on fixture_market.id = leg.fixture_market_id
        join football.prediction_markets market
          on market.id = fixture_market.market_id
        where leg.jackpot_round_id = v_round.id
      ), '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."prediction_get_active_jackpot_round"("p_club_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prediction_get_challenge_detail"("p_challenge_id" "uuid", "p_club_id" bigint DEFAULT NULL::bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'football', 'auth'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_club_id bigint;
  v_challenge_club_id bigint;
  v_summary jsonb;
  v_entries jsonb;
begin
  if v_user_id is null then
    raise exception 'Auth required.';
  end if;

  v_club_id := public.fet_require_club_context(p_club_id);

  select challenge.club_id
    into v_challenge_club_id
    from football.prediction_challenges challenge
   where challenge.id = p_challenge_id
   limit 1;

  if v_challenge_club_id is null or v_challenge_club_id != v_club_id then
    raise exception 'Challenge not found.';
  end if;

  v_summary := public.prediction_challenge_summary_json(p_challenge_id, v_user_id);

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', entry.id,
        'challenge_id', entry.challenge_id,
        'user_id', entry.user_id,
        'predicted_home_score', entry.predicted_home_score,
        'predicted_away_score', entry.predicted_away_score,
        'stake_fet', entry.stake_fet,
        'status', entry.status,
        'payout_fet', entry.payout_fet,
        'joined_at', entry.joined_at,
        'settled_at', entry.settled_at,
        'user_name', user_data.user_json ->> 'display_name',
        'user_avatar', user_data.user_json ->> 'avatar_url',
        'user', user_data.user_json
      )
      order by entry.joined_at asc
    ),
    '[]'::jsonb
  )
    into v_entries
    from football.prediction_challenge_entries entry
    cross join lateral (
      select public.prediction_challenge_user_json(entry.user_id, v_club_id) as user_json
    ) user_data
   where entry.challenge_id = p_challenge_id;

  return jsonb_build_object(
    'challenge', v_summary,
    'entries', coalesce(v_entries, '[]'::jsonb),
    'user_entry', v_summary -> 'my_entry',
    'settlement', v_summary -> 'settlement'
  );
end;
$$;


ALTER FUNCTION "public"."prediction_get_challenge_detail"("p_challenge_id" "uuid", "p_club_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prediction_get_challenge_feed"("p_club_id" bigint DEFAULT NULL::bigint, "p_statuses" "text"[] DEFAULT NULL::"text"[], "p_sort" "text" DEFAULT 'ending_soon'::"text", "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0, "p_only_joined" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'football', 'auth'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_club_id bigint;
  v_sort text := lower(nullif(btrim(coalesce(p_sort, '')), ''));
  v_payload jsonb;
begin
  if v_user_id is null then
    raise exception 'Auth required.';
  end if;

  v_club_id := public.fet_require_club_context(p_club_id);
  v_sort := coalesce(v_sort, 'ending_soon');

  select coalesce(
    jsonb_agg(
      ranked.payload
      order by
        ranked.sort_lock_at asc nulls last,
        ranked.sort_pool desc nulls last,
        ranked.sort_participants desc nulls last,
        ranked.sort_settled desc nulls last,
        ranked.sort_created desc nulls last,
        ranked.created_at desc
    ),
    '[]'::jsonb
  )
    into v_payload
    from (
      select
        public.prediction_challenge_summary_json(challenge.id, v_user_id) as payload,
        challenge.created_at,
        case when v_sort = 'ending_soon' then challenge.lock_at end as sort_lock_at,
        case when v_sort = 'high_pool' then challenge.total_pool_fet end as sort_pool,
        case when v_sort = 'most_participants' then challenge.total_participants end as sort_participants,
        case when v_sort = 'settled' then coalesce(challenge.settled_at, challenge.updated_at, challenge.created_at) end as sort_settled,
        case when v_sort in ('newest', 'open', 'my_joined') then challenge.created_at end as sort_created
      from football.prediction_challenges challenge
      left join football.prediction_challenge_entries viewer_entry
        on viewer_entry.challenge_id = challenge.id
       and viewer_entry.user_id = v_user_id
      where challenge.club_id = v_club_id
        and (
          p_statuses is null
          or array_length(p_statuses, 1) is null
          or challenge.status = any(p_statuses)
        )
        and (not p_only_joined or viewer_entry.id is not null)
      order by
        case when v_sort = 'ending_soon' then challenge.lock_at end asc nulls last,
        case when v_sort = 'high_pool' then challenge.total_pool_fet end desc nulls last,
        case when v_sort = 'most_participants' then challenge.total_participants end desc nulls last,
        case when v_sort = 'settled' then coalesce(challenge.settled_at, challenge.updated_at, challenge.created_at) end desc nulls last,
        challenge.created_at desc
      limit greatest(coalesce(p_limit, 20), 1)
      offset greatest(coalesce(p_offset, 0), 0)
    ) ranked;

  return coalesce(v_payload, '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."prediction_get_challenge_feed"("p_club_id" bigint, "p_statuses" "text"[], "p_sort" "text", "p_limit" integer, "p_offset" integer, "p_only_joined" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prediction_get_dashboard"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'football'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_active_count integer := 0;
  v_settled_count integer := 0;
  v_won_count integer := 0;
  v_lost_count integer := 0;
  v_total_fet integer := 0;
  v_current_streak integer := 0;
  v_win_rate numeric := 0;
begin
  if v_user_id is null then
    return jsonb_build_object(
      'active_count', 0,
      'settled_count', 0,
      'won_count', 0,
      'lost_count', 0,
      'total_fet_earned', 0,
      'current_streak', 0,
      'win_rate', 0
    );
  end if;

  select count(*)
    into v_active_count
  from football.predictions prediction
  where prediction.user_id = v_user_id
    and prediction.status = 'pending';

  select
    count(*) filter (where prediction.status in ('won', 'lost', 'void')),
    count(*) filter (where prediction.status = 'won'),
    count(*) filter (where prediction.status = 'lost'),
    coalesce(sum(prediction.fet_earned), 0)
    into v_settled_count,
         v_won_count,
         v_lost_count,
         v_total_fet
  from football.predictions prediction
  where prediction.user_id = v_user_id;

  select
    coalesce(stats.current_streak, 0),
    coalesce(stats.win_rate, 0)
    into v_current_streak,
         v_win_rate
  from public.prediction_user_stats stats
  where stats.user_id = v_user_id;

  return jsonb_build_object(
    'active_count', coalesce(v_active_count, 0),
    'settled_count', coalesce(v_settled_count, 0),
    'won_count', coalesce(v_won_count, 0),
    'lost_count', coalesce(v_lost_count, 0),
    'total_fet_earned', coalesce(v_total_fet, 0),
    'current_streak', coalesce(v_current_streak, 0),
    'win_rate', coalesce(v_win_rate, 0)
  );
end;
$$;


ALTER FUNCTION "public"."prediction_get_dashboard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prediction_get_detail"("p_prediction_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'football'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_row jsonb;
begin
  if v_user_id is null then
    return null;
  end if;

  select jsonb_build_object(
      'id', prediction.id,
      'slip_id', prediction.slip_id,
      'fixture_id', prediction.fixture_id,
      'market_slug', market.slug,
      'market_name', market.name,
      'market_short_name', market.short_name,
      'market_group', market.market_group,
      'difficulty_tier', market.difficulty_tier,
      'competition_name', competition.short_name,
      'home_team', home_team.name,
      'home_team_short', home_team.short_name,
      'away_team', away_team.name,
      'away_team_short', away_team.short_name,
      'venue_name', fixture.venue_name,
      'kickoff_at', fixture.kickoff_at,
      'fixture_status', fixture.status,
      'home_score', fixture.home_score,
      'away_score', fixture.away_score,
      'selected_outcome', prediction.selected_outcome,
      'correct_outcome', settlement.correct_outcome,
      'status', prediction.status,
      'fet_potential', coalesce(fixture_market.fet_value_override, market.default_fet_value),
      'fet_earned', prediction.fet_earned,
      'placed_at', prediction.placed_at,
      'settled_at', prediction.settled_at
    )
    into v_row
  from football.predictions prediction
  join football.fixture_markets fixture_market on fixture_market.id = prediction.fixture_market_id
  join football.prediction_markets market on market.id = fixture_market.market_id
  join football.fixtures fixture on fixture.id = prediction.fixture_id
  join football.teams home_team on home_team.id = fixture.home_team_id
  join football.teams away_team on away_team.id = fixture.away_team_id
  join football.competitions competition on competition.id = fixture.competition_id
  left join football.prediction_settlements settlement
    on settlement.fixture_id = prediction.fixture_id
   and settlement.market_id = market.id
  where prediction.id = p_prediction_id
    and prediction.user_id = v_user_id
  limit 1;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."prediction_get_detail"("p_prediction_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prediction_get_fixture_markets"("p_fixture_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'football'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_rows jsonb;
BEGIN
  SELECT coalesce(jsonb_agg(row_data ORDER BY sort_order), '[]'::jsonb)
    INTO v_rows
  FROM (
    SELECT
      jsonb_build_object(
        'fixture_market_id', fm.id,
        'market_id', pm.id,
        'market_slug', pm.slug,
        'market_name', pm.name,
        'market_short_name', pm.short_name,
        'market_group', pm.market_group,
        'market_category', pm.market_category,
        'bet_type', pm.bet_type,
        'difficulty_tier', pm.difficulty_tier,
        'description', pm.description,
        'fet_value', coalesce(fm.fet_value_override, pm.default_fet_value),
        'outcomes', fm.outcomes,
        'is_locked',
          fm.is_locked
          OR f.status IN ('live', 'finished')
          OR (f.kickoff_at IS NOT NULL AND f.kickoff_at <= now()),
        'user_prediction', (
          SELECT jsonb_build_object(
            'prediction_id', up.id,
            'selected_outcome', up.selected_outcome,
            'status', up.status
          )
          FROM football.predictions up
          WHERE up.fixture_market_id = fm.id
            AND up.user_id = v_user_id
            AND up.status IN ('pending', 'won', 'lost', 'void')
          LIMIT 1
        )
      ) AS row_data,
      pm.sort_order
    FROM football.fixture_markets fm
    JOIN football.prediction_markets pm ON pm.id = fm.market_id
    JOIN football.fixtures f ON f.id = fm.fixture_id
    WHERE fm.fixture_id = p_fixture_id
      AND pm.is_active = true
      AND jsonb_array_length(fm.outcomes) > 0
    ORDER BY pm.sort_order
  ) sub;

  RETURN v_rows;
END;
$$;


ALTER FUNCTION "public"."prediction_get_fixture_markets"("p_fixture_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prediction_get_friend_challenges"("p_status" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'football'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_status text := lower(nullif(btrim(coalesce(p_status, '')), ''));
  v_rows jsonb;
begin
  if v_user_id is null then
    return '[]'::jsonb;
  end if;

  select coalesce(jsonb_agg(row_data order by created_at desc), '[]'::jsonb)
    into v_rows
  from (
    select
      jsonb_build_object(
        'id', challenge.id,
        'status', challenge.status,
        'club_id', challenge.club_id,
        'fixture_id', challenge.fixture_id,
        'fixture_market_id', challenge.fixture_market_id,
        'competition_name', fixture.competition_name,
        'home_team_name', fixture.home_team_name,
        'home_team_short_name', fixture.home_team_short_name,
        'away_team_name', fixture.away_team_name,
        'away_team_short_name', fixture.away_team_short_name,
        'kickoff_at', fixture.kickoff_at,
        'market_name', market.name,
        'market_short_name', market.short_name,
        'challenger_user_id', challenge.challenger_user_id,
        'challenger_display_name', coalesce(nullif(btrim(challenger_profile.display_name), ''), nullif(btrim(challenger_profile.full_name), ''), challenger_user.public_user_id, 'Supporter'),
        'challenger_outcome', challenge.challenger_outcome,
        'opponent_user_id', challenge.opponent_user_id,
        'opponent_display_name', coalesce(nullif(btrim(opponent_profile.display_name), ''), nullif(btrim(opponent_profile.full_name), ''), opponent_user.public_user_id, 'Supporter'),
        'opponent_outcome', challenge.opponent_outcome,
        'winner_user_id', challenge.winner_user_id,
        'challenge_note', challenge.challenge_note,
        'expires_at', challenge.expires_at,
        'responded_at', challenge.responded_at,
        'settled_at', challenge.settled_at,
        'created_at', challenge.created_at,
        'is_challenger', challenge.challenger_user_id = v_user_id
      ) as row_data,
      challenge.created_at
    from football.prediction_friend_challenges challenge
    join public.football_fixtures_catalog fixture
      on fixture.id = challenge.fixture_id
    join football.fixture_markets fixture_market
      on fixture_market.id = challenge.fixture_market_id
    join football.prediction_markets market
      on market.id = fixture_market.market_id
    left join public.profiles challenger_profile
      on challenger_profile.id = challenge.challenger_user_id
    left join public.users challenger_user
      on challenger_user.id = challenge.challenger_user_id
    left join public.profiles opponent_profile
      on opponent_profile.id = challenge.opponent_user_id
    left join public.users opponent_user
      on opponent_user.id = challenge.opponent_user_id
    where v_user_id in (challenge.challenger_user_id, challenge.opponent_user_id)
      and (v_status is null or lower(challenge.status) = v_status)
    order by challenge.created_at desc
    limit greatest(coalesce(p_limit, 20), 1)
    offset greatest(coalesce(p_offset, 0), 0)
  ) sub;

  return v_rows;
end;
$$;


ALTER FUNCTION "public"."prediction_get_friend_challenges"("p_status" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prediction_get_history"("p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'football'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_rows jsonb;
begin
  if v_user_id is null then
    return '[]'::jsonb;
  end if;

  select coalesce(jsonb_agg(row_data order by settled_at desc), '[]'::jsonb)
  into v_rows
  from (
    select jsonb_build_object(
      'id', p.id,
      'fixture_id', p.fixture_id,
      'market_slug', pm.slug,
      'market_name', pm.short_name,
      'market_group', pm.market_group,
      'home_team', ht.name,
      'home_team_short', ht.short_name,
      'away_team', att.name,
      'away_team_short', att.short_name,
      'home_score', f.home_score,
      'away_score', f.away_score,
      'kickoff_at', f.kickoff_at,
      'competition_name', c.short_name,
      'selected_outcome', p.selected_outcome,
      'status', p.status,
      'fet_earned', p.fet_earned,
      'placed_at', p.placed_at,
      'settled_at', p.settled_at,
      'slip_id', p.slip_id
    ) as row_data,
    p.settled_at
    from football.predictions p
    join football.fixture_markets fm on fm.id = p.fixture_market_id
    join football.prediction_markets pm on pm.id = fm.market_id
    join football.fixtures f on f.id = p.fixture_id
    join football.teams ht on ht.id = f.home_team_id
    join football.teams att on att.id = f.away_team_id
    join football.competitions c on c.id = f.competition_id
    where p.user_id = v_user_id
      and p.status in ('won', 'lost', 'void')
    order by p.settled_at desc
    limit p_limit
    offset p_offset
  ) sub;

  return v_rows;
end;
$$;


ALTER FUNCTION "public"."prediction_get_history"("p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prediction_get_match_center"("p_fixture_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'football'
    AS $$
declare
  v_fixture record;
  v_stats jsonb := '[]'::jsonb;
  v_h2h jsonb := '[]'::jsonb;
  v_events jsonb := '[]'::jsonb;
  v_home_lineup jsonb := '{}'::jsonb;
  v_away_lineup jsonb := '{}'::jsonb;
begin
  select *
    into v_fixture
  from public.football_fixtures_catalog fixture
  where fixture.id = p_fixture_id
  limit 1;

  if v_fixture.id is null then
    return null;
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'label', stat.stat_label,
        'left_value', stat.home_value,
        'right_value', stat.away_value,
        'left_display', coalesce(stat.home_display, trim(to_char(stat.home_value, 'FM999999990.##'))),
        'right_display', coalesce(stat.away_display, trim(to_char(stat.away_value, 'FM999999990.##')))
      )
      order by stat.sort_order, stat.stat_label
    ),
    '[]'::jsonb
  )
    into v_stats
  from football.fixture_stats stat
  where stat.fixture_id = p_fixture_id;

  if v_stats = '[]'::jsonb and v_fixture.status in ('live', 'finished') then
    v_stats := jsonb_build_array(
      jsonb_build_object(
        'label', 'Goals',
        'left_value', coalesce(v_fixture.home_score, 0),
        'right_value', coalesce(v_fixture.away_score, 0),
        'left_display', coalesce(v_fixture.home_score, 0)::text,
        'right_display', coalesce(v_fixture.away_score, 0)::text
      ),
      jsonb_build_object(
        'label', 'Total Goals',
        'left_value', coalesce(v_fixture.home_score, 0) + coalesce(v_fixture.away_score, 0),
        'right_value', coalesce(v_fixture.home_score, 0) + coalesce(v_fixture.away_score, 0),
        'left_display', (coalesce(v_fixture.home_score, 0) + coalesce(v_fixture.away_score, 0))::text,
        'right_display', (coalesce(v_fixture.home_score, 0) + coalesce(v_fixture.away_score, 0))::text
      )
    );
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'home_team', h2h.home_team_name,
        'away_team', h2h.away_team_name,
        'home_score', h2h.home_score,
        'away_score', h2h.away_score,
        'date', h2h.kickoff_at,
        'competition', h2h.competition_name
      )
      order by h2h.kickoff_at desc
    ),
    '[]'::jsonb
  )
    into v_h2h
  from (
    select history.*
    from public.football_fixtures_catalog history
    where history.status = 'finished'
      and history.id <> p_fixture_id
      and (
        (
          history.home_team_slug = v_fixture.home_team_slug
          and history.away_team_slug = v_fixture.away_team_slug
        ) or (
          history.home_team_slug = v_fixture.away_team_slug
          and history.away_team_slug = v_fixture.home_team_slug
        )
      )
    order by history.kickoff_at desc
    limit 5
  ) h2h;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'event_type', event.event_type,
        'event_label', coalesce(event.event_label, initcap(replace(event.event_type, '_', ' '))),
        'event_detail', event.event_detail,
        'team_id', event.team_id,
        'player_id', event.player_id,
        'minute', event.minute,
        'stoppage_minute', event.stoppage_minute
      )
      order by event.minute nulls last, event.stoppage_minute nulls last, event.sort_order, event.created_at
    ),
    '[]'::jsonb
  )
    into v_events
  from football.fixture_events event
  where event.fixture_id = p_fixture_id;

  select coalesce((
    select jsonb_build_object(
      'formation', lineup.formation,
      'coach_name', lineup.coach_name,
      'is_confirmed', lineup.is_confirmed,
      'source', lineup.source,
      'starters', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'name', player.player_name,
            'number', player.squad_number,
            'position', player.position,
            'is_starter', player.lineup_role = 'starter',
            'role', player.lineup_role
          )
          order by player.sort_order, player.squad_number nulls last, player.player_name
        )
        from football.fixture_lineup_players player
        where player.fixture_lineup_id = lineup.id
          and player.lineup_role = 'starter'
      ), '[]'::jsonb),
      'substitutes', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'name', player.player_name,
            'number', player.squad_number,
            'position', player.position,
            'is_starter', player.lineup_role = 'starter',
            'role', player.lineup_role
          )
          order by player.sort_order, player.squad_number nulls last, player.player_name
        )
        from football.fixture_lineup_players player
        where player.fixture_lineup_id = lineup.id
          and player.lineup_role <> 'starter'
      ), '[]'::jsonb)
    )
    from football.fixture_lineups lineup
    where lineup.fixture_id = p_fixture_id
      and lineup.team_id = v_fixture.home_team_id
    limit 1
  ), jsonb_build_object(
    'formation', null,
    'coach_name', null,
    'is_confirmed', false,
    'source', 'roster_proxy',
    'starters', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'name', roster.player_name,
          'number', roster.squad_number,
          'position', roster.position,
          'is_starter', true,
          'role', 'starter'
        )
        order by roster.squad_number nulls last, roster.player_name
      )
      from (
        select *
        from public.football_roster_catalog roster
        where roster.team_slug = v_fixture.home_team_slug
          and roster.is_active = true
        order by roster.squad_number nulls last, roster.player_name
        limit 11
      ) roster
    ), '[]'::jsonb),
    'substitutes', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'name', roster.player_name,
          'number', roster.squad_number,
          'position', roster.position,
          'is_starter', false,
          'role', 'substitute'
        )
        order by roster.squad_number nulls last, roster.player_name
      )
      from (
        select *
        from public.football_roster_catalog roster
        where roster.team_slug = v_fixture.home_team_slug
          and roster.is_active = true
        order by roster.squad_number nulls last, roster.player_name
        offset 11
        limit 7
      ) roster
    ), '[]'::jsonb)
  ))
    into v_home_lineup;

  select coalesce((
    select jsonb_build_object(
      'formation', lineup.formation,
      'coach_name', lineup.coach_name,
      'is_confirmed', lineup.is_confirmed,
      'source', lineup.source,
      'starters', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'name', player.player_name,
            'number', player.squad_number,
            'position', player.position,
            'is_starter', player.lineup_role = 'starter',
            'role', player.lineup_role
          )
          order by player.sort_order, player.squad_number nulls last, player.player_name
        )
        from football.fixture_lineup_players player
        where player.fixture_lineup_id = lineup.id
          and player.lineup_role = 'starter'
      ), '[]'::jsonb),
      'substitutes', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'name', player.player_name,
            'number', player.squad_number,
            'position', player.position,
            'is_starter', player.lineup_role = 'starter',
            'role', player.lineup_role
          )
          order by player.sort_order, player.squad_number nulls last, player.player_name
        )
        from football.fixture_lineup_players player
        where player.fixture_lineup_id = lineup.id
          and player.lineup_role <> 'starter'
      ), '[]'::jsonb)
    )
    from football.fixture_lineups lineup
    where lineup.fixture_id = p_fixture_id
      and lineup.team_id = v_fixture.away_team_id
    limit 1
  ), jsonb_build_object(
    'formation', null,
    'coach_name', null,
    'is_confirmed', false,
    'source', 'roster_proxy',
    'starters', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'name', roster.player_name,
          'number', roster.squad_number,
          'position', roster.position,
          'is_starter', true,
          'role', 'starter'
        )
        order by roster.squad_number nulls last, roster.player_name
      )
      from (
        select *
        from public.football_roster_catalog roster
        where roster.team_slug = v_fixture.away_team_slug
          and roster.is_active = true
        order by roster.squad_number nulls last, roster.player_name
        limit 11
      ) roster
    ), '[]'::jsonb),
    'substitutes', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'name', roster.player_name,
          'number', roster.squad_number,
          'position', roster.position,
          'is_starter', false,
          'role', 'substitute'
        )
        order by roster.squad_number nulls last, roster.player_name
      )
      from (
        select *
        from public.football_roster_catalog roster
        where roster.team_slug = v_fixture.away_team_slug
          and roster.is_active = true
        order by roster.squad_number nulls last, roster.player_name
        offset 11
        limit 7
      ) roster
    ), '[]'::jsonb)
  ))
    into v_away_lineup;

  return jsonb_build_object(
    'fixture_id', v_fixture.id,
    'stats', v_stats,
    'h2h', v_h2h,
    'events', v_events,
    'lineups', jsonb_build_object(
      'home', v_home_lineup,
      'away', v_away_lineup
    )
  );
end;
$$;


