CREATE OR REPLACE FUNCTION "public"."prediction_get_user_stats"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'football'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_stats record;
begin
  if v_user_id is null then
    return jsonb_build_object(
      'total_predictions', 0,
      'total_won', 0,
      'total_lost', 0,
      'total_pending', 0,
      'total_fet_earned', 0,
      'win_rate', 0,
      'current_streak', 0,
      'streak_type', null
    );
  end if;

  select * into v_stats
  from public.prediction_user_stats
  where user_id = v_user_id;

  if v_stats is null then
    return jsonb_build_object(
      'total_predictions', 0,
      'total_won', 0,
      'total_lost', 0,
      'total_pending', 0,
      'total_fet_earned', 0,
      'win_rate', 0,
      'current_streak', 0,
      'streak_type', null
    );
  end if;

  return jsonb_build_object(
    'total_predictions', v_stats.total_predictions,
    'total_won', v_stats.total_won,
    'total_lost', v_stats.total_lost,
    'total_pending', v_stats.total_pending,
    'total_fet_earned', v_stats.total_fet_earned,
    'win_rate', v_stats.win_rate,
    'current_streak', v_stats.current_streak,
    'streak_type', v_stats.streak_type
  );
end;
$$;


ALTER FUNCTION "public"."prediction_get_user_stats"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prediction_mark_notifications_sent"("p_notification_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'football'
    AS $$
declare
  v_count integer;
begin
  if auth.role() != 'service_role' then
    return jsonb_build_object('status', 'error', 'message', 'Service role required.');
  end if;

  update football.prediction_notifications
  set is_sent = true, sent_at = now()
  where id = any(p_notification_ids)
    and is_sent = false;

  get diagnostics v_count = row_count;

  return jsonb_build_object(
    'status', 'ok',
    'marked_sent', v_count
  );
end;
$$;


