CREATE OR REPLACE FUNCTION "public"."prediction_respond_friend_challenge"("p_challenge_id" "uuid", "p_action" "text" DEFAULT 'accepted'::"text", "p_selected_outcome" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'football'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_action text := lower(nullif(btrim(coalesce(p_action, '')), ''));
  v_selected_outcome text := lower(nullif(btrim(coalesce(p_selected_outcome, '')), ''));
  v_challenge football.prediction_friend_challenges;
  v_market record;
begin
  if v_user_id is null then
    raise exception 'Authentication is required.';
  end if;

  if v_action not in ('accepted', 'declined', 'cancelled') then
    raise exception 'Unsupported challenge action.';
  end if;

  select *
    into v_challenge
  from football.prediction_friend_challenges challenge
  where challenge.id = p_challenge_id
  for update;

  if v_challenge.id is null then
    raise exception 'Challenge not found.';
  end if;

  if v_action in ('accepted', 'declined') and v_challenge.opponent_user_id <> v_user_id then
    raise exception 'Only the invited supporter can respond to this challenge.';
  end if;

  if v_action = 'cancelled' and v_challenge.challenger_user_id <> v_user_id then
    raise exception 'Only the challenger can cancel this challenge.';
  end if;

  if v_action = 'accepted' then
    if v_selected_outcome is null then
      raise exception 'A response outcome is required.';
    end if;

    select
      fm.id,
      fm.outcomes,
      fm.is_locked,
      f.status as fixture_status,
      f.kickoff_at
      into v_market
    from football.fixture_markets fm
    join football.fixtures f on f.id = fm.fixture_id
    where fm.id = v_challenge.fixture_market_id
    limit 1;

    if v_market.id is null then
      raise exception 'Fixture market not found.';
    end if;

    if v_market.is_locked
       or v_market.fixture_status in ('live', 'finished')
       or (v_market.kickoff_at is not null and v_market.kickoff_at <= now()) then
      raise exception 'This market is no longer available for challenges.';
    end if;

    if not exists (
      select 1
      from jsonb_array_elements(v_market.outcomes) outcome
      where lower(coalesce(outcome ->> 'key', outcome ->> 'label', '')) = v_selected_outcome
         or lower(coalesce(outcome ->> 'label', outcome ->> 'key', '')) = v_selected_outcome
    ) then
      raise exception 'Selected outcome is not valid for this market.';
    end if;
  end if;

  update football.prediction_friend_challenges
  set status = case
        when v_action = 'accepted' then 'accepted'
        when v_action = 'declined' then 'declined'
        else 'cancelled'
      end,
      opponent_outcome = case
        when v_action = 'accepted' then v_selected_outcome
        else opponent_outcome
      end,
      responded_at = case
        when v_action in ('accepted', 'declined') then timezone('utc', now())
        else responded_at
      end,
      updated_at = timezone('utc', now())
  where id = v_challenge.id
  returning * into v_challenge;

  return jsonb_build_object(
    'status', v_challenge.status,
    'challenge_id', v_challenge.id,
    'message', case v_challenge.status
      when 'accepted' then 'Challenge accepted.'
      when 'declined' then 'Challenge declined.'
      else 'Challenge cancelled.'
    end
  );
end;
$$;


ALTER FUNCTION "public"."prediction_respond_friend_challenge"("p_challenge_id" "uuid", "p_action" "text", "p_selected_outcome" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prediction_settle_acca_slips"("p_fixture_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'football'
    AS $$
declare
  v_slip record;
  v_all_won boolean;
  v_total_base_fet integer;
  v_leg_count integer;
  v_multiplier numeric;
  v_bonus_fet integer;
  v_club_id bigint;
  v_settled_count integer := 0;
begin
  if auth.role() != 'service_role' then
    return jsonb_build_object('status', 'error', 'message', 'Service role required.');
  end if;

  -- Resolve club
  select id into v_club_id from public.african_football_clubs limit 1;

  -- Find acca slips that have legs in this fixture and are still pending
  for v_slip in
    select distinct ps.id as slip_id, ps.user_id, ps.leg_count
    from football.prediction_slips ps
    join football.predictions p on p.slip_id = ps.id
    where p.fixture_id = p_fixture_id
      and ps.slip_type = 'acca'
      and ps.status = 'pending'
  loop
    -- Check if ALL legs in this slip are now settled
    if exists (
      select 1 from football.predictions p
      where p.slip_id = v_slip.slip_id
        and p.status = 'pending'
    ) then
      continue; -- Still has unsettled legs
    end if;

    -- Check if ALL settled legs are won
    v_all_won := not exists (
      select 1 from football.predictions p
      where p.slip_id = v_slip.slip_id
        and p.status != 'won'
    );

    -- Calculate totals
    select count(*), coalesce(sum(p.fet_earned), 0)
    into v_leg_count, v_total_base_fet
    from football.predictions p
    where p.slip_id = v_slip.slip_id;

    -- Determine multiplier
    v_multiplier := case
      when v_leg_count = 2 then 1.5
      when v_leg_count = 3 then 2.0
      when v_leg_count >= 4 then 3.0
      else 1.0
    end;

    if v_all_won then
      -- Acca won — apply multiplier bonus
      v_bonus_fet := floor(v_total_base_fet * (v_multiplier - 1.0));

      update football.prediction_slips
      set status = 'won',
          total_fet_earned = floor(v_total_base_fet * v_multiplier),
          settled_at = now()
      where id = v_slip.slip_id;

      -- Credit bonus FET (individual leg credits already applied)
      if v_club_id is not null and v_bonus_fet > 0 then
        begin
          perform public.add_fan_points(
            p_user_id   := v_slip.user_id,
            p_partner_id := v_club_id::text,
            p_points    := v_bonus_fet,
            p_reason    := 'acca_bonus'
          );
        exception when others then
          raise notice 'Acca bonus FET failed for slip %: %',
            v_slip.slip_id, sqlerrm;
        end;
      end if;
    else
      -- Acca lost
      update football.prediction_slips
      set status = 'lost',
          total_fet_earned = v_total_base_fet, -- individual leg winnings stay
          settled_at = now()
      where id = v_slip.slip_id;
    end if;

    v_settled_count := v_settled_count + 1;
  end loop;

  return jsonb_build_object(
    'status', 'ok',
    'acca_slips_settled', v_settled_count
  );
end;
$$;


ALTER FUNCTION "public"."prediction_settle_acca_slips"("p_fixture_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prediction_settle_fixture"("p_fixture_id" "uuid", "p_settlements" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'football'
    AS $$
declare
  v_settlement jsonb;
  v_market_slug text;
  v_correct_outcome text;
  v_market_id uuid;
  v_fm_id uuid;
  v_fet_value integer;
  v_won_count integer := 0;
  v_lost_count integer := 0;
  v_total_awarded integer := 0;
  v_total_won integer := 0;
  v_total_lost integer := 0;
  v_markets_processed integer := 0;
  v_club_id bigint;
  v_pred record;
begin
  if auth.role() != 'service_role' then
    return jsonb_build_object('status', 'error', 'message', 'Service role required.');
  end if;

  v_club_id := football.prediction_fixture_club_id(p_fixture_id);

  for v_settlement in
    select * from jsonb_array_elements(p_settlements)
  loop
    v_market_slug := lower(coalesce(v_settlement ->> 'market_slug', ''));
    v_correct_outcome := coalesce(v_settlement ->> 'correct_outcome', '');
    v_won_count := 0;
    v_lost_count := 0;

    select
      market.id,
      fixture_market.id,
      coalesce(fixture_market.fet_value_override, market.default_fet_value)
      into v_market_id, v_fm_id, v_fet_value
    from football.fixture_markets fixture_market
    join football.prediction_markets market on market.id = fixture_market.market_id
    where fixture_market.fixture_id = p_fixture_id
      and lower(market.slug) = v_market_slug
    limit 1;

    if v_market_id is null or v_fm_id is null then
      continue;
    end if;

    update football.fixture_markets
    set is_locked = true,
        locked_at = coalesce(locked_at, now()),
        updated_at = now()
    where id = v_fm_id;

    update football.predictions
    set status = case
          when lower(selected_outcome) = lower(v_correct_outcome) then 'won'
          else 'lost'
        end,
        fet_earned = case
          when lower(selected_outcome) = lower(v_correct_outcome) then v_fet_value
          else 0
        end,
        settled_at = now()
    where fixture_market_id = v_fm_id
      and status in ('pending', 'won', 'lost', 'void');

    select count(*) filter (where prediction.status = 'won'),
           count(*) filter (where prediction.status = 'lost')
      into v_won_count, v_lost_count
    from football.predictions prediction
    where prediction.fixture_market_id = v_fm_id
      and prediction.status in ('won', 'lost');

    if v_club_id is not null and v_won_count > 0 then
      for v_pred in
        select prediction.id, prediction.user_id
        from football.predictions prediction
        where prediction.fixture_market_id = v_fm_id
          and prediction.status = 'won'
      loop
        perform football.award_prediction_fet(
          p_prediction_id := v_pred.id,
          p_user_id := v_pred.user_id,
          p_club_id := v_club_id,
          p_amount := v_fet_value,
          p_fixture_id := p_fixture_id,
          p_market_slug := v_market_slug
        );
      end loop;
    end if;

    insert into football.prediction_settlements (
      fixture_id,
      market_id,
      correct_outcome,
      predictions_won,
      predictions_lost,
      total_fet_awarded,
      settled_at,
      metadata
    )
    values (
      p_fixture_id,
      v_market_id,
      v_correct_outcome,
      v_won_count,
      v_lost_count,
      v_won_count * v_fet_value,
      now(),
      jsonb_build_object('club_id', v_club_id)
    )
    on conflict (fixture_id, market_id) do update
      set correct_outcome = excluded.correct_outcome,
          predictions_won = excluded.predictions_won,
          predictions_lost = excluded.predictions_lost,
          total_fet_awarded = excluded.total_fet_awarded,
          settled_at = excluded.settled_at,
          metadata = excluded.metadata;

    v_total_awarded := v_total_awarded + (v_won_count * v_fet_value);
    v_total_won := v_total_won + v_won_count;
    v_total_lost := v_total_lost + v_lost_count;
    v_markets_processed := v_markets_processed + 1;
  end loop;

  update football.prediction_slips slip
  set status = case
        when exists (
          select 1
          from football.predictions prediction
          where prediction.slip_id = slip.id
            and prediction.status = 'pending'
        ) then 'pending'
        when exists (
          select 1
          from football.predictions prediction
          where prediction.slip_id = slip.id
            and prediction.status = 'won'
        ) then 'won'
        when exists (
          select 1
          from football.predictions prediction
          where prediction.slip_id = slip.id
            and prediction.status = 'lost'
        ) then 'lost'
        else slip.status
      end,
      total_fet_earned = (
        select coalesce(sum(prediction.fet_earned), 0)
        from football.predictions prediction
        where prediction.slip_id = slip.id
      ),
      settled_at = case
        when exists (
          select 1
          from football.predictions prediction
          where prediction.slip_id = slip.id
            and prediction.status = 'pending'
        ) then null
        else now()
      end
  where slip.id in (
    select distinct prediction.slip_id
    from football.predictions prediction
    where prediction.fixture_id = p_fixture_id
      and prediction.slip_id is not null
  );

  perform public.prediction_settle_friend_challenges(p_fixture_id);

  return jsonb_build_object(
    'status', 'settled',
    'fixture_id', p_fixture_id,
    'markets_processed', v_markets_processed,
    'total_won', v_total_won,
    'total_lost', v_total_lost,
    'total_fet_awarded', v_total_awarded
  );
end;
$$;


ALTER FUNCTION "public"."prediction_settle_fixture"("p_fixture_id" "uuid", "p_settlements" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prediction_settle_friend_challenges"("p_fixture_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'football'
    AS $$
declare
  v_count integer := 0;
begin
  if auth.role() != 'service_role' then
    return 0;
  end if;

  with resolved as (
    select
      challenge.id,
      case
        when lower(challenge.challenger_outcome) = lower(settlement.correct_outcome)
             and lower(coalesce(challenge.opponent_outcome, '')) <> lower(settlement.correct_outcome)
          then 'challenger_won'
        when lower(coalesce(challenge.opponent_outcome, '')) = lower(settlement.correct_outcome)
             and lower(challenge.challenger_outcome) <> lower(settlement.correct_outcome)
          then 'opponent_won'
        when lower(challenge.challenger_outcome) = lower(settlement.correct_outcome)
             and lower(coalesce(challenge.opponent_outcome, '')) = lower(settlement.correct_outcome)
          then 'draw'
        else 'draw'
      end as resolved_status,
      case
        when lower(challenge.challenger_outcome) = lower(settlement.correct_outcome)
             and lower(coalesce(challenge.opponent_outcome, '')) <> lower(settlement.correct_outcome)
          then challenge.challenger_user_id
        when lower(coalesce(challenge.opponent_outcome, '')) = lower(settlement.correct_outcome)
             and lower(challenge.challenger_outcome) <> lower(settlement.correct_outcome)
          then challenge.opponent_user_id
        else null
      end as resolved_winner
    from football.prediction_friend_challenges challenge
    join football.fixture_markets fixture_market
      on fixture_market.id = challenge.fixture_market_id
    join football.prediction_settlements settlement
      on settlement.fixture_id = challenge.fixture_id
     and settlement.market_id = fixture_market.market_id
    where challenge.fixture_id = p_fixture_id
      and challenge.status = 'accepted'
  )
  update football.prediction_friend_challenges challenge
  set status = resolved.resolved_status,
      winner_user_id = resolved.resolved_winner,
      settled_at = timezone('utc', now()),
      updated_at = timezone('utc', now())
  from resolved
  where challenge.id = resolved.id;

  get diagnostics v_count = row_count;
  return coalesce(v_count, 0);
end;
$$;


ALTER FUNCTION "public"."prediction_settle_friend_challenges"("p_fixture_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prediction_settle_jackpot_entries"("p_fixture_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'football'
    AS $$
declare
  v_prediction_count integer := 0;
begin
  with resolved as (
    select
      prediction.id,
      case
        when lower(prediction.selected_outcome) = lower(settlement.correct_outcome) then 'won'
        else 'lost'
      end as resolved_status
    from football.jackpot_entry_predictions prediction
    join football.fixture_markets fixture_market
      on fixture_market.id = prediction.fixture_market_id
    join football.prediction_settlements settlement
      on settlement.fixture_id = prediction.fixture_id
     and settlement.market_id = fixture_market.market_id
    where prediction.fixture_id = p_fixture_id
      and prediction.status = 'pending'
  )
  update football.jackpot_entry_predictions prediction
  set status = resolved.resolved_status,
      settled_at = timezone('utc', now())
  from resolved
  where prediction.id = resolved.id;

  get diagnostics v_prediction_count = row_count;

  update football.prediction_slips slip
  set status = case
        when exists (
          select 1
          from football.jackpot_entry_predictions prediction
          where prediction.slip_id = slip.id
            and prediction.status = 'pending'
        ) then 'pending'
        when exists (
          select 1
          from football.jackpot_entry_predictions prediction
          where prediction.slip_id = slip.id
            and prediction.status = 'lost'
        ) then 'lost'
        when exists (
          select 1
          from football.jackpot_entry_predictions prediction
          where prediction.slip_id = slip.id
            and prediction.status = 'won'
        ) then 'won'
        else slip.status
      end,
      settled_at = case
        when exists (
          select 1
          from football.jackpot_entry_predictions prediction
          where prediction.slip_id = slip.id
            and prediction.status = 'pending'
        ) then null
        else timezone('utc', now())
      end
  where slip.slip_type = 'jackpot'
    and slip.jackpot_round_id is not null
    and exists (
      select 1
      from football.jackpot_entry_predictions prediction
      where prediction.slip_id = slip.id
        and prediction.fixture_id = p_fixture_id
    );

  return coalesce(v_prediction_count, 0);
end;
$$;


ALTER FUNCTION "public"."prediction_settle_jackpot_entries"("p_fixture_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."protect_users_is_admin"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  if auth.role() <> 'service_role' then
    if tg_op = 'INSERT' and coalesce(new.is_admin, false) then
      raise exception 'is_admin can only be assigned by the service role.';
    end if;

    if tg_op = 'UPDATE' and new.is_admin is distinct from old.is_admin then
      raise exception 'is_admin can only be modified by the service role.';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."protect_users_is_admin"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."purchase_club_tickets"("p_match_id" "uuid", "p_user_id" "uuid", "p_seat_type" "text", "p_quantity" integer, "p_payment_reference" "text") RETURNS TABLE("id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_actor_club_id bigint;
  v_match public.matches;
  v_payment_reference text := pg_catalog.btrim(
    coalesce(p_payment_reference, '')
  );
  v_seat_type text := pg_catalog.lower(
    pg_catalog.btrim(coalesce(p_seat_type, ''))
  );
  v_ticket_amount integer;
  v_existing_count integer;
  v_matching_count integer;
  v_sold_count integer;
begin
  if v_actor_id is null then
    raise exception 'An authenticated supporter is required.';
  end if;

  if v_actor_id is distinct from p_user_id then
    raise exception 'Authenticated user must match the requested ticket owner.';
  end if;

  begin
    v_actor_club_id := nullif(public.requesting_club_id(), '')::bigint;
  exception
    when invalid_text_representation then
      raise exception 'A trusted club scope is required.';
  end;

  if v_actor_club_id is null then
    raise exception 'A trusted club scope is required.';
  end if;

  if p_match_id is null then
    raise exception 'A ticket match is required.';
  end if;

  if p_quantity is null or p_quantity < 1 or p_quantity > 10 then
    raise exception 'Ticket quantity must be between 1 and 10.';
  end if;

  if v_seat_type not in ('general', 'vip') then
    raise exception 'Ticket type must be general or vip.';
  end if;

  if v_payment_reference = ''
     or pg_catalog.length(v_payment_reference) > 120 then
    raise exception 'A valid payment reference is required.';
  end if;

  -- A retried request with the same actor, match, and reference must observe
  -- the first result instead of issuing a second ticket batch.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      v_actor_id::text || ':' || p_match_id::text || ':' || v_payment_reference,
      0
    )
  );

  select match.*
    into v_match
    from public.matches as match
   where match.id = p_match_id
     and match.club_id = v_actor_club_id
   for update;

  if not found then
    raise exception 'Match was not found in the active club.';
  end if;

  select
    pg_catalog.count(*)::integer,
    pg_catalog.count(*) filter (
      where ticket.seat_type = v_seat_type
    )::integer
    into v_existing_count, v_matching_count
    from public.tickets as ticket
   where ticket.match_id = p_match_id
     and ticket.user_id = v_actor_id
     and ticket.momo_reference = v_payment_reference;

  if v_existing_count > 0 then
    if v_existing_count <> p_quantity
       or v_matching_count <> v_existing_count then
      raise exception 'Payment reference was already used for a different ticket request.';
    end if;

    return query
    select ticket.id
      from public.tickets as ticket
     where ticket.match_id = p_match_id
       and ticket.user_id = v_actor_id
       and ticket.momo_reference = v_payment_reference
       and ticket.seat_type = v_seat_type
     order by ticket.created_at, ticket.id;
    return;
  end if;

  if v_match.is_on_sale is not true then
    raise exception 'Tickets are not on sale for this match.';
  end if;

  if v_match.sale_starts_at > pg_catalog.now() then
    raise exception 'Ticket sales have not started for this match.';
  end if;

  if v_match.match_date < current_date then
    raise exception 'Tickets cannot be issued for a completed match date.';
  end if;

  if coalesce(v_match.capacity, 0) <= 0 then
    raise exception 'Ticket capacity is not configured for this match.';
  end if;

  select pg_catalog.count(*)::integer
    into v_sold_count
    from public.tickets as ticket
   where ticket.match_id = p_match_id
     and ticket.status in ('pending', 'valid', 'used');

  if v_sold_count + p_quantity > v_match.capacity then
    raise exception 'Requested quantity exceeds the remaining ticket capacity.';
  end if;

  v_ticket_amount := case v_seat_type
    when 'vip' then coalesce(v_match.ticket_vip_price, 0)
    else coalesce(v_match.ticket_general_price, 0)
  end;

  insert into public.tickets (
    match_id,
    user_id,
    club_id,
    seat_type,
    amount_paid,
    momo_reference,
    status,
    purchased_at,
    confirmed_at
  )
  select
    p_match_id,
    v_actor_id,
    v_actor_club_id,
    v_seat_type,
    v_ticket_amount,
    v_payment_reference,
    'pending',
    pg_catalog.timezone('utc', pg_catalog.now()),
    null
  from pg_catalog.generate_series(1, p_quantity);

  insert into public.admin_audit_log (
    actor_id,
    user_id,
    action,
    target_table,
    target_id,
    old_data,
    new_data,
    club_id,
    entity_type,
    entity_id,
    metadata
  )
  select
    v_actor_id,
    v_actor_id,
    'supporter_ticket_purchase',
    'tickets',
    ticket.id::text,
    null,
    pg_catalog.jsonb_build_object(
      'status', ticket.status,
      'seat_type', ticket.seat_type,
      'amount_paid', ticket.amount_paid
    ),
    v_actor_club_id,
    'ticket',
    ticket.id::text,
    pg_catalog.jsonb_build_object(
      'scope', 'active_club',
      'source', 'mobile_ticket_purchase',
      'batch_quantity', p_quantity
    )
  from public.tickets as ticket
  where ticket.match_id = p_match_id
    and ticket.user_id = v_actor_id
    and ticket.momo_reference = v_payment_reference;

  return query
  select ticket.id
    from public.tickets as ticket
   where ticket.match_id = p_match_id
     and ticket.user_id = v_actor_id
     and ticket.momo_reference = v_payment_reference
     and ticket.seat_type = v_seat_type
   order by ticket.created_at, ticket.id;
end;
$$;


ALTER FUNCTION "public"."purchase_club_tickets"("p_match_id" "uuid", "p_user_id" "uuid", "p_seat_type" "text", "p_quantity" integer, "p_payment_reference" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reconcile_group_contribution_from_sms"("p_contribution_id" "uuid", "p_ledger_entry_id" "uuid", "p_expected_contribution_updated_at" timestamp with time zone, "p_expected_ledger_updated_at" timestamp with time zone, "p_idempotency_key" "text", "p_actor_id" "uuid", "p_actor_context" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_idempotency_key text;
  v_actor_context text;
  v_reference text;
  v_ledger_reference text;
  v_parsed_reference text;
  v_contribution public.group_contributions%rowtype;
  v_group public.groups%rowtype;
  v_ledger public.momo_ledger_entries%rowtype;
  v_parsed public.momo_sms_parsed%rowtype;
  v_reconciliation public.momo_reconciliations%rowtype;
  v_reconciled_at timestamptz := pg_catalog.clock_timestamp();
begin
  if p_contribution_id is null
     or p_ledger_entry_id is null
     or p_expected_contribution_updated_at is null
     or p_expected_ledger_updated_at is null then
    raise exception 'Contribution, ledger entry and exact loaded versions are required.';
  end if;

  if p_actor_id is null then
    raise exception 'A trusted reconciliation actor is required for audit.';
  end if;

  v_actor_context := pg_catalog.lower(
    pg_catalog.regexp_replace(
      pg_catalog.btrim(coalesce(p_actor_context, '')),
      '[^A-Za-z0-9._:-]',
      '',
      'g'
    )
  );
  if pg_catalog.length(v_actor_context) < 3
     or pg_catalog.length(v_actor_context) > 80 then
    raise exception 'A bounded reconciliation actor context is required.';
  end if;

  v_idempotency_key := pg_catalog.lower(
    pg_catalog.regexp_replace(
      pg_catalog.btrim(coalesce(p_idempotency_key, '')),
      '[^A-Za-z0-9:_-]',
      '',
      'g'
    )
  );
  if pg_catalog.length(v_idempotency_key) < 8
     or pg_catalog.length(v_idempotency_key) > 128 then
    raise exception 'A valid reconciliation idempotency key is required.';
  end if;

  select contribution.*
    into v_contribution
    from public.group_contributions as contribution
   where contribution.id = p_contribution_id
   for update;

  if not found then
    raise exception 'Contribution was not found.';
  end if;

  if v_contribution.status = 'confirmed'
     and v_contribution.payment_status = 'verified'::public.payment_status
     and v_contribution.reconciled_ledger_entry_id = p_ledger_entry_id
     and v_contribution.reconciliation_idempotency_key = v_idempotency_key then
    return pg_catalog.jsonb_build_object(
      'status', 'idempotent_replay',
      'contribution_id', v_contribution.id,
      'ledger_entry_id', v_contribution.reconciled_ledger_entry_id,
      'reconciliation_id', v_contribution.reconciliation_id,
      'confirmed_at', v_contribution.confirmed_at
    );
  end if;

  if v_contribution.status <> 'pending'
     or v_contribution.payment_status <> 'pending_verification'::public.payment_status then
    raise exception 'Only a pending, unverified contribution may be reconciled.';
  end if;

  if v_contribution.updated_at is distinct from p_expected_contribution_updated_at then
    raise exception 'Contribution changed after it was loaded; reconciliation was rolled back.';
  end if;

  select contribution_group.*
    into v_group
    from public.groups as contribution_group
   where contribution_group.id = v_contribution.group_id;

  if not found or v_group.club_id is null then
    raise exception 'Contribution group has no valid club boundary.';
  end if;

  select ledger_entry.*
    into v_ledger
    from public.momo_ledger_entries as ledger_entry
   where ledger_entry.id = p_ledger_entry_id
   for update;

  if not found then
    raise exception 'SMS ledger entry was not found.';
  end if;

  if v_ledger.updated_at is distinct from p_expected_ledger_updated_at then
    raise exception 'SMS ledger entry changed after it was loaded; reconciliation was rolled back.';
  end if;

  select parsed_sms.*
    into v_parsed
    from public.momo_sms_parsed as parsed_sms
   where parsed_sms.id = v_ledger.parsed_sms_id;

  if not found then
    raise exception 'SMS ledger entry is not bound to a parsed SMS record.';
  end if;

  v_reference := pg_catalog.upper(
    pg_catalog.regexp_replace(
      pg_catalog.btrim(coalesce(v_contribution.momo_reference, '')),
      '[^A-Za-z0-9]',
      '',
      'g'
    )
  );
  v_ledger_reference := pg_catalog.upper(
    pg_catalog.regexp_replace(
      pg_catalog.btrim(coalesce(v_ledger.external_reference, '')),
      '[^A-Za-z0-9]',
      '',
      'g'
    )
  );
  v_parsed_reference := pg_catalog.upper(
    pg_catalog.regexp_replace(
      pg_catalog.btrim(coalesce(v_parsed.momo_tx_id, '')),
      '[^A-Za-z0-9]',
      '',
      'g'
    )
  );

  if pg_catalog.length(v_ledger_reference) < 6
     or v_parsed_reference is distinct from v_ledger_reference
     or (
       pg_catalog.length(v_reference) > 0
       and v_reference is distinct from v_ledger_reference
     ) then
    raise exception 'Parsed SMS and ledger payment references do not match exactly.';
  end if;

  if exists (
    select 1
      from public.group_contributions as other_contribution
     where other_contribution.momo_reference = v_ledger_reference
       and other_contribution.id <> v_contribution.id
  ) then
    raise exception 'Provider payment reference is already bound to another contribution.';
  end if;

  if v_ledger.user_id is distinct from v_contribution.user_id
     or v_parsed.user_id is distinct from v_contribution.user_id then
    raise exception 'Contribution and SMS ownership do not match.';
  end if;

  if v_ledger.club_id is distinct from v_group.club_id
     or v_parsed.club_id is distinct from v_group.club_id then
    raise exception 'Contribution and SMS club boundaries do not match.';
  end if;

  if v_ledger.amount is distinct from v_contribution.amount
     or v_parsed.amount is distinct from v_contribution.amount then
    raise exception 'Contribution and SMS amounts do not match exactly.';
  end if;

  if pg_catalog.upper(v_ledger.currency) is distinct from pg_catalog.upper(v_group.currency)
     or pg_catalog.upper(v_parsed.currency) is distinct from pg_catalog.upper(v_group.currency) then
    raise exception 'Contribution and SMS currencies do not match.';
  end if;

  if v_ledger.entry_type <> 'debit' or v_parsed.tx_direction <> 'debit' then
    raise exception 'Only an outgoing supporter payment may confirm a contribution.';
  end if;

  if v_ledger.target_record_id is not null
     and (
       v_ledger.target_table is distinct from 'group_contributions'
       or v_ledger.target_record_id is distinct from v_contribution.id
     ) then
    raise exception 'SMS ledger entry is already bound to another target.';
  end if;

  select reconciliation.*
    into v_reconciliation
    from public.momo_reconciliations as reconciliation
   where reconciliation.parsed_sms_id = v_ledger.parsed_sms_id
   for update;

  if found then
    if v_reconciliation.match_status <> 'matched'
       or v_reconciliation.target_table is distinct from 'group_contributions'
       or v_reconciliation.target_record_id is distinct from v_contribution.id
       or v_reconciliation.metadata ->> 'idempotency_key' is distinct from v_idempotency_key
       or v_reconciliation.metadata ->> 'ledger_entry_id' is distinct from v_ledger.id::text then
      raise exception 'Parsed SMS reconciliation is already bound to another decision.';
    end if;
  else
    insert into public.momo_reconciliations (
      parsed_sms_id,
      user_id,
      target_table,
      target_record_id,
      match_type,
      match_status,
      confidence,
      notes,
      metadata,
      reconciled_at,
      country_code,
      club_id
    ) values (
      v_ledger.parsed_sms_id,
      v_contribution.user_id,
      'group_contributions',
      v_contribution.id,
      'exact_sms_reference',
      'matched',
      1.0000,
      'Atomic service reconciliation with exact amount, reference, owner and club binding.',
      pg_catalog.jsonb_build_object(
        'actor_id', p_actor_id,
        'actor_context', v_actor_context,
        'idempotency_key', v_idempotency_key,
        'ledger_entry_id', v_ledger.id
      ),
      v_reconciled_at,
      v_ledger.country_code,
      v_group.club_id
    )
    returning * into v_reconciliation;
  end if;

  update public.momo_ledger_entries
     set target_table = 'group_contributions',
         target_record_id = v_contribution.id,
         ledger_status = 'posted',
         metadata = coalesce(metadata, '{}'::jsonb)
           || pg_catalog.jsonb_build_object(
             'reconciliation_id', v_reconciliation.id,
             'reconciliation_actor_id', p_actor_id,
             'reconciliation_actor_context', v_actor_context,
             'reconciliation_idempotency_key', v_idempotency_key
           )
   where id = v_ledger.id
     and updated_at = p_expected_ledger_updated_at;

  if not found then
    raise exception 'SMS ledger entry changed during reconciliation; transaction was rolled back.';
  end if;

  update public.group_contributions
     set status = 'confirmed',
         payment_status = 'verified'::public.payment_status,
         momo_reference = v_ledger_reference,
         confirmed_at = v_reconciled_at,
         reconciled_ledger_entry_id = v_ledger.id,
         reconciliation_id = v_reconciliation.id,
         reconciliation_idempotency_key = v_idempotency_key,
         reconciled_by = p_actor_id
   where id = v_contribution.id
     and status = 'pending'
     and payment_status = 'pending_verification'::public.payment_status
     and updated_at = p_expected_contribution_updated_at
  returning * into v_contribution;

  if not found then
    raise exception 'Contribution changed during reconciliation; transaction was rolled back.';
  end if;

  insert into public.admin_audit_log (
    actor_id,
    user_id,
    action,
    target_table,
    target_id,
    old_data,
    new_data,
    club_id,
    entity_type,
    entity_id,
    metadata,
    notes
  ) values (
    p_actor_id,
    p_actor_id,
    'group_contribution_sms_reconciled',
    'group_contributions',
    v_contribution.id::text,
    pg_catalog.jsonb_build_object(
      'status', 'pending',
      'payment_status', 'pending_verification',
      'updated_at', p_expected_contribution_updated_at
    ),
    pg_catalog.jsonb_build_object(
      'status', v_contribution.status,
      'payment_status', v_contribution.payment_status,
      'updated_at', v_contribution.updated_at,
      'confirmed_at', v_contribution.confirmed_at
    ),
    v_group.club_id,
    'group_contribution',
    v_contribution.id::text,
    pg_catalog.jsonb_build_object(
      'actor_context', v_actor_context,
      'idempotency_key', v_idempotency_key,
      'ledger_entry_id', v_ledger.id,
      'parsed_sms_id', v_ledger.parsed_sms_id,
      'reconciliation_id', v_reconciliation.id,
      'binding', 'exact_amount_reference_owner_club_and_versions'
    ),
    'Atomic service reconciliation from a verified SMS ledger entry.'
  );

  return pg_catalog.jsonb_build_object(
    'status', 'confirmed',
    'contribution_id', v_contribution.id,
    'ledger_entry_id', v_ledger.id,
    'reconciliation_id', v_reconciliation.id,
    'confirmed_at', v_contribution.confirmed_at
  );
end;
$$;


ALTER FUNCTION "public"."reconcile_group_contribution_from_sms"("p_contribution_id" "uuid", "p_ledger_entry_id" "uuid", "p_expected_contribution_updated_at" timestamp with time zone, "p_expected_ledger_updated_at" timestamp with time zone, "p_idempotency_key" "text", "p_actor_id" "uuid", "p_actor_context" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reconcile_group_contribution_from_sms"("p_contribution_id" "uuid", "p_ledger_entry_id" "uuid", "p_expected_contribution_updated_at" timestamp with time zone, "p_expected_ledger_updated_at" timestamp with time zone, "p_idempotency_key" "text", "p_actor_id" "uuid", "p_actor_context" "text") IS 'Service-only atomic reconciliation: exact owner, club, amount, currency, reference and updated_at binding with immutable audit evidence.';



CREATE OR REPLACE FUNCTION "public"."record_admin_action"("p_action" "text", "p_target_table" "text" DEFAULT NULL::"text", "p_target_id" "text" DEFAULT NULL::"text", "p_old_data" "jsonb" DEFAULT NULL::"jsonb", "p_new_data" "jsonb" DEFAULT NULL::"jsonb", "p_notes" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  insert into public.admin_audit_log (actor_id, action, target_table, target_id, old_data, new_data, notes)
  values (auth.uid(), p_action, p_target_table, p_target_id, p_old_data, p_new_data, p_notes);
$$;


ALTER FUNCTION "public"."record_admin_action"("p_action" "text", "p_target_table" "text", "p_target_id" "text", "p_old_data" "jsonb", "p_new_data" "jsonb", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."redact_momo_sms_artifacts_due"("p_raw_retention" interval DEFAULT '14 days'::interval, "p_attempt_retention" interval DEFAULT '14 days'::interval, "p_batch_size" integer DEFAULT 500) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_now timestamptz := now();
  v_batch_size integer := greatest(coalesce(p_batch_size, 500), 1);
  v_raw_redacted integer := 0;
  v_attempt_payloads_redacted integer := 0;
begin
  with raw_candidates as (
    select raw.id
    from public.momo_sms_raw raw
    join public.momo_sms_parsed parsed
      on parsed.raw_sms_id = raw.id
     and parsed.parse_status = 'parsed'
    join public.momo_reconciliations reconciliation
      on reconciliation.parsed_sms_id = parsed.id
     and reconciliation.match_status = 'matched'
    where raw.sms_body_redacted_at is null
      and raw.parse_status = 'parsed'
      and raw.created_at <= v_now - p_raw_retention
    order by raw.created_at asc
    limit v_batch_size
  )
  update public.momo_sms_raw raw
     set sms_body = '[REDACTED AFTER PARSE + MATCHED RECONCILIATION]',
         sms_body_redacted_at = v_now,
         updated_at = v_now
    from raw_candidates
   where raw.id = raw_candidates.id;

  get diagnostics v_raw_redacted = row_count;

  with attempt_candidates as (
    select attempt.id
    from public.momo_parse_attempts attempt
    join public.momo_sms_raw raw
      on raw.id = attempt.raw_sms_id
    where attempt.payloads_redacted_at is null
      and raw.created_at <= v_now - p_attempt_retention
      and raw.parse_status in ('parsed', 'failed', 'ignored')
    order by attempt.created_at asc
    limit v_batch_size
  )
  update public.momo_parse_attempts attempt
     set request_payload = '{}'::jsonb,
         response_payload = '{}'::jsonb,
         payloads_redacted_at = v_now
    from attempt_candidates
   where attempt.id = attempt_candidates.id;

  get diagnostics v_attempt_payloads_redacted = row_count;

  return jsonb_build_object(
    'raw_redacted', v_raw_redacted,
    'attempt_payloads_redacted', v_attempt_payloads_redacted,
    'executed_at', v_now,
    'raw_retention_days', extract(day from p_raw_retention),
    'attempt_retention_days', extract(day from p_attempt_retention),
    'batch_size', v_batch_size
  );
end;
$$;


ALTER FUNCTION "public"."redact_momo_sms_artifacts_due"("p_raw_retention" interval, "p_attempt_retention" interval, "p_batch_size" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."redact_momo_sms_artifacts_due"("p_raw_retention" interval, "p_attempt_retention" interval, "p_batch_size" integer) IS 'Redacts retained raw MoMo SMS bodies after successful parse + matched reconciliation, and clears stored AI request/response payloads after the retention window.';



CREATE OR REPLACE FUNCTION "public"."refresh_admin_phone_access_for_user"("p_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_phone text;
  v_phone_digits text;
  v_club_ids bigint[];
BEGIN
  IF p_user_id IS NULL THEN
    RETURN;
  END IF;

  SELECT
    COALESCE(NULLIF(u.phone, ''), i.identity_data->>'phone')
  INTO v_phone
  FROM auth.users AS u
  LEFT JOIN auth.identities AS i
    ON i.user_id = u.id
   AND i.provider = 'phone'
  WHERE u.id = p_user_id
  ORDER BY i.updated_at DESC NULLS LAST
  LIMIT 1;

  SELECT ARRAY_REMOVE(ARRAY_AGG(DISTINCT assignments.club_id), NULL)
  INTO v_club_ids
  FROM public.admin_role_assignments AS assignments
  WHERE assignments.user_id = p_user_id
    AND assignments.is_active = true
    AND assignments.role IN (
      'super_admin',
      'admin',
      'club_admin',
      'club_moderator',
      'rayon_sport',
      'bank'
    );

  v_phone_digits := regexp_replace(COALESCE(v_phone, ''), '[^0-9]', '', 'g');

  IF COALESCE(array_length(v_club_ids, 1), 0) = 0 OR v_phone_digits = '' THEN
    DELETE FROM public.admin_phone_access
    WHERE user_id = p_user_id;
    RETURN;
  END IF;

  DELETE FROM public.admin_phone_access
  WHERE normalized_phone = v_phone_digits
    AND user_id <> p_user_id;

  INSERT INTO public.admin_phone_access (
    user_id,
    phone,
    normalized_phone,
    club_ids,
    updated_at
  )
  VALUES (
    p_user_id,
    v_phone,
    v_phone_digits,
    COALESCE(v_club_ids, '{}'),
    timezone('utc', now())
  )
  ON CONFLICT (user_id) DO UPDATE
  SET phone = EXCLUDED.phone,
      normalized_phone = EXCLUDED.normalized_phone,
      club_ids = EXCLUDED.club_ids,
      updated_at = timezone('utc', now());
END;
$$;


ALTER FUNCTION "public"."refresh_admin_phone_access_for_user"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_match_ticket_sales"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_new_match_id uuid;
  v_old_match_id uuid;
begin
  if tg_op <> 'DELETE' then
    v_new_match_id := new.match_id;
  end if;
  if tg_op <> 'INSERT' then
    v_old_match_id := old.match_id;
  end if;

  if v_new_match_id is not null then
    update public.matches as match
       set sold_count = (
             select pg_catalog.count(*)::integer
               from public.tickets as ticket
              where ticket.match_id = v_new_match_id
                and ticket.status in ('pending', 'valid', 'used')
           ),
           updated_at = pg_catalog.timezone('utc', pg_catalog.now())
     where match.id = v_new_match_id;
  end if;

  if v_old_match_id is not null
     and v_old_match_id is distinct from v_new_match_id then
    update public.matches as match
       set sold_count = (
             select pg_catalog.count(*)::integer
               from public.tickets as ticket
              where ticket.match_id = v_old_match_id
                and ticket.status in ('pending', 'valid', 'used')
           ),
           updated_at = pg_catalog.timezone('utc', pg_catalog.now())
     where match.id = v_old_match_id;
  end if;

  return coalesce(new, old);
end;
$$;


