CREATE OR REPLACE FUNCTION "public"."requesting_club_id"() RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with request_claims as (
    select coalesce(
      nullif(current_setting('request.jwt.claims', true), ''),
      '{}'
    )::jsonb as claims
  )
  select coalesce(
    public.normalize_club_id(
      nullif(
        coalesce(
          request_claims.claims ->> 'club_id',
          request_claims.claims -> 'app_metadata' ->> 'club_id'
        ),
        ''
      )
    )::text,
    (
      select profile.club_id::text
      from public.profiles as profile
      where profile.id = auth.uid()
      limit 1
    )
  )
  from request_claims;
$$;


