CREATE OR REPLACE FUNCTION "public"."resolve_partner_ids_for_club"("p_club_id" bigint) RETURNS "uuid"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with partner_sources as (
    select ppr.partner_id
    from public.partner_payment_routes ppr
    where ppr.club_id = p_club_id
      and ppr.partner_id is not null
    union
    select i.partner_id
    from public.initiatives i
    where i.club_id = p_club_id
      and i.partner_id is not null
    union
    select m.partner_id
    from public.matches m
    where m.club_id = p_club_id
      and m.partner_id is not null
    union
    select mp.partner_id
    from public.membership_packages mp
    where mp.club_id = p_club_id
      and mp.partner_id is not null
    union
    select sp.partner_id
    from public.shop_products sp
    where sp.club_id = p_club_id
      and sp.partner_id is not null
    union
    select so.partner_id
    from public.shop_orders so
    where so.club_id = p_club_id
      and so.partner_id is not null
  )
  select coalesce(
    array_agg(distinct partner_id) filter (where partner_id is not null),
    '{}'::uuid[]
  )
  from partner_sources;
$$;


ALTER FUNCTION "public"."resolve_partner_ids_for_club"("p_club_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."restock_cancelled_shop_order"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_item jsonb;
  v_product_id uuid;
  v_quantity integer;
begin
  if old.inventory_reserved
     and not new.inventory_reserved
     and new.status = 'cancelled' then
    for v_item in
      select value
      from pg_catalog.jsonb_array_elements(old.items)
    loop
      v_product_id := coalesce(
        nullif(v_item ->> 'product_id', ''),
        nullif(v_item -> 'product' ->> 'id', '')
      )::uuid;
      v_quantity := (v_item ->> 'quantity')::integer;

      update public.shop_products as product
         set stock = product.stock + v_quantity
       where product.id = v_product_id
         and product.club_id is not distinct from old.club_id;

      if not found then
        raise exception 'Reserved product is missing from the order club.';
      end if;
    end loop;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."restock_cancelled_shop_order"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_membership_application_if_unchanged"("p_application_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_decision" "text", "p_payment_status" "text", "p_actor_id" "uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS "public"."membership_applications"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_decision text := pg_catalog.lower(
    pg_catalog.btrim(coalesce(p_decision, ''))
  );
  v_payment_status text := pg_catalog.lower(
    pg_catalog.btrim(coalesce(p_payment_status, ''))
  );
  v_previous public.membership_applications;
  v_application public.membership_applications;
  v_package public.membership_packages;
  v_partner_id uuid;
begin
  if p_application_id is null
     or p_expected_updated_at is null
     or p_actor_id is null then
    raise exception 'Application, loaded version and review actor are required.';
  end if;

  if v_decision not in ('approved', 'rejected')
     or v_payment_status not in ('paid', 'failed', 'unpaid')
     or pg_catalog.length(coalesce(p_notes, '')) > 500 then
    raise exception 'Membership review values are invalid.';
  end if;

  select application.*
    into v_previous
    from public.membership_applications as application
   where application.id = p_application_id
   for update;

  if not found then
    raise exception 'Membership application was not found.';
  end if;

  if v_previous.status <> 'pending' then
    raise exception 'Membership application is no longer pending. Refresh before retrying.';
  end if;

  if v_previous.updated_at is distinct from p_expected_updated_at then
    raise exception
      'Membership application changed after it was loaded. Refresh before retrying.';
  end if;

  if not exists (
    select 1
    from public.admin_role_assignments as assignment
    where assignment.user_id = p_actor_id
      and assignment.is_active
      and assignment.revoked_at is null
      and (
        assignment.role in ('admin', 'super_admin')
        or (
          assignment.club_id = v_previous.club_id
          and assignment.role in ('club_admin', 'club_moderator', 'rayon_sport')
        )
      )
  ) and not exists (
    select 1
    from public.users as app_user
    where app_user.id = p_actor_id
      and app_user.is_admin
  ) then
    raise exception 'Membership review actor is not authorized for this club.';
  end if;

  if v_decision = 'approved'
     and (
       v_payment_status <> 'paid'
       or v_previous.payment_status <> 'paid'
     ) then
    raise exception
      'Approved memberships require a separately verified payment state.';
  end if;

  update public.membership_applications as application
     set status = v_decision,
         payment_status = v_payment_status,
         reviewer_id = p_actor_id,
         review_date = pg_catalog.now(),
         notes = nullif(pg_catalog.btrim(coalesce(p_notes, '')), '')
   where application.id = v_previous.id
  returning application.* into v_application;

  if v_decision = 'approved' then
    select package.*
      into v_package
      from public.membership_packages as package
     where package.id = (v_previous.metadata ->> 'package_id')::uuid
       and package.is_active
       and package.tier = v_previous.tier
       and package.club_id = v_previous.club_id
       and package.benefit_scope = 'physical_membership'
       and not package.store_billing_required
     limit 1;

    if v_package.id is null then
      raise exception 'Membership offer is no longer eligible for activation.';
    end if;

    v_partner_id := v_package.partner_id;

    insert into public.fan_memberships (
      user_id,
      partner_id,
      club_id,
      tier,
      points,
      chapter,
      payment_status,
      status,
      renewed_at,
      expires_at
    ) values (
      v_previous.user_id,
      v_partner_id,
      v_previous.club_id,
      v_previous.tier,
      0,
      coalesce(nullif(v_previous.metadata ->> 'chapter', ''), 'Main'),
      'verified'::public.payment_status,
      'active',
      pg_catalog.now(),
      pg_catalog.now() + interval '1 year'
    )
    on conflict (user_id, club_id)
    do update set
      partner_id = excluded.partner_id,
      tier = excluded.tier,
      chapter = excluded.chapter,
      payment_status = excluded.payment_status,
      status = excluded.status,
      renewed_at = excluded.renewed_at,
      expires_at = excluded.expires_at,
      updated_at = pg_catalog.now();
  end if;

  insert into public.admin_audit_log (
    actor_id,
    user_id,
    action,
    target_table,
    target_id,
    old_data,
    new_data,
    club_id,
    entity_type,
    entity_id,
    metadata
  ) values (
    p_actor_id,
    v_previous.user_id,
    'membership_application_reviewed',
    'membership_applications',
    v_application.id::text,
    pg_catalog.jsonb_build_object(
      'status', v_previous.status,
      'payment_status', v_previous.payment_status,
      'updated_at', v_previous.updated_at
    ),
    pg_catalog.jsonb_build_object(
      'status', v_application.status,
      'payment_status', v_application.payment_status,
      'updated_at', v_application.updated_at
    ),
    v_application.club_id,
    'membership_application',
    v_application.id::text,
    pg_catalog.jsonb_build_object(
      'optimistic_concurrency', true,
      'membership_activated', v_decision = 'approved',
      'benefit_scope', coalesce(v_package.benefit_scope, 'not_applicable')
    )
  );

  return v_application;
end;
$$;


ALTER FUNCTION "public"."review_membership_application_if_unchanged"("p_application_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_decision" "text", "p_payment_status" "text", "p_actor_id" "uuid", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."revoke_admin_role"("p_assignment_id" "uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller_id uuid;
  v_assignment record;
BEGIN
  v_caller_id := auth.uid();

  -- Only platform admins can revoke roles
  IF NOT EXISTS (
    SELECT 1 FROM public.users u
    WHERE u.id = v_caller_id AND u.is_admin = true
  ) THEN
    RAISE EXCEPTION 'Only platform admins can revoke admin roles.';
  END IF;

  -- Find and validate assignment
  SELECT * INTO v_assignment
  FROM public.admin_role_assignments
  WHERE id = p_assignment_id AND is_active = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Role assignment not found or already revoked.';
  END IF;

  -- Soft-delete
  UPDATE public.admin_role_assignments
  SET is_active = false,
      revoked_at = now(),
      notes = COALESCE(p_notes, notes)
  WHERE id = p_assignment_id;

  RETURN jsonb_build_object(
    'status', 'revoked',
    'assignment_id', p_assignment_id,
    'role', v_assignment.role,
    'user_id', v_assignment.user_id
  );
END;
$$;


ALTER FUNCTION "public"."revoke_admin_role"("p_assignment_id" "uuid", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rls_auto_enable"() RETURNS "event_trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."rls_auto_enable"() OWNER TO "postgres";


