CREATE OR REPLACE FUNCTION "public"."rs_check_ticket_capacity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_capacity integer;
  v_club_id bigint;
  v_sold integer;
begin
  select match.capacity, match.club_id
    into v_capacity, v_club_id
    from public.matches as match
   where match.id = new.match_id
   for update;

  if not found then
    raise exception 'Ticket match was not found.';
  end if;

  if new.club_id is distinct from v_club_id then
    raise exception 'Ticket club must match the selected match.';
  end if;

  if coalesce(v_capacity, 0) <= 0 then
    raise exception 'Ticket capacity is not configured for this match.';
  end if;

  select pg_catalog.count(*)::integer
    into v_sold
    from public.tickets as ticket
   where ticket.match_id = new.match_id
     and ticket.status in ('pending', 'valid', 'used');

  if v_sold >= v_capacity then
    raise exception 'Match is sold out. Capacity: %, Sold: %',
      v_capacity,
      v_sold;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."rs_check_ticket_capacity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rs_decrement_stock_on_order"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_item jsonb;
  v_product_id uuid;
  v_quantity integer;
  v_updated_product_id uuid;
begin
  if new.items is null or pg_catalog.jsonb_array_length(new.items) = 0 then
    return new;
  end if;

  for v_item in
    select value
    from pg_catalog.jsonb_array_elements(new.items)
  loop
    begin
      v_product_id := coalesce(
        nullif(v_item ->> 'product_id', ''),
        nullif(v_item -> 'product' ->> 'id', '')
      )::uuid;
      v_quantity := coalesce((v_item ->> 'quantity')::integer, 1);
    exception
      when invalid_text_representation then
        raise exception 'Order item product and quantity must be valid.';
    end;

    if v_product_id is null or v_quantity <= 0 then
      raise exception 'Order item product and quantity must be valid.';
    end if;

    v_updated_product_id := null;
    update public.shop_products
       set stock = stock - v_quantity
     where id = v_product_id
       and club_id is not distinct from new.club_id
       and is_active = true
       and stock >= v_quantity
    returning id into v_updated_product_id;

    if v_updated_product_id is null then
      raise exception
        'Order item is unavailable in the active club catalog or has insufficient stock.';
    end if;
  end loop;

  return new;
end;
$$;


ALTER FUNCTION "public"."rs_decrement_stock_on_order"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."rs_decrement_stock_on_order"() IS 'Internal shop_orders trigger that atomically decrements public.shop_products stock; not a callable Data API function.';



