CREATE OR REPLACE FUNCTION "public"."sync_group_contract_columns"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  new.group_type := case
    when lower(coalesce(new.group_type, new.type, 'community')) in ('project', 'club', 'team_project')
      then 'project'
    else 'community'
  end;

  new.type := new.group_type;
  new.visibility := 'public';

  if new.current_total is null then
    new.current_total := coalesce(new.amount, 0);
  end if;

  if new.amount is null then
    new.amount := coalesce(new.current_total, 0)::integer;
  end if;

  if new.receiving_momo_code is null and new.momo_code is not null then
    new.receiving_momo_code := new.momo_code;
  end if;

  if new.momo_code is null and new.receiving_momo_code is not null then
    new.momo_code := new.receiving_momo_code;
  end if;

  if new.contribution_amount is null and new.monthly_contribution is not null then
    new.contribution_amount := new.monthly_contribution;
  end if;

  if new.monthly_contribution is null and new.contribution_amount is not null then
    new.monthly_contribution := new.contribution_amount;
  end if;

  if new.is_closed is null then
    new.is_closed := coalesce(new.is_active, true) = false;
  end if;

  if new.is_active is null then
    new.is_active := coalesce(new.is_closed, false) = false;
  end if;

  new.member_count := greatest(coalesce(new.member_count, 0), 0);
  return new;
end;
$$;


ALTER FUNCTION "public"."sync_group_contract_columns"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_group_financials"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_group_id uuid := case when tg_op = 'DELETE' then old.group_id else new.group_id end;
  v_user_id uuid := case when tg_op = 'DELETE' then old.user_id else new.user_id end;
  v_confirmed_total bigint;
begin
  if v_group_id is null then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  select coalesce(pg_catalog.sum(contribution.amount), 0)::bigint
    into v_confirmed_total
    from public.group_contributions as contribution
   where contribution.group_id = v_group_id
     and contribution.status = 'confirmed';

  update public.groups
     set amount = v_confirmed_total::integer,
         current_total = v_confirmed_total
   where id = v_group_id;

  update public.group_members as member
     set contribution_amount = coalesce((
       select pg_catalog.sum(contribution.amount)
         from public.group_contributions as contribution
        where contribution.group_id = member.group_id
          and contribution.user_id = member.user_id
          and contribution.status = 'confirmed'
     ), 0)::integer
   where member.group_id = v_group_id
     and (v_user_id is null or member.user_id = v_user_id);

  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


ALTER FUNCTION "public"."sync_group_financials"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_group_member_count"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  target_group_id uuid := coalesce(new.group_id, old.group_id);
begin
  if target_group_id is null then
    return coalesce(new, old);
  end if;

  update public.groups
  set
    member_count = (
      select count(*)
      from public.group_members gm
      where gm.group_id = target_group_id
    ),
    updated_at = now()
  where id = target_group_id;

  return coalesce(new, old);
end;
$$;


