  into profile_phone, profile_name
  from public.users u
  where u.id = new.user_id;

  new.contact_phone := coalesce(nullif(new.contact_phone, ''), profile_phone);
  new.contact_name := coalesce(profile_name, nullif(new.contact_name, ''));
  return new;
end;
$$;


