CREATE OR REPLACE FUNCTION "public"."user_has_admin_workspace_access"("p_club_id" bigint DEFAULT NULL::bigint, "p_partner_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    public.is_admin_user()
    or (p_club_id is not null and public.is_club_admin(p_club_id))
    or (p_partner_id is not null and public.is_partner_admin(p_partner_id));
$$;


