CREATE OR REPLACE FUNCTION "public"."venue_checkin_validate"("p_club_id" bigint, "p_code_hash" "text", "p_idempotency_key" "text" DEFAULT NULL::"text", "p_location_accuracy_meters" numeric DEFAULT NULL::numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_club_id bigint;
begin
  v_club_id := public.fet_require_club_context(p_club_id);
  return public.venue_checkin_validate_unscoped_internal(
    v_club_id,
    p_code_hash,
    p_idempotency_key,
    p_location_accuracy_meters
  );
end;
$$;


ALTER FUNCTION "public"."venue_checkin_validate"("p_club_id" bigint, "p_code_hash" "text", "p_idempotency_key" "text", "p_location_accuracy_meters" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."venue_checkin_validate_unscoped_internal"("p_club_id" bigint, "p_code_hash" "text", "p_idempotency_key" "text" DEFAULT NULL::"text", "p_location_accuracy_meters" numeric DEFAULT NULL::numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_code public.venue_checkin_codes;
  v_campaign public.venue_checkin_campaigns;
  v_checkin public.venue_checkins;
  v_user_id uuid := auth.uid();
  v_now timestamp with time zone := timezone('utc', now());
  v_idempotency_key text := nullif(btrim(coalesce(p_idempotency_key, '')), '');
  v_location_status text := 'not_requested';
begin
  if v_user_id is null then
    return jsonb_build_object('status', 'error', 'code', 'auth_required');
  end if;

  if v_idempotency_key is not null then
    select *
      into v_checkin
      from public.venue_checkins
     where club_id = p_club_id
       and user_id = v_user_id
       and idempotency_key = v_idempotency_key
     limit 1;

    if v_checkin.id is not null then
      return jsonb_build_object(
        'status', v_checkin.status,
        'code', 'idempotent_replay',
        'checkin_id', v_checkin.id,
        'venue_id', v_checkin.venue_id,
        'fet_awarded', v_checkin.fet_awarded
      );
    end if;
  end if;

  select *
    into v_code
    from public.venue_checkin_codes
   where club_id = p_club_id
     and code_hash = p_code_hash
   limit 1;

  if v_code.id is null then
    return jsonb_build_object('status', 'error', 'code', 'invalid_code');
  end if;

  if v_code.status <> 'active' or v_code.expires_at <= v_now then
    return jsonb_build_object('status', 'error', 'code', 'expired_code');
  end if;

  select *
    into v_campaign
    from public.venue_checkin_campaigns
   where id = v_code.campaign_id
     and club_id = p_club_id
   limit 1;

  if v_campaign.id is null or v_campaign.status <> 'approved' then
    return jsonb_build_object('status', 'error', 'code', 'campaign_paused');
  end if;

  if v_campaign.starts_at > v_now or v_campaign.ends_at <= v_now then
    return jsonb_build_object('status', 'error', 'code', 'campaign_inactive');
  end if;

  if v_campaign.fet_budget > 0 and
     v_campaign.awarded_fet + v_campaign.fet_award_per_checkin > v_campaign.fet_budget then
    return jsonb_build_object('status', 'error', 'code', 'campaign_budget_exhausted');
  end if;

  if v_campaign.require_location then
    if p_location_accuracy_meters is null then
      v_location_status := 'pending_review';
    elsif v_campaign.min_location_accuracy_meters is not null and
          p_location_accuracy_meters > v_campaign.min_location_accuracy_meters then
      v_location_status := 'low_accuracy';
    else
      v_location_status := 'verified';
    end if;
  end if;

  if (
    select count(*)
    from public.venue_checkins previous
    where previous.club_id = p_club_id
      and previous.campaign_id = v_campaign.id
      and previous.user_id = v_user_id
      and previous.status in ('confirmed', 'pending_review')
  ) >= v_campaign.max_checkins_per_user then
    return jsonb_build_object('status', 'error', 'code', 'already_checked_in');
  end if;

  insert into public.venue_checkins (
    club_id,
    venue_id,
    campaign_id,
    code_id,
    user_id,
    status,
    idempotency_key,
    location_verification_status,
    location_accuracy_meters,
    fet_awarded,
    metadata
  )
  values (
    p_club_id,
    v_code.venue_id,
    v_campaign.id,
    v_code.id,
    v_user_id,
    case when v_location_status in ('pending_review', 'low_accuracy') then 'pending_review' else 'confirmed' end,
    v_idempotency_key,
    v_location_status,
    p_location_accuracy_meters,
    v_campaign.fet_award_per_checkin,
    jsonb_build_object('source', 'venue_checkin_validate')
  )
  returning * into v_checkin;

  update public.venue_checkin_campaigns
     set awarded_fet = awarded_fet + v_campaign.fet_award_per_checkin
   where id = v_campaign.id;

  insert into public.venue_promotion_events (
    club_id,
    venue_id,
    campaign_id,
    checkin_id,
    event_type,
    user_id,
    fet_amount,
    idempotency_key
  )
  values (
    p_club_id,
    v_code.venue_id,
    v_campaign.id,
    v_checkin.id,
    'checkin_reward_recorded',
    v_user_id,
    v_campaign.fet_award_per_checkin,
    v_idempotency_key
  )
  on conflict do nothing;

  return jsonb_build_object(
    'status', v_checkin.status,
    'code', 'ok',
    'checkin_id', v_checkin.id,
    'venue_id', v_checkin.venue_id,
    'campaign_id', v_campaign.id,
    'fet_awarded', v_checkin.fet_awarded,
    'location_verification_status', v_checkin.location_verification_status
  );
end;
$$;


ALTER FUNCTION "public"."venue_checkin_validate_unscoped_internal"("p_club_id" bigint, "p_code_hash" "text", "p_idempotency_key" "text", "p_location_accuracy_meters" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."venue_enforce_active_drink_limit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_active_count integer;
begin
  if new.is_active then
    select count(*)
      into v_active_count
      from public.venue_drink_items item
     where item.club_id = new.club_id
       and item.venue_id = new.venue_id
       and item.is_active
       and item.id <> new.id;

    if v_active_count >= 10 then
      raise exception 'A venue can have at most 10 active drinks.';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."venue_enforce_active_drink_limit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."venue_menu_upsert"("p_venue_id" "uuid", "p_item_id" "uuid", "p_name" "text", "p_description" "text", "p_price_amount" integer, "p_currency_code" "text", "p_is_alcohol" boolean, "p_is_active" boolean, "p_sort_order" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_membership public.venue_staff_memberships;
  v_item public.venue_drink_items;
  v_event_type text;
begin
  if v_actor is null then
    return jsonb_build_object('status', 'error', 'code', 'auth_required');
  end if;

  select * into v_membership
  from public.venue_staff_memberships
  where user_id = v_actor
    and venue_id = p_venue_id
    and is_active
    and role = any (array['owner', 'manager'])
  order by granted_at asc
  limit 1;

  if v_membership.id is null then
    return jsonb_build_object('status', 'error', 'code', 'permission_denied');
  end if;

  if length(btrim(coalesce(p_name, ''))) < 2 or length(btrim(p_name)) > 80 then
    return jsonb_build_object('status', 'error', 'code', 'invalid_name');
  end if;
  if p_price_amount is null or p_price_amount < 0 or p_price_amount > 10000000 then
    return jsonb_build_object('status', 'error', 'code', 'invalid_price');
  end if;
  if upper(btrim(coalesce(p_currency_code, ''))) !~ '^[A-Z]{3}$' then
    return jsonb_build_object('status', 'error', 'code', 'invalid_currency');
  end if;

  if p_item_id is null then
    insert into public.venue_drink_items (
      club_id, venue_id, item_name, description, price_amount, currency_code,
      is_active, is_alcohol, sort_order, created_by
    ) values (
      v_membership.club_id, v_membership.venue_id, btrim(p_name),
      nullif(btrim(coalesce(p_description, '')), ''), p_price_amount,
      upper(btrim(p_currency_code)), coalesce(p_is_active, false),
      coalesce(p_is_alcohol, false), coalesce(p_sort_order, 0), v_actor
    ) returning * into v_item;
    v_event_type := 'menu_item_created';
  else
    update public.venue_drink_items
    set item_name = btrim(p_name),
        description = nullif(btrim(coalesce(p_description, '')), ''),
        price_amount = p_price_amount,
        currency_code = upper(btrim(p_currency_code)),
        is_active = coalesce(p_is_active, false),
        is_alcohol = coalesce(p_is_alcohol, false),
        sort_order = coalesce(p_sort_order, 0)
    where id = p_item_id
      and club_id = v_membership.club_id
      and venue_id = v_membership.venue_id
    returning * into v_item;
    if v_item.id is null then
      return jsonb_build_object('status', 'error', 'code', 'item_not_found');
    end if;
    v_event_type := 'menu_item_updated';
  end if;

  insert into public.venue_staff_audit_events (
    club_id, venue_id, actor_id, event_type, entity_type, entity_id, metadata
  ) values (
    v_membership.club_id, v_membership.venue_id, v_actor, v_event_type,
    'venue_drink_item', v_item.id::text,
    jsonb_build_object('is_active', v_item.is_active, 'is_alcohol', v_item.is_alcohol)
  );

  return jsonb_build_object('status', 'success', 'code', 'ok', 'item_id', v_item.id);
exception
  when check_violation then
    return jsonb_build_object('status', 'error', 'code', 'active_item_limit');
end;
$_$;


ALTER FUNCTION "public"."venue_menu_upsert"("p_venue_id" "uuid", "p_item_id" "uuid", "p_name" "text", "p_description" "text", "p_price_amount" integer, "p_currency_code" "text", "p_is_alcohol" boolean, "p_is_active" boolean, "p_sort_order" integer) OWNER TO "postgres";


