ALTER FUNCTION "public"."venue_order_create"("p_club_id" bigint, "p_venue_id" "uuid", "p_checkin_id" "uuid", "p_items" "jsonb", "p_age_gate_confirmed" boolean, "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."venue_order_create_unscoped_internal"("p_club_id" bigint, "p_venue_id" "uuid", "p_checkin_id" "uuid", "p_items" "jsonb", "p_age_gate_confirmed" boolean, "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_checkin public.venue_checkins;
  v_order public.venue_drink_orders;
  v_item jsonb;
  v_drink public.venue_drink_items;
  v_quantity integer;
  v_total integer := 0;
  v_has_alcohol boolean := false;
  v_idempotency_key text := nullif(btrim(coalesce(p_idempotency_key, '')), '');
begin
  if v_user_id is null then
    return jsonb_build_object('status', 'error', 'code', 'auth_required');
  end if;

  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    return jsonb_build_object('status', 'error', 'code', 'items_required');
  end if;

  if jsonb_array_length(p_items) > 10 then
    return jsonb_build_object('status', 'error', 'code', 'item_limit_exceeded');
  end if;

  if v_idempotency_key is not null then
    perform pg_advisory_xact_lock(
      hashtextextended(
        v_user_id::text || ':' || p_club_id::text || ':' || v_idempotency_key,
        0
      )
    );

    select *
      into v_order
      from public.venue_drink_orders
     where club_id = p_club_id
       and user_id = v_user_id
       and idempotency_key = v_idempotency_key
     limit 1;

    if v_order.id is not null then
      return jsonb_build_object(
        'status', v_order.status,
        'code', 'idempotent_replay',
        'order_id', v_order.id,
        'total_amount', v_order.total_amount,
        'currency_code', v_order.currency_code,
        'payment_status', v_order.payment_status
      );
    end if;
  end if;

  select *
    into v_checkin
    from public.venue_checkins
   where id = p_checkin_id
     and club_id = p_club_id
     and venue_id = p_venue_id
     and user_id = v_user_id
     and status in ('confirmed', 'pending_review')
   limit 1;

  if v_checkin.id is null then
    return jsonb_build_object('status', 'error', 'code', 'checkin_required');
  end if;

  insert into public.venue_drink_orders (
    club_id,
    venue_id,
    checkin_id,
    user_id,
    status,
    idempotency_key,
    total_amount,
    age_gate_confirmed
  )
  values (
    p_club_id,
    p_venue_id,
    v_checkin.id,
    v_user_id,
    'created',
    v_idempotency_key,
    0,
    p_age_gate_confirmed
  )
  returning * into v_order;

  for v_item in select * from jsonb_array_elements(p_items)
  loop
    begin
      v_quantity := (v_item ->> 'quantity')::integer;
    exception
      when others then
        raise exception 'Drink quantity must be an integer between 1 and 20.';
    end;

    if v_quantity is null or v_quantity < 1 or v_quantity > 20 then
      raise exception 'Drink quantity must be between 1 and 20.';
    end if;

    select *
      into v_drink
      from public.venue_drink_items
     where id = (v_item ->> 'drink_item_id')::uuid
       and club_id = p_club_id
       and venue_id = p_venue_id
       and is_active
     limit 1;

    if v_drink.id is null then
      raise exception 'Drink item is unavailable.';
    end if;

    v_has_alcohol := v_has_alcohol or v_drink.is_alcohol;
    v_total := v_total + (v_drink.price_amount * v_quantity);

    insert into public.venue_drink_order_items (
      club_id,
      venue_id,
      order_id,
      drink_item_id,
      item_name,
      quantity,
      unit_price_amount,
      line_total_amount,
      is_alcohol
    )
    values (
      p_club_id,
      p_venue_id,
      v_order.id,
      v_drink.id,
      v_drink.item_name,
      v_quantity,
      v_drink.price_amount,
      v_drink.price_amount * v_quantity,
      v_drink.is_alcohol
    );
  end loop;

  if v_has_alcohol and not p_age_gate_confirmed then
    raise exception 'Age gate confirmation is required for alcohol items.';
  end if;

  update public.venue_drink_orders
     set total_amount = v_total,
         age_gate_confirmed = p_age_gate_confirmed
   where id = v_order.id
   returning * into v_order;

  insert into public.venue_order_events (
    club_id,
    venue_id,
    order_id,
    event_type,
    to_status,
    actor_id,
    metadata
  )
  values (
    p_club_id,
    p_venue_id,
    v_order.id,
    'order_created',
    'created',
    v_user_id,
    jsonb_build_object('item_count', jsonb_array_length(p_items))
  );

  return jsonb_build_object(
    'status', v_order.status,
    'code', 'ok',
    'order_id', v_order.id,
    'total_amount', v_order.total_amount,
    'currency_code', v_order.currency_code,
    'payment_status', v_order.payment_status
  );
exception
  when others then
    if v_order.id is not null then
      delete from public.venue_drink_orders where id = v_order.id;
    end if;
    raise;
end;
$$;


ALTER FUNCTION "public"."venue_order_create_unscoped_internal"("p_club_id" bigint, "p_venue_id" "uuid", "p_checkin_id" "uuid", "p_items" "jsonb", "p_age_gate_confirmed" boolean, "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."venue_order_update_status"("p_club_id" bigint, "p_order_id" "uuid", "p_status" "text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_order public.venue_drink_orders;
  v_previous_status text;
  v_actor uuid := auth.uid();
  v_next_status text := lower(btrim(coalesce(p_status, '')));
begin
  if v_actor is null then
    return jsonb_build_object('status', 'error', 'code', 'auth_required');
  end if;

  select *
    into v_order
    from public.venue_drink_orders
   where id = p_order_id
     and club_id = p_club_id
   for update;

  if v_order.id is null then
    return jsonb_build_object('status', 'error', 'code', 'order_not_found');
  end if;

  if not public.venue_staff_can_access(v_order.venue_id, array['owner', 'manager', 'staff']) and
     not public.is_club_admin(p_club_id) and
     not public.is_super_admin() then
    return jsonb_build_object('status', 'error', 'code', 'permission_denied');
  end if;

  if v_next_status <> all (array['accepted', 'preparing', 'ready', 'served', 'cancelled']) then
    return jsonb_build_object('status', 'error', 'code', 'invalid_status');
  end if;

  v_previous_status := v_order.status;

  update public.venue_drink_orders
     set status = v_next_status
   where id = p_order_id
   returning * into v_order;

  insert into public.venue_order_events (
    club_id,
    venue_id,
    order_id,
    event_type,
    from_status,
    to_status,
    actor_id,
    reason
  )
  values (
    p_club_id,
    v_order.venue_id,
    v_order.id,
    'order_status_changed',
    v_previous_status,
    v_next_status,
    v_actor,
    nullif(btrim(coalesce(p_reason, '')), '')
  );

  return jsonb_build_object(
    'status', v_order.status,
    'code', 'ok',
    'order_id', v_order.id
  );
end;
$$;


ALTER FUNCTION "public"."venue_order_update_status"("p_club_id" bigint, "p_order_id" "uuid", "p_status" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."venue_promotion_launch"("p_venue_id" "uuid", "p_campaign_id" "uuid", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_membership public.venue_staff_memberships;
  v_campaign public.venue_checkin_campaigns;
  v_key text := nullif(btrim(coalesce(p_idempotency_key, '')), '');
  v_event public.venue_promotion_events;
  v_is_replay boolean := false;
begin
  if v_actor is null then
    return jsonb_build_object('status', 'error', 'code', 'auth_required');
  end if;
  if v_key is null then
    return jsonb_build_object('status', 'error', 'code', 'idempotency_required');
  end if;

  select * into v_membership
  from public.venue_staff_memberships
  where user_id = v_actor
    and venue_id = p_venue_id
    and is_active
    and role = any (array['owner', 'manager'])
  order by granted_at asc limit 1;
  if v_membership.id is null then
    return jsonb_build_object('status', 'error', 'code', 'permission_denied');
  end if;

  select * into v_campaign
  from public.venue_checkin_campaigns
  where id = p_campaign_id
    and club_id = v_membership.club_id
    and venue_id = v_membership.venue_id
  limit 1;
  if v_campaign.id is null then
    return jsonb_build_object('status', 'error', 'code', 'campaign_not_found');
  end if;
  if v_campaign.status <> 'approved' then
    return jsonb_build_object('status', 'error', 'code', 'campaign_not_approved');
  end if;
  if timezone('utc', now()) < v_campaign.starts_at or timezone('utc', now()) >= v_campaign.ends_at then
    return jsonb_build_object('status', 'error', 'code', 'campaign_outside_window');
  end if;
  if v_campaign.fet_budget > 0 and v_campaign.awarded_fet >= v_campaign.fet_budget then
    return jsonb_build_object('status', 'error', 'code', 'campaign_budget_exhausted');
  end if;

  select * into v_event
  from public.venue_promotion_events
  where club_id = v_membership.club_id
    and venue_id = v_membership.venue_id
    and idempotency_key = v_key
  limit 1;

  if v_event.id is not null then
    v_is_replay := true;
  else
    insert into public.venue_promotion_events (
      club_id, venue_id, campaign_id, event_type, fet_amount,
      idempotency_key, metadata
    ) values (
      v_membership.club_id, v_membership.venue_id, v_campaign.id,
      'campaign_launched_by_venue', 0, v_key,
      jsonb_build_object('actor_id', v_actor)
    )
    on conflict (club_id, venue_id, idempotency_key) where idempotency_key is not null
    do nothing
    returning * into v_event;

    if v_event.id is null then
      select * into v_event
      from public.venue_promotion_events
      where club_id = v_membership.club_id
        and venue_id = v_membership.venue_id
        and idempotency_key = v_key
      limit 1;
      v_is_replay := true;
    end if;
  end if;

  if not v_is_replay then
    insert into public.venue_staff_audit_events (
      club_id, venue_id, actor_id, event_type, entity_type, entity_id, metadata
    ) values (
      v_membership.club_id, v_membership.venue_id, v_actor,
      'promotion_launched', 'venue_checkin_campaign', v_campaign.id::text,
      jsonb_build_object('promotion_event_id', v_event.id, 'idempotency_key', v_key)
    );
  end if;

  return jsonb_build_object(
    'status', 'success',
    'code', case when v_is_replay then 'idempotent_replay' else 'ok' end,
    'event_id', v_event.id
  );
end;
$$;


ALTER FUNCTION "public"."venue_promotion_launch"("p_venue_id" "uuid", "p_campaign_id" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."venue_staff_can_access"("p_venue_id" "uuid", "p_roles" "text"[] DEFAULT NULL::"text"[]) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.venue_staff_memberships staff
    where staff.venue_id = p_venue_id
      and staff.user_id = auth.uid()
      and staff.is_active
      and (p_roles is null or staff.role = any (p_roles))
  );
$$;


ALTER FUNCTION "public"."venue_staff_can_access"("p_venue_id" "uuid", "p_roles" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."xp_events_compat_write"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_event public.fet_events%rowtype;
begin
  if tg_op = 'DELETE' then
    delete from public.fet_events
    where id = old.id;
    return old;
  end if;

  if tg_op = 'UPDATE' then
    update public.fet_events
    set
      user_id = new.user_id,
      club_id = coalesce(new.club_id, old.club_id),
      event_type = new.event_type,
      fet_awarded = coalesce(new.xp_awarded, old.xp_awarded, 0),
      metadata = coalesce(new.metadata, old.metadata, '{}'::jsonb),
      event_at = coalesce(new.event_at, old.event_at),
      created_at = coalesce(new.created_at, old.created_at)
    where id = old.id
    returning * into v_event;

    new.id := v_event.id;
    new.created_at := v_event.created_at;
    new.event_at := v_event.event_at;
    new.xp_awarded := v_event.fet_awarded;
    return new;
  end if;

  insert into public.fet_events (
    user_id,
    club_id,
    event_type,
    fet_awarded,
    metadata,
    event_at,
    created_at
  )
  values (
    new.user_id,
    new.club_id,
    new.event_type,
    coalesce(new.xp_awarded, 0),
    coalesce(new.metadata, '{}'::jsonb),
    coalesce(new.event_at, timezone('utc', now())),
    coalesce(new.created_at, timezone('utc', now()))
  )
  returning * into v_event;

  new.id := v_event.id;
  new.created_at := v_event.created_at;
  new.event_at := v_event.event_at;
  new.xp_awarded := v_event.fet_awarded;
  return new;
end;
$$;


ALTER FUNCTION "public"."xp_events_compat_write"() OWNER TO "postgres";


