CREATE OR REPLACE VIEW "football"."fixture_features" WITH ("security_invoker"='true') AS
 SELECT "id" AS "fixture_id",
    "competition_id",
    "home_team_id",
    "away_team_id",
    "kickoff_at",
    "status",
    ( SELECT (("count"(*) FILTER (WHERE ("fx"."home_score" > "fx"."away_score")))::numeric / (NULLIF("count"(*), 0))::numeric)
           FROM "football"."fixtures" "fx"
          WHERE (("fx"."home_team_id" = "f"."home_team_id") AND ("fx"."status" = 'finished'::"football"."fixture_status") AND ("fx"."id" <> "f"."id"))) AS "home_team_win_rate",
    ( SELECT (("count"(*) FILTER (WHERE ("fx"."away_score" > "fx"."home_score")))::numeric / (NULLIF("count"(*), 0))::numeric)
           FROM "football"."fixtures" "fx"
          WHERE (("fx"."away_team_id" = "f"."away_team_id") AND ("fx"."status" = 'finished'::"football"."fixture_status") AND ("fx"."id" <> "f"."id"))) AS "away_team_win_rate",
    ( SELECT (("count"(*) FILTER (WHERE ("fx"."home_score" = "fx"."away_score")))::numeric / (NULLIF("count"(*), 0))::numeric)
           FROM "football"."fixtures" "fx"
          WHERE (("fx"."home_team_id" = "f"."home_team_id") AND ("fx"."status" = 'finished'::"football"."fixture_status") AND ("fx"."id" <> "f"."id"))) AS "home_team_draw_rate",
    ( SELECT COALESCE("avg"("fx"."home_score"), (0)::numeric) AS "coalesce"
           FROM "football"."fixtures" "fx"
          WHERE (("fx"."home_team_id" = "f"."home_team_id") AND ("fx"."status" = 'finished'::"football"."fixture_status") AND ("fx"."id" <> "f"."id"))) AS "home_goals_scored_avg",
    ( SELECT COALESCE("avg"("fx"."away_score"), (0)::numeric) AS "coalesce"
           FROM "football"."fixtures" "fx"
          WHERE (("fx"."home_team_id" = "f"."home_team_id") AND ("fx"."status" = 'finished'::"football"."fixture_status") AND ("fx"."id" <> "f"."id"))) AS "home_goals_conceded_avg",
    ( SELECT COALESCE("avg"("fx"."away_score"), (0)::numeric) AS "coalesce"
           FROM "football"."fixtures" "fx"
          WHERE (("fx"."away_team_id" = "f"."away_team_id") AND ("fx"."status" = 'finished'::"football"."fixture_status") AND ("fx"."id" <> "f"."id"))) AS "away_goals_scored_avg",
    ( SELECT COALESCE("avg"("fx"."home_score"), (0)::numeric) AS "coalesce"
           FROM "football"."fixtures" "fx"
          WHERE (("fx"."away_team_id" = "f"."away_team_id") AND ("fx"."status" = 'finished'::"football"."fixture_status") AND ("fx"."id" <> "f"."id"))) AS "away_goals_conceded_avg",
    ( SELECT "count"(*) FILTER (WHERE ((("fx"."home_team_id" = "f"."home_team_id") AND ("fx"."home_score" > "fx"."away_score")) OR (("fx"."away_team_id" = "f"."home_team_id") AND ("fx"."away_score" > "fx"."home_score")))) AS "count"
           FROM "football"."fixtures" "fx"
          WHERE (("fx"."status" = 'finished'::"football"."fixture_status") AND ((("fx"."home_team_id" = "f"."home_team_id") AND ("fx"."away_team_id" = "f"."away_team_id")) OR (("fx"."home_team_id" = "f"."away_team_id") AND ("fx"."away_team_id" = "f"."home_team_id"))))) AS "h2h_home_wins",
    ( SELECT "count"(*) FILTER (WHERE ((("fx"."home_team_id" = "f"."away_team_id") AND ("fx"."home_score" > "fx"."away_score")) OR (("fx"."away_team_id" = "f"."away_team_id") AND ("fx"."away_score" > "fx"."home_score")))) AS "count"
           FROM "football"."fixtures" "fx"
          WHERE (("fx"."status" = 'finished'::"football"."fixture_status") AND ((("fx"."home_team_id" = "f"."home_team_id") AND ("fx"."away_team_id" = "f"."away_team_id")) OR (("fx"."home_team_id" = "f"."away_team_id") AND ("fx"."away_team_id" = "f"."home_team_id"))))) AS "h2h_away_wins",
    ( SELECT "count"(*) FILTER (WHERE ("fx"."home_score" = "fx"."away_score")) AS "count"
           FROM "football"."fixtures" "fx"
          WHERE (("fx"."status" = 'finished'::"football"."fixture_status") AND ((("fx"."home_team_id" = "f"."home_team_id") AND ("fx"."away_team_id" = "f"."away_team_id")) OR (("fx"."home_team_id" = "f"."away_team_id") AND ("fx"."away_team_id" = "f"."home_team_id"))))) AS "h2h_draws",
    ( SELECT "st"."position"
           FROM "football"."standings" "st"
          WHERE (("st"."team_id" = "f"."home_team_id") AND ("st"."competition_id" = "f"."competition_id"))
          ORDER BY "st"."updated_at" DESC
         LIMIT 1) AS "home_league_position",
    ( SELECT "st"."position"
           FROM "football"."standings" "st"
          WHERE (("st"."team_id" = "f"."away_team_id") AND ("st"."competition_id" = "f"."competition_id"))
          ORDER BY "st"."updated_at" DESC
         LIMIT 1) AS "away_league_position"
   FROM "football"."fixtures" "f"
  WHERE ("status" = 'scheduled'::"football"."fixture_status");


ALTER VIEW "football"."fixture_features" OWNER TO "postgres";


COMMENT ON VIEW "football"."fixture_features" IS 'Pre-computed features for the probability engine. Reads historical fixture stats, h2h, and standings.';



CREATE TABLE IF NOT EXISTS "football"."fixture_lineup_players" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "fixture_lineup_id" "uuid" NOT NULL,
    "player_id" "uuid",
