    "squad_number" integer,
    "position" "text",
    "lineup_role" "text" DEFAULT 'starter'::"text" NOT NULL,
    "sort_order" integer DEFAULT 0 NOT NULL,
    "minute_on" integer,
    "minute_off" integer,
    "is_captain" boolean DEFAULT false NOT NULL,
