CREATE OR REPLACE VIEW "football"."prediction_volume" WITH ("security_invoker"='true') AS
 SELECT "fm"."fixture_id",
    "fm"."id" AS "fixture_market_id",
    "pm"."slug" AS "market_slug",
    "p"."selected_outcome",
    "count"(*) AS "vote_count",
    (("count"(*))::numeric / NULLIF("sum"("count"(*)) OVER (PARTITION BY "fm"."id"), (0)::numeric)) AS "vote_pct"
   FROM (("football"."predictions" "p"
     JOIN "football"."fixture_markets" "fm" ON (("fm"."id" = "p"."fixture_market_id")))
     JOIN "football"."prediction_markets" "pm" ON (("pm"."id" = "fm"."market_id")))
  WHERE ("p"."status" = 'pending'::"text")
  GROUP BY "fm"."fixture_id", "fm"."id", "pm"."slug", "p"."selected_outcome";


ALTER VIEW "football"."prediction_volume" OWNER TO "postgres";


COMMENT ON VIEW "football"."prediction_volume" IS 'Aggregated user voting percentages per fixture market outcome. Used for liability adjustment.';



