CREATE OR REPLACE VIEW "public"."contribution_groups" WITH ("security_invoker"='true') AS
 SELECT "id",
    NULL::"uuid" AS "creator_id",
    "name",
    "description",
        CASE
            WHEN ("lower"(COALESCE("group_type", "type", 'community'::"text")) = ANY (ARRAY['project'::"text", 'club'::"text", 'team_project'::"text"])) THEN 'project'::"text"
            ELSE 'community'::"text"
        END AS "group_type",
    "target_amount",
    COALESCE("current_total", ("amount")::numeric, (0)::numeric) AS "current_total",
    "receiving_momo_code" AS "momo_recipient_code",
    "receiving_momo_route_type" AS "momo_route_type",
    "deadline",
    "is_recurring",
    "is_closed",
    "member_count",
    "created_at",
    "club_id",
    "partner_id",
    "currency",
    "updated_at",
    "is_active",
    "country",
    "type",
    "amount",
    "monthly_contribution",
    NULL::"text" AS "bank_partner_id",
    NULL::"text" AS "momo_number",
    "frequency",
    NULL::"text" AS "receiving_momo_route_type",
    NULL::"text" AS "receiving_momo_code",
    "cycle_days",
    "contribution_amount"
   FROM "public"."groups" "g"
  WHERE (COALESCE("visibility", 'public'::"text") = 'public'::"text");


ALTER VIEW "public"."contribution_groups" OWNER TO "postgres";


COMMENT ON VIEW "public"."contribution_groups" IS 'Security-invoker compatibility projection. Public initiative fields are column-granted to anon/authenticated; only authenticated same-club readers can select the canonical receiving route; legacy raw routing and creator fields are null.';



