    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."fet_events" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."cool_events" WITH ("security_invoker"='true') AS
 SELECT "id",
    "user_id",
    "event_type",
    NULLIF(("metadata" ->> 'source_id'::"text"), ''::"text") AS "source_id",
    COALESCE("fet_awarded", 0) AS "points_awarded",
    "metadata",
        CASE
            WHEN (COALESCE(("metadata" ->> 'referrer_id'::"text"), ''::"text") ~* '^[0-9a-f-]{36}$'::"text") THEN (("metadata" ->> 'referrer_id'::"text"))::"uuid"
            ELSE NULL::"uuid"
        END AS "referrer_id",
    "created_at",
    NULLIF(("metadata" ->> 'dedupe_key'::"text"), ''::"text") AS "dedupe_key",
    NULLIF(("metadata" ->> 'campaign_id'::"text"), ''::"text") AS "campaign_id",
        CASE
            WHEN (COALESCE(("metadata" ->> 'season_id'::"text"), ''::"text") ~* '^[0-9a-f-]{36}$'::"text") THEN (("metadata" ->> 'season_id'::"text"))::"uuid"
            ELSE NULL::"uuid"
        END AS "season_id",
    false AS "is_mock",
    NULLIF(("metadata" ->> 'mock_batch'::"text"), ''::"text") AS "mock_batch",
    "club_id",
    "fet_awarded",
    "fet_awarded" AS "xp_awarded",
    "event_at"
   FROM "public"."fet_events" "x";


ALTER VIEW "public"."cool_events" OWNER TO "postgres";


