CREATE OR REPLACE VIEW "public"."football_fixtures_catalog" WITH ("security_invoker"='true') AS
 SELECT "f"."id",
    "f"."competition_id",
    "c"."slug" AS "competition_slug",
    "c"."name" AS "competition_name",
    "f"."season_id",
    "s"."slug" AS "season_slug",
    "s"."label" AS "season_label",
    "f"."stage_name",
    "f"."group_name",
    "f"."round_name",
    "f"."matchday",
    "f"."fixture_number",
    "f"."kickoff_at",
    "f"."venue_name",
    "f"."venue_city",
    "f"."venue_country",
    "f"."home_team_id",
    "ht"."slug" AS "home_team_slug",
    "ht"."name" AS "home_team_name",
    "ht"."short_name" AS "home_team_short_name",
    "f"."away_team_id",
    "at"."slug" AS "away_team_slug",
    "at"."name" AS "away_team_name",
    "at"."short_name" AS "away_team_short_name",
    "f"."home_score",
    "f"."away_score",
    "f"."leg_number",
    "f"."status",
    "f"."metadata",
    "f"."created_at",
    "f"."updated_at",
    "ht"."crest_url" AS "home_team_logo_url",
    "at"."crest_url" AS "away_team_logo_url",
    COALESCE("c"."logo_url", ("c"."metadata" ->> 'api_league_logo'::"text"), ("c"."metadata" ->> 'storage_league_logo_url'::"text")) AS "competition_logo_url",
    "f"."external_provider",
    "f"."external_fixture_id",
    COALESCE("ht"."crest_url", ("f"."metadata" ->> 'home_team_logo'::"text")) AS "home_team_logo",
    COALESCE("at"."crest_url", ("f"."metadata" ->> 'away_team_logo'::"text")) AS "away_team_logo",
    COALESCE("c"."logo_url", ("c"."metadata" ->> 'api_league_logo'::"text"), ("c"."metadata" ->> 'storage_league_logo_url'::"text")) AS "competition_logo",
    COALESCE((("f"."metadata" ->> 'api_elapsed'::"text"))::integer, 0) AS "live_elapsed",
    ("f"."metadata" ->> 'api_status_short'::"text") AS "api_status_short"
   FROM (((("football"."fixtures" "f"
     JOIN "football"."competitions" "c" ON (("c"."id" = "f"."competition_id")))
     JOIN "football"."seasons" "s" ON (("s"."id" = "f"."season_id")))
     JOIN "football"."teams" "ht" ON (("ht"."id" = "f"."home_team_id")))
     JOIN "football"."teams" "at" ON (("at"."id" = "f"."away_team_id")));


ALTER VIEW "public"."football_fixtures_catalog" OWNER TO "postgres";


