CREATE OR REPLACE VIEW "public"."football_standings_catalog" WITH ("security_invoker"='true') AS
 SELECT "st"."id",
    "st"."competition_id",
    "c"."slug" AS "competition_slug",
    "c"."name" AS "competition_name",
    "st"."season_id",
    "s"."slug" AS "season_slug",
    "s"."label" AS "season_label",
    "st"."team_id",
    "t"."slug" AS "team_slug",
    "t"."name" AS "team_name",
    "t"."short_name" AS "team_short_name",
    "st"."stage_name",
    "st"."group_name",
    "st"."position",
    "st"."played",
    "st"."won",
    "st"."drawn",
    "st"."lost",
    "st"."goals_for",
    "st"."goals_against",
    "st"."goal_difference",
    "st"."points",
    "st"."form",
    "st"."notes",
    "st"."metadata",
    "st"."created_at",
    "st"."updated_at",
    "t"."crest_url" AS "team_crest_url",
    COALESCE("t"."crest_url", ("st"."metadata" ->> 'api_team_logo'::"text")) AS "team_logo"
   FROM ((("football"."standings" "st"
     JOIN "football"."competitions" "c" ON (("c"."id" = "st"."competition_id")))
     JOIN "football"."seasons" "s" ON (("s"."id" = "st"."season_id")))
     JOIN "football"."teams" "t" ON (("t"."id" = "st"."team_id")));


