CREATE OR REPLACE VIEW "public"."football_sync_overview" WITH ("security_invoker"='true') AS
 SELECT "sc"."id",
    "sc"."external_provider",
    "sc"."external_league_id",
    "sc"."league_name",
    "sc"."season_year",
    "c"."slug" AS "competition_slug",
    "c"."name" AS "competition_name",
    "sc"."sync_fixtures",
    "sc"."sync_standings",
    "sc"."sync_live",
    "sc"."sync_squads",
    "sc"."sync_interval_minutes",
    "sc"."last_synced_at",
    "sc"."last_standings_synced_at",
    "sc"."last_live_synced_at",
    "sc"."sync_status",
    "sc"."is_active",
    "sc"."created_at",
    ( SELECT "jsonb_build_object"('total_fixtures', "count"(*) FILTER (WHERE ("f"."external_provider" = 'api-football'::"text")), 'live_fixtures', "count"(*) FILTER (WHERE ("f"."status" = 'live'::"football"."fixture_status")), 'finished_fixtures', "count"(*) FILTER (WHERE ("f"."status" = 'finished'::"football"."fixture_status")), 'scheduled_fixtures', "count"(*) FILTER (WHERE ("f"."status" = 'scheduled'::"football"."fixture_status"))) AS "jsonb_build_object"
           FROM "football"."fixtures" "f"
          WHERE ("f"."competition_id" = "sc"."competition_id")) AS "fixture_summary",
    ( SELECT "count"(*) AS "count"
           FROM "football"."standings" "st"
          WHERE ("st"."competition_id" = "sc"."competition_id")) AS "standings_count"
   FROM ("public"."football_sync_config" "sc"
     LEFT JOIN "football"."competitions" "c" ON (("c"."id" = "sc"."competition_id")))
  ORDER BY "sc"."league_name";


ALTER VIEW "public"."football_sync_overview" OWNER TO "postgres";


