    "source_key" "text" NOT NULL,
    "display_name" "text" NOT NULL,
    "match_aliases" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "country_aliases" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "external_competition_ids" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "source_urls" "text"[] DEFAULT ARRAY['https://www.livescore.com/en/'::"text"] NOT NULL,
    "sync_fixtures" boolean DEFAULT true NOT NULL,
