CREATE TABLE IF NOT EXISTS "public"."matches" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "partner_id" "uuid" NOT NULL,
    "home_team" "text" NOT NULL,
    "away_team" "text" NOT NULL,
    "competition" "text" NOT NULL,
    "venue" "text" NOT NULL,
    "match_date" "date" NOT NULL,
    "kickoff_time" time without time zone NOT NULL,
    "is_on_sale" boolean DEFAULT true NOT NULL,
    "ticket_general_price" integer DEFAULT 0 NOT NULL,
    "ticket_vip_price" integer DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "sale_starts_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "capacity" integer DEFAULT 0 NOT NULL,
    "is_mock" boolean DEFAULT false NOT NULL,
    "mock_batch" "text",
    "sold_count" integer DEFAULT 0 NOT NULL,
    "image_url" "text",
    "club_id" bigint,
    "roster" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "match_status" "text" DEFAULT 'scheduled'::"text" NOT NULL,
    "home_score" integer DEFAULT 0 NOT NULL,
    "away_score" integer DEFAULT 0 NOT NULL,
    "live_minute" integer,
    "match_summary" "text",
    "live_stats" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "live_events" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "is_featured" boolean DEFAULT false NOT NULL,
    "fixture_id" "uuid",
    "image_provenance_id" "text",
    "image_rights_approved" boolean DEFAULT false NOT NULL,
    "image_rights_approved_at" timestamp with time zone,
    "image_rights_approved_by" "uuid",
    "home_team_logo_provenance_id" "text",
    "home_team_logo_rights_approved" boolean DEFAULT false NOT NULL,
    "away_team_logo_provenance_id" "text",
    "away_team_logo_rights_approved" boolean DEFAULT false NOT NULL,
    CONSTRAINT "matches_approved_media_has_provenance" CHECK ((((NOT "image_rights_approved") OR ((NULLIF("btrim"("image_provenance_id"), ''::"text") IS NOT NULL) AND ("image_rights_approved_at" IS NOT NULL) AND ("image_rights_approved_by" IS NOT NULL))) AND ((NOT "home_team_logo_rights_approved") OR (NULLIF("btrim"("home_team_logo_provenance_id"), ''::"text") IS NOT NULL)) AND ((NOT "away_team_logo_rights_approved") OR (NULLIF("btrim"("away_team_logo_provenance_id"), ''::"text") IS NOT NULL)))),
    CONSTRAINT "rs_matches_check_capacity" CHECK (("capacity" >= 0))
);


