CREATE OR REPLACE VIEW "public"."prediction_fixture_community" WITH ("security_invoker"='true') AS
 SELECT "p"."fixture_id",
    "p"."fixture_market_id",
    "pm"."name" AS "market_name",
    "pm"."short_name" AS "market_short_name",
    "p"."selected_outcome",
    "count"(*) AS "pick_count",
    "round"(((("count"(*))::numeric / NULLIF("sum"("count"(*)) OVER (PARTITION BY "p"."fixture_market_id"), (0)::numeric)) * (100)::numeric), 1) AS "pick_percentage"
   FROM (("football"."predictions" "p"
     JOIN "football"."fixture_markets" "fm" ON (("fm"."id" = "p"."fixture_market_id")))
     JOIN "football"."prediction_markets" "pm" ON (("pm"."id" = "fm"."market_id")))
  WHERE ("p"."status" <> 'cancelled'::"text")
  GROUP BY "p"."fixture_id", "p"."fixture_market_id", "pm"."name", "pm"."short_name", "p"."selected_outcome";


ALTER VIEW "public"."prediction_fixture_community" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."prediction_leaderboard" WITH ("security_invoker"='true') AS
 SELECT "user_id",
    ('Supporter '::"text" || "upper"("substr"("md5"(("user_id")::"text"), 1, 6))) AS "display_name",
    "count"(*) FILTER (WHERE ("status" = 'won'::"text")) AS "wins",
    "count"(*) FILTER (WHERE ("status" = ANY (ARRAY['won'::"text", 'lost'::"text"]))) AS "total_settled",
    COALESCE("sum"("fet_earned"), (0)::bigint) AS "total_fet_earned",
        CASE
            WHEN ("count"(*) FILTER (WHERE ("status" = ANY (ARRAY['won'::"text", 'lost'::"text"]))) > 0) THEN "round"(((("count"(*) FILTER (WHERE ("status" = 'won'::"text")))::numeric / ("count"(*) FILTER (WHERE ("status" = ANY (ARRAY['won'::"text", 'lost'::"text"]))))::numeric) * (100)::numeric), 1)
            ELSE (0)::numeric
        END AS "win_rate"
   FROM "football"."predictions" "prediction"
  WHERE ("status" = ANY (ARRAY['won'::"text", 'lost'::"text"]))
  GROUP BY "user_id"
  ORDER BY COALESCE("sum"("fet_earned"), (0)::bigint) DESC, ("count"(*) FILTER (WHERE ("status" = 'won'::"text"))) DESC;


ALTER VIEW "public"."prediction_leaderboard" OWNER TO "postgres";


