CREATE OR REPLACE VIEW "public"."prediction_supported_competitions_catalog" WITH ("security_invoker"='true') AS
 SELECT "psc"."id" AS "support_id",
    "psc"."sort_order" AS "support_sort_order",
    "psc"."highlight_label",
    "psc"."is_active" AS "is_supported",
    COALESCE("fx"."fixture_count", 0) AS "fixture_count",
    "c"."id",
