    "c"."created_at",
    "c"."updated_at"
   FROM (("public"."prediction_supported_competitions" "psc"
     JOIN "public"."football_competitions_catalog" "c" ON (("c"."id" = "psc"."competition_id")))
     LEFT JOIN LATERAL ( SELECT ("count"(*))::integer AS "fixture_count"
           FROM "football"."fixtures" "f"
          WHERE ("f"."competition_id" = "psc"."competition_id")) "fx" ON (true));


