CREATE OR REPLACE VIEW "public"."prediction_user_stats" WITH ("security_invoker"='true') AS
 SELECT "user_id",
    "count"(*) FILTER (WHERE ("status" = ANY (ARRAY['won'::"text", 'lost'::"text"]))) AS "total_predictions",
    "count"(*) FILTER (WHERE ("status" = 'won'::"text")) AS "total_won",
    "count"(*) FILTER (WHERE ("status" = 'lost'::"text")) AS "total_lost",
    "count"(*) FILTER (WHERE ("status" = 'pending'::"text")) AS "total_pending",
    COALESCE("sum"("fet_earned"), (0)::bigint) AS "total_fet_earned",
        CASE
            WHEN ("count"(*) FILTER (WHERE ("status" = ANY (ARRAY['won'::"text", 'lost'::"text"]))) > 0) THEN "round"(((("count"(*) FILTER (WHERE ("status" = 'won'::"text")))::numeric / ("count"(*) FILTER (WHERE ("status" = ANY (ARRAY['won'::"text", 'lost'::"text"]))))::numeric) * (100)::numeric), 1)
            ELSE (0)::numeric
        END AS "win_rate",
    ( SELECT "count"(*) AS "count"
           FROM ( SELECT "p2"."status",
                    "row_number"() OVER (ORDER BY "p2"."settled_at" DESC) AS "rn"
                   FROM "football"."predictions" "p2"
                  WHERE (("p2"."user_id" = "p"."user_id") AND ("p2"."status" = ANY (ARRAY['won'::"text", 'lost'::"text"])))) "streak"
          WHERE (("streak"."status" = ( SELECT "p3"."status"
                   FROM "football"."predictions" "p3"
                  WHERE (("p3"."user_id" = "p"."user_id") AND ("p3"."status" = ANY (ARRAY['won'::"text", 'lost'::"text"])))
                  ORDER BY "p3"."settled_at" DESC
                 LIMIT 1)) AND ("streak"."rn" <= 50))) AS "current_streak",
    ( SELECT "p4"."status"
           FROM "football"."predictions" "p4"
          WHERE (("p4"."user_id" = "p"."user_id") AND ("p4"."status" = ANY (ARRAY['won'::"text", 'lost'::"text"])))
          ORDER BY "p4"."settled_at" DESC
         LIMIT 1) AS "streak_type"
   FROM "football"."predictions" "p"
  GROUP BY "user_id";


ALTER VIEW "public"."prediction_user_stats" OWNER TO "postgres";


CREATE SEQUENCE IF NOT EXISTS "public"."public_user_id_seq"
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
