CREATE OR REPLACE VIEW "public"."supporter_presence_catalog" WITH ("security_invoker"='true') AS
 WITH "device_presence" AS (
         SELECT "token"."user_id",
            "token"."club_id",
            "token"."last_seen_at"
           FROM "public"."user_fcm_tokens" "token"
          WHERE (("token"."user_id" IS NOT NULL) AND ("token"."club_id" IS NOT NULL))
        UNION ALL
         SELECT "subscription"."user_id",
            (NULLIF("subscription"."club_id", ''::"text"))::bigint AS "club_id",
            "subscription"."last_seen_at"
           FROM "public"."web_push_subscriptions" "subscription"
          WHERE (("subscription"."user_id" IS NOT NULL) AND (NULLIF("subscription"."club_id", ''::"text") ~ '^[0-9]+$'::"text"))
        )
 SELECT "user_id",
    "club_id",
    "max"("last_seen_at") AS "last_seen_at",
    ("max"("last_seen_at") >= ("timezone"('utc'::"text", "now"()) - '00:10:00'::interval)) AS "is_online"
   FROM "device_presence"
  GROUP BY "user_id", "club_id";


ALTER VIEW "public"."supporter_presence_catalog" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."unified_matches" WITH ("security_invoker"='true') AS
 SELECT COALESCE("m"."id", "f"."id") AS "id",
    "f"."id" AS "fixture_id",
    "m"."id" AS "legacy_match_id",
    "m"."club_id",
    COALESCE("f"."home_team_name", "m"."home_team") AS "home_team",
    COALESCE("f"."away_team_name", "m"."away_team") AS "away_team",
    COALESCE("f"."competition_name", "m"."competition") AS "competition",
    COALESCE("f"."venue_name", "m"."venue") AS "venue",
    COALESCE(("f"."kickoff_at")::"date", "m"."match_date") AS "match_date",
    COALESCE(("f"."kickoff_at")::time without time zone, "m"."kickoff_time") AS "kickoff_time",
    "f"."kickoff_at",
    COALESCE("m"."is_on_sale", false) AS "is_on_sale",
    COALESCE("m"."ticket_general_price", 0) AS "ticket_general_price",
    COALESCE("m"."ticket_vip_price", 0) AS "ticket_vip_price",
    COALESCE(("f"."status")::"text", "m"."match_status") AS "match_status",
    COALESCE("f"."home_score", "m"."home_score") AS "home_score",
    COALESCE("f"."away_score", "m"."away_score") AS "away_score",
    COALESCE("f"."live_elapsed", "m"."live_minute") AS "live_minute",
    "m"."live_stats",
    "m"."live_events",
    "m"."image_url",
    COALESCE("m"."is_featured", false) AS "is_featured",
    "m"."capacity",
    "m"."sold_count",
    "f"."competition_slug",
    "f"."season_slug",
    "f"."home_team_logo",
    "f"."away_team_logo",
    "f"."competition_logo",
    "f"."home_team_logo_url" AS "home_team_crest_url",
    "f"."away_team_logo_url" AS "away_team_crest_url",
    "f"."home_team_slug",
    "f"."away_team_slug",
    "f"."home_team_short_name",
    "f"."away_team_short_name",
    "f"."api_status_short",
    "f"."external_fixture_id"
   FROM ("public"."football_fixtures_catalog" "f"
     LEFT JOIN "public"."matches" "m" ON ((("m"."fixture_id" = "f"."id") OR (("m"."fixture_id" IS NULL) AND ("m"."match_date" = ("f"."kickoff_at")::"date") AND ("lower"(TRIM(BOTH FROM COALESCE("m"."home_team", ''::"text"))) = "lower"(TRIM(BOTH FROM COALESCE("f"."home_team_name", ''::"text")))) AND ("lower"(TRIM(BOTH FROM COALESCE("m"."away_team", ''::"text"))) = "lower"(TRIM(BOTH FROM COALESCE("f"."away_team_name", ''::"text")))) AND ((NULLIF(TRIM(BOTH FROM COALESCE("m"."competition", ''::"text")), ''::"text") IS NULL) OR ("lower"(TRIM(BOTH FROM "m"."competition")) = "lower"(TRIM(BOTH FROM COALESCE("f"."competition_name", ''::"text")))))))));


ALTER VIEW "public"."unified_matches" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."unified_roster" WITH ("security_invoker"='true') AS
 SELECT COALESCE("s"."id", "r"."id") AS "id",
    "r"."id" AS "registration_id",
    "s"."club_id",
    COALESCE("r"."player_name", "s"."name") AS "name",
    COALESCE("r"."position", "s"."position") AS "role",
    COALESCE("r"."squad_number", "s"."shirt_number") AS "number",
    "s"."nationality",
    "s"."bio",
    COALESCE("s"."photo_url", "s"."image_url") AS "image_url",
    "s"."is_active",
    "r"."season_slug"
   FROM ("public"."football_roster_catalog" "r"
     LEFT JOIN "public"."squad_players" "s" ON (("s"."name" = "r"."player_name")));


ALTER VIEW "public"."unified_roster" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."unified_standings" WITH ("security_invoker"='true') AS
 SELECT COALESCE("s"."id", "st"."id") AS "id",
    "st"."id" AS "fixture_standing_id",
    "s"."club_id",
    COALESCE("st"."team_name", "s"."club_name") AS "club_name",
    COALESCE("st"."team_slug", "s"."club_slug") AS "club_slug",
    COALESCE("st"."position", "s"."position") AS "position",
    COALESCE("st"."played", "s"."played") AS "played",
    COALESCE("st"."won", "s"."won") AS "won",
    COALESCE("st"."drawn", "s"."drawn") AS "drawn",
    COALESCE("st"."lost", "s"."lost") AS "lost",
    COALESCE("st"."goals_for", "s"."goals_for") AS "goals_for",
    COALESCE("st"."goals_against", "s"."goals_against") AS "goals_against",
    COALESCE("st"."goal_difference", "s"."goal_difference") AS "goal_difference",
    COALESCE("st"."points", "s"."points") AS "points",
    COALESCE("st"."form", "s"."form") AS "form",
    "st"."competition_slug",
    "st"."season_slug",
    "st"."team_crest_url",
    "st"."team_logo"
   FROM ("public"."football_standings_catalog" "st"
     LEFT JOIN "public"."standings" "s" ON (("s"."club_slug" = "st"."team_slug")));


